#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0          /* CE0 (GPIO8) */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */
#define ADC_CHANNEL 0          /* MCP3008 CH0 */
#define SAMPLE_US   1000000    /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0-1023 on success, or -1 on SPI transfer failure.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: start bit (0x01)
     * Byte 1: SGL/DIFF=1 + D2 D1 D0 channel, shifted left 4 bits
     * Byte 2: don't care (clocks out low 2 bits of result)
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + 8 bits of rx[2] */
    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return value;
}

static void log_moisture_level(int moisture_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s - Moisture Level: %d\n", timestamp, moisture_level);
    fflush(stdout);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Sensor Reader (MCP3008 CH0)\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int moisture_level = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (moisture_level < 0) {
            fprintf(stderr, "Error reading moisture level, retrying in 1 s...\n");
            fflush(stderr);
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_moisture_level(moisture_level);
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

