/*
 * Raspberry Pi 4 Model B - MLX91219 Hall-effect current sensor reader
 *
 * Hardware:
 *   - MLX91219 analog output -> ADS1115 AIN0
 *   - ADS1115 ADDR -> GND  (I2C address 0x48 on bus 1)
 *   - ADS1115 SDA -> GPIO2 (I2C bus 1 SDA)
 *   - ADS1115 SCL -> GPIO3 (I2C bus 1 SCL)
 *
 * The MLX91219 has an analog output; the ADS1115 is used to digitize it.
 * The ADS1115 is configured for single-shot, AIN0 single-ended, PGA ±4.096V,
 * 128 samples per second, and a 500 ms loop interval.
 *
 * Build:  gcc -O2 -Wall -o current_reader current_reader.c -lpigpio -lrt
 * Run:    sudo ./current_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 register addresses ---- */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* ---- ADS1115 config-register bits ---- */
#define ADS1115_CFG_OS_BEGIN   (1u << 15)   /* Bit 15: Operational status / single-shot start */
#define ADS1115_CFG_MUX_AIN0   (0x4000u)   /* Bits 14:12 = 100: AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096  (0x0200u)   /* Bits 11:9 = 001: PGA ±4.096V */
#define ADS1115_CFG_MODE_SS   (0x0100u)   /* Bit 8 = 1: Single-shot mode */
#define ADS1115_CFG_DR_128    (0x0080u)   /* Bits 7:5 = 100: 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x0003u)   /* Bits 2:0 = 100: Disable comparator */

#define ADS1115_I2C_BUS       1
#define ADS1115_I2C_ADDR      0x48

#define MLX91219_SENSITIVITY  0.040f   /* 40 mV/A */
#define MLX91219_OFFSET      0.5f     /* Zero-current offset (mid-supply) */

#define LOOP_DELAY_US        500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register.                        */
/* pigpio's i2cWriteI2CBlockData expects little-endian byte order.     */
/* ------------------------------------------------------------------ */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, buf, 3) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData (reg 0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register.                       */
/* pigpio's i2cReadI2CBlockData returns data in the order it was written. */
/* ------------------------------------------------------------------ */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONFIG, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData (reg 0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion and read the result.               */
/* Returns 0 on success, -1 on I2C error.                             */
/* ------------------------------------------------------------------ */
static int ads1115_read_conversion(int handle, int16_t *out)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128
                    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS, use 10 ms). */
    gpioDelay(10000);

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) < 0)
        return -1;

    *out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus to ADS1115 ---- */
    g_i2c_handle = i2cOpen(ADS1115_I2C_BUS, ADS1115_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                ADS1115_I2C_BUS, ADS1115_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 current reader started.  Press Ctrl+C to exit.\n");
    printf("ADS1115 @ 0x%02X, AIN0, PGA ±4.096V, 128 SPS, 500 ms loop.\n",
           ADS1115_I2C_ADDR);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_conversion(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: I2C read error; retrying next cycle.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /*
         * MLX91219: 40 mV/A full-scale, zero-current offset at mid-supply.
         * Current = (raw - offset) / sensitivity.
         */
        float current = (float)(raw - MLX91219_OFFSET) / MLX91219_SENSITIVITY;

        printf("Current: %.3f A\n", current);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

