#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d (rc=%d)\n", FLAME_SENSOR_GPIO, value);
        return -1;
    }
    return value;
}

static float adc_to_temperature(int adc_value) {
    if (adc_value < 0) return -100.0f;
    return 10.0f + (float)adc_value * 3.0f;
}

static int log_data(int flame_detected, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT) failed");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Sensor read error; skipping log entry\n");
        } else {
            int adc_value = spiRead(spi_handle, MCP3008_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "SPI read error (channel %d)\n", MCP3008_CHANNEL);
            } else {
                float temperature = adc_to_temperature(adc_value);
                if (temperature < -50.0f || temperature > 150.0f) {
                    fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                } else {
                    if (log_data(flame_detected, temperature) < 0) {
                        fprintf(stderr, "Failed to log data\n");
                    }
                }
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

