#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define FLAME_THRESHOLD 50000
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 100000
#define BUZZER_DURATION_US 2000000

#define ADC_GAIN_4_096V 0x0200
#define ADC_MODE_SINGLE 0x0100
#define ADC_DR_128SPS 0x0080
#define ADC_OS_SINGLE 0x8000
#define ADC_MUX_AIN0_GND 0x4000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    static uint32_t last_event_tick = 0;
    uint32_t now = tick;
    if (now - last_event_tick < DEBOUNCE_MS * 1000) {
        return;
    }
    last_event_tick = now;
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
}

static int read_ads1115(int handle, float *temperature) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADC_OS_SINGLE << 15) | (ADC_MUX_AIN0_GND << 12) | (ADC_GAIN_4_096V << 9) | (ADC_DR_128SPS << 5);
    config[2] = (ADC_OS_SINGLE << 15) | (ADC_MUX_AIN0_GND << 12) | (ADC_GAIN_4_096V << 9) | (ADC_DR_128SPS << 5);

    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config\n");
        return -1;
    }

    gpioDelay(10000);

    char reg[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    *temperature = (raw * 4.096) / 32768.0;
    return 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set flame sensor ISR\n");
        cleanup();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(FLAME_SENSOR_GPIO) == 0) {
            gpioDelay(10000);
            if (gpioRead(FLAME_SENSOR_GPIO) == 0) {
                float temp;
                if (read_ads1115(i2c_handle, &temp) == 0) {
                    if (temp > TEMP_THRESHOLD) {
                        log_event("Temperature above threshold!");
                    } else {
                        log_event("Temperature normal.");
                    }
                } else {
                    log_event("ADC read error.");
                }
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

