#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define FAN_GPIO_LINE   18
#define GPIO_CHIP_NAME  "gpiochip4"
#define GPIO_CHIP_NAME_FALLBACK "gpiochip0"

#define DEFAULT_SENSITIVITY 100.0f  /* mV/A */
#define DEFAULT_THRESHOLD   5.0f    /* A */
#define SAMPLE_INTERVAL_S   1

#define ADC_VREF          3.3f
#define ADC_MAX_VALUE     1023.0f

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_fan_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME_FALLBACK);
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    }
    if (!g_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    g_fan_line = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_fan_line, "mlx91219_fan", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n",
                FAN_GPIO_LINE, strerror(errno));
        g_fan_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_fan_line) {
        gpiod_line_set_value(g_fan_line, 0);
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

static int read_adc(int *adc_value)
{
    if (g_spi_fd < 0) {
        return -1;
    }

    uint8_t tx[3] = { 0x01, 0x80, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_current(int adc_value, float sensitivity)
{
    if (adc_value < 0 || adc_value > 1023) {
        return 0.0f;
    }
    float voltage = ((float)adc_value / ADC_MAX_VALUE) * ADC_VREF;
    return (voltage / sensitivity) * 1000.0f;
}

static int log_data(float current)
{
    FILE *fp = fopen("current_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, %.2f A\n", timestamp, current);
    fclose(fp);
    return 0;
}

int main(int argc, char *argv[])
{
    int adc_value = 0;
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "s:t:h")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity_mv_per_A] [-t threshold_A]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (sensitivity <= 0.0f) {
        fprintf(stderr, "Invalid sensitivity value. Using default %.2f mV/A.\n", sensitivity);
        sensitivity = DEFAULT_SENSITIVITY;
    }
    if (threshold <= 0.0f) {
        fprintf(stderr, "Invalid threshold value. Using default %.2f A.\n", threshold);
        threshold = DEFAULT_THRESHOLD;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91219 Current Sensor Monitor\n");
    printf("Sensitivity: %.2f mV/A, Threshold: %.2f A\n", sensitivity, threshold);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_adc(&adc_value) < 0) {
            fprintf(stderr, "ADC read error, retrying in %d s...\n", SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC saturated (raw=%d), sensor may be absent or disconnected\n", adc_value);
        }

        float current = adc_to_current(adc_value, sensitivity);

        if (current > threshold) {
            if (gpiod_line_set_value(g_fan_line, 1) < 0) {
                fprintf(stderr, "Error turning fan ON: %s\n", strerror(errno));
            }
        } else {
            if (gpiod_line_set_value(g_fan_line, 0) < 0) {
                fprintf(stderr, "Error turning fan OFF: %s\n", strerror(errno));
            }
        }

        if (log_data(current) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Current: %.2f A, ADC: %d, Fan: %s\n", current, adc_value,
               (current > threshold) ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

