#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/* ADS1115 Registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/* ADS1115 Config: MUX=AIN0, PGA=4.096V, Single-shot, 128 SPS */
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_MODE_SINGLE 0x0100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw_value) {
    char config[3];
    char data[2];
    int16_t val;

    /* Write config: MUX=AIN0, PGA=4.096V, Single-shot, 128 SPS */
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                  ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS |
                  ADS1115_CONFIG_CQUE_NONE | ADS1115_CONFIG_MODE_SINGLE) & 0xFFFC;
    config[2] = 0x00;

    if (i2cWriteDevice(handle, config, 3) != 0) {
        return -1;
    }

    /* Wait for conversion to complete (~8ms at 128 SPS) */
    gpioDelay(10000);

    /* Read conversion register */
    if (i2cWriteByte(handle, ADS1115_REG_CONVERSION) != 0) {
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }

    val = (int16_t)((data[0] << 8) | data[1]);
    *raw_value = val;
    return 0;
}

static float calculate_co_ppm(int16_t raw_value) {
    /* Calibrated logarithmic curve: PPM = 100 * log10(raw_value + 1) */
    return 100.0f * log10f((float)raw_value + 1.0f);
}

static int log_co_concentration(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f PPM\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw_value = 0;
        if (ads1115_read_conversion(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Error reading from ADS1115 ADC\n");
        } else {
            float co_ppm = calculate_co_ppm(raw_value);
            if (log_co_concentration(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO concentration\n");
            } else {
                printf("CO concentration: %.2f PPM\n", co_ppm);
            }
        }

        /* Sleep in 100ms increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

