#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define MCP3008_CHANNEL 0
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_SEC 1

/* Global variables for signal handler */
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

/* Function prototypes */
static int read_flame_sensor(void);
static float convert_adc_to_temperature(int adc_value);
static int log_data(int flame_detected, float temperature);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Reads the flame sensor via the KY-026 digital output (D0).
 * Returns 1 if flame is detected (D0 = 1), 0 if no flame (D0 = 0),
 * or -1 on SPI transfer error.
 */
static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor GPIO %d: %d\n",
                FLAME_SENSOR_GPIO, value);
        return -1;
    }
    return value;
}

/*
 * Converts the 10-bit ADC value (0-1023) to a temperature in degrees Celsius.
 * The KY-026 analog output is linearly proportional to temperature.
 * Returns the temperature in degrees Celsius, or -100.0 on error.
 */
static float convert_adc_to_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -100.0;
    }
    /* Linear approximation: 10.0°C for 0 ADC, 40.0°C for 1023 ADC */
    return 10.0f + ((float)adc_value / 1023.0f) * 30.0f;
}

/*
 * Logs the flame detection and temperature data to a CSV file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(int flame_detected, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure flame sensor GPIO as input */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI channel (mode 0, active-low CS on CE0) */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, skipping log entry.\n");
        } else {
            float temperature = convert_adc_to_temperature(flame_detected);
            if (temperature < -90.0f) {
                fprintf(stderr, "Error converting ADC to temperature, skipping log entry.\n");
            } else {
                if (log_data(flame_detected, temperature) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            }
        }

        /* Sleep for 1 second, checking running flag every 100 ms for responsiveness */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

