#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CO_THRESHOLD_PPM 25.0

#define REG_CO_DATA_L 0x00
#define REG_RED_DATA_L 0x02
#define REG_CONFIG_L 0x04

#define CONFIG_CO_RES_16BIT 0x01
#define CONFIG_RED_RES_16BIT 0x02
#define CONFIG_MEAS_RATE_1HZ 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *co_data, uint16_t *red_data) {
    char buf[4];
    int ret;

    ret = i2cReadI2CBlockData(handle, REG_CO_DATA_L, buf, 4);
    if (ret != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", ret);
        return -1;
    }

    *co_data = (uint16_t)((buf[1] << 8) | buf[0]);
    *red_data = (uint16_t)((buf[3] << 8) | buf[2]);
    return 0;
}

static float calculate_co_ppm(uint16_t co_data) {
    return (float)co_data / 1000.0f;
}

static void log_data(float co_ppm, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
    fclose(fp);
}

static void log_alert(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening alert log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Alert: CO level exceeded threshold!\n", timestamp);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t co_data, red_data;
    float co_ppm;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor: 16-bit resolution, 1 Hz measurement rate
    char config[2];
    config[0] = REG_CONFIG_L;
    config[1] = CONFIG_CO_RES_16BIT | CONFIG_RED_RES_16BIT | CONFIG_MEAS_RATE_1HZ;
    if (i2cWriteI2CBlockData(i2c_handle, config[0], &config[1], 1) != 0) {
        fprintf(stderr, "Error writing configuration\n");
        cleanup();
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sensor_data(i2c_handle, &co_data, &red_data) == 0) {
            co_ppm = calculate_co_ppm(co_data);
            printf("CO: %.2f PPM\n", co_ppm);

            if (co_ppm > CO_THRESHOLD_PPM) {
                log_alert(LOG_FILE);
            }

            log_data(co_ppm, LOG_FILE);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

