#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define SAMPLE_COUNT 100
#define REFERENCE_PRESSURE 20.0e-6
#define SENSITIVITY -38.0
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mic(int handle, float *pressure_out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read error on handle %d: %d\n", handle, bytes);
        return ERROR_VALUE;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *pressure_out = (float)raw * SENSITIVITY - 32.768;
    return *pressure_out;
}

static float calculate_average(float *buffer, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

static void log_data(float avg_pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1 (0x%02X): %d\n", MIC1_ADDR, handle1);
        gpioTerminate();
        return 1;
    }

    int handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2 (0x%02X): %d\n", MIC2_ADDR, handle2);
        i2cClose(handle1);
        gpioTerminate();
        return 1;
    }

    float buffer1[SAMPLE_COUNT];
    float buffer2[SAMPLE_COUNT];
    int idx1 = 0, idx2 = 0;
    int error1 = 0, error2 = 0;

    while (running) {
        float p1 = read_mic(handle1, &buffer1[idx1]);
        float p2 = read_mic(handle2, &buffer2[idx2]);

        if (p1 == ERROR_VALUE) error1 = 1;
        if (p2 == ERROR_VALUE) error2 = 1;

        if (error1 || error2) {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        } else {
            buffer1[idx1] = 0.0;
            buffer2[idx2] = 0.0;
            idx1 = (idx1 + 1) % SAMPLE_COUNT;
            idx2 = (idx2 + 1) % SAMPLE_COUNT;

            if (idx1 == 0 && idx2 == 0) {
                float avg = calculate_average(buffer1, SAMPLE_COUNT);
                log_data(avg);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

