#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define VREF 5.0
#define ADC_MAX_COUNT 32767.0
#define ADC_PGA 4.096
#define ADC_MAX_CURRENT 3.33
#define SENSOR_MIN_CURRENT 0.0
#define SENSOR_MAX_CURRENT 100.0

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *buffer, float value);
float get_average_current(CircularBuffer *buffer);
void check_overcurrent(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit value from ADS1115 channel A0
int read_ads1115(int16_t *raw_value) {
    // Write configuration: single-shot, A0 single-ended, PGA=4.096V, 128 SPS, continuous mode
    // Config register: 0xC183 (0xC1 = start single conversion, bit7=1 for continuous, bits6-4=100 for A0, bits3-0=0011 for 128SPS)
    char config[3];
    config[0] = 0xC1;
    config[1] = 0x83;
    config[2] = 0x00;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (128 SPS = ~7.8ms, wait 10ms for safety)
    time_sleep(0.01);

    // Read conversion register (0x00)
    char reg = 0x00;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *raw_value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

// Convert raw ADC value to current (ratiometric, 0.5V to 4.5V for 0-100A)
float convert_to_current(int16_t raw_value) {
    float voltage = (float)raw_value * ADC_PGA / ADC_MAX_COUNT;
    float current = (voltage - SENSOR_MIN_CURRENT) / (SENSOR_MAX_CURRENT - SENSOR_MIN_CURRENT) * VREF;
    return current;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get average current from circular buffer
float get_average_current(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Check for overcurrent condition
void check_overcurrent(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        printf("Overcurrent detected! Average current: %.2fA\n", average_current);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    current_buffer.head = 0;
    current_buffer.count = 0;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    float current_value;
    time_t start_time, end_time;
    double elapsed_time;
    int16_t raw_value;

    while (program_running) {
        // Read sensor value
        if (read_ads1115(&raw_value) != 0) {
            fprintf(stderr, "Error reading sensor value, retrying...\n");
            time_sleep(0.1);
            continue;
        }

        // Convert to current
        current_value = convert_to_current(raw_value);

        // Add to buffer
        add_to_buffer(&current_buffer, current_value);

        // Get average current
        float average_current = get_average_current(&current_buffer);

        // Check for overcurrent
        check_overcurrent(average_current);

        // Calculate elapsed time for timing
        time(&start_time);
        // Wait for next sample (10Hz)
        time(&end_time);
        elapsed_time = difftime(end_time, start_time);
        if (elapsed_time < 0.1) {
            time_sleep(0.1 - elapsed_time);
        }
    }

    // Cleanup
    cleanup();
    return 0;
}

