#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDR        0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE      0x00
#define TCS34725_ATIME       0x01
#define TCS34725_ID          0x12
#define TCS34725_CONTROL     0x0F
#define TCS34725_CDATA       0x14
#define TCS34725_RDATA       0x16
#define TCS34725_GDATA       0x18
#define TCS34725_BDATA       0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

#define I2C_BUS              1
#define LOG_FILE             "color_log.csv"
#define MAX_CONSECUTIVE_ERRORS 3
#define SAMPLE_INTERVAL_US   1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)(TCS34725_COMMAND_BIT | reg), (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char cmd = (char)(TCS34725_COMMAND_BIT | reg);
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    char cmd = (char)(TCS34725_COMMAND_BIT | reg);
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        return -1;
    }
    return 0;
}

static int tcs34725_init(int handle) {
    uint8_t id = 0;
    if (i2c_read_reg(handle, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error: cannot read ID register\n");
        return -1;
    }
    if ((id & 0xF0) != 0x44) {
        fprintf(stderr, "Error: invalid sensor ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    if (i2c_write_reg(handle, TCS34725_ATIME, 0xFF) != 0) {
        fprintf(stderr, "Error: failed to set integration time\n");
        return -1;
    }
    if (i2c_write_reg(handle, TCS34725_CONTROL, 0x01) != 0) {
        fprintf(stderr, "Error: failed to set gain\n");
        return -1;
    }

    if (i2c_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) {
        fprintf(stderr, "Error: failed to power on sensor\n");
        return -1;
    }
    gpioDelay(3000);
    return 0;
}

static int tcs34725_read_color(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    if (i2c_read_block(handle, TCS34725_CDATA, buf, 8) != 0) {
        fprintf(stderr, "Warning: failed to read color data block\n");
        return -1;
    }
    *clear = (uint16_t)((buf[1] << 8) | buf[0]);
    *red   = (uint16_t)((buf[3] << 8) | buf[2]);
    *green = (uint16_t)((buf[5] << 8) | buf[4]);
    *blue  = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

static int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

