#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define SPI_RETRIES 3
#define SPI_RETRY_DELAY_US 10000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *shutdown_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!shutdown_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(shutdown_line, "motor_shutdown", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        shutdown_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n", attempt + 1, SPI_RETRIES, strerror(errno));
        usleep(SPI_RETRY_DELAY_US);
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", SPI_RETRIES);
    return -1;
}

