    const float voltage_range = 3.3f;
    const float voltage_offset = 0.05f;
    const float voltage_sensitivity = 0.1f;
    const float current_sensitivity = 1.0f / voltage_sensitivity;

    float voltage = (float)adc_value * voltage_range / 1023.0f;
    float current = (voltage - voltage_offset) * current_sensitivity;

    if (current < 0.0f) current = 0.0f;
    if (current > 10.0f) current = 10.0f;

    return current;
}

static int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

