    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1);
        gpiod_line_release(shutdown_line);
        shutdown_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

