        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Current_Amperes\n");
        fflush(log_file);
    }

    printf("Monitoring current... Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Current: %.2f A\n", current);
            if (gpiod_line_set_value(shutdown_line, 0) < 0) {
                fprintf(stderr, "Failed to disable motor: %s\n", strerror(errno));
            }
            log_current(current);
            usleep(1000000);
            if (gpiod_line_set_value(shutdown_line, 1) < 0) {
                fprintf(stderr, "Failed to re-enable motor: %s\n", strerror(errno));
            }
            log_current(current);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

