#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define MAX_READ_ERR   5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp   = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio code %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(int16_t *raw_out)
{
    int rc = i2cReadWordData(g_i2c_handle, PRESSURE_REG);
    if (rc < 0) {
        fprintf(stderr, "Error reading pressure register 0x%02X: pigpio code %d\n",
                PRESSURE_REG, rc);
        return -1;
    }
    *raw_out = (int16_t)rc;
    return 0;
}

static float convert_to_kPa(int16_t raw)
{
    return ((float)raw / 65535.0f) * 500.0f;
}

static int log_data(float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time\n");
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "Error converting time to UTC\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only once */
    if (fseek(g_log_fp, 0, SEEK_END) != 0) {
        perror("fseek");
        cleanup();
        return EXIT_FAILURE;
    }
    long fsize = ftell(g_log_fp);
    if (fsize < 0) {
        perror("ftell");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fsize == 0) {
        if (fprintf(g_log_fp, "timestamp,pressure_kPa\n") < 0) {
            perror("Error writing header");
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            perror("Error flushing header");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (read_pressure(&raw) == 0) {
            consecutive_errors = 0;
            float pressure = convert_to_kPa(raw);
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_READ_ERR) {
                fprintf(stderr, "Too many consecutive I2C read failures; aborting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

