        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only once */
    if (fseek(g_log_fp, 0, SEEK_END) != 0) {
        perror("fseek");
        cleanup();
        return EXIT_FAILURE;
    }
    long fsize = ftell(g_log_fp);
    if (fsize < 0) {
        perror("ftell");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fsize == 0) {
        if (fprintf(g_log_fp, "timestamp,pressure_kPa\n") < 0) {
            perror("Error writing header");
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            perror("Error flushing header");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (read_pressure(&raw) == 0) {
            consecutive_errors = 0;
            float pressure = convert_to_kPa(raw);
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_READ_ERR) {
                fprintf(stderr, "Too many consecutive I2C read failures; aborting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

