#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          1
#define ADS1115_ADDR     0x48
#define LED_GPIO         17
#define PRESSURE_THRESHOLD 105.0f
#define SAMPLE_PERIOD_US 1000000  /* 1 second */
#define MAX_RETRIES      3

/* ---- ADS1115 Registers ---- */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* ---- ADS1115 Config bits ---- */
#define ADS1115_CFG_OS_BEGIN   (1u << 15)
#define ADS1115_CFG_MUX_AIN0   (0x4000u)  /* AIN0 vs GND */
#define ADS1115_CFG_MUX_AIN1   (0x5000u)  /* AIN1 vs GND */
#define ADS1115_CFG_PGA_2_3    (0x0100u)  /* FSR = ±6.144 V */
#define ADS1115_CFG_MODE_SINGLE (0x0100u) /* Single-shot */
#define ADS1115_CFG_DR_128SPS  (0x0080u)  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE  (0x0003u)  /* Disable comparator */
#define ADS1115_CFG_DEFAULT   (ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                              ADS1115_CFG_PGA_2_3 | ADS1115_CFG_MODE_SINGLE |
                              ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE)

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Prototypes ---- */
static int  ads1115_init(void);
static int  ads1115_read_single_ended(int16_t *out_raw);
static float adc_to_pressure(int16_t raw);
static float adc_to_temperature(int16_t raw);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- ADS1115 init ---- */
static int ads1115_init(void)
{
    uint16_t config = ADS1115_CFG_DEFAULT;

    /*
     * Config word: [15:12] OS, [11:10] MUX, [9:8] PGA, [7:5] MODE,
     * [4:3] DR, [2:0] CQUE
     */
    config |= ADS1115_CFG_OS_BEGIN;
    config |= ADS1115_CFG_MUX_AIN0;
    config |= ADS1115_CFG_PGA_2_3;
    config |= ADS1115_CFG_MODE_SINGLE;
    config |= ADS1115_CFG_DR_128SPS;
    config |= ADS1115_CFG_CQUE_NONE;

    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (char)(config >> 8);
    cfg[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, cfg, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }
    return 0;
}

/* ---- Read single-ended channel 0 ---- */
static int ads1115_read_single_ended(int16_t *out_raw)
{
    char reg = ADS1115_REG_CONVERSION;
    char buf[2];

    /* Point to conversion register */
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion pointer\n");
        return -1;
    }

    /* Read 2 bytes of conversion result */
    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion data\n");
        return -1;
    }

    *out_raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                          (uint16_t)(uint8_t)buf[1]);
    return 0;
}

/* ---- Linear transfer functions ---- */
static float adc_to_pressure(int16_t raw)
{
    const float v_min = 0.0f;
    const float v_max = 6.144f;
    const float p_min = 0.0f;
    const float p_max = 400.0f;
    return p_min + (raw * (p_max - p_min)) / (v_max - v_min);
}

static float adc_to_temperature(int16_t raw)
{
    const float v_min = 1.0f;
    const float v_max = 2.0f;
    const float t_min = 0.0f;
    const float t_max = 100.0f;
    return t_min + (raw * (t_max - t_min)) / (v_max - v_min);
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init() < 0) {
        fprintf(stderr, "Error: ADS1115 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Signal handling */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure Sensor Interface (ADS1115 bridge)\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int16_t raw = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_single_ended(&raw) == 0) {
                ok = 1;
                break;
            }
            usleep(10000); /* 10 ms backoff */
        }

        if (!ok) {
            fprintf(stderr, "Error: ADS1115 read failed after %d attempts\n",
                    MAX_RETRIES);
            gpioWrite(LED_GPIO, 0);
            continue;
        }

        float pressure = adc_to_pressure(raw);
        float temperature = adc_to_temperature(raw);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n",
               pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    gpioWrite(LED_GPIO, 0);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

