static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int  read_mcp3008(int channel);
static double adc_to_voltage(int adc_value);
static double voltage_to_current(double voltage);
static void log_current(double current);
static void shutdown_motor(void);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                         (start bit)
     *   Byte 1: (0x08 | channel) << 4        (single-ended + channel)
     *   Byte 2: 0x00                         (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* Convert ADC count to voltage (0-3.3V full-scale) */
static double adc_to_voltage(int adc_value)
{
    return ((double)adc_value / (double)ADC_MAX) * VREF;
}

/* Convert voltage to current (sensitivity 66 mV/A) */
static double voltage_to_current(double voltage)
{
    return (voltage - 0.5 * VREF) / SENSITIVITY;
}

/* Log current reading with timestamp */
static void log_current(double current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "%s, %.4f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* Assert shutdown pin HIGH to trigger motor shutdown */
static void shutdown_motor(void)
{
    if (gpioWrite(SHUTDOWN_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set shutdown pin HIGH\n");
    }
    fprintf(log_file, "OVERCURRENT DETECTED! Motor SHUT DOWN.\n");
    fflush(log_file);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Reset shutdown pin to LOW before terminating */
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure shutdown pin as output, initially LOW */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set shutdown pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SHUTDOWN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize shutdown pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI channel: mode 0, active-low CE */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (program_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double current = voltage_to_current(voltage);

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            shutdown_motor();
            break;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

