#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define HUMIDITY_THRESHOLD 80.0
#define EMAIL_RECIPIENT "recipient@example.com"
#define LOG_FILE "humidity_log.txt"

#define MCP3208_VREF 5.0
#define MCP3208_RESOLUTION 4095.0
#define MCP3208_ADC_CHANNEL 0

#define HIH4602_VOUT_MIN 0.824
#define HIH4602_VOUT_MAX 0.976
#define HIH4602_RH_MIN 0.0
#define HIH4602_RH_MAX 100.0

#define BETA 3950.0
#define R0 10000.0
#define T0 298.15

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float calculate_humidity(int adc_value) {
    if (adc_value < 0) return -1.0;
    float vout = (float)adc_value / MCP3208_RESOLUTION * MCP3208_VREF;
    float rh = HIH4602_RH_MIN + (vout - HIH4602_VOUT_MIN) * (HIH4602_RH_MAX - HIH4602_RH_MIN) / (HIH4602_VOUT_MAX - HIH4602_VOUT_MIN);
    if (rh < HIH4602_RH_MIN || rh > HIH4602_RH_MAX) return -1.0;
    return rh;
}

float calculate_temperature(int adc_value) {
    if (adc_value < 0) return -1.0;
    float vout = (float)adc_value / MCP3208_RESOLUTION * MCP3208_VREF;
    float rs = (MCP3208_VREF - vout) / vout * R0;
    float t = (BETA / (BETA + 1.0)) * (T0 / 1.0) * (1.0 - pow(rs / R0, 1.0 / BETA));
    return t;
}

int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
    return 0;
}

int send_email_alert(float humidity) {
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening log file for email alert\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fclose(fp);

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file for email alert");
        return -1;
    }

    fprintf(fp, "%s,Humidity: %.2f%%,Temperature: %.2fC\n", timestamp, humidity, temperature);
    fclose(fp);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Humidity: %.2f%%, Temperature: %.2fC\" | ssmtp %s", humidity, temperature, EMAIL_RECIPIENT);
    int ret = system(command);
    if (ret != 0) {
        fprintf(stderr, "Error sending email alert (ret=%d)\n", ret);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting humidity monitoring...\n");

    while (running) {
        int adc_value = read_mcp3208(MCP3208_ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        if (humidity < 0 || temperature < 0) {
            fprintf(stderr, "Error calculating humidity or temperature\n");
            sleep(1);
            continue;
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded! Sending email alert.\n");
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(5);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

