#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL 0          /* CE0 (GPIO8) */
#define SPI_SPEED 1000000      /* 1 MHz */
#define SPI_FLAGS 0             /* Mode 0, active-low CS handled by pigpio */
#define ADC_CHANNELS 3         /* MCP3008 channels 0,1,2 */
#define SAMPLE_RATE 100        /* Hz */
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)
#define IMPACT_THRESHOLD 2.0f  /* g */
#define VREF 3.3f              /* Supply voltage */
#define ADC_MAX 1023           /* 10-bit ADC */
#define SENSITIVITY 0.3f       /* 300 mV/g */
#define ZERO_G_MV 1650.0f      /* 1.65V at 0g */
#define LOG_FILE "impact_log.txt"

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read one channel from MCP3008 (0-7) via SPI                           */
/* Returns 0-1023 on success, -1 on SPI error, -2 on invalid channel   */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -2;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range on channel %d: %d\n",
                channel, adc_value);
        return -1;
    }
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC to g force                                              */
/* ------------------------------------------------------------------ */
static float raw_to_g(int adc_value)
{
    float voltage = ((float)adc_value / (float)ADC_MAX) * VREF;
    float g = (voltage - ZERO_G_MV) / SENSITIVITY;
    return g;
}

/* ------------------------------------------------------------------ */
/* Log a data line with timestamp                                         */
/* ------------------------------------------------------------------ */
static void log_data(int x, int y, int z, float g_x, float g_y, float g_z,
                     int impact)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (impact) {
        fprintf(log_file, "%s,%d,%d,%d,%.2f,%.2f,%.2f,IMPACT DETECTED\n",
                ts, x, y, z, g_x, g_y, g_z);
    } else {
        fprintf(log_file, "%s,%d,%d,%d,%.2f,%.2f,%.2f\n",
                ts, x, y, z, g_x, g_y, g_z);
    }
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x,y,z,gx,gy,gz,impact\n");
        fflush(log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 impact detection started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int x = read_mcp3008(0);
        int y = read_mcp3008(1);
        int z = read_mcp3008(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "SPI read error, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gx = raw_to_g(x);
        float gy = raw_to_g(y);
        float gz = raw_to_g(z);

        int impact = (fabsf(gx) > IMPACT_THRESHOLD ||
                      fabsf(gy) > IMPACT_THRESHOLD ||
                      fabsf(gz) > IMPACT_THRESHOLD);

        log_data(x, y, z, gx, gy, gz, impact);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

