/* Si1172-A30-GMR I2C 7-bit default address */
#define SI1172_ADDR 0x49

/* Si1172 register addresses (command register 0xC0, data registers 0xC1-0xC4) */
#define SI1172_REG_COMMAND 0xC0
#define SI1172_REG_DATA_IR 0xC1
#define SI1172_REG_DATA_RED 0xC2
#define SI1172_REG_DATA_GREEN 0xC3
#define SI1172_REG_DATA_BLUE 0xC4

/* Si1172 command codes */
#define SI1172_CMD_RESET 0x01
#define SI1172_CMD_START 0x0F

/* Default measurement interval (ms) */
#define DEFAULT_MEAS_INTERVAL 100

/* Default sampling interval (seconds) */
#define DEFAULT_SAMPLE_INTERVAL 1

/* Global variables for graceful shutdown */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int initialize_i2c(void);
static int read_si1172_data(int16_t *ir_sample, int16_t *red_sample);
static int log_data(time_t timestamp, int16_t ir_sample, int16_t red_sample, int error_flag);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Initializes the pigpio library and opens the I2C bus to the Si1172.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SI1172_ADDR, 0); /* Bus 1, address 0x49, no flags */
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s (handle=%d)\n", strerror(errno), i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* Reset the sensor to a known state */
    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting Si1172: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }
    gpioDelay(10000); /* 10 ms reset delay */

    return 0;
}

/*
 * Reads raw PPG data from the Si1172.
 * The Si1172 requires a proprietary algorithm to convert raw ADC values
 * to HR and SpO2. This function reads the IR, RED, GREEN, and BLUE
 * 16-bit ADC values from the FIFO registers (0xC1-0xC4) as a proxy.
 * Returns 0 on success, -1 on failure.
 */
static int read_si1172_data(int16_t *ir_sample, int16_t *red_sample) {
    int16_t ir_raw, red_raw;

    /* Read IR sample (0xC1) */
    ir_raw = i2cReadWordData(i2c_handle, SI1172_REG_DATA_IR);
    if (ir_raw < 0) {
        fprintf(stderr, "Error reading IR data: %s\n", strerror(errno));
        return -1;
    }
    *ir_sample = (int16_t)ir_raw;

    /* Read RED sample (0xC2) */
    red_raw = i2cReadWordData(i2c_handle, SI1172_REG_DATA_RED);
    if (red_raw < 0) {
        fprintf(stderr, "Error reading RED data: %s\n", strerror(errno));
        return -1;
    }
    *red_sample = (int16_t)red_raw;

    return 0;
}

