 * Returns 0 on success, -1 on failure.
 */
static int log_data(time_t timestamp, int16_t ir_sample, int16_t red_sample, int error_flag) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (error_flag == 0) {
        fprintf(log_file, "%ld,%d,%d\n", (long)timestamp, ir_sample, red_sample);
    } else {
        fprintf(log_file, "%ld,ERROR,%d,%d\n", (long)timestamp, ir_sample, red_sample);
    }

    fflush(log_file);
    return 0;
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/*
 * Cleans up resources before exiting.
 */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int16_t ir_sample, red_sample;
    time_t current_time;
    int error_flag;

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    /* Open the log file in append mode */
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Write the header row if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%),Error Flag\n");
        fflush(log_file);
    }

    /* Main loop */
    while (!terminate) {
        /* Trigger a measurement */
        if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_START) < 0) {
            fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
            error_flag = 1;
        } else {
            /* Wait for the measurement to complete */
            gpioDelay(DEFAULT_MEAS_INTERVAL * 1000); /* 100 ms */

            /* Read the PPG data */
            if (read_si1172_data(&ir_sample, &red_sample) == 0) {
                /* Get the current timestamp */
                current_time = time(NULL);

                /* Log the data */
                error_flag = log_data(current_time, ir_sample, red_sample, error_flag);
            } else {
                error_flag = 1; /* Treat read failure as an error */
            }
        }

        /* Wait for the next sample interval */
        gpioDelay(DEFAULT_SAMPLE_INTERVAL * 1000000); /* 1 second */
    }

    /* Graceful shutdown */
    cleanup();
    return 0;
}

