#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNELS 2
#define NUM_SAMPLES 1000
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel, int *value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    int ret = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

int main(int argc, char *argv[]) {
    int gain = 1;
    int opt;

    while ((opt = getopt(argc, argv, "g:h")) != -1) {
        switch (opt) {
            case 'g':
                gain = atoi(optarg);
                if (gain <= 0) {
                    fprintf(stderr, "Gain must be positive\n");
                    return 1;
                }
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-g gain]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Noise Cancellation Audio Sampler\n");
    printf("Sampling %d channels at %d Hz, gain: %d\n", ADC_CHANNELS, 1000000 / (2 * ADC_CHANNELS), gain);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int *mic1 = malloc(sizeof(int) * ADC_CHANNELS);
        int *mic2 = malloc(sizeof(int) * ADC_CHANNELS);
        if (!mic1 || !mic2) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        for (int i = 0; i < ADC_CHANNELS; i++) {
            if (read_adc(i, &mic1[i]) != 0) {
                free(mic1);
                free(mic2);
                spiClose(spi_handle);
                gpioTerminate();
                return 1;
            }
            if (read_adc(i, &mic2[i]) != 0) {
                free(mic1);
                free(mic2);
                spiClose(spi_handle);
                gpioTerminate();
                return 1;
            }
        }

        free(mic1);
        free(mic2);

        int diff[ADC_CHANNELS];
        for (int i = 0; i < ADC_CHANNELS; i++) {
            diff[i] = mic1[i] - mic2[i];
        }

        for (int i = 0; i < ADC_CHANNELS; i++) {
            printf("%d,%d\n", diff[i], gain * diff[i]);
        }
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

