#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define LED_GPIO    17
#define WATER_HIGH  75.0f
#define WATER_LOW   70.0f
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_US 5000000
#define JSON_FILE "water_levels.json"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_spi(void) {
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel, int *out_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3];
    unsigned char rx[3];

    tx[0] = 0x01;
    tx[1] = (unsigned char)(0x80 | (channel << 4));
    tx[2] = 0x00;

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(ret));
        return -1;
    }
    if (ret != 3) {
        fprintf(stderr, "SPI transfer short read: %d bytes\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    *out_value = adc_value;
    return 0;
}

static float adc_to_percentage(int adc_value) {
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static int log_to_json(float water_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(g_json_fp, "[{\"timestamp\":\"%s\",\"water_level\":%.2f}]",
                timestamp, water_level) < 0) {
        fprintf(stderr, "Error writing to JSON file\n");
        return -1;
    }
    fflush(g_json_fp);
    return 0;
}

static void cleanup(void) {
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_json_fp != NULL) {
        fclose(g_json_fp);
        g_json_fp = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_json_fp = fopen(JSON_FILE, "w");
    if (g_json_fp == NULL) {
        perror("Error opening JSON file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(g_json_fp, "[{\"timestamp\":\"\",\"water_level\":0.0}"]\n",
                JSON_FILE, "water_levels.json") < 0) {
        fprintf(stderr, "Error writing JSON header\n");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(g_json_fp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            gpioDelay(100000);
            continue;
        }

        float water_level = adc_to_percentage(adc_value);

        if (log_to_json(water_level) != 0) {
            fprintf(stderr, "Warning: failed to log water level\n");
        }

        if (water_level > WATER_HIGH) {
            gpioWrite(LED_GPIO, 1);
        } else if (water_level < WATER_LOW) {
            gpioWrite(LED_GPIO, 0);
        }

        printf("Water level: %.2f%% (ADC: %d)\n", water_level, adc_value);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

