#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"

static int spi_channel = DEFAULT_SPI_CHANNEL;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static int min_raw = DEFAULT_MIN_RAW;
static int max_raw = DEFAULT_MAX_RAW;
static int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
static int logging_interval = DEFAULT_LOGGING_INTERVAL;
static char recipient_email[256] = DEFAULT_RECIPIENT_EMAIL;
static char msmtp_config_path[256] = DEFAULT_MSMTP_CONFIG;

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture_percentage(int raw_value) {
    if (raw_value < 0) return -1.0f;
    float percentage = 100.0f - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0f;
    if (percentage < 0.0f) percentage = 0.0f;
    if (percentage > 100.0f) percentage = 100.0f;
    return percentage;
}

static int log_data(float moisture_percentage) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open plant_data.txt for appending\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

static int send_email_alert(float moisture_percentage) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "echo \"Subject: Plant Moisture Alert\n\nPlant moisture is below threshold.\nMoisture level: %.2f%%\" | msmtp -t -a default %s",
        moisture_percentage, recipient_email);

    FILE *fp = popen(command, "r");
    if (!fp) {
        fprintf(stderr, "Error: popen failed for email alert\n");
        return -1;
    }

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fp)) {
        printf("Email body: %s", buffer);
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed\n");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

static int setup_spi(void) {
    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", spi_handle);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:t:i:r:p:h")) != -1) {
        switch (opt) {
            case 'c': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_raw = atoi(optarg); break;
            case 't': max_raw = atoi(optarg); break;
            case 'i': moisture_threshold = atoi(optarg); break;
            case 'r': logging_interval = atoi(optarg); break;
            case 'p': recipient_email = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_raw] [-t max_raw] [-i moisture_threshold] [-r logging_interval] [-p recipient_email] [-h]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (setup_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Logging every %d seconds. Press Ctrl+C to exit.\n", logging_interval);

    while (!terminate) {
        int raw_value = read_mcp3008(adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", logging_interval);
            sleep(logging_interval);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(raw_value);
        if (moisture_percentage < 0.0f) {
            fprintf(stderr, "Error: Invalid raw value %d, retrying in %d seconds...\n", raw_value, logging_interval);
            sleep(logging_interval);
            continue;
        }

        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        if (moisture_percentage < moisture_threshold) {
            printf("Moisture below threshold (%.2f%% < %.2f%%). Sending email alert...\n", moisture_percentage, moisture_threshold);
            if (send_email_alert(moisture_percentage) != 0) {
                fprintf(stderr, "Warning: Email alert failed\n");
            }
        }

        sleep(logging_interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

