#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 channel 0
#define ADC_MAX_VALUE 1023  // 10-bit ADC
#define VREF 3.3            // Reference voltage (V)
#define MIN_PRESSURE 0.5    // Minimum pressure (V)
#define MAX_PRESSURE 4.5    // Maximum pressure (V)
#define MIN_VOLTAGE 0.0     // Minimum valid voltage
#define MAX_VOLTAGE 4.0     // Maximum valid voltage
#define SAMPLE_INTERVAL 1   // Seconds

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio(void);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Initialize pigpio and SPI
int initialize_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read MCP3008 ADC value via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buffer[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value / (float)ADC_MAX_VALUE * VREF;
}

// Convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    // Linear mapping: 0.5V -> 0.5kPa, 4.5V -> 150kPa
    return MIN_PRESSURE + (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE);
}

// Log pressure reading with timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
}

// Cleanup resources
void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("Sampling every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break;
        }

        float voltage = adc_to_voltage(adc_value);

        // Sensor-absent detection: voltage stuck at 0V or 3.3V
        if (voltage == MIN_VOLTAGE || voltage == MAX_VOLTAGE) {
            fprintf(stderr, "Warning: Sensor absent or wiring fault. Voltage at %.3fV\n", voltage);
        } else {
            float pressure = voltage_to_pressure(voltage);
            log_pressure(pressure);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

