#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL    0          /* CE0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define PUMP_GPIO      17         /* Relay control pin */
#define MOISTURE_LOW   300        /* ADC threshold (wet) */
#define MOISTURE_HIGH  600        /* ADC threshold (dry) */
#define SAMPLE_INTERVAL 5         /* Seconds */
#define BUFFER_SIZE    20

/* MCP3008 single-ended channel 0 */
#define MCP3008_CHANNEL 0

/* Globals for cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer */
typedef struct {
    time_t timestamp;
    int    moisture;
    int    pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 (single-ended)                       */
/* Returns 0-1023 on success, -1 on SPI error.                         */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     *   Byte 2: 0x00  (don't care, clocked out to read data)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Log entry to circular buffer                                        */
/* ------------------------------------------------------------------ */
static void log_entry(int moisture, int pump_state)
{
    log_buffer[buffer_index].timestamp  = time(NULL);
    log_buffer[buffer_index].moisture  = moisture;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* ------------------------------------------------------------------ */
/* Print full log buffer                                               */
/* ------------------------------------------------------------------ */
static void print_log_buffer(void)
{
    printf("\n--- Log Buffer (%d entries) ---\n", BUFFER_SIZE);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        time_t t = log_buffer[idx].timestamp;
        if (localtime_r(&t, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            strncpy(ts, "----", sizeof(ts) - 1);
            ts[sizeof(ts) - 1] = '\0';
        }
        printf("[%s] Moisture: %4d  Pump: %s\n",
               ts, log_buffer[idx].moisture,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("-----------------------------------------------\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started.  SPI ch%d @ %d Hz, pump GPIO %d.\n",
           SPI_CHANNEL, SPI_SPEED, PUMP_GPIO);
    printf("Thresholds: wet < %d, dry > %d  (hysteresis off).  Ctrl+C to exit.\n",
           MOISTURE_LOW, MOISTURE_HIGH);

    /* Timer: sample every SAMPLE_INTERVAL seconds */
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL, sample_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer 0\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main loop: wait for signal */
    while (!terminate) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    print_log_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Timer callback (runs in pigpio thread)                              */
/* ------------------------------------------------------------------ */
static void sample_callback(void *user_data)
{
    (void)user_data;

    int moisture = read_mcp3008(MCP3008_CHANNEL);
    if (moisture < 0) {
        fprintf(stderr, "ADC read error — skipping sample\n");
        return;
    }

    int pump_state = 0;

    if (moisture < MOISTURE_LOW) {
        if (!pump_state) {
            if (gpioWrite(PUMP_GPIO, 1) == 0) {
                pump_state = 1;
                printf("Moisture %4d  ->  Pump ON\n", moisture);
            } else {
                fprintf(stderr, "Failed to activate pump\n");
            }
        }
    } else if (moisture > MOISTURE_HIGH) {
        if (pump_state) {
            if (gpioWrite(PUMP_GPIO, 0) == 0) {
                pump_state = 0;
                printf("Moisture %4d  ->  Pump OFF\n", moisture);
            } else {
                fprintf(stderr, "Failed to deactivate pump\n");
            }
        }
    }

    log_entry(moisture, pump_state);
}

