#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "health_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) return -1;
    return 0;
}

static int max30102_init(int handle) {
    uint8_t part_id;
    if (i2c_read_reg(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present.\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("MAX30102 detected (Part ID: 0x%02X).\n", part_id);

    if (i2c_write_reg(handle, REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset MAX30102.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(handle, REG_MODE_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to set SpO2 mode.\n");
        return -1;
    }

    if (i2c_write_reg(handle, REG_SPO2_CONFIG, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to set SPO2 config.\n");
        return -1;
    }

    if (i2c_write_reg(handle, REG_LED1_PA, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to set LED1 PA.\n");
        return -1;
    }
    if (i2c_write_reg(handle, REG_LED2_PA, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to set LED2 PA.\n");
        return -1;
    }

    return 0;
}

static int max30102_read_fifo(int handle, uint16_t *red, uint16_t *ir) {
    uint8_t buf[6];
    int rc = i2cReadI2CBlockData(handle, REG_FIFO_DATA, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: Failed to read FIFO data (rc=%d).\n", rc);
        return -1;
    }
    *red = ((uint16_t)buf[0] << 8) | buf[1];
    *ir  = ((uint16_t)buf[2] << 8) | buf[3];
    return 0;
}

static float calculate_spo2(uint16_t red, uint16_t ir) {
    if (ir == 0) return 0.0f;
    float ratio = (float)red / (float)ir;
    float spo2 = 11.0f - 12.0f * ratio - 2.0f * ratio * ratio;
    if (spo2 < 0.0f) spo2 = 0.0f;
    if (spo2 > 100.0f) spo2 = 100.0f;
    return spo2;
}

static int detect_heart_rate(uint16_t *ir_buf, int buf_size, int *hr) {
    int max_count = 0;
    int peak_idx = -1;
    for (int i = 1; i < buf_size - 1; i++) {
        int count = 0;
        for (int j = 0; j < i; j++) {
            if (ir_buf[j] > ir_buf[i]) {
                count++;
            }
        }
        if (count > max_count) {
            max_count = count;
            peak_idx = i;
        }
    }
    if (peak_idx == -1) return -1;
    int hr_val = (peak_idx - 1) * 10;
    if (hr_val < 0) hr_val = 0;
    if (hr_val > 100) hr_val = 100;
    *hr = hr_val;
    return 0;
}

static void log_data(float spo2, int hr) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(fp, "%s, SpO2: %.2f%%, Heart Rate: %d BPM\n", ts, spo2, hr);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d addr 0x%02X (rc=%d).\n", I2C_BUS, MAX30102_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (max30102_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t red, ir;
    uint16_t ir_buf[100];
    int buf_size = 0;
    int hr = 0;

    while (running) {
        if (max30102_read_fifo(i2c_handle, &red, &ir) == 0) {
            float spo2 = calculate_spo2(red, ir);
            if (detect_heart_rate(ir_buf, buf_size, &hr) == 0) {
                log_data(spo2, hr);
            }
            buf_size = 0;
        } else {
            buf_size = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

