#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_BASE    0x8000
#define ADS1115_CONFIG_PGA_4V  0x0200
#define ADS1115_CONFIG_MODE_SS 0x0000
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_CQUE_1 0x0001
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_A0  0x4000
#define ADS1115_CONFIG_PGA_4V  0x0200
#define ADS1115_CONFIG_MODE_SS 0x0000
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_CQUE_1 0x0001
#define ADS1115_CONFIG_OS_BEGIN 0x8000

#define RELAY_GPIO 17
#define REED_SENSOR_GPIO 27
#define LOG_FILE "/var/log/door_events.log"
#define NUM_BASELINE_SAMPLES 10
#define POLL_INTERVAL_MS 200
#define RELAY_ON_MS 3000
#define RELAY_OFF_MS 2000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_adc(int fd, int16_t *out) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_PGA_4V |
                      ADS1115_CONFIG_MODE_SS | ADS1115_CONFIG_DR_128 |
                      ADS1115_CONFIG_CQUE_1;
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) return -1;
    usleep(10000);
    uint16_t cfg;
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg16(fd, ADS1115_REG_CONFIG, &cfg) < 0) return -1;
        if (cfg & 0x8000) break;
        usleep(5000);
    }
    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) < 0) return -1;
    *out = (int16_t)raw;
    return 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, event);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); return 1; }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_GPIO);
    struct gpiod_line *reed = gpiod_chip_get_line(chip, REED_SENSOR_GPIO);
    if (!relay || !reed) { perror("gpiod_get_line"); gpiod_chip_close(chip); return 1; }
    if (gpiod_line_request_output(relay, "door_relay", 0) < 0 ||
        gpiod_line_request_input(reed, "door_reed") < 0) {
        perror("gpiod_request"); gpiod_chip_close(chip); return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); gpiod_chip_close(chip); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); close(i2c_fd); gpiod_chip_close(chip); return 1;
    }

    int16_t baseline[NUM_BASELINE_SAMPLES];
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        if (read_adc(i2c_fd, &baseline[i]) < 0) {
            fprintf(stderr, "Baseline read failed at sample %d: %s\n", i, strerror(errno));
            close(i2c_fd); gpiod_chip_close(chip); return 1;
        }
        usleep(50000);
    }
    int avg = 0;
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) avg += baseline[i];
    avg /= NUM_BASELINE_SAMPLES;
    int threshold = avg * 0.8;
    printf("Threshold: %d\n", threshold);

    while (running) {
        int16_t raw;
        if (read_adc(i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read failed: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }
        if (raw < threshold) {
            gpiod_line_set_value(relay, 1);
            usleep(RELAY_ON_MS * 1000);
            gpiod_line_set_value(relay, 0);
            usleep(RELAY_OFF_MS * 1000);
            int reed = gpiod_line_get_value(reed);
            if (reed < 0) {
                fprintf(stderr, "Reed sensor read failed: %s\n", strerror(errno));
            } else {
                if (reed == 0) log_event("door opened");
                else log_event("door not opened");
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_line_release(reed);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

