#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int pump_state = 0;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc < 0 || adc > 1023) {
                fprintf(stderr, "ADC value out of range: %d\n", adc);
                return -1;
            }
            return adc;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static float calculate_moisture(int adc) {
    if (adc < 0) return 0.0f;
    if (adc > 1023) adc = 1023;
    float pct = 100.0f - ((float)(adc - 800) / (float)(200 - 800) * 100.0f);
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static void control_pump(int state) {
    if (state != pump_state) {
        if (gpioWrite(PUMP_GPIO, state) != 0) {
            fprintf(stderr, "Failed to write pump GPIO\n");
            return;
        }
        pump_state = state;
        log_event(state ? "Pump ON" : "Pump OFF");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:h")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (threshold < 0 || threshold > 100 || duration <= 0 || sleep_interval <= 0) {
        fprintf(stderr, "Invalid parameters. Using defaults.\n");
        threshold = DEFAULT_THRESHOLD;
        duration = DEFAULT_DURATION;
        sleep_interval = DEFAULT_SLEEP_INTERVAL;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        cleanup();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Irrigation system started");

    while (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            log_event("SPI read error, skipping cycle");
            gpioDelay(sleep_interval * 1000000);
            continue;
        }

        float moisture = calculate_moisture(adc);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture: %.1f%% (ADC: %d)", moisture, adc);
        log_event(msg);

        if (moisture < threshold) {
            log_event("Moisture below threshold, activating pump");
            control_pump(1);
            gpioDelay(duration * 1000000);
            control_pump(0);
            log_event("Pump deactivated");
        }

        gpioDelay(sleep_interval * 1000000);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

