#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL_US 10000
#define EMA_ALPHA 0.2
#define PEAK_THRESHOLD_PERCENT 20

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_ema(double new_value, double *ema, double alpha) {
    return alpha * new_value + (1.0 - alpha) * *ema;
}

static int log_event(double value, double ema) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Value: %.2f, EMA: %.2f\n", timestamp, value, ema) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    int spi_handle = -1;
    double ema = 0.0;
    double peak_detected = 0.0;
    double raw_value;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        raw_value = read_mcp3008(spi_handle, MCP3008_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read MCP3008\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        ema = calculate_ema(raw_value, &ema, EMA_ALPHA);

        if (raw_value > ema * (1.0 + PEAK_THRESHOLD_PERCENT / 100.0)) {
            peak_detected = raw_value;
            if (log_event(raw_value, ema) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

