#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define PCF8591_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *byte) {
    if (read(fd, byte, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * PCF8591 control byte (7-bit):
     *   [7:6]  SGL/DIFF=1 (single-ended)
     *   [5:4]  AIN0..AIN7 (channel 0-7)
     *   [3:2]  reserved
     *   [1:0]  reserved
     *
     * Writing 0x40 selects AIN0 single-ended, analog output disabled.
     */
    if (i2c_write_byte(fd, 0x40) < 0) {
        goto cleanup;
    }

    uint8_t dummy;
    if (i2c_read_byte(fd, &dummy) < 0) {
        goto cleanup;
    }

    while (running) {
        uint8_t sample;
        if (i2c_read_byte(fd, &sample) < 0) {
            goto cleanup;
        }

        printf("AIN0: %u\n", sample);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

