#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_CONV_REG     0x00
#define ADS1115_CONFIG_REG   0x01

#define ADC_CHANNEL_A0      0x4000  /* AIN0 single-ended */
#define ADC_CONFIG_OS       0x8000  /* Begin single conversion */
#define ADC_CONFIG_MUX_A0  0x4000  /* AIN0 vs GND */
#define ADC_CONFIG_PGA_4_024 0x0200 /* PGA = +/-4.096 V */
#define ADC_CONFIG_MODE_SS  0x0100 /* Single-shot */
#define ADC_CONFIG_DR_128   0x0080 /* 128 SPS */
#define ADC_CONFIG_CQUE_1   0x0001 /* Disable comparator */
#define ADC_CONFIG_GROUP_NONE 0x0000 /* Disable group reads */

#define ADC_MAX_COUNT       32767.0f  /* 16-bit signed, 16-bit positive range */
#define ADC_VREF            4.096f    /* PGA full-scale voltage */
#define ADC_ZERO_VCC        3.3f      /* Sensor supply */
#define SS49E_ZERO_V_MV     2500.0f   /* Zero-field output ~2.5 V */
#define SS49E_SENS_MV_VCC   1400.0f   /* Sensitivity: 1.4 mV/Gauss */
#define ADC_VOUT_MV         (ADC_VREF / 1000.0f)
#define ADC_MAX_VOUT_MV     (ADC_MAX_COUNT * ADC_VREF / 65536.0f)
#define BUFFER_SIZE         10
#define MOTOR_SHUTDOWN_PIN  27
#define THRESHOLD_GAUSS     500.0f
#define SAMPLE_PERIOD_US    1000000  /* 1 Hz */

/* ----------------------------- Globals ---------------------------------- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  ads1115_read_channel(int handle, uint16_t channel, int16_t *out);
static float voltage_to_gauss(int16_t raw);
static void add_to_buffer(float *buffer, int *index, float value);
static float buffer_average(float *buffer, int size, int index);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- ADS1115 read ------------------------------ */
/*
 * Read a single-ended channel from the ADS1115.
 * Returns 0 on success (stores raw 16-bit signed value in *out),
 * -1 on I2C error, -2 on invalid conversion (raw < 0 or > 32767).
 */
static int ads1115_read_channel(int handle, uint16_t channel, int16_t *out)
{
    if (channel > 3) {
        syslog(LOG_ERR, "ADS1115: invalid channel %u", channel);
        return -1;
    }

    /*
     * Config: single-shot, AIN0 vs GND, PGA +/-4.096 V, 128 SPS,
     * single-ended, disable comparator, 1 sample, group disable.
     */
    uint16_t config = ADC_CONFIG_OS | (channel & 0x03) | ADC_CONFIG_PGA_4_024 |
                      ADC_CONFIG_MODE_SS | ADC_CONFIG_DR_128 |
                      ADC_CONFIG_CQUE_1 | ADC_CONFIG_GROUP_NONE;

    char cfg[3];
    cfg[0] = ADS1115_CONFIG_REG;
    cfg[1] = (char)(config >> 8);
    cfg[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        syslog(LOG_ERR, "ADS1115: I2C write config failed");
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS, use 10 ms). */
    gpioDelay(10000);

    char reg[1] = { ADS1115_CONV_REG };
    if (i2cWriteDevice(handle, reg, 1) < 0) {
        syslog(LOG_ERR, "ADS1115: I2C write pointer failed");
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        syslog(LOG_ERR, "ADS1115: I2C read conversion failed");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    if (raw < 0 || raw > 32767) {
        syslog(LOG_ERR, "ADS1115: invalid conversion count %d", raw);
        return -2;
    }

    *out = raw;
    return 0;
}

/* ----------------------------- SS49E conversion --------------------------- */
static float voltage_to_gauss(int16_t raw)
{
    float vout_mv = (float)raw * ADC_VOUT_MV;
    float gauss   = (vout_mv - SS49E_ZERO_V_MV) / SS49E_SENS_MV_VCC;
    return gauss;
}

/* ----------------------------- Circular buffer ----------------------------- */
static void add_to_buffer(float *buffer, int *index, float value)
{
    buffer[*index] = value;
    *index = (*index + 1) % BUFFER_SIZE;
}

static float buffer_average(float *buffer, int size, int index)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        int j = (index + i) % size;
        sum += buffer[j];
    }
    return sum / size;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    gpioTerminate();
    closelog();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    openlog("hall_sensor", LOG_PID | LOG_CONS, LOG_USER);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure motor shutdown pin */
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Read calibration table (0x01 config register) */
    char cfg[3];
    cfg[0] = ADS1115_CONFIG_REG;
    cfg[1] = (char)(0x4000);  /* OS bit */
    cfg[2] = 0;
    if (i2cWriteDevice(i2c_handle, cfg, 3) < 0) {
        syslog(LOG_ERR, "Failed to read ADS1115 config register");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    /* Read calibration table */
    char reg[1] = { ADS1115_CONFIG_REG };
    if (i2cWriteDevice(i2c_handle, reg, 1) < 0) {
        syslog(LOG_ERR, "Failed to set config pointer");
        cleanup();
        return EXIT_FAILURE;
    }
    char buf[8];
    if (i2cReadDevice(i2c_handle, buf, 8) != 8) {
        syslog(LOG_ERR, "Failed to read ADS1115 config data");
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t config_raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    uint16_t mux_raw    = ((uint16_t)(buf[2] & 0xFF) << 8) | (uint8_t)buf[3];
    uint16_t pga_raw   = ((uint16_t)(buf[4] & 0xFF) << 8) | (uint8_t)buf[5];
    uint16_t mode_raw  = ((uint16_t)(buf[6] & 0xFF) << 8) | (uint8_t)buf[7];

    if (mux_raw & 0x0001) {
        syslog(LOG_ERR, "ADS1115: invalid mux config 0x%04X", mux_raw);
        cleanup();
        return EXIT_FAILURE;
    }
    if (mode_raw & 0x0001) {
        syslog(LOG_ERR, "ADS1115: invalid mode config 0x%04X", mode_raw);
        cleanup();
        return EXIT_FAILURE;
    }
    if (pga_raw & 0x0001) {
        syslog(LOG_ERR, "ADS1115: invalid PGA config 0x%04X", pga_raw);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start single-shot on AIN0 */
    if (ads1115_read_channel(i2c_handle, ADC_CHANNEL_A0, NULL) < 0) {
        syslog(LOG_ERR, "Failed to start ADS1115 conversion on AIN0");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    float gauss_buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    for (int i = 0; i < BUFFER_SIZE; i++)
        gauss_buffer[i] = 0.0f;

    /* Main sampling loop */
    while (!terminate) {
        int16_t raw = 0;
        int status = ads1115_read_channel(i2c_handle, ADC_CHANNEL_A0, &raw);

        if (status == 0) {
            float gauss = voltage_to_gauss(raw);
            add_to_buffer(gauss_buffer, &buffer_index, gauss);
            float avg = buffer_average(gauss_buffer, BUFFER_SIZE, buffer_index);

            syslog(LOG_INFO, "A0: %.2f Gauß, Avg: %.2f Gauß", gauss, avg);

            if (avg > THRESHOLD_GAUSS) {
                syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauß", avg);
                gpioWrite(MOTOR_SHUTDOWN_PIN, 1);
                syslog(LOG_INFO, "Motor shutdown signal activated");
            }
        } else if (status == -2) {
            syslog(LOG_ERR, "ADC read error, skipping sample");
        } else {
            syslog(LOG_ERR, "ADC read invalid, skipping sample");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

