    for (int i = 0; i < size; i++) {
        int j = (index + i) % size;
        sum += buffer[j];
    }
    return sum / size;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    gpioTerminate();
    closelog();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    openlog("hall_sensor", LOG_PID | LOG_CONS, LOG_USER);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure motor shutdown pin */
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Read calibration table (0x01 config register) */
    char cfg[3];
    cfg[0] = ADS1115_CONFIG_REG;
    cfg[1] = (char)(0x4000);  /* OS bit */
    cfg[2] = 0;
    if (i2cWriteDevice(i2c_handle, cfg, 3) < 0) {
        syslog(LOG_ERR, "Failed to read ADS1115 config register");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    /* Read calibration table */
    char reg[1] = { ADS1115_CONFIG_REG };
    if (i2cWriteDevice(i2c_handle, reg, 1) < 0) {
        syslog(LOG_ERR, "Failed to set config pointer");
        cleanup();
        return EXIT_FAILURE;
    }
    char buf[8];
    if (i2cReadDevice(i2c_handle, buf, 8) != 8) {
        syslog(LOG_ERR, "Failed to read ADS1115 config data");
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t config_raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    uint16_t mux_raw    = ((uint16_t)(buf[2] & 0xFF) << 8) | (uint8_t)buf[3];
    uint16_t pga_raw   = ((uint16_t)(buf[4] & 0xFF) << 8) | (uint8_t)buf[5];
    uint16_t mode_raw  = ((uint16_t)(buf[6] & 0xFF) << 8) | (uint8_t)buf[7];

    if (mux_raw & 0x0001) {
        syslog(LOG_ERR, "ADS1115: invalid mux config 0x%04X", mux_raw);
        cleanup();
        return EXIT_FAILURE;
    }
    if (mode_raw & 0x0001) {
        syslog(LOG_ERR, "ADS1115: invalid mode config 0x%04X", mode_raw);
        cleanup();
        return EXIT_FAILURE;
    }
    if (pga_raw & 0x0001) {
        syslog(LOG_ERR, "ADS1115: invalid PGA config 0x%04X", pga_raw);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start single-shot on AIN0 */
    if (ads1115_read_channel(i2c_handle, ADC_CHANNEL_A0, NULL) < 0) {
        syslog(LOG_ERR, "Failed to start ADS1115 conversion on AIN0");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    float gauss_buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    for (int i = 0; i < BUFFER_SIZE; i++)
        gauss_buffer[i] = 0.0f;

    /* Main sampling loop */
    while (!terminate) {
        int16_t raw = 0;
        int status = ads1115_read_channel(i2c_handle, ADC_CHANNEL_A0, &raw);

        if (status == 0) {
            float gauss = voltage_to_gauss(raw);
            add_to_buffer(gauss_buffer, &buffer_index, gauss);
            float avg = buffer_average(gauss_buffer, BUFFER_SIZE, buffer_index);

            syslog(LOG_INFO, "A0: %.2f Gauß, Avg: %.2f Gauß", gauss, avg);

            if (avg > THRESHOLD_GAUSS) {
                syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauß", avg);
                gpioWrite(MOTOR_SHUTDOWN_PIN, 1);
                syslog(LOG_INFO, "Motor shutdown signal activated");
            }
        } else if (status == -2) {
            syslog(LOG_ERR, "ADC read error, skipping sample");
        } else {
            syslog(LOG_ERR, "ADC read invalid, skipping sample");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

