#define ADS1115_CONFIG_MUX_AIN0_GND (0x4000)
#define ADS1115_CONFIG_PGA_4_096V (0x0200)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100)
#define ADS1115_CONFIG_DR_128_SPS (0x0080)
#define ADS1115_CONFIG_CQUE_NONE (0x0003)
#define ADS1115_CONFIG_CMODE_CONT (0x0000)
#define ADS1115_CONFIG_CPOL_DOWN (0x0000)
#define ADS1115_CONFIG_CPOL_DOWN_DOWN (0x0000)
#define ADS1115_CONFIG_MODE_SINGLE_START (0x8000)

#define SENSOR_SENSITIVITY 0.001f
#define SENSOR_VREF 3.3f
#define ADC_MAX_COUNT 32767.0f
#define ADC_PGA_VOLTS 4.096f
#define ADC_VREF_VOLTS (ADC_PGA_VOLTS / 32768.0f)

static volatile sig_atomic_t running = 1;
static float threshold = 100.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: I2C write failed for config 0x%04X\n", config);
        return -1;
    }
    return 0;
}

