    while (running) {
        int16_t raw;
        if (ads1115_read_conversion(i2c_handle, &raw) != 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
