#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30.0
#define MOISTURE_THRESHOLD_HIGH 35.0
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_COMMAND_TOPIC "pump_control"
#define SAMPLE_INTERVAL_SEC 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed on channel %d", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float process_moisture_level(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d", PUMP_GPIO);
        return -1;
    }
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

static void publish_moisture(float moisture) {
    char payload[128];
    int len = snprintf(payload, sizeof(payload), "{\"moisture\": %.2f}", moisture);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "Payload formatting failed");
        return;
    }
    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, len, payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed");
    }
}

static void handle_command(const char *topic, const char *command) {
    syslog(LOG_INFO, "Received command: %s", command);
    if (strcmp(topic, "pump_control") == 0) {
        if (strcmp(command, "on") == 0) {
            control_pump(1);
        } else if (strcmp(command, "off") == 0) {
            control_pump(0);
        }
    }
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        if (mosquitto_subscribe(m, NULL, MQTT_COMMAND_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to command topic");
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_COMMAND_TOPIC) == 0) {
            handle_command(message->topic, message->payload);
        }
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (mosquitto_lib_cleanup() != MOSQ_ERR_SUCCESS) {
        syslog(LOG_WARNING, "mosquitto_lib_cleanup failed");
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", pigpio_error(spi_handle));
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Soil moisture monitoring started");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "ADC read failed, retrying in %d s", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float moisture = process_moisture_level(adc_value);
        if (moisture < 0) {
            syslog(LOG_ERR, "Moisture processing failed, retrying in %d s", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (moisture < MOISTURE_THRESHOLD_LOW && moisture > MOISTURE_THRESHOLD_HIGH) {
            control_pump(0);
        } else if (moisture < MOISTURE_THRESHOLD_LOW) {
            control_pump(1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
            control_pump(0);
        }

        publish_moisture(moisture);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

