            control_pump(0);
        }
    }
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        if (mosquitto_subscribe(m, NULL, MQTT_COMMAND_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to command topic");
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_COMMAND_TOPIC) == 0) {
            handle_command(message->topic, message->payload);
        }
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (mosquitto_lib_cleanup() != MOSQ_ERR_SUCCESS) {
        syslog(LOG_WARNING, "mosquitto_lib_cleanup failed");
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", pigpio_error(spi_handle));
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Soil moisture monitoring started");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "ADC read failed, retrying in %d s", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float moisture = process_moisture_level(adc_value);
        if (moisture < 0) {
            syslog(LOG_ERR, "Moisture processing failed, retrying in %d s", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (moisture < MOISTURE_THRESHOLD_LOW && moisture > MOISTURE_THRESHOLD_HIGH) {
            control_pump(0);
        } else if (moisture < MOISTURE_THRESHOLD_LOW) {
            control_pump(1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
            control_pump(0);
        }

        publish_moisture(moisture);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

