static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *light_level) {
    if (i2c_write_byte(fd, BH1750_CONT_HIGHRES_MODE) < 0)
        return -1;

    usleep(180000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *light_level = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int spi_fd, int channel, int *out) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(FILE *fp, int sound_level, float light_level, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (error_code != 0) {
        fprintf(fp, "%s,%d,%.2f,ERROR,%d\n", timestamp, sound_level, light_level, error_code);
    } else {
        fprintf(fp, "%s,%d,%.2f,OK\n", timestamp, sound_level, light_level);
    }
    fflush(fp);
    return 0;
}

