    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){SPI_SPEED}) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    printf("Tamper detection system started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        int sound_level = -1;
        float light_level = 0.0f;
        int error_code = 0;

        if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &sound_level) < 0) {
            error_code = 1;
        }

        if (read_bh1750(i2c_fd, &light_level) < 0) {
            error_code = 2;
        }

        if (error_code == 0) {
            log_data(fp, sound_level, light_level, 0);
        } else {
            log_data(fp, sound_level, light_level, error_code);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

