#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"
#define PWM_FREQ 100
#define PWM_RANGE 100
#define SAMPLE_INTERVAL 5

static volatile int running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_value(int x, int in_min, int in_max, int out_min, int out_max) {
    if (in_max == in_min) return out_min;
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

static void log_data(int *raw, int *avg, int *val) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Raw: %d, %d, %d, %d, %d\n", ts, *raw[0], *raw[1], *raw[2], *avg, *val);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    int raw[NUM_SENSORS];
    int avg = 0;
    int val = 0;
    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int r = read_mcp3008(i);
            if (r >= 0) {
                avg += r;
                raw[i] = r;
            } else {
                fprintf(stderr, "Sensor %d read failed\n", i);
            }
        }
        if (avg > 0) {
            val = map_value(avg, 0, 1023, 0, 100);
            if (gpioPWM(VALVE_GPIO, val) != 0) {
                fprintf(stderr, "PWM write failed\n");
            }
        }
        log_data(raw, &avg, &val);
        sleep(SAMPLE_INTERVAL);
    }
    gpioPWM(VALVE_GPIO, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

