#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE 1000000
#define SAMPLE_INTERVAL 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | (channel << 4));
    tx_buf[2] = 0x00;

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0f;
    }
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static int log_data(float moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Moisture: %.2f%%\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;
        int delay_us = RETRY_DELAY_BASE;

        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            gpioDelay(delay_us);
            delay_us *= 2;
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries, skipping sample\n", MAX_RETRIES);
        } else {
            float moisture_level = calculate_moisture_percentage(adc_value);
            if (moisture_level < 0) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            } else {
                if (log_data(moisture_level) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                } else {
                    printf("Moisture: %.2f%%\n", moisture_level);
                }
            }
        }

        if (!terminate) {
            gpioDelay(SAMPLE_INTERVAL * 1000000);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

