#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define PWM_CHANNEL 0

#define CONFIG_FILE "theremin_config.txt"
#define PWM_DIR "/sys/class/pwm/pwmchip0"
#define PWM_EXPORT "/sys/class/pwm/pwmchip0/export"
#define PWM_UNEXPORT "/sys/class/pwm/pwmchip0/unexport"
#define PWM_PERIOD "/sys/class/pwm/pwmchip0/pwm0/period"
#define PWM_DUTY_CYCLE "/sys/class/pwm/pwmchip0/pwm0/duty_cycle"
#define PWM_ENABLE "/sys/class/pwm/pwmchip0/pwm0/enable"

#define SPEED_OF_SOUND 34300.0
#define MIN_FREQUENCY 220.0
#define MAX_FREQUENCY 880.0
#define MIN_VOLUME 0
#define MAX_VOLUME 100
#define SAMPLE_INTERVAL_US 10000
#define ECHO_TIMEOUT_US 30000

volatile sig_atomic_t program_running = 1;

struct gpiod_chip *chip = NULL;
struct gpiod_line *trig_line = NULL;
struct gpiod_line *echo_line = NULL;

int spi_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int init_pwm() {
    char path[64];
    snprintf(path, sizeof(path), "%s/pwm0", PWM_DIR);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM directory: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, PWM_ENABLE, 0) < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, PWM_EXPORT, 0) < 0) {
        fprintf(stderr, "Failed to export PWM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

void cleanup_pwm(int fd) {
    if (fd >= 0) {
        if (ioctl(fd, PWM_UNEXPORT, 0) < 0) {
            fprintf(stderr, "Failed to unexport PWM: %s\n", strerror(errno));
        }
        close(fd);
    }
}

int set_pwm_duty_cycle(int duty_cycle) {
    char path[64];
    snprintf(path, sizeof(path), "%s/duty_cycle", PWM_DIR);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, O_RDWR, &duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int init_gpio() {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_input(echo_line, "theremin") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

void cleanup_gpio() {
    if (trig_line) {
        gpiod_line_release(trig_line);
        trig_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int read_distance() {
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig_line, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1;

    struct timespec start, end;
    long long start_ns, end_ns;
    int timeout = 0;

    while (gpiod_line_get_value(echo_line) == 0) {
        if (timeout++ > ECHO_TIMEOUT_US) return -1;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        if (timeout++ > ECHO_TIMEOUT_US) return -1;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    long long diff_ns = end_ns - start_ns;
    if (diff_ns <= 0) return -1;
    double distance = diff_ns * SPEED_OF_SOUND / 2000000000.0;
    return (int)distance;
}

int read_volume() {
    if (spi_fd < 0) return -1;
    unsigned char tx_buf[3] = {0x01, (0x08 | (volume / 10)) << 4, 0x00};
    unsigned char rx_buf[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return rx_buf[1];
}

int load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return -1;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "volume", 6) == 0) {
            volume = atoi(line + 6);
            if (volume < MIN_VOLUME || volume > MAX_VOLUME) volume = MIN_VOLUME;
        }
    }
    fclose(fp);
    return 0;
}

int save_config() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) return -1;
    fprintf(fp, "volume=%d\n", volume);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (load_config() < 0) {
        volume = MIN_VOLUME;
        save_config();
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    spi_fd = spi_fd;
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup_gpio();
        return 1;
    }

    int fd = init_pwm();
    if (fd < 0) {
        fprintf(stderr, "PWM initialization failed\n");
        cleanup_gpio();
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Distance read error, holding last valid state\n");
            distance = -1;
        }

