        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip); chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(line, "mq3-alcohol") < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip); chip = NULL; line = NULL;
        return -1;
    }

    return 0;
