            fprintf(stderr, "SPI transfer failed after %d retries: %s\n",
                    MAX_RETRIES, strerror(errno));
            return -1;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        return adc_value;
    }

    fprintf(stderr, "MCP3008 read failed after %d attempts\n", MAX_RETRIES);
    return -1;
