// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture_level, int pump_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: SGL/DIFF=1 (single) + D2 D1 D0 (channel) + padding
    // Byte 2: Don't care (clocks out remaining data bits)
    char spi_tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value: bits 9-2 from rx_buf[1], bits 1-0 from rx_buf[2]
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | (spi_rx_buf[2] & 0xFF);
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log data to a file
void log_data(int moisture_level, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Moisture: %d, Pump: %s\n", timestamp, moisture_level, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int moisture_level = read_mcp3008(0); // Read from channel 0

        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            log_data(-1, 0); // Log error
        } else {
            int pump_state = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;
            control_pump(pump_state);
            log_data(moisture_level, pump_state);
        }

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Irrigation system stopped.\n");
    return 0;
}

