#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIR 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Potentiometer ADC Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed Mapping Parameters
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion Profile Parameters
#define ACCELERATION_TIME 2 // seconds
#define HOLD_TIME 2 // seconds
#define PAUSE_TIME 5 // seconds

// Global Variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int read_potentiometer(int channel);
int map_speed(int pot_value);
void set_motor_speed(int motor_id, int speed);
void move_motor(int motor_id, int direction);
void cleanup();
void signal_handler(int signal);

// Function to read potentiometer value from MCP3008
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: SGL/DIFF=1 (single) + D2 D1 D0 (channel) + padding
    // Byte 2: Don't care (clocks out remaining data)
    unsigned char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value: bits 9-2 from rx_buf[1] (lower 2 bits) and rx_buf[2] (all 8 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor (0-1)
int map_speed(int pot_value) {
    if (pot_value < 0) return 0;
    if (pot_value > 1023) return 1;

    // Logarithmic mapping: lower potentiometer = lower speed, higher speed = higher potentiometer
    // This provides finer control at low speeds
    double log_speed = log(1023.0 / (double)pot_value + 1.0);
    if (log_speed < 0) log_speed = 0;
    if (log_speed > 1) log_speed = 1;
    return (int)(log_speed * MAX_SPEED);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_id, int speed) {
    if (motor_id == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
        gpioWrite(MOTOR1_DIR, (speed > 0) ? 1 : 0);
    } else if (motor_id == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
        gpioWrite(MOTOR2_DIR, (speed > 0) ? 1 : 0);
    } else {
        fprintf(stderr, "Error: Invalid motor ID %d\n", motor_id);
    }
}

// Function to move motor in specified direction
void move_motor(int motor_id, int direction) {
    if (motor_id == 1) {
        if (direction > 0) {
            set_motor_speed(motor_id, MAX_SPEED);
        } else if (direction < 0) {
            set_motor_speed(motor_id, 0);
        } else {
            set_motor_speed(motor_id, MIN_SPEED);
        }
    } else if (motor_id == 2) {
        if (direction > 0) {
            set_motor_speed(motor_id, MIN_SPEED);
        } else if (direction < 0) {
            set_motor_speed(motor_id, 0);
        } else {
            set_motor_speed(motor_id, MAX_SPEED);
        }
    } else {
        fprintf(stderr, "Error: Invalid motor ID %d\n", motor_id);
    }
}

// Cleanup function to release resources
void cleanup() {
    // Stop motors
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioWrite(MOTOR1_DIR, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR2_DIR, 0);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    // Set PWM range for motors
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Open SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read potentiometer values
        int pot1_value = read_potentiometer(POT1_CHANNEL);
        int pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            break;
        }

        // Map potentiometer values to speed factors
