#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define DEBOUNCE_DELAY_US 10000
#define SAMPLE_DELAY_US 100000
#define CALIBRATION_DURATION_US 5000000
#define NUM_SAMPLES 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise(void) {
    int sum = 0;
    int valid = 0;
    int samples[NUM_SAMPLES];

    printf("Calibrating noise level for %d seconds...\n", CALIBRATION_DURATION_US / 1000000);

    for (int i = 0; i < NUM_SAMPLES && running; i++) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "Calibration read error at sample %d\n", i);
            return -1;
        }
        sum += val;
        valid++;
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (valid == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        return -1;
    }

    int avg = sum / valid;
    printf("Average ambient level: %d\n", avg);
    return avg;
}

static int check_noise_threshold(int current, int avg) {
    int threshold = avg * 0.1;
    return (current > threshold) ? 1 : 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int avg = calibrate_noise();
    if (avg < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sound levels...\n");

    while (running) {
        int current = read_mcp3008(0);
        if (current < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (check_noise_threshold(current, avg)) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(DEBOUNCE_DELAY_US);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

