#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0     // MCP3008 channel connected to AWM720P
#define VREF 3.3          // Reference voltage for MCP3008
#define ADC_MAX 1023      // 10-bit ADC
#define VOLTAGE_MIN 0.5   // Voltage at 0 SLPM
#define VOLTAGE_MAX 4.5   // Voltage at 200 SLPM
#define SLPM_MAX 200.0    // Maximum airflow in SLPM
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_US 100000 // 100 ms

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(float voltage);
void log_data(float airflow);
void signal_handler(int signal);

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: 0x01 (Start bit)
    // Byte 1: (0x08 | channel) << 4 (Single-ended mode + channel selection)
    // Byte 2: 0x00 (Don't care, clocking out data)
    unsigned char tx_buffer[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx_buffer, (char *)rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buffer[1] contains the two most significant bits in its lower 2 bits
    // rx_buffer[2] contains the 8 least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert voltage to airflow (SLPM)
float voltage_to_airflow(float voltage) {
    if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
        fprintf(stderr, "Error: Voltage out of range: %.3f V\n", voltage);
        return -1.0;
    }
    float airflow = ((voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN)) * SLPM_MAX;
    return airflow;
}

// Function to log data to file
void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI_MODE0, active low CE
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed\n");
            log_data(-1.0); // Log error with -1.0
        } else {
            // Convert ADC value to voltage
            float voltage = (float)adc_value / ADC_MAX * VREF;

            // Convert voltage to airflow
            float airflow = voltage_to_airflow(voltage);

            if (airflow >= 0.0) {
                log_data(airflow);
            } else {
                fprintf(stderr, "Error: Airflow conversion failed\n");
                log_data(-1.0);
            }
        }

        // Wait for 100 ms
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

