#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL335 analog output pins (X, Y, Z) connected to MCP3008 channels 0, 1, 2
#define ADXL335_X_OUT 0
#define ADXL335_Y_OUT 1
#define ADXL335_Z_OUT 2

// MCP3008 SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_CS_PIN 8      // GPIO8 (CE0)

// ADXL335 parameters
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define ADXL335_ZERO_G_BIAS 1.5 // 1.5V at 0g

// Kalman filter parameters
#define Q_DIAGONAL 0.01 // Process noise
#define R_DIAGONAL 0.1 // Measurement noise
#define P_INIT 1.0     // Initial error covariance

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
double P[2][2] = {{0.0, 0.0}, {0.0, 0.0}};
double Q[2][2] = {{0.01, 0.0}, {0.0, 0.01}};
double R[2][2] = {{0.1, 0.0}, {0.0, 0.1}};
double K[2][2] = {{0.0, 0.0}, {0.0, 0.0}};
double P_prev[2][2] = {{0.0, 0.0}, {0.0, 0.0}};
double Q_prev[2][2] = {{0.01, 0.0}, {0.0, 0.01}};
double R_prev[2][2] = {{0.1, 0.0}, {0.0, 0.1}};

// Function prototypes
int read_mcp3008(int channel);
double read_accelerometer(int channel);
void kalman_filter(double x, double y, double z);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format: Start bit (1), SGL/DIFF=1, D2 D1 D0 (channel)
    unsigned char tx_buf[3] = {1, (0x80 | (channel << 4)), 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transaction failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to read accelerometer data from MCP3008
double read_accelerometer(int channel) {
    int adc_value = read_mcp3008(channel);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC value from channel %d\n", channel);
        return 0.0;
    }

    // Convert ADC value to voltage (3.3V reference)
    double voltage = (double)adc_value / 1023.0 * 3.3;

    // Convert voltage to acceleration (g)
    double acceleration = (voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;

    return acceleration;
}

// Kalman filter function
void kalman_filter(double x, double y, double z) {
    // Prediction
    P[0][0] = P_prev[0][0] + Q_prev[0][0];
    P[1][1] = P_prev[1][1] + Q_prev[1][1];
    K[0][0] = P_prev[0][0] / (P_prev[0][0] + R_prev[0][0]);
    K[1][1] = P_prev[1][1] / (P_prev[1][1] + R_prev[0][0]);
    K[0][1] = K[1][0] = 0.0;

    double x_pred = P_prev[0][0] * x + P_prev[1][0] * y;
    double y_pred = P_prev[0][1] * x + P_prev[1][1] * y;

    // Update
    double S = R_prev[0][0] + K[0][0] * R_prev[0][0];
    double S_inv = 1.0 / S;

    P[0][0] = (1.0 - K[0][0]) * P_prev[0][0] + K[0][0] * Q_prev[0][0];
    P[1][1] = (1.0 - K[1][0]) * P_prev[1][1] + K[1][0] * Q_prev[1][1];

    double x_post = x_pred + K[0][0] * (y - y_pred);
    double y_post = y - y_pred;

    // Update state estimate
    double P_post = P[0][0] + Q_prev[0][0];

    // Print filtered values
    printf("Filtered X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_post, y_post, z_post);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO8 as output and ensure it is low
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);
    gpioWrite(SPI_CS_PIN, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize Kalman filter state
    P[0][0] = P_INIT;
    P[1][1] = P_INIT;
    Q[0][0] = Q_DIAGONAL;
    Q[1][1] = Q_DIAGONAL;
    R[0][0] = R_DIAGONAL;
    R[1][1] = R_DIAGONAL;
    P_prev[0][0] = P_INIT;
    P_prev[1][1] = P_INIT;
    Q_prev[0][0] = Q_DIAGONAL;
    Q_prev[1][1] = Q_DIAGONAL;
    R_prev[0][0] = R_DIAGONAL;
    R_prev[1][1] = R_DIAGONAL;

    // Main loop
    while (!terminate) {
