#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define VCC 3.3
#define SENSITIVITY 0.025
#define V_QUIESCENT (VCC / 2.0)
#define MIN_MT -100.0
#define MAX_MT 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static double calculate_magnetic_field(int sensor_value) {
    double voltage = (double)sensor_value * VCC;
    double field_mt = (voltage - V_QUIESCENT) / SENSITIVITY;
    return field_mt;
}

static int log_data(double sensor1_mt, double sensor2_mt, double sensor3_mt) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mt, sensor2_mt, sensor3_mt);
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int pins[3] = {SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO};
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055_sensor") < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("DRV5055VA Sensor Logging Started. Press Ctrl+C to exit.\n");

    while (program_running) {
        double sensor1_mt = calculate_magnetic_field(gpiod_line_get_value(lines[0]));
        double sensor2_mt = calculate_magnetic_field(gpiod_line_get_value(lines[1]));
        double sensor3_mt = calculate_magnetic_field(gpiod_line_get_value(lines[2]));

        if (sensor1_mt < MIN_MT || sensor1_mt > MAX_MT) {
            fprintf(stderr, "Warning: Sensor 1 (GPIO%d) out of range: %.2f mT\n", SENSOR1_GPIO, sensor1_mt);
        }
        if (sensor2_mt < MIN_MT || sensor2_mt > MAX_MT) {
            fprintf(stderr, "Warning: Sensor 2 (GPIO%d) out of range: %.2f mT\n", SENSOR2_GPIO, sensor2_mt);
        }
        if (sensor3_mt < MIN_MT || sensor3_mt > MAX_MT) {
            fprintf(stderr, "Warning: Sensor 3 (GPIO%d) out of range: %.2f mT\n", SENSOR3_GPIO, sensor3_mt);
        }

        if (log_data(sensor1_mt, sensor2_mt, sensor3_mt) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

