#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define MAX_RECONNECT_DELAY_BASE 1
#define MAX_RECONNECT_DELAY_STEP 2
#define MAX_RECONNECT_DELAY_STEP_2 4
#define MAX_RECONNECT_DELAY_STEP_3 8
#define MAX_RECONNECT_DELAY_STEP_4 16
#define MAX_RECONNECT_DELAY_STEP_5 32
#define MAX_RECONNECT_DELAY_STEP_6 64

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("MQTT connect failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc == 0) {
        printf("Disconnected from MQTT broker\n");
    } else {
        log_error("MQTT disconnect failed");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        char payload[message->payloadlen + 1];
        int rc = mosquitto_message_ strcpy(payload, message->payload, message->payloadlen);
        if (rc != 0) {
            log_error("mosquitto_message_strcpy failed");
            return;
        }
        printf("Received message: %s\n", payload);
        cJSON *json = cJSON_Parse(payload);
        if (!json) {
            log_error("JSON parse failed");
            return;
        }
        cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
        if (!led_state) {
            log_error("JSON key 'led_state' missing");
            cJSON_Delete(json);
            return;
        }
        if (cJSON_IsBool(led_state)) {
            int led_val = cJSON_GetNumberValue(led_state);
            if (gpioWrite(LED_GPIO, led_val) != 0) {
                log_error("gpioWrite failed");
            }
        }
        cJSON_Delete(json);
    }
}

static void reconnect_with_backoff(void) {
    int delay = MAX_RECONNECT_DELAY_BASE;
    int rc;
    struct mosquitto *m;
    while (running && delay > 0) {
        rc = mosquitto_reconnect(mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT reconnect failed");
            delay *= 2;
            if (delay > MAX_RECONNECT_DELAY) delay = MAX_RECONNECT_DELAY;
            sleep(delay);
            delay *= 2;
            continue;
        }
        printf("Reconnected to MQTT broker\n");
        delay = MAX_RECONNECT_DELAY_BASE;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        log_error("gpioSetMode failed");
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("mosquitto_new failed");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("MQTT connect failed");
        mosquitto_destroy(mosq);
        mosq = NULL;
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("mosquitto_loop_start failed");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        gpioTerminate();
        return 1;
    }

    while (running) {
        rc = mosquitto_loop_wait(mosq, 1000);
        if (rc != MOSQ_ERR_SUCCESS) {
            if (rc == MOSQ_ERR_CONN_LOST) {
                log_error("MQTT connection lost, attempting reconnect");
                reconnect_with_backoff();
            } else {
                log_error("mosquitto_loop_wait failed");
            }
            break;
        }
    }

    printf("Cleaning up...\n");
    mosquitto_loop_stop(mosq, false);
    mosquitto_destroy(mosq);
    mosq = NULL;

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

