    ret = gpiod_line_request_input(sound_line, "sound_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the alarm LED line as output, initial value LOW */
    ret = gpiod_line_request_output(led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(alarm)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

