            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(alarm OFF)");
                break;
            }
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    /* Clean up GPIO resources */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

