#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3f
#define LM35_MV_PER_C 10.0f
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define SAMPLE_INTERVAL_US 5000000

typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: returned %d\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0f;
    return voltage * 100.0f / LM35_MV_PER_C;
}

static void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, float value) {
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static int buffer_write_to_file(const char *filename, const CircularBuffer *cb) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t written = fwrite(cb->data, sizeof(float), cb->count, fp);
    if (written != (size_t)cb->count) {
        fprintf(stderr, "Error writing to file: wrote %zu of %d entries\n", written, cb->count);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    CircularBuffer temp_buffer;
    buffer_init(&temp_buffer);

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MCP3008, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);

        buffer_add(&temp_buffer, temperature);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        printf("%s Temperature: %.2f °C\n", timestamp, temperature);

        if (buffer_write_to_file(LOG_FILE, &temp_buffer) != 0) {
            fprintf(stderr, "Failed to write buffer to file\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

