#define MCP4725_ADDR 0x62
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_celsius(int adc_value) {
    return (float)adc_value * 100.0f / 1023.0f - 50.0f;
}

static int set_dac_voltage(float voltage) {
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > 3.3f) voltage = 3.3f;

    unsigned char dac_data[2] = {
        (unsigned char)((voltage / 3.3f) * 1023.0f),
        0
    };

    if (i2cWriteDevice(i2c_handle, (char *)dac_data, 2) != 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC: %.2f V\n",
                timestamp, adc_value, temperature, voltage) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

