        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);
        float voltage = temperature * 3.3f;

        if (set_dac_voltage(voltage) != 0) {
            fprintf(stderr, "Failed to set DAC voltage.\n");
        }

        if (log_data(adc_value, temperature, voltage) != 0) {
            fprintf(stderr, "Logging failed.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

