#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

// BCM GPIO pins for the four relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Number of relays
#define NUM_RELAYS 4

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// GPIO chip and line handles
struct gpiod_chip *chip = NULL;
struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL};

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
void activate_relay(int pin);
void deactivate_relay(int pin);
void signal_handler(int sig);

// Initialize GPIO lines for the relays
int init_gpio(void) {
    // Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+)
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    // Get the four relay GPIO lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, RELAY1_PIN + i);
        if (!relay_lines[i]) {
            perror("Failed to get GPIO line");
            return -1;
        }

        // Request the line as an output, initially LOW (relay inactive)
        if (gpiod_line_request_output(relay_lines[i], "relay-seq", 0) < 0) {
            perror("Failed to request GPIO line as output");
            return -1;
        }
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    // Deactivate all relays (set LOW)
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

// Activate a relay (set HIGH)
void activate_relay(int pin) {
    if (gpiod_line_set_value(relay_lines[pin - 1], 1) < 0) {
        perror("Failed to activate relay");
    }
}

// Deactivate a relay (set LOW)
void deactivate_relay(int pin) {
    if (gpiod_line_set_value(relay_lines[pin - 1], 0) < 0) {
        perror("Failed to deactivate relay");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Relay sequencer started. Press Ctrl+C to stop.\n");

    // Main loop: activate and deactivate relays sequentially
    while (program_running) {
        // Activate relay 1
        activate_relay(1);
        sleep(1);
        deactivate_relay(1);

        // Delay between relays
        sleep(1);

        // Activate relay 2
        activate_relay(2);
        sleep(1);
        deactivate_relay(2);

        // Delay between relays
        sleep(1);

        // Activate relay 3
        activate_relay(3);
        sleep(1);
        deactivate_relay(3);

        // Delay between relays
        sleep(1);

        // Activate relay 4
        activate_relay(4);
        sleep(1);
        deactivate_relay(4);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();
    printf("Relay sequencer stopped.\n");
    return EXIT_SUCCESS;
}

