#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define RAIN_THRESHOLD 5
#define MOTOR_SPEED 150
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LOG_FILE "rain_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int map_rain_level(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return 10 - ((int)((float)adc_value / 1023.0f * 10.0f));
}

static int set_motor(int forward) {
    int level1 = (forward) ? 1 : 0;
    int level2 = (forward) ? 0 : 1;
    if (gpioWrite(MOTOR_IN1, level1) != 0) {
        fprintf(stderr, "Failed to write MOTOR_IN1\n");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2, level2) != 0) {
        fprintf(stderr, "Failed to write MOTOR_IN2\n");
        return -1;
    }
    if (gpioPWM(MOTOR_ENA, MOTOR_SPEED) != 0) {
        fprintf(stderr, "Failed to set PWM on MOTOR_ENA\n");
        return -1;
    }
    return 0;
}

static int log_rain_level(int rain_level) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Failed to get current time\n");
        return -1;
    }
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Failed to convert time\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        return -1;
    }
    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
        return -1;
    }
    return 0;
}

