#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

#define MIC_GPIO 26
#define LED_GPIO 16
#define THRESHOLD_VOLTAGE 2.31
#define DEBOUNCE_DELAY_US 50000
#define LED_ON_DELAY_US 500000
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read the MAX9814 electret microphone amplifier output as an analog
 * voltage via pigpio's bit-banged ADC on GPIO26.
 *
 * The MAX9814 has an internal AGC and a 1.2 V supply; the output
 * voltage is approximately 0.7 x 3.3 V = 2.31 V when the mic is
 * held near the sensor.  We sample at 1 kHz and convert to a 10-bit
 * digital value (0-1023).
 */
static int read_mic_voltage(void) {
    int samples = 100;
    int high_count = 0;
    int total = 0;

    for (int i = 0; i < samples; i++) {
        if (gpioSetMode(MIC_GPIO, PI_INPUT) < 0) {
            fprintf(stderr, "Error: failed to set MIC_GPIO as input\n");
            return -1;
        }
        if (gpioSetPullUpDown(MIC_GPIO, PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: failed to set pull-up on MIC_GPIO\n");
            return -1;
        }

        int level = gpioRead(MIC_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read MIC_GPIO\n");
            return -1;
        }

        if (level == 1) {
            high_count++;
        }
        total++;
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (total == 0) {
        return -1;
    }

    int voltage = (high_count * 1.2) / (float)total;
    return (int)(voltage * 1023.0);
}

static void trigger_led(void) {
    if (gpioWrite(LED_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to turn on LED\n");
        return;
    }
    gpioDelay(LED_ON_DELAY_US);
    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to turn off LED\n");
    }
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LED_GPIO as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool last_state = false;
    uint32_t last_trigger_tick = 0;

    while (running) {
        int mic_value = read_mic_voltage();
        if (mic_value < 0) {
            fprintf(stderr, "Error: failed to read MIC_GPIO\n");
            gpioDelay(100000);
            continue;
        }

        bool current_state = (mic_value > (THRESHOLD_VOLTAGE * 1023.0 / 3.3));

        if (current_state != last_state) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick >= DEBOUNCE_DELAY_US) {
                last_trigger_tick = now;
                if (current_state) {
                    trigger_led();
                    log_detection();
                }
            }
        }

        last_state = current_state;
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

