#define B -6.0
#define ERROR_VALUE -1
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_gpio_value(int pin) {
    FILE *fp = fopen("/sys/class/gpio/gpio" PIN "/value", "r");
    if (!fp) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", pin, strerror(errno));
        return ERROR_VALUE;
    }
    char val[32];
    if (!fgets(val, sizeof(val), fp)) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        fclose(fp);
        return ERROR_VALUE;
    }
    fclose(fp);
    return (val[0] == '0') ? 0 : 1;
}

static int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, %d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int activate_feeder(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
        return 0;
    } else {
        printf("Feeder Idle\n");
        return 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (access("/sys/class/gpio", F_OK) != 0) {
        fprintf(stderr, "GPIO sysfs directory not found. Is pigpiod running?\n");
        return 1;
    }

    if (access("/sys/class/gpio/gpio" GPIO_PIN, F_OK) != 0) {
        fprintf(stderr, "GPIO %d sysfs directory not found. Is pigpiod running?\n", GPIO_PIN);
        return 1;
    }

    if (access("/sys/class/gpio/gpio" GPIO_PIN "/export", F_OK) != 0) {
        if (access("/sys/class/gpio/gpio" GPIO_PIN, F_OK) == 0) {
            if (access("/sys/class/gpio/gpio" GPIO_PIN "/unexport", F_OK) != 0) {
                fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
                return 1;
            }
        } else {
            fprintf(stderr, "GPIO %d directory not found. Is pigpiod running?\n", GPIO_PIN);
            return 1;
        }
    }

    if (access("/sys/class/gpio/gpio" GPIO_PIN "/unexport", F_OK) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
        return 1;
    }

    if (access("/sys/class/gpio/gpio" GPIO_PIN, W_OK) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        return 1;
    }

    if (access("/sys/class/gpio/gpio" GPIO_PIN "/direction", F_OK) != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction\n", GPIO_PIN);
        return 1;
    }

    if (access("/sys/class/gpio/gpio" GPIO_PIN "/value", W_OK) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        return 1;
    }

    if (access("/sys/class/gpio/gpio" GPIO_PIN "/pull-up-down", F_OK) != 0) {
        fprintf(stderr, "Failed to set GPIO %d pull-up/down\n", GPIO_PIN);
        return 1;
    }

    if (access("/sys/class/gpio/gpio" GPIO_PIN "/offset", F_OK) != 0) {
        fprintf(stderr, "Failed to set GPIO %d offset\n", GPIO_PIN);
        return 1;
    }

    printf("Starting distance sensor monitoring on GPIO %d...\n", GPIO_PIN);

    while (running) {
        int value = read_gpio_value(GPIO_PIN);
        if (value == ERROR_VALUE) {
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        float voltage = (float)value * VOLTAGE_HIGH;
        float distance = A / voltage + B;

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        if (activate_feeder(distance) != 0) {
            fprintf(stderr, "Feeder activation failed, continuing...\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (access("/sys/class/gpio/gpio" GPIO_PIN, F_OK) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
        return 1;
    }
    if (access("/sys/class/gpio/gpio" GPIO_PIN "/unexport", F_OK) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
        return 1;
    }
    printf("GPIO %d unexported. Exiting.\n", GPIO_PIN);
    return 0;
}

