#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define PUMP_GPIO_LINE 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pump_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return -1.0;
    float pct = 100.0 - ((float)(adc_value - 300) / (float)(800 - 300)) * 100.0;
    if (pct < 0) pct = 0;
    if (pct > 100) pct = 100;
    return pct;
}

static int control_pump(int state) {
    int ret = gpiod_line_set_value(pump_line, state);
    if (ret < 0) {
        perror("Failed to set pump GPIO");
        return -1;
    }
    return 0;
}

static void log_data(float moisture, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n",
            timestamp, moisture, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);
        gpiod_line_release(pump_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        fclose(log_file);
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){SPI_SPEED}) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        cleanup();
        return 1;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO_LINE);
    if (!pump_line) {
        perror("Failed to get pump GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture_pump", 0) < 0) {
        perror("Failed to request pump GPIO as output");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = calculate_moisture_percentage(adc_value);
        int pump_state = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;

        if (control_pump(pump_state) < 0) {
            fprintf(stderr, "Failed to control pump\n");
        }

        log_data(moisture, pump_state);
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

