#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  /* 1 MHz */
#define MCP3008_CHANNEL 0
#define LED_GPIO 21
#define VOLTAGE_SUPPLY 3.3
#define FIELD_THRESHOLD 10.0
#define ADC_RESOLUTION 1023.0
#define ADC_VREF 3.3
#define SENSITIVITY_MV_PER_MT 1.65  /* DRV5055VA: 2.5 mV/mT at 3.3 V */
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_DELAY_US 100000  /* 100 ms */

/* Global state */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read MCP3008 single-ended channel; returns 0-1023 or -1 on error */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     * Byte 2: 0x00 (don't care, clocked out to read low byte)
     * Response: byte[1] low nibble + byte[2] form the 10-bit result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* Convert ADC value to voltage */
static float adc_to_voltage(int adc_value) {
    return (float)adc_value * (VOLTAGE_SUPPLY / ADC_RESOLUTION);
}

/* Convert voltage to magnetic field strength in mT */
static float voltage_to_field(float voltage) {
    float field_mT = (voltage - (VOLTAGE_SUPPLY / 2.0)) * 1000.0 / SENSITIVITY_MV_PER_MT;
    return field_mT;
}

/* Log field strength with timestamp */
static void log_field_strength(float field_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, Field: %.2f mT\n", timestamp, field_mT);
    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring magnetic field... (Ctrl+C to exit)\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float field_mT = voltage_to_field(voltage);

        log_field_strength(field_mT);

        if (field_mT > FIELD_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

