#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W - MLX91211 current sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 5V (Pi pin 2/4)
 *   MCP3008 VREF -> 5V (Pi pin 2/4)
 *   MCP3008 AGND -> GND (Pi pin 6/8)
 *   MCP3008 DGND -> GND (Pi pin 6/8)
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   MLX91211 VDD -> 5V (Pi pin 2/4)
 *   MLX91211 GND -> GND (Pi pin 6/8)
 *   MLX91211 AOUT -> MCP3008 CH0
 *
 * MLX91211 ratiometric: 2.5V (VDD/2) at 0A, 5.0V (VDD) at +50A.
 * Current = (voltage - 2.5) * (50.0 / 2.5)
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl-C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 (single-ended)                       */
/* Returns 0-1023 on success, -1 on SPI error.                         */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       Start bit
     *   tx[1] = 0x80 | (channel << 4)      Single-ended + channel
     *   tx[2] = 0x00                       Don't-care
     *
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC code to voltage (0-5.0 V)                          */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value %d out of range\n", adc_value);
        return -1.0f;
    }
    return ((float)adc_value / 1023.0f) * 5.0f;
}

/* ------------------------------------------------------------------ */
/* Convert voltage to current (0-50 A)                                */
/* MLX91211 ratiometric: 2.5 V at 0 A, 5.0 V at +50 A.                 */
/* Returns -1.0f on invalid voltage.                                 */
/* ------------------------------------------------------------------ */
static float voltage_to_current(float voltage)
{
    if (voltage < 0.0f || voltage > 5.0f) {
        fprintf(stderr, "Invalid voltage %.2f V\n", voltage);
        return -1.0f;
    }
    if (voltage <= 2.5f) {
        return 0.0f;
    }
    return ((voltage - 2.5f) / 2.5f) * 50.0f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file               */
/* ------------------------------------------------------------------ */
static void log_current(float current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s .%02.1f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0, 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current monitor started. Logging to '%s'.\n", LOG_FILE);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        if (voltage < 0.0f) {
            fprintf(stderr, "Voltage conversion error, skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = voltage_to_current(voltage);
        if (current < 0.0f) {
            fprintf(stderr, "Current conversion error (voltage %.2f V), skipping sample\n", voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        printf("ADC: %4d  Voltage: %.2f V  Current: %.2f A\n",
               adc_value, voltage, current);
        log_current(current);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

