#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the gpiochip that exposes GPIO4 and GPIO17 on the Pi 5 */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("gpiod_chip_get_line (sensor1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("gpiod_chip_get_line (sensor2)");
        goto cleanup;
    }

    /* Request both lines as inputs with pull-up disabled (sensors drive LOW) */
    if (gpiod_line_request_input(line1, "b5w-db01-s1") < 0) {
        perror("gpiod_line_request_input (sensor1)");
        goto cleanup;
    }
    if (gpiod_line_request_input(line2, "b5w-db01-s2") < 0) {
        perror("gpiod_line_request_input (sensor2)");
        goto cleanup;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("B5W-DB01 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int val1 = -1, val2 = -1;
        int ok1 = 0, ok2 = 0;

        /* Debounce: sample DEBOUNCE_SAMPLES times with DEBOUNCE_DELAY_MS between */
        for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
            int v1 = gpiod_line_get_value(line1);
            if (v1 < 0) {
                perror("gpiod_line_get_value (sensor1)");
                goto cleanup;
            }
            if (v1 == 0) {
                ok1 = 1;
                val1 = v1;
                break;
            }
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
            int v2 = gpiod_line_get_value(line2);
            if (v2 < 0) {
                perror("gpiod_line_get_value (sensor2)");
                goto cleanup;
            }
            if (v2 == 0) {
                ok2 = 1;
                val2 = v2;
                break;
            }
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        if (!ok1 || !ok2) {
            fprintf(stderr, "Warning: sensor read error, skipping cycle\n");
            goto cleanup;
        }

        /* Sensor 1: LOW = object present, HIGH = no object */
        int s1 = (val1 == 0) ? 0 : 1;
        /* Sensor 2: LOW = object present, HIGH = no object */
        int s2 = (val2 == 0) ? 0 : 1;

        printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

