#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define PIR_PIN 17
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_US 50000
#define CAPTURE_WIDTH 1280
#define CAPTURE_HEIGHT 720
#define CAPTURE_DIR "/home/pi/security_cam/"
#define TIMESTAMP_LEN 32

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int generate_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int capture_image(const char *timestamp) {
    char command[512];
    char filepath[512];
    int ret;

    snprintf(filepath, sizeof(filepath), "%s%s.jpg", CAPTURE_DIR, timestamp);

    ret = snprintf(command, sizeof(command),
                   "libcamera-still -o %s --width %d --height %d --nopreview",
                   filepath, CAPTURE_WIDTH, CAPTURE_HEIGHT);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        syslog(LOG_ERR, "Command buffer too small for libcamera-still");
        return -1;
    }

    int pipefd[2] = { -1, -1 };
    if (pipe(pipefd) != 0) {
        syslog(LOG_ERR, "pipe() failed: %m");
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %m");
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    }

    if (pid == 0) {
        /* Child process */
        close(pipefd[1]);
        if (dup2(pipefd[0], STDIN_FILENO) < 0) {
            syslog(LOG_ERR, "dup2(STDIN) failed: %m");
            _exit(127);
        }
        close(pipefd[0]);
        execlp("libcamera-still", "libcamera-still", "-o", filepath, "--width", "1280", "--height", "720", (char *)NULL);
        /* If execlp returns, it failed */
        _exit(127);
    }

    /* Parent process */
    close(pipefd[0]);
    if (pipefd[1] < 0) {
        syslog(LOG_ERR, "close(PIPE_READ) failed: %m");
        return -1;
    }

    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!running) {
                syslog(LOG_ERR, "waitpid interrupted by signal");
                return -1;
            }
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %m");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured: %s", filepath);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (status=%d)", WEXITSTATUS(status));
    return -1;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %m");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (PIR on GPIO%d)", PIR_PIN);

    int last_state = gpioRead(PIR_PIN);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead(%d) failed", PIR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_PIN);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_PIN);
                if (generate_timestamp(timestamp_str, TIMESTAMP_LEN) == 0) {
                    if (capture_image(timestamp_str) == 0) {
                        syslog(LOG_INFO, "Image captured: %s", timestamp_str);
                    } else {
                        syslog(LOG_ERR, "Failed to capture image");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to generate timestamp");
                }
            } else {
                syslog(LOG_INFO, "Motion stopped on GPIO%d", PIR_PIN);
            }

            last_state = current_state;
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Security camera shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

