#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define DEFAULT_WIDTH 640
#define DEFAULT_HEIGHT 480
#define DEFAULT_FPS 30
#define DEFAULT_BUFFER_COUNT 1
#define DEFAULT_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_device(const char *device, int *fd_out) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }
    *fd_out = fd;
    return 0;
}

static int set_format(int fd, int width, int height, int fps, int *format_out) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GRAY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }
    *format_out = fmt.fmt.pix.pixelformat;
    return 0;
}

static int set_fps(int fd, int fps) {
    struct v4l2_streamparm sp;
    memset(&sp, 0, sizeof(sp));
    sp.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    sp.parm.capture.timeperframe.numerator = fps;
    sp.parm.capture.timeperframe.denominator = 1;
    if (ioctl(fd, VIDIOC_S_PARM, &sp) < 0) {
        fprintf(stderr, "Error setting fps: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int open_mmap_device(int fd, int *mmap_fd_out) {
    struct v4l2_mmap_buf mmap;
    memset(&mmap, 0, sizeof(mmap));
    mmap.index = 0;
    mmap.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    mmap.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &mmap) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }
    *mmap_fd_out = mmap.fd;
    return 0;
}

static int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = DEFAULT_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "select() error: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select() timeout (0 bytes).\n");
        return -1;
    }

    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int write_pgm(const char *filename, const unsigned char *data, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }
    if (fwrite(data, 1, width * height, fp) != (size_t)(width * height)) {
        fprintf(stderr, "Error writing to %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device = (argc > 1) ? argv[1] : DEFAULT_DEVICE;
    int width = DEFAULT_WIDTH;
    int height = DEFAULT_HEIGHT;
    int fps = DEFAULT_FPS;
    int buffer_count = DEFAULT_BUFFER_COUNT;
    int timeout_sec = DEFAULT_TIMEOUT_SEC;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    int fd = -1;
    int mmap_fd = -1;
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));

    if (open_device(device, &fd) != 0) {
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        goto cleanup;
    }

    if (set_format(fd, width, height, fps, &cap.fmt.pix.pixelformat) != 0) {
        goto cleanup;
    }

    if (set_fps(fd, fps) != 0) {
        goto cleanup;
    }

    if (buffer_count > 0) {
        if (open_mmap_device(fd, &mmap_fd) != 0) {
            goto cleanup;
        }
    }

    unsigned char *buffer = (unsigned char *)malloc(width * height);
    if (!buffer) {
        fprintf(stderr, "Error allocating buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    while (!g_stop) {
        if (dequeue_buffer(fd, &buf) == 0) {
            if (mmap_fd >= 0) {
                if (ioctl(mmap_fd, VIDIOC_DQBUF, &buf) < 0) {
                    fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
                    break;
                }
            }
            memcpy(buffer, buf.data.pixel, buf.bytesused);
            if (write_pgm("image_0001.pgm", buffer, width, height) != 0) {
                fprintf(stderr, "Error writing image_0001.pgm\n");
            }
            free(buffer);
            buffer = NULL;
        } else {
            if (g_stop) break;
            continue;
        }
    }

cleanup:
    if (mmap_fd >= 0) {
        if (ioctl(mmap_fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        }
        if (munmap(mmap_fd, buf.bytesused) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        }
    }
    if (fd >= 0) {
        if (ioctl(fd, VIDIOC_STREAMOFF, &buf) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }
    }
    if (buffer) {
        free(buffer);
    }
    return (g_stop || exit_code(0) == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

