        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct v4l2_buffer *buf_out = NULL;
    if (ioctl(fd, VIDIOC_STREAMON, &buf) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    buf_out = (struct v4l2_buffer *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buf_out == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int capture_frame(int fd, unsigned char *buffer, int width, int height) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    int bytes_read = buf.bytesused;
    if (bytes_read < 0) {
        fprintf(stderr, "VIDIOC_QBUF bytesused error: %s\n", strerror(errno));
        return -1;
    }

    if (bytes_read != (int)width * height * 2) {
        fprintf(stderr, "Frame size mismatch: read %d, expected %d\n", bytes_read, width * height * 2);
        return -1;
    }

    memcpy(buffer, buffer, bytes_read);
    return 0;
}

static int fragment_frame(unsigned char *frame, int width, int height, int *fragment_count, unsigned char **fragments) {
    int fragment_size = 640 * 480 * 2;
    int total_fragments = (width * height * 2 + fragment_size - 1) / fragment_size;
    if (total_fragments > MAX_FRAGMENTS) total_fragments = MAX_FRAGMENTS;

    int offset = 0;
    for (int i = 0; i < total_fragments; i++) {
        unsigned char *fragment = (unsigned char *)malloc(fragment_size);
        if (!fragment) {
            fprintf(stderr, "Memory allocation failed for fragment %d\n", i);
            return -1;
        }

        memcpy(fragment, frame + offset, fragment_size);
        offset += fragment_size;

        if (offset >= (int)width * height * 2) {
            *fragment_count = i + 1;
            *fragments = fragments + 1;
            return 0;
        }
    }

    free(fragment);
    return -1;
}

static int send_udp_datagram(int udp_fd, const unsigned char *data, int data_len, const struct sockaddr_in *server_addr, int port) {
    if (sendto(udp_fd, data, data_len, 0, (struct sockaddr *)server_addr, sizeof(*server_addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *server_ip = (argc > 1) ? argv[1] : DEFAULT_SERVER_IP;
    int server_port = (argc > 2) ? atoi(argv[2]) : DEFAULT_SERVER_PORT;
    int width = DEFAULT_WIDTH;
    int height = DEFAULT_HEIGHT;
    int fps = DEFAULT_FPS;
    int buffer_count = DEFAULT_BUFFER_COUNT;
    int buffer_size = DEFAULT_BUFFER_SIZE;
    int udp_buffer_size = DEFAULT_UDP_BUFFER_SIZE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    int fd = setup_v4l2_device("/dev/video0", width, height, fps, buffer_count);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    int udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        fprintf(stderr, "socket failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", server_ip);
        close(udp_fd);
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char *frame = (unsigned char *)malloc(width * height * 2);
    if (!frame) {
        fprintf(stderr, "Frame buffer allocation failed\n");
        close(udp_fd);
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char **fragments = (unsigned char **)malloc(total_fragments * sizeof(unsigned char *));
    if (!fragments) {
        fprintf(stderr, "Fragment buffer allocation failed\n");
        free(frame);
        close(udp_fd);
        close(fd);
        return EXIT_FAILURE;
    }

    int fragment_count = 0;
    int udp_datagram_len = 0;

    while (g_running) {
        if (capture_frame(fd, frame, width, height) < 0) {
            break;
        }

        if (fragment_frame(frame, width, height, &fragment_count, fragments) < 0) {
            break;
        }

        for (int i = 0; i < fragment_count; i++) {
            if (send_udp_datagram(udp_fd, fragments[i], udp_datagram_len, &server_addr, port) < 0) {
                break;
            }
            udp_datagram_len += udp_buffer_size;
        }

        if (udp_datagram_len > 0) {
            udp_datagram_len = 0;
        }
    }

    free(frame);
    for (int i = 0; i < total_fragments; i++) {
        if (fragments[i]) {
            free(fragments[i]);
        }
    }
    free(fragments);
    free(frame);
    close(udp_fd);
    close(fd);

    return EXIT_SUCCESS;
}

