#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "image.jpg"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS  4
#define FRAME_SIZE   (IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2)

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int capture_jpeg(int fd, const char *filename) {
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers req;
    unsigned char *buffer = NULL;
    int ret = -1;

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    for (int i = 0; i < req.count; i++) {
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }
        if (buf.length < FRAME_SIZE) {
            fprintf(stderr, "Buffer too small (%d bytes < %d)\n", buf.length, FRAME_SIZE);
            return -1;
        }
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, V4L2_STREAM_CAPTURE) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    struct v4l2_buffer qbuf;
    memset(&qbuf, 0, sizeof(qbuf));
    qbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    qbuf.memory = V4L2_MEMORY_MMAP;

    for (;;) {
        if (g_stop) {
            fprintf(stderr, "\nInterrupted by signal.\n");
            ret = -1;
            goto cleanup;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &qbuf) < 0) {
            perror("VIDIOC_DQBUF");
            ret = -1;
            goto cleanup;
        }

        if (qbuf.index >= req.count) {
            fprintf(stderr, "Unexpected buffer count: %d\n", qbuf.index);
            ret = -1;
            goto cleanup;
        }

        buffer = (unsigned char *)mmap(NULL, qbuf.bytesused, PROT_READ, MAP_SHARED, fd, qbuf.m.offset);
        if (buffer == MAP_FAILED) {
            perror("mmap");
            ret = -1;
            goto cleanup;
        }

        if (qbuf.bytesused == 0) {
            fprintf(stderr, "Empty buffer (0 bytes)\n");
            ret = -1;
            goto cleanup;
        }

        FILE *fp = fopen(filename, "wb");
        if (!fp) {
            perror("fopen");
            ret = -1;
            goto cleanup;
        }

        size_t written = fwrite(buffer, 1, qbuf.bytesused, fp);
        if (written != qbuf.bytesused) {
            fprintf(stderr, "Short write: %zu of %d bytes\n", written, qbuf.bytesused);
            ret = -1;
            goto cleanup;
        }

        if (fclose(fp) != 0) {
            perror("fclose");
            ret = -1;
            goto cleanup;
        }

        printf("Captured %s (%d bytes)\n", filename, qbuf.bytesused);
        ret = 0;

    cleanup:
        if (ioctl(fd, VIDIOC_STREAMOFF, V4L2_STREAM_CAPTURE) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
        if (buffer) {
            munmap(buffer, qbuf.bytesused);
        }
    }
}

int main(void) {
    int fd = -1;
    unsigned char *buffers[NUM_BUFFERS];
    int i;

    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
