        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&buffers, 0, sizeof(buffers));
    for (i = 0; i < NUM_BUFFERS; i++) {
        buffers[i] = NULL;
    }

    for (i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        if (buf.length < FRAME_SIZE) {
            fprintf(stderr, "Buffer too small (%d bytes < %d)\n", buf.length, FRAME_SIZE);
            goto cleanup;
        }

        buffers[i] = (unsigned char *)malloc(buf.length);
        if (!buffers[i]) {
            perror("malloc");
            goto cleanup;
        }
    }

    memset(&buffers, 0, sizeof(buffers));
    for (i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    memset(&buffers, 0, sizeof(buffers));
    for (i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            goto cleanup;
        }

        if (buf.index >= NUM_BUFFERS) {
            fprintf(stderr, "Unexpected buffer count: %d\n", buf.index);
            goto cleanup;
        }

        buffers[buf.index] = (unsigned char *)mmap(NULL, buf.bytesused, PROT_READ, MAP_SHARED, fd, buf.m.offset);
        if (buffers[buf.index] == MAP_FAILED) {
            perror("mmap");
            goto cleanup;
        }
    }

    if (capture_jpeg(fd, OUTPUT_FILE) < 0) {
        fprintf(stderr, "Failed to capture image.\n");
        goto cleanup;
    }

    printf("Image saved to %s\n", OUTPUT_FILE);

cleanup:
    if (fd >= 0) {
        if (ioctl(fd, VIDIOC_STREAMOFF, V4L2_STREAM_CAPTURE) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
        for (i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i] && buffers[i] != MAP_FAILED) {
                munmap(buffers[i], buf.length);
            }
        }
        close(fd);
    }
    return EXIT_SUCCESS;
}

