#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define WIDTH 640
#define HEIGHT 480
#define KERNEL_SIZE 5
#define QUALITY 75
#define MAX_FRAMES 10
#define VIDEO_DEVICE "/dev/video0"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    *fd = open(VIDEO_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("open");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto fail;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto fail;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto fail;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto fail;
    }

    unsigned long buf_size = buf.length;
    unsigned char *buffer = (unsigned char *)mmap(NULL, buf_size, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        goto fail;
    }

    if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto fail;
    }

    struct v4l2_buffer qbuf;
    memset(&qbuf, 0, sizeof(qbuf));
    qbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    qbuf.memory = V4L2_MEMORY_MMAP;
    qbuf.index = 0;

    if (xioctl(*fd, VIDIOC_STREAMON, &qbuf) < 0) {
        perror("VIDIOC_STREAMON");
        goto fail;
    }

    return 0;

fail:
    munmap((void *)buffer, buf_size);
    close(*fd);
    *fd = -1;
    return -1;
}

static int capture_frame(int fd, unsigned char **frame, size_t *frame_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) return -1;

    memset(frame, 0, *frame_size);
    if (xioctl(fd, VIDIOC_DQBUF, &qbuf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *frame_size = qbuf.bytesused;
    *frame = (unsigned char *)malloc(*frame_size);
    if (*frame == NULL) {
        perror("malloc");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &qbuf) < 0) {
        perror("VIDIOC_QBUF");
        free(*frame);
        *frame = NULL;
        return -1;
    }

    return 0;
}

static void convert_yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, int w, int h) {
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x += 2) {
            int yuyv_idx = (y * w + x) * 2;
            int r = yuyv[yuyv_idx];
            int g = yuyv[yuyv_idx + 1];
            int b = yuyv[yuyv_idx + 2];
            int y = yuyv[yuyv_idx + 3];

            rgb[yuyv_idx] = (r * 299) / 512 + (g * 510) / 65536 + (b * 108) / 10000;
            rgb[yuyv_idx + 1] = (r * 20) / 255 + (g * 128) / 255 + (b * 170) / 255;
            rgb[yuyv_idx + 2] = r;
            rgb[yuyv_idx + 3] = y;
        }
    }
}

static void apply_box_blur(unsigned char *rgb, int w, int h, int radius) {
    int half_radius = radius / 2;
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int sum = 0;
            for (int dy = -half_radius; dy <= half_radius; dy++) {
                for (int dx = -half_radius; dx <= half_radius; dx++) {
                    int src_x = x + dx;
                    int src_y = y + dy;
                    if (src_x >= 0 && src_x < w && src_y >= 0 && src_y < h) {
                        int src_idx = (src_y * w + src_x) * 3;
                        int dst_idx = (y * w + x) * 3;
                        sum += rgb[src_idx];
                    }
                }
            }
            rgb[dst_idx] = (sum * 2) / 5 + (rgb[dst_idx] * 3) / 5;
        }
    }
}

static int save_jpeg(const unsigned char *rgb, int w, int h, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *fp = NULL;
    JSAMPROW row_pointer[1];
    JSAMPROW plane[4];

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    if (setjmp(cinfo.err_buf)) {
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, fp);
    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * w * 3];
        plane[0] = &rgb[cinfo.next_scanline * w * 3 + 1];
        plane[1] = &rgb[cinfo.next_scanline * w * 3 + 2];
        plane[2] = &rgb[cinfo.next_scanline * w * 3 + 3];
        plane[3] = &rgb[cinfo.next_scanline * w * 3 + 4];

        jpeg_write_scanlines(&cinfo, plane, row_pointer);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(fp);
    return 0;
}

int main(void) {
    int fd = -1;
    unsigned char *frame = NULL;
    size_t frame_size = 0;
    unsigned char *rgb = NULL;
    char filename[128];
    time_t rawtime;
    struct tm *timeinfo;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_camera(&fd) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    printf("Capturing frame...\n");
    if (capture_frame(fd, &frame, &frame_size) < 0) {
        fprintf(stderr, "Frame capture failed\n");
        goto cleanup;
    }

    printf("Converting YUYV to RGB...\n");
    convert_yuyv_to_rgb(frame, rgb, WIDTH, HEIGHT);

    printf("Applying box blur...\n");
    apply_box_blur(rgb, WIDTH, HEIGHT, KERNEL_SIZE);

    printf("Saving JPEG...\n");
    if (save_jpeg(rgb, WIDTH, HEIGHT, filename) < 0) {
        fprintf(stderr, "JPEG save failed\n");
        goto cleanup;
    }

    printf("Saved: %s\n", filename);

cleanup:
    if (frame != NULL) free(frame);
    if (rgb != NULL) free(rgb);
    if (fd >= 0) close(fd);
    printf("Exiting.\n");
    return 0;
}

