#define DEVICE_NAME "/dev/video0"
#define MAX_FRAMESIZES 16
#define MAX_FRAMEINTERVALS 16

static int print_supported_resolutions(int fd) {
    struct v4l2_frmsizeenum frms;
    memset(&frms, 0, sizeof(frms));
    frms.type = V4L2_FRAMESIZE_ENUM;

    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frms) < 0) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        return -1;
    }

    printf("Supported frame sizes:\n");
    for (int i = 0; i < frms.count; i++) {
        printf("  %d (%dx%d)\n", i, frms.size.width, frms.size.height);
    }
    return 0;
}

static int print_supported_frame_intervals(int fd) {
    struct v4l2_frmintenum frms;
    memset(&frms, 0, sizeof(frms));
    frms.type = V4L2_FRAMEINTERVAL_ENUM;

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frms) < 0) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        return -1;
    }

    printf("Supported frame intervals:\n");
    for (int i = 0; i < frms.count; i++) {
        printf("  %d\n", frms.interval.numerator);
    }
    return 0;
}

