#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_CENTER_PULSE_WIDTH 1500
#define STEP_SIZE 10
#define LOOP_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* Configure button pins as inputs with internal pull-ups */
    int buttons[] = {UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN};
    for (size_t i = 0; i < sizeof(buttons) / sizeof(buttons[0]); ++i) {
        if (gpioSetMode(buttons[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", buttons[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(buttons[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", buttons[i]);
            gpioTerminate();
            return -1;
        }
    }

    /* Configure servo pins as outputs */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure servos start at center */
    if (gpioServo(PAN_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Error: failed to set initial pulse width on GPIO %d.\n", PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioServo(TILT_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Error: failed to set initial pulse width on GPIO %d.\n", TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void move_servo(int pin, int new_pulse_width)
{
    if (new_pulse_width < SERVO_MIN_PULSE_WIDTH) new_pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (new_pulse_width > SERVO_MAX_PULSE_WIDTH) new_pulse_width = SERVO_MAX_PULSE_WIDTH;

    if (gpioServo(pin, new_pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on GPIO %d.\n", pin);
    }
}

static void cleanup_gpio(void)
{
    /* Stop PWM on both servos */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Camera Control\n");
    printf("======================\n");
    printf("Pan servo: GPIO%d | Tilt servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("UP button: GPIO%d | DOWN button: GPIO%d\n", UP_BUTTON_PIN, DOWN_BUTTON_PIN);
    printf("LEFT button: GPIO%d | RIGHT button: GPIO%d\n", LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    int pan_pos = SERVO_CENTER_PULSE_WIDTH;
    int tilt_pos = SERVO_CENTER_PULSE_WIDTH;

    while (g_running) {
        int up_state = gpioRead(UP_BUTTON_PIN);
        int down_state = gpioRead(DOWN_BUTTON_PIN);
        int left_state = gpioRead(LEFT_BUTTON_PIN);
        int right_state = gpioRead(RIGHT_BUTTON_PIN);

        if (up_state < 0 || down_state < 0 || left_state < 0 || right_state < 0) {
            fprintf(stderr, "Warning: gpioRead failed on one or more button pins.\n");
        }

        if (up_state == 0) {
            pan_pos += STEP_SIZE;
            if (pan_pos > SERVO_MAX_PULSE_WIDTH) pan_pos = SERVO_MAX_PULSE_WIDTH;
            move_servo(PAN_SERVO_PIN, pan_pos);
        }
        if (down_state == 0) {
            pan_pos -= STEP_SIZE;
            if (pan_pos < SERVO_MIN_PULSE_WIDTH) pan_pos = SERVO_MIN_PULSE_WIDTH;
            move_servo(PAN_SERVO_PIN, pan_pos);
        }
        if (left_state == 0) {
            tilt_pos += STEP_SIZE;
            if (tilt_pos > SERVO_MAX_PULSE_WIDTH) tilt_pos = SERVO_MAX_PULSE_WIDTH;
            move_servo(TILT_SERVO_PIN, tilt_pos);
        }
        if (right_state == 0) {
            tilt_pos -= STEP_SIZE;
            if (tilt_pos < SERVO_MIN_PULSE_WIDTH) tilt_pos = SERVO_MIN_PULSE_WIDTH;
            move_servo(TILT_SERVO_PIN, tilt_pos);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

