static int create_motion_captures_dir(void) {
    struct stat st;
    if (stat("motion_captures", &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            return 0;
        }
        fprintf(stderr, "Error: 'motion_captures' exists but is not a directory\n");
        return -1;
    }
    if (mkdir("motion_captures", 0755) != 0) {
        if (errno == EEXIST) {
            return 0;
        }
        fprintf(stderr, "Error creating 'motion_captures' directory: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

