#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define PIR_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000
#define DEBOUNCE_POLL_MS (DEBOUNCE_MS * 1000 / POLL_TIMEOUT_MS)
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define IMAGE_TIMEOUT_MS 2000
#define CAPTURE_CMD "libcamera-still"
#define CAPTURE_ARG_FMT "--o %s --width %d --height %d -q %d --timeout %d --nopreview"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(const char *filename) {
    char cmd[512];
    snprintf(cmd, sizeof(cmd), "%s %s", CAPTURE_CMD, filename);
    int ret = system(cmd);
    if (ret == -1) {
        perror("Error executing libcamera-still");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "libcamera-still failed (exit status %d)\n", ret);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir-motion-capture") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    log_event("Motion detection system started.");

    while (program_running) {
        struct timespec ts = {0, DEBOUNCE_POLL_MS * 1000000L};
        int ev = gpiod_line_event_wait(pir_line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ev == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        struct timespec ts_start, ts_now;
        clock_gettime(CLOCK_MONOTONIC, &ts_start);

        while (program_running) {
            if (!gpiod_line_event_wait(pir_line, &ts)) break;
            if (gpiod_line_event_read(pir_line, &event) < 0) break;
            if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) break;
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            if ((ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                  (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L >= DEBOUNCE_MS) {
                break;
            }
        }

        if (!program_running) break;

        time_t rawtime;
        struct tm *timeinfo;
        char filename[256];
        char timestamp[32];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (!timeinfo) {
            perror("localtime");
            continue;
        }

        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
        snprintf(filename, sizeof(filename), "%s/%s_mmm.jpg",
                 IMAGE_DIR, timestamp);

        if (capture_image(filename) == 0) {
            log_event(filename);
        } else {
            log_event("Failed to capture image.");
        }
    }

    log_event("Motion detection system stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

