#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define NEUTRAL_ANGLE 90
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile int running = 1;

void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

int set_servo_angle(int gpio, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle %d out of range (0-180)\n", angle);
        return -1;
    }
    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);
    if (gpioServo(gpio, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for GPIO %d (pulse %d)\n", gpio, pulse_width);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE) < 0 || set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE) < 0) {
        gpioTerminate();
        return 1;
    }

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    char key;
    while (running) {
        key = getchar();
        if (key == 'q' || key == 'Q') {
            break;
        }

        switch (key) {
            case 'a':
                pan_angle += STEP_SIZE;
                if (pan_angle > 180) pan_angle = 180;
                break;
            case 'd':
                pan_angle -= STEP_SIZE;
                if (pan_angle < 0) pan_angle = 0;
                break;
            case 'w':
                tilt_angle += STEP_SIZE;
                if (tilt_angle > 180) tilt_angle = 180;
                break;
            case 's':
                tilt_angle -= STEP_SIZE;
                if (tilt_angle < 0) tilt_angle = 0;
                break;
        }

        if (set_servo_angle(PAN_GPIO, pan_angle) < 0 || set_servo_angle(TILT_GPIO, tilt_angle) < 0) {
            break;
        }
        usleep(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
    return 0;
}

