#define SSD1306_HEIGHT 64
#define SSD1306_PAGES (SSD1306_HEIGHT / 8)

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define CPU_USAGE_FILE "/proc/stat"

#define ERROR_TEMP -1000.0f
#define ERROR_CPU_USAGE -1.0f

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    char data[20];
} cpu_usage_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_usage(cpu_usage_t *usage) {
    FILE *fp = fopen(CPU_USAGE_FILE, "r");
    if (!fp) {
        perror("Failed to open CPU usage file");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        perror("Failed to read CPU usage file");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *token = strtok(line, " ");
    if (!token) {
        fprintf(stderr, "Failed to parse CPU usage data\n");
        return -1;
    }

    usage->data[0] = 0;
    usage->data[1] = 0;

    char *endptr;
    long user = strtol(token, &endptr, 10);
    if (endptr == token) {
        fprintf(stderr, "Failed to parse user time\n");
        return -1;
    }

    token = strtok(NULL, " ");
    if (!token) {
        fprintf(stderr, "Failed to parse system time\n");
        return -1;
    }

    long sys = strtol(token, &endptr, 10);
    if (endptr == token) {
        fprintf(stderr, "Failed to parse system time\n");
        return -1;
    }

    usage->data[2] = (sys - user) / 1000000000LL;
    usage->data[3] = (sys - user) % 1000000000LL / 1000000LL;
    usage->data[4] = (sys - user) % 1000000000LL % 1000000LL / 10000LL;
    usage->data[5] = (sys - user) % 1000000000LL % 1000000LL % 10000LL / 1000LL;
    usage->data[6] = (sys - user) % 1000000000LL % 1000000LL % 1000000LL / 100LL;
    usage->data[7] = (sys - user) % 1000000000LL % 1000000LL % 1000000LL % 100LL;
    usage->data[8] = (sys - user) % 1000000000LL % 1000000LL % 1000000LL % 10LL;
    usage->data[9] = (sys - user) % 1000000000LL % 1000000LL % 1000000LL % 1LL;

    return 0;
}

static float read_cpu_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return ERROR_TEMP;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        perror("Failed to read temperature file");
        fclose(fp);
        return ERROR_TEMP;
    }
    fclose(fp);

    char *token = strtok(line, " ");
    if (!token) {
        fprintf(stderr, "Failed to parse temperature data\n");
        return ERROR_TEMP;
    }

    char *endptr;
    long temp = strtol(token, &endptr, 10);
    if (endptr == token) {
        fprintf(stderr, "Failed to parse temperature value\n");
        return ERROR_TEMP;
    }

    return (float)temp / 1000.0f;
}

static void display_text(int page, int col, const char *text) {
    if (page < 0 || page >= SSD1306_PAGES || col < 0 || col >= SSD1306_WIDTH) {
        return;
    }

    char command[3];
    int len = strlen(text);
    if (len > 16) {
        len = 16;
    }
    snprintf(command, sizeof(command), "G3_PAGE%d_START_X%d_Y%d_MODE3", page, col, 0);

    if (i2cWriteDevice(i2c_handle, command, 1) != 0) {
        fprintf(stderr, "I2C write failed for page %d, col %d\n", page, col);
        return;
    }

    if (len > 0) {
        if (i2cWriteDevice(i2c_handle, text, len) != 0) {
            fprintf(stderr, "I2C write failed for page %d, col %d\n", page, col);
        }
    }
}

static void display_bitmap(int page, int col, const unsigned char *bitmap, int width) {
    if (page < 0 || page >= SSD1306_PAGES || col < 0 || col >= SSD1306_WIDTH) {
        return;
    }

    char command[3];
    int len = width * 8;
    if (len > 16) {
        len = 16;
    }
    snprintf(command, sizeof(command), "G3_PAGE%d_START_X%d_Y%d_MODE3", page, col, 0);

    if (i2cWriteDevice(i2c_handle, command, 1) != 0) {
        fprintf(stderr, "I2C write failed for page %d, col %d\n", page, col);
        return;
    }

    if (len > 0) {
        if (i2cWriteDevice(i2c_handle, bitmap, len) != 0) {
            fprintf(stderr, "I2C write failed for page %d, col %d\n", page, col);
        }
    }
}

static void display_error(const char *message) {
    display_text(0, 0, message);
    display_bitmap(0, 0, (unsigned char[]){0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, 8);
}

static void display_usage(float cpu_usage) {
    char temp_str[32];
    char usage_str[32];

    snprintf(temp_str, sizeof(temp_str), "Temp: %.2f C", read_cpu_temperature());
    snprintf(usage_str, sizeof(usage_str), "CPU: %d%%", cpu_usage);

    display_text(0, 0, "Temp: ");
    display_bitmap(0, 0, (unsigned char*)temp_str, 16);

    display_text(1, 0, "CPU: ");
    display_bitmap(1, 0, (unsigned char*)usage_str, 16);
}

static void display_error_text(const char *message) {
    display_text(0, 0, message);
}

