#define I2C_BUS 1
#define I2C_ADDR 0x27
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_US 1000000
#define UPDATE_INTERVAL_US 10000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(void) {
    int count = 0;
    int last_state = gpioRead(FLOW_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", FLOW_SENSOR_GPIO);
        return -1;
    }
    while (running) {
        int current_state = gpioRead(FLOW_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", FLOW_SENSOR_GPIO);
            return -1;
        }
        if (current_state == 1 && last_state == 0) {
            count++;
        }
        last_state = current_state;
        usleep(1000);
    }
    return (int)(count * PULSES_PER_LITER / 1000.0);
}

static void update_lcd(float total_volume) {
    char line1[20], line2[20];
    snprintf(line1, sizeof(line1), "Flow Rate: %.2f L/min", total_volume / 60.0);
    snprintf(line2, sizeof(line2), "Total Volume: %.2f L", total_volume);
