#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

#define ROW_PINS {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_PINS {5, 6, 12, 13, 19, 16, 26, 20}

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW_PINS[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row GPIO %d\n", ROW_PINS[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led-matrix", 1) < 0) {
            fprintf(stderr, "Failed to request row GPIO %d as output\n", ROW_PINS[i]);
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, COL_PINS[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col GPIO %d\n", COL_PINS[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led-matrix", 0) < 0) {
            fprintf(stderr, "Failed to request col GPIO %d as output\n", COL_PINS[i]);
            return -1;
        }
    }

    return 0;
}

static void scan_display(const int *pattern) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            int val = (pattern[row * NUM_COLS + col] == 1) ? 0 : 1;
            if (gpiod_line_set_value(row_lines[row], val) < 0) {
                perror("gpiod_line_set_value (row)");
                release_resources();
                exit(EXIT_FAILURE);
            }
            if (gpiod_line_set_value(col_lines[col], 0) < 0) {
                perror("gpiod_line_set_value (col)");
                release_resources();
                exit(EXIT_FAILURE);
            }
        }
    }
}

static void display_wave(const int *pattern) {
    for (int i = 0; i < NUM_ROWS && keep_running; i++) {
        scan_display(pattern);
        usleep(SCAN_DELAY_US);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        release_resources();
        return EXIT_FAILURE;
    }

    int left_wave[] = {1, 1, 1, 1, 0, 0, 0, 0};
    int right_wave[] = {0, 0, 0, 0, 1, 1, 1, 1};

    while (keep_running) {
        display_wave(left_wave);
        if (!keep_running) break;
        display_wave(right_wave);
    }

    release_resources();
    return EXIT_SUCCESS;
}

