            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], CONSUMER, 1) < 0) {
            perror("gpiod_line_request_output (row)");
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], CONSUMER, 1) < 0) {
            perror("gpiod_line_request_output (col)");
            return -1;
