            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], CONSUMER, 1) < 0) {
            perror("gpiod_line_request_output (col)");
            return -1;
        }
    }

    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_set_value(row_lines[i], 1);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_set_value(col_lines[i], 1);
    }
}

static void light_column(int col) {
    if (col < 0 || col >= NUM_COLS) return;
    gpiod_line_set_value(col_lines[col], 0);
    clear_matrix();
    usleep(150000);
    gpiod_line_set_value(col_lines[col], 1);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        release_resources();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        for (int col = 0; col < NUM_COLS && keep_running; col++) {
            light_column(col);
        }
    }

    release_resources();
    return EXIT_SUCCESS;
}

