/*
 * VL53L3CX Time-of-Flight Sensor Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download sequence
 * during initialization. This stub implementation assumes the firmware
 * is already loaded and the sensor is ready. In a production system,
 * this section would be replaced with the ST Ultra Lite Driver (ULD)
 * initialization sequence.
 *
 * Build: gcc -Wall -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29

/* VL53L3CX Register Map (simplified for demonstration) */
#define VL53L3CX_REG_MODEL_ID 0x010F
#define VL53L3CX_REG_SOFT_RESET 0x0003
#define VL53L3CX_REG_SYSTEM_START 0x0001
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_DISTANCE 0x0096

#define EXPECTED_MODEL_ID 0xEA

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Write a 16-bit value to a 16-bit register address */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit value from a 16-bit register address */
static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(data_buf[0] & 0xFF) << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Read a 16-bit value from a 16-bit register address (with auto-increment) */
static int i2c_read_reg16_auto(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(data_buf[0] & 0xFF) << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Initialize the VL53L3CX sensor */
static int initialize_sensor(int handle) {
    uint16_t model_id = 0;

    /* Soft reset */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Soft reset failed.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset */

    /* Check model ID */
    if (i2c_read_reg16(handle, VL53L3CX_REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID: 0x%04X (expected 0x%02X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    printf("VL53L3CX detected. Model ID: 0x%04X\n", model_id);

    /* Start continuous ranging */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

/* Read distance data from the sensor */
static int read_distance_data(int handle, uint16_t *distances) {
    uint16_t status = 0;
    uint16_t distance = 0;
    int retries = 10;

    while (retries > 0) {
        /* Read range status */
        if (i2c_read_reg16(handle, VL53L3CX_REG_RESULT_RANGE_STATUS, &status) != 0) {
            fprintf(stderr, "Error: Failed to read range status.\n");
            gpioDelay(100000); /* 100 ms backoff */
            retries--;
            continue;
        }

        /* Check if data is ready */
        if ((status & 0x0001) == 0) {
            break; /* Data not ready yet */
        }

        /* Read distance for each target */
        for (int i = 0; i < 4; i++) {
            if (i2c_read_reg16_auto(handle, VL53L3CX_REG_RESULT_DISTANCE + (i * 2), &distance) != 0) {
                fprintf(stderr, "Error: Failed to read distance for target %d.\n", i);
                gpioDelay(100000); /* 100 ms backoff */
                retries--;
                continue;
            }
        }

        /* Check if all targets are valid */
        if ((status & 0x0001) == 0 && (status & 0x0001) == 0) {
            break; /* All targets valid */
        }

        gpioDelay(10000); /* 10 ms delay before retrying */
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read distance data after multiple retries.\n");
        return -1;
    }

    distances[0] = distance; /* Target 0 */
    distances[1] = distance; /* Target 1 */
    distances[2] = distance; /* Target 2 */
    distances[3] = distance; /* Target 3 */

    return 0;
}

/* Log data with ISO-8601 timestamp */
static void log_data(uint16_t distances[4]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("[%s] Distance: %u, %u, %u, %u mm\n",
           timestamp,
           distances[0], distances[1], distances[2], distances[3]);
}

int main() {
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n",
                VL53L3CX_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L3CX sensor initialized. Reading distance data every 100 ms...\n");

    /* Main loop */
    while (running) {
        uint16_t distances[4];

        if (read_distance_data(i2c_handle, distances) == 0) {
            log_data(distances);
        } else {
            fprintf(stderr, "Warning: Failed to read distance data.\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Clean up resources */
    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

