static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,Distance\n") < 0) {
            fprintf(stderr, "Error: Failed to write CSV header.\n");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(log_file);
    }

    printf("MLX75031 Distance Logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t distance = 0;
        if (read_distance(&distance) == 0) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Warning: Logging failed, attempting to re-open I2C.\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                if (init_i2c() != 0) {
                    fprintf(stderr, "Fatal: I2C re-initialization failed. Exiting.\n");
                    break;
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance. Attempting to re-open I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "Fatal: I2C re-initialization failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

