static int write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    char wbuf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, wbuf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) failed: reg=0x%02X\n", reg);
        return -1;
    }
    char rbuf[1];
    if (i2cReadDevice(i2c_handle, rbuf, 1) != 1) {
        fprintf(stderr, "I2C read failed: reg=0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)rbuf[0];
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;
    if (read_reg(SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0) return -1;
    gpioDelay(10000);

    if (write_reg(SI1145_REG_HW_KEY, 0x17) != 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE0, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_ENABLE, 0x00) != 0) return -1;

    return 0;
}

