#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1145 I2C default address (ADDR pin tied to GND) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define REG_PART_ID          0x00
#define REG_HW_KEY           0x07
#define REG_MEAS_RATE0       0x08
#define REG_MEAS_RATE1       0x09
#define REG_PS_RATE          0x0A
#define REG_ALS_RATE         0x0B
#define REG_PS_LED21         0x0C
#define REG_ALS_LED21        0x0D
#define REG_COMMAND          0x30
#define REG_PS1_DATA0        0x18
#define REG_PS1_DATA1        0x19
#define REG_ALS_VIS_DATA0    0x22
#define REG_ALS_VIS_DATA1    0x23
#define REG_CH_LIST          0x4F

/* Si1145 command codes */
#define CMD_PS_FORCE         0x06
#define CMD_ALS_FORCE        0x07

/* Expected PART_ID for Si1145 */
#define EXPECTED_PART_ID     0x45

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): %s\n",
                reg, len, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1145 initialization                                               */
/* ------------------------------------------------------------------ */
static int si1145_init(void)
{
    uint8_t part_id = 0;

    /* Verify sensor identity */
    if (i2c_read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID = 0x%02X).\n", part_id);

    /* Write HW_KEY to enable the device */
    if (i2c_write_reg(REG_HW_KEY, 0x17) != 0)
        return -1;

    /* Enable PS1 and ALS_VIS channels in CH_LIST */
    if (i2c_write_reg(REG_CH_LIST, 0x03) != 0)
        return -1;

    /* Set measurement rates */
    if (i2c_write_reg(REG_MEAS_RATE0, 0x0A) != 0)
        return -1;
    if (i2c_write_reg(REG_MEAS_RATE1, 0x00) != 0)
        return -1;
    if (i2c_write_reg(REG_PS_RATE, 0x0A) != 0)
        return -1;
    if (i2c_write_reg(REG_ALS_RATE, 0x0A) != 0)
        return -1;

    /* Configure LED currents for PS1 and ALS_VIS */
    if (i2c_write_reg(REG_PS_LED21, 0x3F) != 0)
        return -1;
    if (i2c_write_reg(REG_ALS_LED21, 0x3F) != 0)
        return -1;

    /* Start with a clean state */
    if (i2c_write_reg(REG_COMMAND, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair                            */
/* ------------------------------------------------------------------ */
static int si1145_read_reg16(uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg(reg_low, &lo) != 0)
        return -1;
    if (i2c_read_reg(reg_low + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a forced measurement and read both channels                */
/* ------------------------------------------------------------------ */
static int si1145_read_data(uint16_t *proximity, uint16_t *ambient)
{
    /* Trigger PS_FORCE measurement */
    if (i2c_write_reg(REG_COMMAND, CMD_PS_FORCE) != 0)
        return -1;

    /* Wait for measurement to complete (PS_FORCE typically ~10 ms) */
    gpioDelay(15000); /* 15 ms */

    /* Trigger ALS_FORCE measurement */
    if (i2c_write_reg(REG_COMMAND, CMD_ALS_FORCE) != 0)
        return -1;

    /* Wait for ALS_FORCE measurement to complete */
    gpioDelay(15000); /* 15 ms */

    /* Read PS1 data */
    if (si1145_read_reg16(REG_PS1_DATA0, proximity) != 0)
        return -1;

    /* Read ALS_VIS data */
    if (si1145_read_reg16(REG_ALS_VIS_DATA0, ambient) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to the CSV file                                        */
/* ------------------------------------------------------------------ */
static int log_data(uint16_t proximity, uint16_t ambient)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient) < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1145 default address */
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device (handle %d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,proximity,ambient_light\n");
        fflush(log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting data acquisition (Ctrl+C to stop)...\n");

    /* Main acquisition loop */
    while (!terminate) {
        uint16_t proximity = 0, ambient = 0;

        if (si1145_read_data(&proximity, &ambient) == 0) {
            printf("Proximity: %u, Ambient Light: %u\n", proximity, ambient);
            if (log_data(proximity, ambient) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        }

        /* Sleep 1 second (microseconds) */
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

