#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define LOG_FILE "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define POLL_INTERVAL_S 60
#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define WATER_THRESHOLD_CM 15.0f

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void log_distance(float distance) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

static void log_reminder(void) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
    fflush(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int trigger_sensor(void) {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int measure_echo_pulse(void) {
    struct timespec start, end;
    int timeout_count;

    if (gpiod_line_event_wait(echo_line, NULL) < 0) {
        fprintf(stderr, "Error waiting for echo event: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_event_read(echo_line, &start) < 0) {
        fprintf(stderr, "Error reading start event: %s\n", strerror(errno));
        return -1;
    }

    timeout_count = 0;
    while (gpiod_line_event_wait(echo_line, NULL) > 0) {
        if (timeout_count++ > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
    }

    if (gpiod_line_event_read(echo_line, &end) < 0) {
        fprintf(stderr, "Error reading end event: %s\n", strerror(errno));
        return -1;
    }

    long pulse_duration_ns = (end.tv_sec - start.tv_sec) * 1000000000L +
                             (end.tv_nsec - start.tv_nsec);
    return (int)pulse_duration_ns;
}

static float calculate_distance(int pulse_duration_us) {
    if (pulse_duration_us <= 0) return -1.0f;
    return (float)pulse_duration_us * 34300.0f / 2.0f;
}

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        log_error("GPIO initialization failed");
        fclose(log_file);
        return 1;
    }

    log_message("System started");

    while (program_running) {
        if (trigger_sensor() < 0) {
            log_error("Trigger sensor failed");
            sleep(POLL_INTERVAL_S);
            continue;
        }

        int pulse_duration = measure_echo_pulse();
        if (pulse_duration < 0) {
            log_error("Echo measurement failed");
            sleep(POLL_INTERVAL_S);
            continue;
        }

        float distance = calculate_distance(pulse_duration);
        if (distance < 0.0f || distance > MAX_DISTANCE_CM) {
            log_error("Distance out of valid range");
        } else if (distance < MIN_DISTANCE_CM || distance > WATER_THRESHOLD_CM) {
            log_reminder();
        } else {
            log_distance(distance);
        }

        sleep(POLL_INTERVAL_S);
    }

    log_message("System shutting down");
    cleanup_gpio();
    if (log_file) fclose(log_file);
    return 0;
}

