#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_ADDR 0x39

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_RED_L 0x96
#define APDS9960_RED_H 0x97
#define APDS9960_GREEN_L 0x98
#define APDS9960_GREEN_H 0x99
#define APDS9960_BLUE_L 0x9A
#define APDS9960_BLUE_H 0x9B
#define APDS9960_PROX_L 0x9C

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int apds9960_init(int handle) {
    uint8_t id;
    if (i2c_read_word(handle, APDS9960_ID, &id) < 0) {
        return -1;
    }
    if (id != 0xAB) {
        fprintf(stderr, "Unexpected APDS9960 ID: 0x%02X (expected 0xAB)\n", id);
        return -1;
    }

    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_ATIME, 0xDB) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_WTIME, 0xF6) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PPULSE, 0x87) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;

    return 0;
}

static int read_color_proximity(int handle, uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    if (i2c_read_word(handle, APDS9960_RED_L, red) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_GREEN_L, green) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_BLUE_L, blue) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_PROX_L, proximity) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            red, green, blue, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, APDS9960_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (apds9960_init(i2c_handle) < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

