    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("APDS9960 color and proximity logger started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t red, green, blue, proximity;
        if (read_color_proximity(i2c_handle, &red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(log_file, red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Read error; re-opening I2C bus and re-initializing sensor.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
