#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define SI1182_I2C_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define CSV_FILE "heartrate.csv"
#define SAMPLE_INTERVAL_MS 100

/* Si1182 register addresses */
#define REG_PART_ID          0x00
#define REG_MEAS_RATE0       0x08
#define REG_COMMAND          0x47
#define REG_PS_DATA0         0x24
#define REG_PS_DATA1         0x25

#define EXPECTED_PART_ID     0x82
#define MEAS_RATE_1HZ        0x00
#define CMD_RESET            0x01

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X, 2 bytes) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(void) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(i2c_fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X). Wrong sensor?\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X).\n", part_id);

    /* Set continuous proximity measurement rate */
    if (i2c_write_reg8(i2c_fd, REG_MEAS_RATE0, MEAS_RATE_1HZ) != 0) {
        fprintf(stderr, "Failed to set MEAS_RATE0.\n");
        return -1;
    }

    /* Issue software reset */
    if (i2c_write_reg8(i2c_fd, REG_COMMAND, CMD_RESET) != 0) {
        fprintf(stderr, "Failed to send reset command.\n");
        return -1;
    }
    usleep(10000); /* allow reset to complete */

    return 0;
}

static int read_proximity(uint16_t *prox) {
    return i2c_read_reg16(i2c_fd, REG_PS_DATA0, prox);
}

static int calculate_bpm(uint16_t prox) {
    /* Placeholder linear BPM calculation */
    return (int)(((float)prox / 100.0f) * 60.0f);
}

static int log_data(uint16_t prox, int bpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(csv_fp, "%s,%d\n", timestamp, bpm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(csv_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", SI1182_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    csv_fp = fopen(CSV_FILE, "a");
    if (csv_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Logging heart rate to %s every %d ms. Press Ctrl+C to stop.\n", CSV_FILE, SAMPLE_INTERVAL_MS);

    while (running) {
        uint16_t prox = 0;
        if (read_proximity(&prox) != 0) {
            fprintf(stderr, "Warning: proximity read failed, skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        int bpm = calculate_bpm(prox);
        if (log_data(prox, bpm) != 0) {
            fprintf(stderr, "Warning: CSV write failed.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    if (csv_fp) fclose(csv_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

