    if (bytes != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2)\n", bytes);
        return -1;
    }

    *distance_mm = ((buf[0] << 8) | (buf[1] & 0xFF));
    return 0;
