#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 20.0f
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

static int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: I2C open failed (bus=%d, addr=0x%02X): %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

static int read_distance(int handle) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (returned %d)\n", result);
        return -1;
    }
    int distance = (buf[0] << 8) | buf[1];
    return distance;
}

static void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(fp);
}

static void control_led(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", gpio);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_pigpio() < 0) {
        return EXIT_FAILURE;
    }

    i2c_handle = init_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    printf("Starting distance monitoring (threshold: %.1f cm)...\n", DISTANCE_THRESHOLD);

    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(distance / 10.0f);
            control_led(GPIO_LED, (distance < DISTANCE_THRESHOLD) ? 1 : 0);
        } else {
            fprintf(stderr, "Warning: Invalid distance reading, skipping log and LED control\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

