#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Si1182-GMR I2C address (7-bit) */
#define SI1182_ADDR 0x60

/* Register addresses (from datasheet) */
#define SI1182_REG_ALS_DATA_L 0x16
#define SI1182_REG_ALS_DATA_H 0x17
#define SI1182_REG_PS1_DATA_L 0x18
#define SI1182_REG_PS1_DATA_H 0x19

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 100000  /* 100 ms */

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown (SIGINT / Ctrl+C) */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register with retry logic */
static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Warning: I2C read failed (reg 0x%02X, attempt %d/%d): %s\n",
                    reg, retries, MAX_RETRIES, strerror(errno));
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

/* Read proximity data with retry logic */
static int read_proximity(int handle, uint16_t *proximity) {
    return read_register16(handle, SI1182_REG_PS1_DATA_L, proximity);
}

/* Read ambient light data with retry logic */
static int read_ambient_light(int handle, uint16_t *ambient_light) {
    return read_register16(handle, SI1182_REG_ALS_DATA_L, ambient_light);
}

/* Log data to file with timestamp */
static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n",
            timestamp, proximity, ambient_light);
    fflush(fp);
}

int main(void) {
    uint16_t proximity, ambient_light;
    int result;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection on bus 1 at address 0x60 */
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d: %s\n",
                SI1182_ADDR, I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for SIGINT (Ctrl+C) */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Si1182-GMR logger started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        result = read_proximity(i2c_handle, &proximity);
        if (result == 0) {
            result = read_ambient_light(i2c_handle, &ambient_light);
            if (result == 0) {
                log_data(log_file, proximity, ambient_light);
            } else {
                fprintf(stderr, "Warning: Failed to read ambient light data\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read proximity data\n");
        }

        gpioDelay(500000); /* 500 ms */
    }

    /* Clean resource release on exit */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

