#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x50
#define NUM_SAMPLES    10
#define INTRUSION_THRESH 1000
#define LOG_FILE       "intrusion_log.txt"
#define SAMPLE_DELAY_MS 100
#define MEAS_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t data[15];
    if (i2c_read_data(fd, data, sizeof(data)) < 0)
        return -1;

    if (data[0] != SENSOR_ADDR) {
        fprintf(stderr, "Sensor NACK: header 0x%02X (expected 0x%02X)\n",
                data[0], SENSOR_ADDR);
        return -1;
    }

    uint16_t distance = (uint16_t)((data[11] << 8) | data[12]);
    *distance_mm = distance;
    return 0;
}

static int log_intrusion(int distance_mm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Intrusion detected! Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int sum = 0;
        int valid = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            int distance;
            if (read_distance(fd, &distance) == 0) {
                sum += distance;
                valid++;
            } else {
                fprintf(stderr, "Sensor read error (sample %d)\n", i);
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid > 0) {
            int avg_distance = sum / valid;
            if (avg_distance < INTRUSION_THRESH) {
                printf("Intrusion detected! Average distance: %d mm\n", avg_distance);
                if (log_intrusion(avg_distance) < 0) {
                    fprintf(stderr, "Failed to log intrusion.\n");
                }
            }
        } else {
            fprintf(stderr, "No valid readings in this cycle.\n");
        }
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return 0;
}

