#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L0X_ADDR        0x29
#define I2C_BUS             1
#define POLL_TIMEOUT_MS     100
#define LOOP_DELAY_MS       500

/* VL53L0X register addresses */
#define REG_SYSRANGE_START  0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS      0x14
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0B
#define REG_MODEL_ID              0xC0
#define EXPECTED_MODEL_ID         0xEE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance)
{
    uint8_t status;
    int elapsed = 0;

    /* Start a single-shot ranging measurement */
    if (write_register(handle, REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS until bit 0 is set (data ready) */
    while (elapsed < POLL_TIMEOUT_MS) {
        if (read_register(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        elapsed++;
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for ranging data\n");
        return -1;
    }

    /* Read 16-bit distance from RESULT_RANGE_STATUS (two bytes, little-endian) */
    uint8_t lo, hi;
    if (read_register(handle, REG_RESULT_RANGE_STATUS, &lo) < 0)
        return -1;
    if (read_register(handle, REG_RESULT_RANGE_STATUS + 1, &hi) < 0)
        return -1;
    *distance = (uint16_t)((hi << 8) | lo);

    /* Clear the interrupt so the next measurement can be triggered */
    if (write_register(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Distance: %u mm\n", buffer, (unsigned)rawtime);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading model ID */
    uint8_t model_id = 0;
    if (read_register(g_i2c_handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Cannot read model ID — sensor not present or bus error\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance sensor ready. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t distance = 0;
        if (read_distance(g_i2c_handle, &distance) == 0) {
            print_timestamp();
        } else {
            fprintf(stderr, "Read failed; will retry next cycle\n");
        }
        gpioDelay(LOOP_DELAY_MS * 1000); /* gpioDelay takes microseconds */
    }

    printf("\nExiting gracefully...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

