#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define REG_AMBIENT_LIGHT 0x02
#define REG_DISTANCE_0 0x03
#define REG_DISTANCE_1 0x04

#define REG_AMBIENT_LIGHT_LSB 0x05
#define REG_AMBIENT_LIGHT_MSB 0x06
#define REG_DISTANCE_0_LSB 0x07
#define REG_DISTANCE_0_MSB 0x08
#define REG_DISTANCE_1_LSB 0x09
#define REG_DISTANCE_1_MSB 0x0A

#define EXPECTED_CONFIG_VALUE 0x00
#define EXPECTED_AMBIENT_LIGHT_LSB 0x00
#define EXPECTED_AMBIENT_LIGHT_MSB 0x00
#define EXPECTED_DISTANCE_0_LSB 0x00
#define EXPECTED_DISTANCE_0_MSB 0x00
#define EXPECTED_DISTANCE_1_LSB 0x00
#define EXPECTED_DISTANCE_1_MSB 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_distance_channel(int handle, uint8_t channel) {
    uint8_t lsb, msb;
    if (read_register(handle, REG_DISTANCE_0_LSB + (channel * 2), &lsb) < 0) return -1;
    if (read_register(handle, REG_DISTANCE_0_MSB + (channel * 2), &msb) < 0) return -1;
    return (msb << 8) | lsb;
}

static int read_ambient_light(int handle) {
    uint8_t lsb, msb;
    if (read_register(handle, REG_AMBIENT_LIGHT_LSB, &lsb) < 0) return -1;
    if (read_register(handle, REG_AMBIENT_LIGHT_MSB, &msb) < 0) return -1;
    return (msb << 8) | lsb;
}

static int init_opt3101(int handle) {
    uint8_t config = EXPECTED_CONFIG_VALUE;
    if (write_register(handle, REG_CONFIG, config) < 0) return -1;
    gpioDelay(10000);
    uint8_t ambient_light = EXPECTED_AMBIENT_LIGHT_LSB;
    if (read_register(handle, REG_AMBIENT_LIGHT, &ambient_light) < 0) return -1;
    if (ambient_light != EXPECTED_AMBIENT_LIGHT_LSB) {
        fprintf(stderr, "Ambient light check failed: got 0x%02X, expected 0x%02X\n", ambient_light, EXPECTED_AMBIENT_LIGHT_LSB);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, OPT3101_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_opt3101(i2c_handle) < 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3101 initialized. Logging every 500 ms...\n");

    while (running) {
        uint8_t ambient_light = read_ambient_light(i2c_handle);
        if (ambient_light < 0) {
            fprintf(stderr, "Error reading ambient light\n");
        } else {
            uint8_t distance_0 = read_distance_channel(i2c_handle, 0);
            uint8_t distance_1 = read_distance_channel(i2c_handle, 1);
            if (distance_0 < 0 || distance_1 < 0) {
                fprintf(stderr, "Error reading distance data\n");
            } else {
                printf("Ambient Light: %u, Distance 0: %u, Distance 1: %u\n", ambient_light, distance_0, distance_1);
            }
        }
        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

