#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kOhm series resistor
 *   HC-SR04 VCC  -> 5V (external supply recommended; Pi 3.3V pin is insufficient)
 *   HC-SR04 GND  -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND_CM_PER_US 0.0343f   /* cm per microsecond at 20 C */
#define MAX_PULSE_US             38000     /* HC-SR04 max range timeout (~5 m) */
#define ECHO_TIMEOUT_US          200000    /* 200 ms timeout for echo edges */
#define SAMPLE_PERIOD_US         1000000   /* 1 second between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in cm from the HC-SR04.                               */
/* Returns 0 on success, -1 on timeout, -2 on invalid pulse.           */
/* ------------------------------------------------------------------ */
static int read_distance(float *distance_cm)
{
    uint32_t start_tick, end_tick;
    uint32_t pulse_us;

    /* --- Issue a 10 us trigger pulse --- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1;
    }

    /* --- Wait for echo rising edge (timeout) --- */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo rising-edge timeout (sensor absent or not responding)\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge (timeout) --- */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo falling-edge timeout (data stuck high)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    pulse_us = end_tick - start_tick;

    /* --- Validate pulse width --- */
    if (pulse_us <= 0) {
        fprintf(stderr, "Error: Invalid pulse duration (%u us)\n", pulse_us);
        return -1;
    }
    if (pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: Pulse width exceeds maximum range (%u us > %d)\n",
                pulse_us, MAX_PULSE_US);
        return -1;
    }

    /* --- Convert to distance --- */
    *distance_cm = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading with a timestamp.                                     */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    float distance;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger init low) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance reader started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d | Sample period: %d us\n",
           TRIGGER_PIN, ECHO_PIN, SAMPLE_PERIOD_US);
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        int rc = read_distance(&distance);

        if (rc == 0) {
            log_reading(distance);
        } else if (rc == -1) {
            /* Timeout / error already reported to stderr */
        }

        /* Sleep for the remainder of the 1 s period */
        uint32_t remaining = SAMPLE_PERIOD_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    /* --- Graceful cleanup --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

