#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0f
#define RANGE_BIN_COUNT 64
#define RANGE_RESOLUTION 0.0486f
#define DATA_FRAME_SIZE 128
#define MAGIC_WORD_SIZE 8
#define LOG_FILE "intrusion_log.csv"

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_data(int fd, uint8_t *buf, int max_len) {
    int total = 0;
    while (total < max_len && running) {
        int n = read(fd, buf + total, max_len - total);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
            perror("UART read error");
            return -1;
        }
        if (n == 0) {
            usleep(10000);
            continue;
        }
        total += n;
    }
    return (total > 0) ? total : -1;
}

static int detect_intrusion(const uint8_t *data, int data_len) {
    if (data_len < (int)sizeof(uint16_t) * RANGE_BIN_COUNT) {
        fprintf(stderr, "Intrusion detection: Insufficient data for %d range bins\n", RANGE_BIN_COUNT);
        return 1;
    }

    uint16_t *range_profile = (uint16_t *)data;
    float distance_threshold = INTRUSION_THRESHOLD * RANGE_RESOLUTION;
    float max_distance = (float)RANGE_BIN_COUNT * RANGE_RESOLUTION;

    for (int i = 0; i < RANGE_BIN_COUNT; i++) {
        float range = (float)range_profile[i];
        if (range < distance_threshold) {
            return 1;
        }
    }
    return 0;
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    uint8_t data_buffer[DATA_FRAME_SIZE];
    int data_len = 0;

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int bytes_read = read_uart_data(uart_fd, data_buffer, sizeof(data_buffer));
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error, exiting\n");
            break;
        }
        if (bytes_read == 0) {
            usleep(100000);
            continue;
        }

        if (memcmp(data_buffer, magic_word, MAGIC_WORD_SIZE) == 0) {
            if (data_len < (int)sizeof(uint16_t) * RANGE_BIN_COUNT) {
                data_len = sizeof(uint16_t) * RANGE_BIN_COUNT;
            }
            memcpy(data_buffer + MAGIC_WORD_SIZE, data_buffer, data_len);
            detect_intrusion(data_buffer, data_len);
            if (data_len > 0) {
                log_intrusion((float)data_len / RANGE_BIN_COUNT);
            }
        } else {
            data_len = 0;
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    if (uart_fd >= 0) close(uart_fd);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

