#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        fprintf(stderr, "Error requesting sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    int last_state = -1;

    while (program_running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
            break;
        }

        int obstacle_detected = (sensor_value == 0);

        if (obstacle_detected && last_state != 1) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
                break;
            }
            if (log_event("Obstacle detected, buzzer activated") < 0) {
                fprintf(stderr, "Error logging event\n");
            }
            last_state = 1;
        } else if (!obstacle_detected && last_state != 0) {
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error deactivating buzzer: %s\n", strerror(errno));
                break;
            }
            if (log_event("Obstacle removed, buzzer deactivated") < 0) {
                fprintf(stderr, "Error logging event\n");
            }
            last_state = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

