#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DISTANCE_REG_H 0x31
#define DISTANCE_REG_L 0x32
#define ALERT_GPIO     17
#define THRESHOLD_CM   10.0f
#define SAMPLE_US      100000  /* 100 ms */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_pigpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit distance value from the two consecutive registers.
 * Returns 0 on success, -1 on error.
 */
static int read_distance(float *distance_cm)
{
    int high, low;

    high = i2cReadByteData(g_i2c_handle, DISTANCE_REG_H);
    if (high < 0) {
        fprintf(stderr, "Error: i2cReadByteData (high byte) failed: %d\n", high);
        return -1;
    }

    low = i2cReadByteData(g_i2c_handle, DISTANCE_REG_L);
    if (low < 0) {
        fprintf(stderr, "Error: i2cReadByteData (low byte) failed: %d\n", low);
        return -1;
    }

    uint16_t raw = ((uint16_t)high << 8) | (uint16_t)low;
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

static int log_distance(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error: cannot open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error: localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f cm\n", timestamp, distance_cm) < 0) {
        perror("Error: fprintf to log file failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error: fclose on log file failed");
        return -1;
    }
    return 0;
}

static void trigger_alert(float distance_cm)
{
    if (distance_cm < THRESHOLD_CM) {
        if (gpioWrite(ALERT_GPIO, 1) < 0) {
            fprintf(stderr, "Warning: gpioWrite(ALERT_GPIO, 1) failed.\n");
        }
        printf("ALERT: Object detected at %.2f cm (threshold %.1f cm)\n",
               distance_cm, THRESHOLD_CM);
    } else {
        if (gpioWrite(ALERT_GPIO, 0) < 0) {
            fprintf(stderr, "Warning: gpioWrite(ALERT_GPIO, 0) failed.\n");
        }
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    if (init_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ALERT_GPIO) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    printf("Starting distance monitoring (threshold %.1f cm, sample every 100 ms)...\n",
           THRESHOLD_CM);

    while (g_running) {
        float distance_cm;

        if (read_distance(&distance_cm) == 0) {
            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "Warning: log_distance failed for this sample.\n");
            }
            trigger_alert(distance_cm);
        } else {
            fprintf(stderr, "Warning: I2C read failed; skipping sample.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

