#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_MODEL_ID  0x010F
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_SYSRANGE_STATUS 0x001
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x002
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x013
#define VL53L1X_REG_RESULT_RANGE_MM          0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR   0x014
#define VL53L1X_REG_SYSTEM_MODE_START        0x007
#define VL53L1X_MODEL_ID_EXPECTED            0xEA
#define I2C_BUS 1
#define LOG_FILE "distance_log.csv"
#define POLL_INTERVAL_US 100000
#define MODE_START_TIMEOUT_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: software reset failed\n");
        return -1;
    }
    gpioDelay(2000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_wait_data_ready(int handle) {
    uint8_t status = 0;
    for (int i = 0; i < MODE_START_TIMEOUT_US; i += 10) {
        if (i2c_read_reg16(handle, VL53L1X_REG_SYSRANGE_INTERRUPT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01) return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "Error: timeout waiting for data ready\n");
    return -1;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_SYSRANGE_INTERRUPT_STATUS, &status, 1) < 0)
        return -1;
    if (!(status & 0x01)) return 1;
    uint8_t range_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, range_buf, 2) < 0)
        return -1;
    *distance_mm = ((uint16_t)range_buf[0] << 8) | range_buf[1];
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;
    return 0;
}

