    if (distance < 300) printf("STOP\n");
    else if (distance < 600) printf("APPROACH\n");
    else if (distance < 1200) printf("SLOW\n");
    else printf("CLEAR\n");
}

static void cleanup(void) {
    if (g_log_file) { fclose(g_log_file); g_log_file = NULL; }
    if (g_i2c_handle >= 0) { i2cClose(g_i2c_handle); g_i2c_handle = -1; }
