        cleanup();
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    printf("Parking Assistance System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (vl53l1x_wait_data_ready(g_i2c_handle) < 0) {
            fprintf(stderr, "Warning: data-ready timeout, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Warning: read error, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        log_distance(g_log_file, distance);
        get_guidance(distance);
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

