#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* CH201 I2C default address (SA0 tied to GND) */
#define CH201_ADDR 0x45

/* CH201 register addresses */
#define CH201_REG_CONFIG 0x00
#define CH201_REG_DISTANCE 0x01

/* LED GPIO pin */
#define LED_PIN 18

/* Blink frequency range (Hz) */
#define MIN_FREQUENCY 1.0f
#define MAX_FREQUENCY 10.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* I2C open retry count */
#define I2C_OPEN_RETRIES 3

/* I2C read retry delay (microseconds) */
#define I2C_RETRY_DELAY_US 10000

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* CH201 config: 100 samples, 100 Hz, 100 mm range */
#define CH201_CONFIG_VALUE 0x0000000A

/* Distance mapping: 50 mm -> 10 Hz, 500 mm -> 1 Hz */
#define MIN_DISTANCE 50.0f
#define MAX_DISTANCE 500.0f

/* Half-cycle delay for LED blink (microseconds) */
#define HALF_CYCLE_DELAY_US 50000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                                */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    for (int attempt = 0; attempt < I2C_OPEN_RETRIES; attempt++) {
        int rc = i2cWriteDevice(i2c_handle, buf, 3);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_OPEN_RETRIES, strerror(errno));
        if (attempt < I2C_OPEN_RETRIES - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg(uint8_t reg, uint16_t *value)
{
    char buf[2];

    for (int attempt = 0; attempt < I2C_OPEN_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
        if (rc == 2) {
            *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_OPEN_RETRIES, strerror(errno));
        if (attempt < I2C_OPEN_RETRIES - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* CH201 initialization                                                */
/* ------------------------------------------------------------------ */
static int init_ch201(void)
{
    if (i2c_write_reg(CH201_REG_CONFIG, CH201_CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to write CH201 config register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settling time */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance conversion                                                  */
/* ------------------------------------------------------------------ */
static float convert_distance(uint16_t raw)
{
    /* CH201: distance = raw * 0.02 mm (100 samples, 100 Hz) */
    return (float)raw * 0.02f;
}

/* ------------------------------------------------------------------ */
/* Blink LED with smooth half-cycle                                     */
/* ------------------------------------------------------------------ */
static void blink_led(float distance)
{
    float distance_range = MAX_DISTANCE - MIN_DISTANCE;
    float distance_in_range = (distance - MIN_DISTANCE) / distance_range;

    float frequency = MIN_FREQUENCY +
                       (distance_in_range * (MAX_FREQUENCY - MIN_FREQUENCY));

    if (frequency < MIN_FREQUENCY)
        frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY)
        frequency = MAX_FREQUENCY;

    int on_us = (int)(frequency * HALF_CYCLE_DELAY_US / 2.0f);
    int off_us = HALF_CYCLE_DELAY_US - on_us;

    gpioWrite(LED_PIN, 1);
    gpioDelay(on_us);
    gpioWrite(LED_PIN, 0);
    gpioDelay(off_us);
}

/* ------------------------------------------------------------------ */
/* Timestamped logging                                                  */
/* ------------------------------------------------------------------ */
static void log_data(float distance, float frequency)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %.2f mm, Blink Frequency: %.2f Hz\n",
           timestamp, distance, frequency);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at CH201 address */
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, CH201_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize CH201 */
    if (init_ch201() != 0) {
        fprintf(stderr, "CH201 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting CH201 distance monitoring (I2C addr 0x%02X, LED on GPIO %d)\n",
           CH201_ADDR, LED_PIN);
    fflush(stdout);

    /* Main sampling loop */
    while (!terminate) {
        uint16_t raw_distance;

        if (i2c_read_reg(CH201_REG_DISTANCE, &raw_distance) != 0) {
            fprintf(stderr, "Sensor read failed; continuing after delay\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float distance = convert_distance(raw_distance);
        blink_led(distance);
        log_data(distance, (float)distance);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

