#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "proximity_log.txt"
#define POLL_INTERVAL_US 10000
#define DEBOUNCE_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d - %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int prev_state[2] = {-1, -1};
    int current_state[2];
    int sensor_ids[2] = {SENSOR_1_GPIO, SENSOR_2_GPIO};
    int debounce_delay[2] = {DEBOUNCE_DELAY_US, DEBOUNCE_DELAY_US};
    int ret = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < 2; i++) {
        if (gpioSetMode(sensor_ids[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", sensor_ids[i]);
            goto cleanup;
        }
        if (gpioSetPullUpDown(sensor_ids[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", sensor_ids[i]);
            goto cleanup;
        }
    }

    printf("Monitoring TCRT5000 sensors on GPIO %d and %d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);

    while (running) {
        for (int i = 0; i < 2; i++) {
            int raw = gpioRead(sensor_ids[i]);
            if (raw < 0) {
                fprintf(stderr, "gpioRead failed on GPIO %d\n", sensor_ids[i]);
                goto cleanup;
            }

            if (raw != prev_state[i]) {
                if (running) {
                    if (raw == 1) {
                        if (log_event(i + 1, "CLEARED") != 0) {
                            fprintf(stderr, "Failed to log CLEARED event for sensor %d\n", i + 1);
                        }
                    } else {
                        if (log_event(i + 1, "DETECTED") != 0) {
                            fprintf(stderr, "Failed to log DETECTED event for sensor %d\n", i + 1);
                        }
                    }
                }
                prev_state[i] = raw;
            }
        }

        gpioDelay(POLL_INTERVAL_US);

        for (int i = 0; i < 2; i++) {
            gpioDelay(debounce_delay[i]);
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();
    return ret;
}

