#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49
#define MEAS_TRIGGER   0x04
#define MEAS_STATUS    0x06
#define DIST_HIGH      0x08
#define DIST_LOW       0x09
#define DATA_READY     0x01
#define POLL_TIMEOUT_MS 50
#define SAMPLE_PERIOD_MS 500
#define CSV_FILENAME   "distance_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg_msb, uint8_t reg_lsb, uint16_t *out)
{
    uint8_t msb, lsb;
    if (i2c_read_byte(fd, reg_msb, &msb) < 0) return -1;
    if (i2c_read_byte(fd, reg_lsb, &lsb) < 0) return -1;
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int trigger_measurement(int fd)
{
    return i2c_write_byte(fd, MEAS_TRIGGER, 0x01);
}

static int wait_data_ready(int fd)
{
    uint8_t status;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_byte(fd, MEAS_STATUS, &status) < 0) return -1;
        if (status & DATA_READY) return 0;
        usleep(1000);
    }
    fprintf(stderr, "Timeout waiting for CH-101 data-ready\n");
    return -1;
}

static int read_distance(int fd, uint16_t *distance_mm)
