#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_US 10000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(int handle, uint16_t *distance) {
    char buf[2];
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        int result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            *distance = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d): %s\n", I2C_RETRY_COUNT - retries, strerror(errno));
        retries--;
        if (retries > 0) gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld Distance: %u mm\n", timestamp, ts.tv_nsec / 1000000, distance);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", MLX75030_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance after retries.\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

