#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* VL53L4CX I2C default address (SA0 tied to GND) */
#define VL53L4CX_ADDR 0x29

/* Register addresses (from datasheet) */
#define REG_SOFT_RESET          0x7FFF
#define REG_SYSTEM_START        0x0009
#define REG_INT_STATUS          0x0046
#define REG_RESULT_HIGH         0x0096
#define REG_RESULT_LOW          0x0097

#define I2C_BUS 1
#define POLL_INTERVAL_US 500000  /* 500 ms */
#define RESET_DELAY_US 10000     /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%04X: %s\n",
                value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit register 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_sensor(int handle)
{
    if (write_reg(handle, REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(RESET_DELAY_US);
    if (write_reg(handle, REG_SYSTEM_START, 0x00) != 0)
        return -1;
    return 0;
}

static int read_distance(int handle, uint16_t *distance)
{
    uint8_t status;
    if (read_reg(handle, REG_INT_STATUS, &status) != 0)
        return -1;
    if (!(status & 0x01))
        return 1;  /* no new data yet */
    if (read_reg16(handle, REG_RESULT_HIGH, distance) != 0)
        return -1;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%06ld", ts.tv_nsec / 1000);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L4CX distance sensor ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = read_distance(g_i2c_handle, &distance);
        if (rc == 0) {
            char ts[40];
            get_timestamp(ts, sizeof(ts));
            printf("%s, Distance: %u mm\n", ts, distance);
            fflush(stdout);
        } else if (rc < 0) {
            fprintf(stderr, "I2C communication error during read\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

