                I2C_BUS, VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
