#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_S 34300.0
#define BUZZER_THRESHOLD_CM 30.0
#define POLL_INTERVAL_US    100000  /* 100 ms */
#define TRIGGER_PULSE_US    10
#define ECHO_TIMEOUT_US     30000   /* 30 ms */
#define MIN_DISTANCE_CM     2.0
#define MAX_DISTANCE_CM     400.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * pigpio's gpioTick() returns a 32-bit microsecond counter that wraps
 * every ~71.6 minutes.  We use a 32-bit subtraction to handle the wrap.
 */
static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;  /* unsigned subtraction wraps correctly */
}

/*
 * Trigger a 10 us HIGH pulse on the trigger pin, then wait for the
 * echo pin to go HIGH.  Returns the echo pulse width in microseconds,
 * or -1 on timeout / no echo.
 */
static int trigger_and_wait_echo(void)
{
    /* Ensure trigger is LOW before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0)
        return -1;
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0)
        return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0)
        return -1;

    uint32_t start_tick = gpioTick();
    uint32_t deadline = start_tick + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() >= deadline)
            return -1;  /* no echo */
    }

    uint32_t echo_start = gpioTick();
    deadline = echo_start + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() >= deadline)
            return -1;  /* echo stuck HIGH */
    }

    uint32_t echo_end = gpioTick();
    return tick_diff(echo_start, echo_end);
}

/*
 * Compute distance in cm from the echo pulse width in microseconds.
 * Returns -1.0 on timeout / no echo, -2.0 on invalid reading.
 */
static float get_distance(uint32_t pulse_us)
{
    if (pulse_us < 0)
        return -1.0;

    /* distance = (pulse_us * speed_of_sound) / 2 */
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_S / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM)
        return -2.0;

    return distance;
}

static void buzzer_on(void)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0)
        fprintf(stderr, "Warning: failed to set buzzer HIGH\n");
}

static void buzzer_off(void)
{
    if (gpioWrite(BUZZER_PIN, 0) < 0)
        fprintf(stderr, "Warning: failed to set buzzer LOW\n");
}

static void buzzer_set(int on)
{
    if (on)
        buzzer_on();
    else
        buzzer_off();
}

static void echo_alert(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        uint32_t pulse = trigger_and_wait_echo();
        if (pulse < 0) {
            fprintf(stderr, "Error: echo timeout on GPIO %d\n", gpio);
            return;
        }
        float distance = get_distance(pulse);
        if (distance < 0.0) {
            fprintf(stderr, "Error: invalid distance %u us on GPIO %d\n",
                    pulse, gpio);
            return;
        }
        printf("Distance: %.2f cm\n", distance);
        buzzer_set(distance < BUZZER_THRESHOLD_CM ? 1 : 0);
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        buzzer_set(0);
    }
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set BUZZER_PIN %d as output\n",
                BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    buzzer_off();

    /* Register alert callback for echo pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_alert, NULL) < 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor running.  Trigger=GPIO%d, Echo=GPIO%d, Buzzer=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    buzzer_off();
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

