#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_RESULT_PEAK_SIGNAL_COUNT 0x0018
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

static int i2c_handle = -1;
static MQTTClient mqtt_client = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x00) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance) {
    uint8_t buf[2];
