        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mqtt_client = MQTTClientCreate(MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, NULL, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Error creating MQTT client\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    MQTTClientSetCallbacks(mqtt_client, NULL, handle_mqtt_message, NULL);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
