#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_PULSE_US             100
#define MAX_PULSE_US             30000
#define TIMEOUT_US               60000   /* 60 ms timeout for echo */
#define MEASURE_INTERVAL_US      200000 /* 200 ms between measurements */
#define TRIGGER_PULSE_US         10

static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int      echo_ready = 0;
static FILE              *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — captures both rising and falling edges     */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        rising_tick = tick;
    } else if (level == 0) {
        falling_tick = tick;
        echo_ready  = 1;
    }
}

/* ------------------------------------------------------------------ */
/* Compute distance in cm from pulse duration in microseconds         */
/* ------------------------------------------------------------------ */
static double calculate_distance(uint32_t pulse_us)
{
    if (pulse_us < MIN_PULSE_US) {
        return -1.0;
    }
    return (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO 8601 timestamp                            */
/* ------------------------------------------------------------------ */
static void log_reading(double distance)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);
    if (log_file) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Log a warning with an ISO 8601 timestamp                            */
/* ------------------------------------------------------------------ */
static void log_warning(const char *msg)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(stderr, "%s WARNING: %s\n", timestamp, msg);
    if (log_file) {
        fprintf(log_file, "%s WARNING: %s\n", timestamp, msg);
        fflush(log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins                           */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on ECHO_PIN %d.\n",
                ECHO_PIN);
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN %d LOW.\n",
                TRIGGER_PIN);
        return -1;
    }

    /* Register alert callback for ECHO */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n",
                ECHO_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the trigger pin                             */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d HIGH.\n",
                TRIGGER_PIN);
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d LOW.\n",
                TRIGGER_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open distance_log.txt: %s\n",
                strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, logging to distance_log.txt\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t start_tick = gpioTick();
        while (!echo_ready && running) {
            if ((gpioTick() - start_tick) > TIMEOUT_US) {
                log_warning("Timeout: no echo received within 60 ms.");
                break;
            }
            gpioDelay(100); /* poll every 100 us */
        }

        if (!echo_ready) {
            /* No valid echo — check timeout */
            if ((gpioTick() - start_tick) > TIMEOUT_US) {
                log_warning("Timeout: no echo received within 60 ms.");
            }
            continue;
        }

        uint32_t pulse_us = falling_tick - rising_tick;
        double distance = calculate_distance(pulse_us);

        if (distance < 0.0) {
            log_warning("Invalid pulse width: out of valid range.");
        } else {
            log_reading(distance);
        }

        /* Wait before next measurement (5 Hz) */
        gpioDelay(MEASURE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

