        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on ECHO_PIN %d.\n",
                ECHO_PIN);
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN %d LOW.\n",
                TRIGGER_PIN);
        return -1;
    }

    /* Register alert callback for ECHO */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n",
                ECHO_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the trigger pin                             */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d HIGH.\n",
                TRIGGER_PIN);
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d LOW.\n",
                TRIGGER_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open distance_log.txt: %s\n",
                strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, logging to distance_log.txt\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t start_tick = gpioTick();
        while (!echo_ready && running) {
            if ((gpioTick() - start_tick) > TIMEOUT_US) {
                log_warning("Timeout: no echo received within 60 ms.");
                break;
            }
            gpioDelay(100); /* poll every 100 us */
        }

        if (!echo_ready) {
            /* No valid echo — check timeout */
            if ((gpioTick() - start_tick) > TIMEOUT_US) {
                log_warning("Timeout: no echo received within 60 ms.");
            }
            continue;
        }

        uint32_t pulse_us = falling_tick - rising_tick;
        double distance = calculate_distance(pulse_us);

        if (distance < 0.0) {
            log_warning("Invalid pulse width: out of valid range.");
        } else {
            log_reading(distance);
        }

        /* Wait before next measurement (5 Hz) */
        gpioDelay(MEASURE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

