#define VL53L1X_SOFT_RESET_VAL 0x01
#define VL53L1X_SYSTEM_START_REG 0x0000
#define VL53L1X_SYSTEM_START_VAL 0x01
#define VL53L1X_RESULT_RANGE_STATUS_REG 0x0089
#define VL53L1X_RESULT_DISTANCE_H_REG 0x0096
#define VL53L1X_RESULT_DISTANCE_L_REG 0x0097

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t val) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *val) {
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *val) {
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *val = ((uint16_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id;
    if (i2c_read_reg8(handle, VL53L1X_MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_VAL) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0x%02X).\n", model_id, VL53L1X_MODEL_ID_VAL);
        return -1;
    }
    if (i2c_write_reg8(handle, VL53L1X_SOFT_RESET_REG, VL53L1X_SOFT_RESET_VAL) < 0) {
        fprintf(stderr, "Error: Failed to soft reset sensor.\n");
        return -1;
