    gpioDelay(10000);
    if (i2c_write_reg8(handle, VL53L1X_SYSTEM_START_REG, VL53L1X_SYSTEM_START_VAL) < 0) {
        fprintf(stderr, "Error: Failed to start sensor.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle, float *distance) {
    uint16_t status;
    if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS_REG, &status) < 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        *distance = -1.0;
        return 0;
    }
    uint16_t dist;
    if (i2c_read_reg16(handle, VL53L1X_RESULT_DISTANCE_H_REG, &dist) < 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        *distance = -1.0;
        return -1;
    }
    *distance = (float)dist;
    return 0;
}

