#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_DELAY_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X 16-bit register addresses */
#define VL53L1X_SOFT_RESET_REG 0x0003
#define VL53L1X_SYSTEM_START_REG 0x0001
#define VL53L1X_RESULT_RANGE_STATUS_REG 0x0014
#define VL53L1X_RESULT_DISTANCE_MM_REG 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, addr[0], &addr[1], 1) < 0) return -1;
    return i2cReadI2CBlockData(handle, addr[0], (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Configure timing budget (100 ms) */
    if (vl53l1x_write_reg16(handle, 0x000B, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x000C, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x000D, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x000E, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x000F, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0010, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0011, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0012, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0013, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0014, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0015, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0016, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0017, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0018, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x0019, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x001A, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x001B, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x001C, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x001D, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x001E, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, 0x001F, 0x00) < 0) return -1;

    /* Start ranging */
    if (vl53l1x_write_reg16(handle, VL53L1X_SYSTEM_START_REG, 0x01) < 0) return -1;
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status;
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS_REG, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) return 1; /* not ready */
    uint8_t data[2];
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_DISTANCE_MM_REG, data, 2) < 0) return -1;
    *distance_mm = (data[0] << 8) | data[1];
    return 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

