    if (i2c_write_byte(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_byte(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
