#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define I2C_BUS 1

#define MPR121_TOUCH_STATUS_L 0x00
#define MPR121_TOUCH_STATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AFE_CONFIG 0x5C
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHD 0x33
#define MPR121_NCL 0x34
#define MPR121_FDL 0x35
#define MPR121_DEBOUNCE_CONFIG 0x5D
#define MPR121_SOFT_RESET 0x80

#define MPR121_DEVID 0x00
#define MPR121_DEVID_VAL 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing 0x%02X to MPR121 register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value) {
    char buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error selecting MPR121 register 0x%02X for read\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char*)value, 1) != 1) {
        fprintf(stderr, "Error reading MPR121 register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    uint8_t devid = 0;
    if (mpr121_read_reg(MPR121_DEVID, &devid) != 0) {
        fprintf(stderr, "Failed to read MPR121 device ID\n");
        return -1;
    }
    if (devid != MPR121_DEVID_VAL) {
        fprintf(stderr, "MPR121 not found (device ID: 0x%02X, expected 0x%02X)\n", devid, MPR121_DEVID_VAL);
        return -1;
    }

    if (mpr121_write_reg(MPR121_SOFT_RESET, 0x5F) != 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE_CONFIG, 0x00) != 0) return -1;

    if (mpr121_write_reg(MPR121_AFE_CONFIG, 0x0B) != 0) return -1;
    if (mpr121_write_reg(MPR121_MHDR, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) != 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x0E) != 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_NHD, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_NCL, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_FDL, 0x00) != 0) return -1;

    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_TOUCH_STATUS_L, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_TOUCH_STATUS_H, 0x00) != 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    *touch_status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_event(void) {
    FILE *fp = fopen("proximity.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", s);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) != 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch_status & 0x0001) {
            printf("Proximity detected on electrode 0\n");
            log_event();
            gpioWrite(LED_GPIO, 1);
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(10000);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

