#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define SPEED_OF_SOUND_CM_S 0.0343f
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    1000000
#define TRIGGER_HOLD_US  5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(fp, "%s ERROR: %s\n", ts, msg);
    fflush(fp);
    fclose(fp);
}

static int trigger_sensor(struct gpiod_line *trig)
{
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig,0)");
        return -1;
    }
    usleep(TRIGGER_HOLD_US);
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig,1)");
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig,0)");
        return -1;
    }
    return 0;
}

static long long measure_pulse_us(struct gpiod_line *echo)
{
    struct timespec start, now;
    long long elapsed_us;

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        if (!gpiod_line_get_value(echo)) {
            return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_us = (now.tv_sec - start.tv_sec) * 1000000LL +
                     (now.tv_nsec - start.tv_nsec) / 1000LL;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            return -1;
        }
        if (elapsed_us >= 1000000) {
            return -1;
        }
    }
}

static float calculate_distance(long long pulse_us)
{
    return (float)pulse_us * SPEED_OF_SOUND_CM_S / 2.0f;
}

static void log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(fp, "%s Distance: %.2f cm\n", ts, distance);
    fflush(fp);
    fclose(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (trigger_sensor(trig) < 0) {
            log_error("trigger_sensor failed");
            usleep(LOOP_DELAY_US);
            continue;
        }

        long long pulse = measure_pulse_us(echo);
        if (pulse < 0) {
            log_error("echo timeout or read error");
            usleep(LOOP_DELAY_US);
            continue;
        }

        float distance = calculate_distance(pulse);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Distance out of range: %.2f cm (pulse=%lld us)",
                     distance, pulse);
            log_error(msg);
        } else {
            log_distance(distance);
        }

        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    printf("Program terminated.\n");
    return ret;
}

