#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define LOG_FILE_NAME "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_US 1000000
#define MIN_VALID_PULSE_US 58
#define MAX_VALID_PULSE_US 25000

static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end   = 0;
static volatile int      g_echo_seen  = 0;
static volatile int      g_echo_valid = 0;
static FILE             *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_pulse_start = tick;
    } else if (level == 0) {
        g_pulse_end = tick;
        g_echo_seen = 1;
        g_echo_valid = 1;
    }
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        return -1;
    }

    return 0;
}

static int log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, %.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

static void cleanup(void)
{
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
            fprintf(stderr, "Error: gpioTrigger failed.\n");
            break;
        }

        uint32_t waited = 0;
        while (g_running && !g_echo_valid) {
            gpioDelay(1000);
            waited += 1000;
            if (waited >= 200000) {
                fprintf(stderr, "Error: echo timeout (no echo received).\n");
                break;
            }
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_valid) {
            continue;
        }

        uint32_t pulse_us = g_pulse_end - g_pulse_start;
        float distance = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;

        if (distance < 0.0f || distance > 4.0f) {
            fprintf(stderr, "Warning: distance %.2f m out of expected range (1 cm - 4 m).\n", distance);
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Warning: logging failed.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

