#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define LOG_FILE "gate_log.txt"
#define POLL_DELAY_US 100000

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0015
#define VL53L1X_REG_SYSTEM_MODE_RANGE_START 0x0015
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x008A
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0083
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0006
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_V1 0x0006
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x0017
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD_V1 0x0017
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_SHORT 0x0001
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_LONG 0x0002
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_V1_SHORT 0x0001
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_V1_LONG 0x0002
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x008A

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID register.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, VL53L1X_REG_SYSTEM_RANGE_CONFIG_SHORT) != 0) {
        fprintf(stderr, "Error: Failed to set ranging mode to short.\n");
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, float *distance_cm) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1;
    }

    uint8_t dist_msb = 0;
    uint8_t dist_lsb = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &dist_msb) != 0) {
        return -1;
    }
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE + 1, &dist_lsb) != 0) {
        return -1;
    }

    int16_t raw = (int16_t)((dist_msb << 8) | dist_lsb);
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

static void log_event(const char *event, float distance_cm, int gate_open) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s, Distance: %.2f cm, Gate: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            event, distance_cm, gate_open ? "OPEN" : "CLOSED");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float distance_cm = 0.0f;
        int ret = vl53l1x_read_distance(i2c_handle, &distance_cm);

        if (ret == 0) {
            int gate_open = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
            if (gpioWrite(GATE_GPIO, gate_open) != 0) {
                fprintf(stderr, "Error: Failed to write GPIO %d.\n", GATE_GPIO);
            }
            log_event("Distance read", distance_cm, gate_open);
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C read failure.\n");
            log_event("I2C read error", 0.0f, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    log_event("Shutdown", 0.0f, 0);
    cleanup();
    return EXIT_SUCCESS;
}

