    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s, Distance: %.2f cm, Gate: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            event, distance_cm, gate_open ? "OPEN" : "CLOSED");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float distance_cm = 0.0f;
        int ret = vl53l1x_read_distance(i2c_handle, &distance_cm);

        if (ret == 0) {
            int gate_open = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
            if (gpioWrite(GATE_GPIO, gate_open) != 0) {
                fprintf(stderr, "Error: Failed to write GPIO %d.\n", GATE_GPIO);
            }
            log_event("Distance read", distance_cm, gate_open);
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C read failure.\n");
            log_event("I2C read error", 0.0f, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    log_event("Shutdown", 0.0f, 0);
    cleanup();
    return EXIT_SUCCESS;
}

