#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_S 34300.0
#define SERVO_MIN_PULSE_US   500
#define SERVO_MAX_PULSE_US   2500
#define SERVO_MIN_ANGLE      0
#define SERVO_MAX_ANGLE      180
#define SERVO_CENTER_ANGLE   90
#define SERVO_CENTER_PULSE   1500
#define TRIGGER_PULSE_US     10
#define ECHO_TIMEOUT_US      30000
#define SAMPLE_COUNT         5
#define TRIGGER_INTERVAL_US  100000
#define MIN_DISTANCE_CM      2.0
#define MAX_DISTANCE_CM      400.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end = 0;
static volatile int g_echo_ready = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        g_pulse_start = tick;
    } else if (level == 0) {
        g_pulse_end = tick;
        g_echo_ready = 1;
    }
}

static float calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us <= 0) return -1.0f;
    float distance = (float)pulse_width_us * SPEED_OF_SOUND_CM_S / 2.0f / 1000000.0f;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0f;
    }
    return distance;
}

static float moving_average(float new_value, float *buffer, int buffer_size, int *index) {
    buffer[*index] = new_value;
    *index = (*index + 1) % buffer_size;
    float sum = 0.0f;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i];
    }
    return sum / buffer_size;
}

static int map_distance_to_angle(float distance) {
    if (distance < 0.0f) return SERVO_MIN_ANGLE;
    if (distance < 10.0f) return SERVO_MIN_ANGLE;
    if (distance < 20.0f) return (int)(SERVO_MIN_ANGLE + (distance - 10.0f) * 10.0f / 10.0f);
    if (distance < 30.0f) return (int)(SERVO_MIN_ANGLE + (distance - 20.0f) * 5.0f / 5.0f);
    if (distance < 40.0f) return (int)(SERVO_MIN_ANGLE + (distance - 30.0f) * 2.0f / 2.0f);
    return SERVO_MAX_ANGLE;
}

static int calculate_servo_pulse(float angle) {
    if (angle < 0.0f) return SERVO_MIN_PULSE_US;
    if (angle > 180.0f) return SERVO_MAX_PULSE_US;
    return SERVO_CENTER_PULSE + (int)((angle - SERVO_CENTER_ANGLE) * SERVO_MAX_PULSE_US / (180.0f - SERVO_CENTER_ANGLE));
}

static int set_servo_angle(int angle) {
    int pulse = calculate_servo_pulse(angle);
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void log_data(float distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(g_log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
    fflush(g_log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("distance_log.csv", "w");
    if (!g_log_file) {
        perror("Failed to open distance_log.csv");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "timestamp,distance_cm,servo_angle_deg\n");
    fflush(g_log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        g_pulse_start = 0;
        g_pulse_end = 0;
        g_echo_ready = 0;

        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = gpioTick();
        while (!g_echo_ready && g_running) {
            if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
                g_echo_ready = 1;
                break;
            }
            gpioDelay(10);
        }

        if (!g_echo_ready) {
            fprintf(stderr, "Timeout waiting for echo\n");
            log_data(-1.0f, -1);
            gpioDelay(TRIGGER_INTERVAL_US);
            continue;
        }

        uint32_t pulse_width = g_pulse_end - g_pulse_start;
        float distance = calculate_distance(pulse_width);
        int servo_angle = map_distance_to_angle(distance);

        if (distance < 0.0f) {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            log_data(-1.0f, servo_angle);
        } else {
            if (set_servo_angle(servo_angle) < 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }
            log_data(distance, servo_angle);
        }

        gpioDelay(TRIGGER_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    if (g_log_file) {
        fclose(g_log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

