    if (high < 0) {
        fprintf(stderr, "Error: failed to read high byte from register 0x%02X (code %d)\n",
                PROXIMITY_HIGH_REG, high);
        return -1;
    }
    int low = i2cReadByteData(i2c_handle, PROXIMITY_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error: failed to read low byte from register 0x%02X (code %d)\n",
                PROXIMITY_LOW_REG, low);
        return -1;
    }
    *proximity = (high << 8) | low;
    return 0;
}

static void log_proximity(int proximity) {
    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Proximity: %d, Status: %s\n",
            timestamp, proximity,
            (proximity > threshold) ? "ALERT" : "SAFE");
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
}

static void alert_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;
    int proximity;
    if (read_proximity(&proximity) == 0) {
        log_proximity(proximity);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                break;
            case 't':
                threshold = atoi(optarg);
                if (threshold <= 0) {
                    fprintf(stderr, "Error: threshold must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    pthread_t alert_thread;
    if (pthread_create(&alert_thread, NULL, alert_handler, NULL) != 0) {
        fprintf(stderr, "Error: failed to create alert ISR thread\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Proximity monitoring started. Threshold: %d, I2C addr: 0x%02X\n",
           threshold, i2c_address);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    pthread_join(alert_thread, NULL);
    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

