#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SPEAKER_PIN 18

#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define ECHO_TIMEOUT_US 200000
#define TRIGGER_PULSE_US 10
#define PWM_RANGE 1000
#define PWM_DUTY_50 500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        return -1;
    }
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set speaker pin mode\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin\n");
        return -1;
    }
    if (gpioWrite(SPEAKER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise speaker pin\n");
        return -1;
    }

    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (trigger_sensor() < 0) {
        return -1.0;
    }

    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
    }

    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - start_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }

    end_tick = gpioTick();

    double pulse_width_us = (double)(end_tick - start_tick);
    double distance = (pulse_width_us * 0.0343) / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }

    return distance;
}

static int calculate_frequency(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    double log_distance = log10(distance);
    double freq = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) *
                  exp(log_distance / 50.0);

    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;

    return (int)freq;
}

static int set_speaker_frequency(int frequency) {
    if (frequency < 0) frequency = 0;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    int pwm_freq = (frequency * PWM_RANGE) / 1000;
    if (pwm_freq < 0) pwm_freq = 0;
    if (pwm_freq > 1000) pwm_freq = 1000;

    if (gpioSetPWMfrequency(SPEAKER_PIN, pwm_freq) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        return -1;
    }
    if (gpioPWM(SPEAKER_PIN, PWM_DUTY_50) < 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(SPEAKER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        int frequency = calculate_frequency(distance);

        if (frequency < 0) {
            fprintf(stderr, "Error: invalid distance, keeping previous frequency\n");
        } else {
            if (set_speaker_frequency(frequency) < 0) {
                fprintf(stderr, "Error: failed to set frequency\n");
            }
        }

        gpioDelay(50000);
    }

    cleanup();
    printf("Theremin stopped.\n");
    return EXIT_SUCCESS;
}

