#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_FREQ    200
#define MAX_FREQ    2000
#define MIN_DIST    5.0f
#define MAX_DIST    50.0f

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  100000
#define LOOP_DELAY_US    10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float read_distance(void) {
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck low (timeout)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck high (timeout)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    return (float)diff / 1000.0f;
}

static int map_distance_to_frequency(float distance) {
    if (distance < 0.0f) distance = 0.0f;
    if (distance > MAX_DIST) distance = MAX_DIST;
    if (distance < MIN_DIST) distance = MIN_DIST;

    float frac = (distance - MIN_DIST) / (MAX_DIST - MIN_DIST);
    float freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * frac;
    if (freq < MIN_FREQ) freq = MIN_FREQ;
    if (freq > MAX_FREQ) freq = MAX_FREQ;
    return (int)freq;
}

static void set_pwm_frequency(int freq) {
    if (gpioHardwarePWM(PWM_PIN, freq, 500000) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for freq %d\n", freq);
    }
}

