        gpioSetMode(ECHO_PIN, PI_INPUT) != 0 ||
        gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: GPIO mode set failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not install SIGINT handler\n");
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = read_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read error, using last valid distance\n");
            distance = -1.0f;
        }

        int freq = map_distance_to_frequency(distance);
        set_pwm_frequency(freq);

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, freq);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioHardwarePWM(PWM_PIN, 0, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

