#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  50000   /* 50 ms timeout for echo pulse */
#define TRIGGER_US  10
#define LOOP_DELAY  500000  /* 500 ms between readings */
#define MIN_DISTANCE 2.0f
#define MAX_DISTANCE 400.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   > 0  : pulse width in microseconds
 *   -1   : timeout (no echo received within TIMEOUT_US)
 *   -2   : pigpio read error (not a valid pulse width)
 */
static int measure_echo_pulse(int pin, int *pulse_us)
{
    uint32_t start_tick = 0, end_tick = 0;
    int level;

    /* Wait for the echo pin to go HIGH (start of pulse) */
    for (uint32_t elapsed = 0; elapsed < TIMEOUT_US; elapsed += 10) {
        level = gpioRead(pin);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on echo pin\n");
            return -1;
        }
        if (level == 1) {
            start_tick = gpioTick();
            break;
        }
        gpioDelay(10);
    }
    if (start_tick == 0) {
        return -1;
    }

    /* Wait for the echo pin to go LOW (end of pulse) */
    for (uint32_t elapsed = 0; elapsed < TIMEOUT_US; elapsed += 10) {
        level = gpioRead(pin);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on echo pin\n");
            return -1;
        }
        if (level == 0) {
            end_tick = gpioTick();
            break;
        }
        gpioDelay(10);
    }
    if (end_tick == 0) {
        return -1;
    }

    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    uint32_t diff = end_tick - start_tick;
