#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define MEASUREMENT_DELAY_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_byte(uint8_t data) {
    char tx[2] = {0x00, data};
    int ret = spiWrite(spi_handle, tx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write failed (ret=%d)\n", ret);
        return -1;
    }
    return 0;
}

static int spi_read_byte(uint8_t *data) {
    char rx[2] = {0x00, 0x00};
    int ret = spiXfer(spi_handle, rx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read failed (ret=%d)\n", ret);
        return -1;
    }
    *data = rx[1];
    return 0;
}

static int init_sensor(void) {
    if (spi_write_byte(0x01) != 0) return -1;
    if (spi_write_byte(0x00) != 0) return -1;
    if (spi_write_byte(0x01) != 0) return -1;
    return 0;
}

static int read_distance(int *distance_mm) {
    uint8_t low, high;
    if (spi_read_byte(&low) != 0) return -1;
    if (spi_read_byte(&high) != 0) return -1;
    *distance_mm = (high << 8) | low;
    return 0;
}

static void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        cleanup();
        return 1;
    }
    gpioWrite(CS_PIN, 1);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    while (running) {
        int distance;
        if (read_distance(&distance) == 0) {
            if (distance >= 200 && distance <= 5000) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %d mm\n", distance);
            }
        } else {
            fprintf(stderr, "SPI read error\n");
        }
        gpioDelay(MEASUREMENT_DELAY_US);
    }

    cleanup();
    return 0;
}

