    /*
     * Reset the sensor by writing 0x01 to the reset register.
     * The Si1120 datasheet specifies a reset pulse of at least 1 ms.
     */
    if (i2cWriteByteData(i2c_handle, SI1120_REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write reset register (0x30): %s\n",
                strerror(errno));
        return -1;
    }
    gpioDelay(2000); /* 2 ms reset settling time */

    /* Verify part ID */
    int part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
    if (part_id < 0) {
