        fprintf(stderr, "Error: Unexpected part ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1120_PART_ID_EXPECTED);
        return -1;
    }

    printf("Si1120 initialised successfully (part ID 0x%02X).\n", part_id);
    return 0;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success, -1 on failure.
 */
static int read_16bit(int handle, uint8_t reg_low, uint16_t *value)
{
    int low = i2cReadByteData(handle, reg_low);
    if (low < 0) {
        fprintf(stderr, "Error: Failed to read low byte from 0x%02X: %s\n",
                reg_low, strerror(errno));
        return -1;
    }

    int high = i2cReadByteData(handle, reg_low + 1);
    if (high < 0) {
        fprintf(stderr, "Error: Failed to read high byte from 0x%02X: %s\n",
                reg_low + 1, strerror(errno));
        return -1;
    }

    *value = (uint16_t)((high << 8) | low);
    return 0;
}

