    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, ALS: %u, PS1: %u\n",
                timestamp, als, ps1) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush() failed: %s\n", strerror(errno));
    }

    return 0;
}

/*
 * Cleanup all resources.
