    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return 1;
    }

    /* Initialise pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Open I2C bus 1 at address 0x60 */
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SI1120_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialise the Si1120 sensor */
    if (init_si1120() < 0) {
        fprintf(stderr, "Error: Si1120 initialisation failed.\n");
        cleanup();
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Logging Si1120 data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (!terminate) {
        uint16_t als_raw, ps1_raw;

        if (read_si1120_data(&als_raw, &ps1_raw) == 0) {
            if (log_data(als_raw, ps1_raw) < 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data.\n");
        }

        /* Sleep for 500 ms, checking terminate flag every 100 ms */
        for (int i = 0; i < 5 && !terminate; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

