#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1182_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 100

/* Si1182-A-GM register addresses */
#define REG_PART_ID          0x00
#define REG_MEAS_RATE        0x08
#define REG_ALS_VIS_DATA0    0x22
#define REG_ALS_VIS_DATA1    0x23
#define REG_PS1_DATA0        0x24
#define REG_PS1_DATA1        0x25

#define EXPECTED_PART_ID     0x82
#define ALS_VIS_SCALE        0.1f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd) {
    uint16_t part_id = 0;
    if (i2c_read_reg16(fd, REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%04X (expected 0x%02X). Sensor not present?\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_MEAS_RATE, 0x07) < 0) {
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *lux, uint16_t *prox) {
    uint16_t als_vis = 0, ps1 = 0;
    if (i2c_read_reg16(fd, REG_ALS_VIS_DATA0, &als_vis) < 0) return -1;
    if (i2c_read_reg16(fd, REG_PS1_DATA0, &ps1) < 0) return -1;
    *lux = (float)als_vis * ALS_VIS_SCALE;
    *prox = ps1;
    return 0;
}

static void log_data(FILE *fp, float lux, uint16_t prox) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t len = strlen(timestamp);
    snprintf(timestamp + len, sizeof(timestamp) - len, ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%.2f,%u\n", timestamp, lux, prox);
    fflush(fp);
    printf("%s,%.2f,%u\n", timestamp, lux, prox);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float lux = 0.0f;
        uint16_t prox = 0;
        if (read_sensor_data(g_i2c_fd, &lux, &prox) == 0) {
            log_data(g_log_fp, lux, prox);
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

