    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float lux = 0.0f;
        uint16_t prox = 0;
        if (read_sensor_data(g_i2c_fd, &lux, &prox) == 0) {
            log_data(g_log_fp, lux, prox);
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

