        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSignalHandler(SIGINT, signal_handler) != 0) {
        fprintf(stderr, "Error: failed to set SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
