#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 20.0
#define MAX_DISTANCE 110.0
#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500
#define SERVO_ANGLE_MIN 0
#define SERVO_ANGLE_MAX 180
#define SERVO_PULSE_MIN 1000
#define SERVO_PULSE_MAX 2000
#define SERVO_RANGE 180
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    trigger_sensor();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go high (timeout)\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go low (timeout)\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (double)diff * SPEED_OF_SOUND / 2000000.0;
    return distance;
}

static int calculate_servo_angle(double distance) {
    if (distance <= MIN_DISTANCE) {
        return SERVO_ANGLE_MIN;
    }
    if (distance >= MAX_DISTANCE) {
        return SERVO_ANGLE_MAX;
    }
    double angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (SERVO_RANGE - 1);
    if (angle < 0) angle = 0;
    if (angle > SERVO_RANGE) angle = SERVO_RANGE;
    return (int)angle;
}

static void set_servo_angle(int angle) {
    int pulse_us = SERVO_PULSE_MIN + (angle * (SERVO_PULSE_MAX - SERVO_PULSE_MIN) / SERVO_RANGE);
    gpioServo(SERVO_PIN, pulse_us);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = calculate_servo_angle(distance);
        set_servo_angle(angle);

        printf("Distance: %.2f cm, Servo Angle: %d\n", distance, angle);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

