static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write_reg(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%04X\n", value, reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg(uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error setting read register 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%04X\n", reg);
        return -1;
    }
    *value = buf[0];
    return 0;
}

