#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI7005_ADDR 0x40
#define SI7005_REG_TEMP 0x01
#define SI7005_REG_HUMID 0x02
#define SI7005_REG_CONFIG 0x03
#define SI7005_CMD_READ 0x00
#define SI7005_CMD_WRITE 0x01
#define SI7005_CONFIG_INT_TEMP 0x00
#define SI7005_CONFIG_HEATER_OFF 0x00
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 2000000
#define CONV_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    char cmd = (char)reg;
    char data[1];
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing register address 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data;
    return 0;
}

static int read_sensor(int handle, float *temperature, float *humidity) {
    uint8_t config = SI7005_CONFIG_HEATER_OFF | SI7005_CONFIG_INT_TEMP;
    if (write_register(handle, SI7005_REG_CONFIG, config) != 0) {
        return -1;
    }
    gpioDelay(CONV_DELAY_US);

    uint8_t temp_raw, humid_raw;
    if (read_register(handle, SI7005_REG_TEMP, &temp_raw) != 0) {
        return -1;
    }
    if (read_register(handle, SI7005_REG_HUMID, &humid_raw) != 0) {
        return -1;
    }

    *temperature = (175.72f * (float)temp_raw) / 65536.0f - 46.85f;
    *humidity = (125.0f * (float)humid_raw) / 65536.0f - 6.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

