#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C default address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_WHO_AM_I     0x75

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* Sensitivity scales for ±2 g accelerometer and ±250 °/s gyroscope */
#define ACCEL_SENSITIVITY 16384.0f  /* LSB per g  */
#define GYRO_SENSITIVITY  131.0f     /* LSB per °/s */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an MPU-6050 register                          */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes from an MPU-6050 register starting at reg     */
/* ------------------------------------------------------------------ */
static int mpu_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error: i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050: verify identity, reset, configure settings */
/* ------------------------------------------------------------------ */
static int mpu_init(int handle)
{
    /* Verify device identity */
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00) < 0)
        return -1;
    gpioDelay(100000);  /* 100 ms settle after wake-up */

    /* Sample-rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (mpu_write_reg(handle, MPU6050_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* ACCEL_CONFIG: ±2 g (AFS_SEL = 0, FS_SEL = 0) */
    if (mpu_write_reg(handle, 0x1C, 0x00) < 0)
        return -1;

    /* GYRO_CONFIG: ±250 °/s (FS_SEL = 0) */
    if (mpu_write_reg(handle, 0x1B, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and parse 14 bytes of accelerometer + temperature + gyroscope  */
/* data.  Returns 0 on success, -1 on error.                           */
/* ------------------------------------------------------------------ */
static int mpu_read_data(int handle, float *ax, float *ay, float *az,
                         float *gx, float *gy, float *gz)
{
    uint8_t buf[14];

    if (mpu_read_block(handle, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_ax = (int16_t)((buf[0]  << 8) | buf[1]);
    int16_t raw_ay = (int16_t)((buf[2]  << 8) | buf[3]);
    int16_t raw_az = (int16_t)((buf[4]  << 8) | buf[5]);
    /* buf[6..7] = temperature (skipped) */
    int16_t raw_gx = (int16_t)((buf[8]  << 8) | buf[9]);
    int16_t raw_gy = (int16_t)((buf[10] << 8) | buf[11]);
    int16_t raw_gz = (int16_t)((buf[12] << 8) | buf[13]);

    *ax = (float)raw_ax / ACCEL_SENSITIVITY;
    *ay = (float)raw_ay / ACCEL_SENSITIVITY;
    *az = (float)raw_az / ACCEL_SENSITIVITY;
    *gx = (float)raw_gx / GYRO_SENSITIVITY;
    *gy = (float)raw_gy / GYRO_SENSITIVITY;
    *gz = (float)raw_gz / GYRO_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialise pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 default address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (mpu_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised on I2C bus 1, address 0x%02X.\n", MPU6050_ADDR);
    printf("Logging accelerometer (±2 g) and gyroscope (±250 °/s) data every 100 ms.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float ax, ay, az, gx, gy, gz;

        if (mpu_read_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g | Gyro: X=%.2f °/s, Y=%.2f °/s, Z=%.2f °/s\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: I2C read error — continuing.\n");
        }

        gpioDelay(100000);  /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

