#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT40_ADDR        0x44
#define MEASURE_CMD       0xFD
#define MEASURE_DELAY_US  10000   /* 10 ms */
#define READ_INTERVAL_S   5
#define I2C_BUS           1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8 polynomial 0x31, init 0xFF (Sensirion spec) */
static uint8_t sht40_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int open_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SHT40_ADDR, g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t data[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error writing measurement command to SHT40\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(g_i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading 6 bytes from SHT40\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (sht40_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht40_crc8(&data[0], 2), data[2]);
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (sht40_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht40_crc8(&data[3], 2), data[5]);
        return -1;
    }

    uint16_t raw_t = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_h = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *humidity    = -6.0f  + 125.0f * (float)raw_h / 65535.0f;

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;

    while (g_running) {
        if (read_sht40(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read SHT40 sensor. Re-initializing I2C...\n");
            if (open_i2c() != 0) {
                fprintf(stderr, "Fatal: I2C re-initialization failed. Exiting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

