#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr = MLX90614_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg;

    msgs[1].addr = MLX90614_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = buf;

    data.msgs = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        return -1;
    }

    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_temperature(int fd, uint8_t reg, float *temp) {
    uint16_t raw;
    if (i2c_read_reg16(fd, reg, &raw) < 0) {
        return -1;
    }
    *temp = (float)raw / 100.0f;
    return 0;
}

static int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        return -1;
    }

    if (fflush(fp) != 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Ambient Temperature (C),Object Temperature (C)\n");
        fflush(log_fp);
    }

    printf("MLX90614 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient, object;

        if (read_temperature(i2c_fd, AMBIENT_TEMP_REG, &ambient) < 0) {
            fprintf(stderr, "Error: Failed to read ambient temperature.\n");
        } else if (read_temperature(i2c_fd, OBJECT_TEMP_REG, &object) < 0) {
            fprintf(stderr, "Error: Failed to read object temperature.\n");
        } else {
            if (log_temperature(log_fp, ambient, object) < 0) {
                fprintf(stderr, "Error: Failed to log temperature data.\n");
            } else {
                printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

