#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP31_ADDR     0x28
#define TRIGGER_CMD    0x21 0x96
#define SAMPLE_PERIOD_US 100000
#define MAX_RETRIES     3
#define LOG_FILE        "airflow.log"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP31 */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sdp31_trigger_and_read(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = { (uint8_t)(TRIGGER_CMD >> 8), (uint8_t)(TRIGGER_CMD & 0xFF) };
    uint8_t buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "[attempt %d] I2C write failed (trigger)\n", attempt + 1);
            gpioDelay(1000000); /* 1 s backoff */
            continue;
        }

        gpioDelay(1000); /* 1 ms conversion time */

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "[attempt %d] I2C read failed (data)\n", attempt + 1);
            gpioDelay(1000000); /* 1 s backoff */
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] CRC mismatch on pressure\n", attempt + 1);
            gpioDelay(1000000);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "[attempt %d] CRC mismatch on temperature\n", attempt + 1);
            gpioDelay(1000000);
            continue;
        }

        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

        *pressure    = (float)raw_pressure / 60.0f;
        *temperature = (float)raw_temp     / 200.0f;
        return 0;
    }

    return -1;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SDP31_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float pressure, temperature;
    while (g_running) {
        if (sdp31_trigger_and_read(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "Shutting down cleanly...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

