#define CMD_TEMP_NOHOLD 0xF3
#define CMD_HUM_NOHOLD  0xF5
#define POLL_DELAY_US  20000   /* 20 ms max wait per measurement */
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE       "sensor_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature (°C) from the Si7015 in No Hold Master mode.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_temperature(int handle, float *temperature)
{
    char cmd = CMD_TEMP_NOHOLD;
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write temperature command to Si7015 (pigpio error: %s)\n",
                pigpio_error(0));
        return -1;
    }

    /* Wait for the measurement to be ready (max ~12 ms for 14-bit temp) */
    gpioDelay(POLL_DELAY_US);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read temperature data from Si7015 (pigpio error: %s)\n",
                pigpio_error(0));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/*
 * Read humidity (%%RH) from the Si7015 in No Hold Master mode.
 * Returns 0 on success, -1 on I2C error.
 */
