        fprintf(stderr, "Error: failed to write humidity command to Si7015 (pigpio error: %s)\n",
                pigpio_error(0));
        return -1;
    }

    /* Wait for the measurement to be ready (max ~12 ms for 14-bit hum) */
    gpioDelay(POLL_DELAY_US);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read humidity data from Si7015 (pigpio error: %s)\n",
                pigpio_error(0));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
