#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SDP800_ADDR 0x25
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "airflow_data.txt"
#define MEASUREMENT_CMD_MSB 0x36
#define MEASUREMENT_CMD_LSB 0x2F
#define SCALE_FACTOR_PRESSURE 240.0f
#define SCALE_FACTOR_TEMPERATURE 200.0f
#define OFFSET_TEMPERATURE -45.0f
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define READ_DELAY_MS 10
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_response(uint8_t *buf, size_t len) {
    ssize_t n = read(i2c_fd, buf, len);
    if (n != (ssize_t)len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sdp800(float *pressure, float *temperature) {
    uint8_t buf[6];
    int16_t raw_pressure, raw_temperature;

    if (i2c_write_cmd(MEASUREMENT_CMD_MSB, MEASUREMENT_CMD_LSB) < 0)
        return -1;

    usleep(READ_DELAY_MS * 1000);

    if (i2c_read_response(buf, 6) < 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE;
    *temperature = (float)raw_temperature / SCALE_FACTOR_TEMPERATURE + OFFSET_TEMPERATURE;

    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
