#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD 28.0f
#define HUMID_THRESHOLD 27.0f
#define BUFFER_SIZE    60
#define RETRY_COUNT    3
#define MEAS_DELAY_US  10000
#define LOOP_DELAY_US  2000000

typedef struct {
    float temperature;
    float humidity;
    time_t timestamp;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    int raw_temp, raw_hum;
    int result;

    /* Trigger temperature measurement (Hold Master) */
    result = i2cWriteByte(i2c_handle, 0xE3);
    if (result < 0) {
        fprintf(stderr, "Error writing temperature trigger: %d\n", result);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    result = i2cReadWordData(i2c_handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    raw_temp = (int)result;

    /* Trigger humidity measurement (Hold Master) */
    result = i2cWriteByte(i2c_handle, 0xE5);
    if (result < 0) {
        fprintf(stderr, "Error writing humidity trigger: %d\n", result);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    result = i2cReadWordData(i2c_handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    raw_hum = (int)result;

    *temperature = 175.72f * (float)raw_temp / 65536.0f - 46.85f;
    *humidity = 125.0f * (float)raw_hum / 65536.0f - 6.0f;

    return 0;
}

static void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Error setting fan GPIO %d HIGH\n", FAN_GPIO);
        }
    } else if (temperature < HUMID_THRESHOLD && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Error setting fan GPIO %d LOW\n", FAN_GPIO);
        }
    }
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    circular_buffer[buffer_index].timestamp = now;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;

    printf("Timestamp: %ld, Temp: %.2f C, Hum: %.2f %%\n",
           (long)now, temperature, humidity);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Si7021 monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries.\n", RETRY_COUNT);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

