    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *rh) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 9)\n", rc);
        return -1;
    }

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 6; i++) {
        if (crc8(&buf[i * 2], 2) != buf[i * 2 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t raw_co2 = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_t = ((uint16_t)buf[2] << 8) | buf[3];
    uint16_t raw_h = ((uint16_t)buf[4] << 8) | buf[5];

    *co2 = raw_co2;
    *temp = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *rh = 100.0f * (float)raw_h / 65535.0f;
    return 0;
}

static int log_data(uint16_t co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed for address 0x%02X (rc=%d)\n", SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete */
    gpioDelay(1000000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    uint16_t co2;
    float temp, rh;
    int ready = 0;

    while (!terminate) {
        ready = 0;
        if (send_command(CMD_READ_DATA_READY) != 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        gpioDelay(10000); /* 10 ms */

        uint8_t buf[3];
        int rc = i2cReadDevice(i2c_handle, (char *)buf, 3);
        if (rc != 3) {
            fprintf(stderr, "Error: i2cReadDevice returned %d (data-ready)\n", rc);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint16_t data = ((uint16_t)buf[0] << 8) | buf[1];
        if (data & 0x0001) ready = 1;

        if (ready) {
            if (send_command(CMD_READ_MEASUREMENT) != 0) {
                fprintf(stderr, "Error: failed to send read measurement command\n");
                gpioDelay(POLL_INTERVAL_US);
                continue;
            }
            gpioDelay(10000); /* 10 ms */

            if (read_measurement(&co2, &temp, &rh) != 0) {
                fprintf(stderr, "Error: failed to read measurement data\n");
                gpioDelay(POLL_INTERVAL_US);
                continue;
            }

            if (log_data(co2, temp, rh) != 0) {
                fprintf(stderr, "Error: failed to log data\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

