#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_ADDR        0x62
#define I2C_BUS           1
#define LED_GPIO          17
#define BUFFER_SIZE       20
#define MEASUREMENT_INTERVAL_US 5000000  /* 5 seconds */
#define CO2_THRESHOLD     1000.0f

/* SCD40 command codes (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define CMD_GET_DATA_READY_STATUS      0xE4B8
#define CMD_READ_MEASUREMENT           0xEC05

typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t data_buffer;
static volatile sig_atomic_t terminate = 0;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8_data(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        return -1;
    }
    gpioWrite(LED_GPIO, 0);
    return 0;
}

static int init_circular_buffer(void) {
    data_buffer.head = 0;
    data_buffer.count = 0;
    return 0;
}

static int start_periodic_measurement(void) {
    uint8_t cmd[2] = {
        (uint8_t)((CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF),
        (uint8_t)(CMD_START_PERIODIC_MEASUREMENT & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error starting periodic measurement\n");
        return -1;
    }
    return 0;
}

static int stop_periodic_measurement(void) {
    uint8_t cmd[2] = {
        (uint8_t)((CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF),
        (uint8_t)(CMD_STOP_PERIODIC_MEASUREMENT & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error stopping periodic measurement\n");
        return -1;
    }
    return 0;
}

static int wait_for_data_ready(void) {
    uint8_t cmd[2] = {
        (uint8_t)((CMD_GET_DATA_READY_STATUS >> 8) & 0xFF),
        (uint8_t)(CMD_GET_DATA_READY_STATUS & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing data-ready command\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    uint8_t status[3];
    if (i2cReadDevice(i2c_handle, (char *)status, 3) != 3) {
        fprintf(stderr, "Error reading data-ready status\n");
        return -1;
    }

    if (crc8(status, 2) != status[2]) {
        fprintf(stderr, "CRC mismatch on data-ready status\n");
        return -1;
    }

    uint16_t word = ((uint16_t)status[0] << 8) | status[1];
    return (word & 0x01) ? 1 : 0;
}

static int read_measurement(sensor_data_t *data) {
    uint8_t cmd[2] = {
        (uint8_t)((CMD_READ_MEASUREMENT >> 8) & 0xFF),
        (uint8_t)(CMD_READ_MEASUREMENT & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing read-measurement command\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    uint8_t raw[9];
    if (i2cReadDevice(i2c_handle, (char *)raw, 9) != 9) {
        fprintf(stderr, "Error reading measurement data\n");
        return -1;
    }

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8_data(&raw[i * 3], 2) != raw[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = ((uint16_t)raw[0] << 8) | raw[1];
    uint16_t temp_raw = ((uint16_t)raw[3] << 8) | raw[4];
    uint16_t hum_raw  = ((uint16_t)raw[6] << 8) | raw[7];

    data->co2    = (float)co2_raw;
    data->temperature = (float)temp_raw / 100.0f;
    data->humidity = (float)hum_raw / 100.0f;
    return 0;
}

static void add_to_buffer(sensor_data_t data) {
    data_buffer.data[data_buffer.head] = data;
    data_buffer.head = (data_buffer.head + 1) % BUFFER_SIZE;
    if (data_buffer.count < BUFFER_SIZE)
        data_buffer.count++;
}

static void print_buffer(void) {
    if (data_buffer.count == 0) {
        printf("No readings in buffer.\n");
        return;
    }
    int start = (data_buffer.count < BUFFER_SIZE) ? 0 : data_buffer.head;
    printf("--- CO2 Readings (last %d) ---\n", data_buffer.count);
    for (int i = 0; i < data_buffer.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%2d] CO2: %.2f ppm  Temp: %.2f C  Hum: %.2f %%\n",
               i, data_buffer.data[idx].co2,
               data_buffer.data[idx].temperature,
               data_buffer.data[idx].humidity);
    }
    printf("----------------------------\n");
}

static void control_led(float co2) {
    gpioWrite(LED_GPIO, (co2 > CO2_THRESHOLD) ? 1 : 0);
}

static void cleanup(void) {
    stop_periodic_measurement();
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_circular_buffer() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (start_periodic_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 CO2 monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int ready = wait_for_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Data-ready check failed; retrying next cycle\n");
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }
        if (ready == 0) {
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        sensor_data_t data;
        if (read_measurement(&data) != 0) {
            fprintf(stderr, "Measurement read failed; retrying next cycle\n");
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        add_to_buffer(data);
        print_buffer();
        control_led(data.co2);

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

