#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define TIMEOUT_US 50000             /* 50 ms timeout per edge */
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

/* ------------------------------------------------------------------ */
/* Read TMP05: returns 0 on success, -1 on timeout, -2 on error        */
/* ------------------------------------------------------------------ */
static int read_tmp05(int gpio, float *temperature)
{
    uint32_t start_tick, end_tick, elapsed;
    int high_count = 0;
    int level;

    /* Wait for the sensor to drive the line low (start of a cycle). */
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if ((int32_t)(gpioTick() - start_tick) >= TIMEOUT_US) {
            return -1;  /* sensor absent or stuck */
        }
    }

    /* Record the start of the falling edge. */
    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if ((int32_t)(gpioTick() - start_tick) >= TIMEOUT_US) {
            return -1;  /* stuck at low */
        }
    }
    end_tick = gpioTick();

    /* Wait for the sensor to drive the line high (end of cycle). */
    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if ((int32_t)(gpioTick() - start_tick) >= TIMEOUT_US) {
            return -1;  /* stuck at low */
        }
    }
    end_tick = gpioTick();

    /* Wait for the sensor to drive the line low (end of cycle). */
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if ((int32_t)(gpioTick() - start_tick) >= TIMEOUT_US) {
            return -1;  /* stuck at high */
        }
    }
    end_tick = gpioTick();

    /* Calculate high-time (TH) and total-cycle-time (TL). */
    uint32_t th = end_tick - start_tick;
    uint32_t tl = end_tick - start_tick;

    /* Guard against division by zero. */
    if (tl == 0) {
        return -2;
    }

    /* Convert to temperature using TMP05 formula. */
    *temperature = 4215.0f - (2143.0f * (float)th / (float)tl);

    /* Sanity-check the result. */
    if (*temperature < -40.0f || *temperature > 150.0f) {
        return -3;
    }

    return 0;
}

