/* Log a reading or malfunction entry                                    */
/* ------------------------------------------------------------------ */
static void log_data(const char *timestamp, int error_code, const char *message)
{
    if (g_log_file != NULL) {
        if (error_code >= 0) {
            fprintf(g_log_file, "%s, %d, %s\n", timestamp, error_code, message);
        } else {
            fprintf(g_log_file, "%s, %d, SENSOR MALFUNCTION\n", timestamp, error_code);
        }
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int consecutive_errors = 0;

    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure the TMP05 GPIO as input. */
    if (gpioSetMode(TMP05_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TMP05_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode. */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature logger started on GPIO%d. Press Ctrl+C to exit.\n",
           TMP05_GPIO);

    while (g_running) {
        int rc = read_tmp05(TMP05_GPIO, &temperature);

        if (rc == 0) {
            consecutive_errors = 0;
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            printf("%s, Temperature: %.2f C\n", timestamp, temperature);
            log_data(timestamp, 0, NULL);
        } else if (rc == -1) {
            /* Sensor absent or stuck. */
            log_data(get_timestamp(NULL, sizeof(timestamp)), rc,
                     "Sensor absent or stuck");
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_data(get_timestamp(NULL, sizeof(timestamp)), rc,
                         "SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
        } else if (rc == -2) {
            log_data(get_timestamp(NULL, sizeof(timestamp)), rc,
                     "Temperature out of valid range");
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
