#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH 0x24
#define MEASURE_CMD_LOW 0x00
#define MEASURE_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define LOG_INTERVAL_US 5000000
#define LOG_FILE "environmental_data.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed.\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed.\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    uint16_t raw_hum = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *humidity = 100.0f * (float)raw_hum / 65535.0f;

    return 0;
}

static void simulate_offset(float *temp, float *hum) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", utc);

    *temp += (float)(rand() % 2) * 2.0f;
    *hum += (float)(rand() % 5) * 5.0f;
}

static int log_data(float temp, float hum, const char *ts) {
    if (fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, hum) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", SHT35_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temp, hum;
    char ts[32];

    while (running) {
        int success = 0;
        for (int attempt = 0; attempt < RETRY_COUNT && running; attempt++) {
            if (read_sht35(i2c_handle, &temp, &hum) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Retry %d/%d...\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
        }

        if (!success) {
            fprintf(stderr, "Error: All %d retries failed. Logging NaNs.\n", RETRY_COUNT);
            temp = NAN;
            hum = NAN;
        }

        simulate_offset(&temp, &hum);

        time_t now = time(NULL);
        struct tm *utc = gmtime(&now);
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", utc);

        if (log_data(temp, hum, ts) != 0) {
            fprintf(stderr, "Error: Logging failed. Continuing.\n");
        }

        gpioDelay(LOG_INTERVAL_US);
    }

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

