#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT35_ADDR        0x44
#define SHT35_CMD_MEASURE 0x2400  /* single-shot, high repeatability, clock stretching disabled */
#define I2C_BUS           1
#define LOG_FILE          "environment.csv"
#define SAMPLE_INTERVAL_S 5
#define MEAS_DELAY_US     20000  /* 20 ms — datasheet: typ 12.1 ms, max 15 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (polynomial 0x31, init 0xFF) per Sensirion SHT3x spec ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler for clean shutdown ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a 16-bit command to the SHT35 ---- */
static int sht35_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

/* ---- Read 6 bytes from the SHT35 after a measurement command ---- */
static int sht35_read_data(int handle, uint8_t *data)
{
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }
    return 0;
}

/* ---- Convert raw sensor values to physical units ---- */
static void sht35_convert(const uint8_t *data, float *temperature, float *humidity)
{
    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;
}

/* ---- Log a reading to the CSV file ---- */
static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s for appending\n", LOG_FILE);
        return -1;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "[ERROR] fclose failed\n");
        return -1;
    }
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x44 */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main sampling loop */
    while (g_running) {
        uint8_t data[6];

        /* Trigger single-shot measurement */
        if (sht35_write_cmd(g_i2c_handle, SHT35_CMD_MEASURE) != 0) {
            fprintf(stderr, "[ERROR] Measurement command failed; skipping sample\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Wait for conversion to complete (datasheet: typ 12.1 ms, max 15 ms) */
        gpioDelay(MEAS_DELAY_US);

        /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
        if (sht35_read_data(g_i2c_handle, data) != 0) {
            fprintf(stderr, "[ERROR] I2C read failed; skipping sample\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Validate CRC-8 checksums for temperature and humidity */
        if (sht35_crc8(&data[0], 2) != data[2]) {
            fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        if (sht35_crc8(&data[3], 2) != data[5]) {
            fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float temperature, humidity;
        sht35_convert(data, &temperature, &humidity);

        /* Log the reading */
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "[ERROR] Logging failed\n");
        }

        /* Wait for the next sample interval */
        sleep(SAMPLE_INTERVAL_S);
    }

    /* ---- Clean shutdown ---- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    fprintf(stderr, "\n[INFO] Shutdown complete.\n");
    return EXIT_SUCCESS;
}

