#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define READ_INTERVAL  5
#define MEAS_TIMEOUT_MS 100

/* Si7021 commands */
#define CMD_RESET       0xFE
#define CMD_MEASURE_H   0xF3
#define CMD_MEASURE_T  0xF5
#define CMD_READ_H_T    0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0x00 (Si7021 datasheet) */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    uint8_t buf[3];
    int elapsed = 0;

    while (elapsed < MEAS_TIMEOUT_MS) {
        if (i2c_write_cmd(fd, cmd) < 0)
            return -1;

        usleep(2000); /* 2 ms conversion time */

        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;

        if (crc8(buf, 2) == buf[2]) {
            *raw = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
        return -1;
    }

    fprintf(stderr, "Timeout waiting for measurement 0x%02X\n", cmd);
    return -1;
}

static int read_temperature(int fd, float *temp) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_T, &raw) < 0)
        return -1;
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *hum) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_H, &raw) < 0)
        return -1;
    *hum = (125.0f * (float)raw / 65536.0f) - 6.0f;
    return 0;
}

static int log_data(const char *filename, float temp, float hum) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
