#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define I2C_BUS        1
#define I2C_ADDR       0x28
#define FAN_GPIO       18
#define PWM_FREQ       25000  /* 25 kHz */
#define PWM_RANGE      1000   /* 0-1000 */
#define SAMPLE_US      100000 /* 100 ms */
#define LOG_FILE       "flow_log.txt"

/* Sensor: 16-bit word, 2 status bits in bits 15:14, 14-bit flow in bits 13:0 */
#define FLOW_COUNTS_1638  1638  /* 0 SLPM */
#define FLOW_COUNTS_10     14745 /* 10 SLPM */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 16-bit raw flow value from sensor */
static int read_sensor(int handle, int16_t *raw_flow) {
    char buf[2];
    int rc;

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error: returned %d\n", rc);
        return -1;
    }

    /* 16-bit word, 2 status bits in bits 15:14, 14-bit flow in bits 13:0 */
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *raw_flow = (int16_t)(raw >> 2); /* shift right by 2 to get 14-bit value */
    return 0;
}

/* Convert raw 14-bit value to flow rate (SLPM) */
static float convert_to_flow_rate(int16_t raw_flow) {
    float flow_rate = ((float)raw_flow / 32767.0f) * 10.0f;
    if (flow_rate < 0.0f) flow_rate = 0.0f;
    if (flow_rate > 10.0f) flow_rate = 10.0f;
    return flow_rate;
}

/* Set fan PWM duty cycle (0-100%) */
static void set_fan_speed(int gpio, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int duty = (duty_percent * PWM_RANGE) / 100;
    gpioPWM(gpio, duty);
}

/* Log timestamped flow rate to file */
static void log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", ts, flow_rate);
    fflush(log_file);
}

int main(void) {
    int16_t raw_flow;
    float flow_rate;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO for hardware PWM */
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Airflow control started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sensor(i2c_handle, &raw_flow) == 0) {
            flow_rate = convert_to_flow_rate(raw_flow);
            set_fan_speed(FAN_GPIO, (int)(flow_rate * 100.0f));
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }
        gpioDelay(SAMPLE_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    set_fan_speed(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

