#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_pressure(int32_t *pressure) {
    uint8_t xl, l, h;
    if (read_register(PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(PRESS_OUT_L, &l) < 0) return -1;
    if (read_register(PRESS_OUT_H, &h) < 0) return -1;
    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | xl;
    if (raw & 0x800000) raw |= 0xFF000000;
    *pressure = raw;
    return 0;
}

static int read_temperature(int16_t *temp) {
    uint8_t l, h;
    if (read_register(TEMP_OUT_L, &l) < 0) return -1;
    if (read_register(TEMP_OUT_H, &h) < 0) return -1;
    *temp = (int16_t)(((uint16_t)h << 8) | l);
    return 0;
}

static void log_data(int32_t pressure, int16_t temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime_r(&now, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            timestamp, (double)pressure / 4096.0, (double)temperature / 480.0);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i = 0;
    if (read_register(WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(CTRL_REG1, 0xB0) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("LPS33HW logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int32_t pressure = 0;
        int16_t temperature = 0;

        if (read_pressure(&pressure) < 0 || read_temperature(&temperature) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            time_t now = time(NULL);
            struct tm *tm_info = localtime_r(&now, NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
            fflush(log_file);
        } else {
            log_data(pressure, temperature);
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

