     * little-endian bytes. Swap the two bytes to get the correct
     * big-endian value. */
    uint16_t swapped = (uint16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));

    /* 9-bit two's-complement: sign-extend the 8-bit data bits
     * into the 16-bit word, then right-shift by 7 to get the
     * 9-bit temperature value. */
    int9bit = (int8_t)(swapped >> 7);
    if (swapped & 0x800) {
        int9bit |= 0xF00;
    }

    *temperature = (float)9.0f * (float)int9bit / 512.0f;
    return 0;
}

static void add_to_buffer(float *buffer, int *index, float value)
{
    buffer[*index] = value;
    *index = (*index + 1) % BUFFER_SIZE;
}

static float calculate_average(float *buffer, int size)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / (float)size;
}

int main(void)
{
    float temperature;
    float buffer[BUFFER_SIZE];
    int buffer_index = 0;
    float average_temperature = 0.0f;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
