    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STLM75 temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            add_to_buffer(buffer, &buffer_index, temperature);
            average_temperature = calculate_average(buffer, BUFFER_SIZE);

            printf("Temperature: %.2f C, Average: %.2f C\n",
                   temperature, average_temperature);

            if (average_temperature > TEMP_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping iteration\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

