#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_SEC 2
#define MAX_RETRIES 3

/* SCD30 commands */
#define CMD_START_PERIODIC_MEASUREMENT 0x0000
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0001
#define CMD_SET_MEASUREMENT_INTERVAL 0x0002
#define CMD_SET_MEASUREMENT_MODE 0x0003
#define CMD_SET_MEASUREMENT_CONFIG 0x0004
#define CMD_SET_MEASUREMENT_TRIGGER 0x0005
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_READ_DATA_READY 0x0202
#define CMD_READ_SYSTEM_DATA 0x0006
#define CMD_READ_MEASUREMENT_DATA 0x0007
#define CMD_READ_MEASUREMENT_DATA_CRC 0x0008

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* SCD30 CRC-8: polynomial 0x31, initial value 0xFF */
static uint8_t scd30_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int scd30_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int scd30_write_command_with_arg(uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = scd30_crc8(&buf[2], 2);
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 5);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int scd30_read_data(uint8_t *data, size_t len) {
    int rc = i2cReadDevice(i2c_handle, (char *)data, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != (int)len) {
        fprintf(stderr, "I2C read short: got %d, expected %zu\n", rc, len);
        return -1;
    }
    return 0;
}

static int scd30_init(void) {
    if (scd30_write_command(CMD_START_PERIODIC_MEASUREMENT) < 0) return -1;
    gpioDelay(10000); /* 10 ms startup delay */

    if (scd30_write_command(CMD_SET_MEASUREMENT_INTERVAL) < 0) return -1;
    if (scd30_write_command(0x0000) < 0) return -1; /* 2 s interval */

    if (scd30_write_command(CMD_SET_MEASUREMENT_MODE) < 0) return -1;
    if (scd30_write_command(0x0001) < 0) return -1; /* continuous mode */

    if (scd30_write_command(CMD_SET_MEASUREMENT_CONFIG) < 0) return -1;
    if (scd30_write_command(0x0000) < 0) return -1; /* no averaging */

    if (scd30_write_command(CMD_SET_MEASUREMENT_TRIGGER) < 0) return -1;
    if (scd30_write_command(0x0000) < 0) return -1; /* no trigger */

    if (scd30_write_command(CMD_START_PERIODIC_MEASUREMENT) < 0) return -1;
    gpioDelay(10000); /* 10 ms startup delay */
    return 0;
}

static int scd30_read_measurement(uint16_t *co2, float *temp, float *rh) {
    if (scd30_write_command(CMD_READ_MEASUREMENT) < 0) return -1;

    gpioDelay(10000); /* 10 ms processing delay */

    uint8_t data[18];
    if (scd30_read_data(data, sizeof(data)) < 0) return -1;

    if (scd30_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on CO2 data\n");
        return -1;
    }
    if (scd30_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    if (scd30_crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "CRC mismatch on humidity data\n");
        return -1;
    }

    uint16_t co2_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t temp_raw = (uint16_t)((data[3] << 8) | data[4]);
    uint16_t rh_raw = (uint16_t)((data[6] << 8) | data[7]);

    *co2 = co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *rh = (float)rh_raw / 100.0f;
    return 0;
}

static void control_ventilation(uint16_t co2) {
    if (co2 > 1200) {
        printf("CO2: %u ppm - HIGH (ventilation ON)\n", co2);
        fflush(stdout);
    } else if (co2 > 800) {
        printf("CO2: %u ppm - LOW (ventilation MEDIUM)\n", co2);
        fflush(stdout);
    } else {
        printf("CO2: %u ppm - OFF (ventilation OFF)\n", co2);
        fflush(stdout);
    }
}

static void log_data(uint16_t co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(log_file);
    printf("%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, SCD30_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (scd30_init() < 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SCD30 initialized. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, MEASUREMENT_INTERVAL_SEC);
    fflush(stdout);

    while (running) {
        int ready = 0;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (scd30_write_command(CMD_READ_DATA_READY) < 0) {
                gpioDelay(1000000);
                continue;
            }
            gpioDelay(10000); /* 10 ms */
            if (scd30_read_data((uint8_t *)&ready, 1) < 0) {
                gpioDelay(1000000);
                continue;
            }
            if (ready) break;
            gpioDelay(100000);
        }
        if (!ready) {
            fprintf(stderr, "Sensor not ready after %d attempts\n", MAX_RETRIES);
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (scd30_read_measurement(&co2, &temp, &rh) == 0) {
                log_data(co2, temp, rh);
                control_ventilation(co2);
                break;
            }
            gpioDelay(100000);
        }

        if (!ready) {
            fprintf(stderr, "Sensor not ready after %d attempts\n", MAX_RETRIES);
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    if (scd30_write_command(CMD_STOP_PERIODIC_MEASUREMENT) < 0) {
        fprintf(stderr, "Warning: failed to stop periodic measurement\n");
    }
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

