#define SAMPLE_INTERVAL_MS 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int sdp32_start_continuous(int handle) {
    uint8_t cmd[2] = {0x36, 0x2F};
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send continuous-measurement command to SDP32.\n");
        return -1;
    }
    return 0;
}

static int sdp32_read_data(int handle, int16_t *pressure, int16_t *temperature, int16_t *scale_factor) {
    uint8_t buf[9];
    int bytes_read = i2cReadDevice(handle, (char *)buf, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error: I2C read failed (expected 9 bytes, got %d).\n", bytes_read);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Scale-factor CRC mismatch.\n");
        return -1;
    }

    *pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    *scale_factor = (int16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static int sdp32_convert_to_pa(int16_t raw_pressure, int16_t scale_factor, float *pressure_pa) {
    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (zero).\n");
        return -1;
    }
    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    return 0;
}

