    float pressure_pa;
    int retries = 0;

    while (running) {
        if (sdp32_read_data(i2c_handle, &raw_pressure, &raw_temperature, &scale_factor) == 0) {
            if (sdp32_convert_to_pa(raw_pressure, scale_factor, &pressure_pa) == 0) {
                log_data(pressure_pa);
            } else {
                fprintf(stderr, "Warning: Pressure conversion failed.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed. Retrying...\n");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Error: Max retries reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(sample_interval_ms * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

