#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP810_ADDR        0x25
#define I2C_BUS            1
#define CMD_CONTINUOUS     0x3615
#define CONV_DELAY_US      45000   /* 45 ms max conversion time */
#define SAMPLE_PERIOD_US   1000000 /* 1 s */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one 9-byte continuous-measurement frame from the SDP810.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONTINUOUS >> 8) & 0xFF),
        (uint8_t)(CMD_CONTINUOUS & 0xFF)
    };
    uint8_t buf[9];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error: failed to write continuous-measurement command\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONV_DELAY_US);

    /* Read 9 bytes: pressure(2)+scale, temperature(2)+scale, scale(3) */
    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 9)\n", n);
        return -1;
    }

    /* Validate CRC on each 3-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -2;
        }
    }

    /* Convert raw values using per-reading scale factors */
    uint16_t p_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t t_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t s_p   = (uint16_t)((buf[6] << 8) | buf[7]);
    uint16_t s_t   = (uint16_t)((buf[9] << 8)  | buf[8]);

    if (s_p == 0 || s_t == 0) {
        fprintf(stderr, "Error: invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)p_raw / s_p;
    *temperature = (float)t_raw / 200.0f;

    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (err %d)\n",
                I2C_BUS, SDP810_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa reader started on I2C bus %d, addr 0x%02X\n",
           I2C_BUS, SDP810_ADDR);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);
        if (rc == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: I2C read error, continuing\n");
        } else {
            fprintf(stderr, "Warning: CRC error, continuing\n");
        }

        /* Sleep 1 s, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* Graceful cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

