#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define READ_REG 0x00
#define READ_LEN 1
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(int handle, float *pressure) {
    char reg = READ_REG;
    char buf[READ_LEN];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n",
                READ_REG, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error reading %d bytes from register 0x%02X: %s\n",
                READ_LEN, READ_REG, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw;
    return 0;
}

static void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, MLX90833_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90833 pressure sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        if (read_pressure(i2c_handle, &pressure) == 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying in 1 second.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

