#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x63
#define MEASURE_CMD    0x40
#define READ_OTP_CMD   0x50
#define READ_OTP_LEN   8
#define READ_MEAS_LEN  6
#define SAMPLE_PERIOD  5
#define MEAS_DELAY_US  7000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_otp_coefficients(int handle, uint16_t cal[4])
{
    char cmd = (char)READ_OTP_CMD;
    char buf[READ_OTP_LEN];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2cReadDevice(handle, buf, READ_OTP_LEN) != READ_OTP_LEN) {
        fprintf(stderr, "Error: failed to read OTP coefficients\n");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(buf[2 * i + 1] & 0xFF) << 8) | (uint8_t)buf[2 * i];
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t cal[4],
                            float *temperature, float *pressure)
{
    char cmd = (char)MEASURE_CMD;
    char buf[READ_MEAS_LEN];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(handle, buf, READ_MEAS_LEN) != READ_MEAS_LEN) {
        fprintf(stderr, "Error: failed to read measurement data\n");
        return -1;
    }

    uint16_t raw_t = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    uint32_t raw_p = ((uint32_t)(buf[3] & 0xFF) << 16) |
                     ((uint32_t)(buf[4] & 0xFF) << 8) |
                     (uint8_t)buf[5];

    float scale_t = (float)cal[0];
    float scale_p = (float)cal[1];
    float scale_h = (float)cal[2];

    *temperature = ((float)raw_t / scale_t) * 100.0f;
    *pressure = ((float)raw_p / (scale_p * 100.0f)) * 101325.0f;
    return 0;
}

static void log_data(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temperature, pressure);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (handle=%d)\n",
                I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t cal[4];
    if (read_otp_coefficients(g_i2c_handle, cal) != 0) {
        fprintf(stderr, "Error: sensor absent or OTP read failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 sensor ready. Logging every %d seconds.\n", SAMPLE_PERIOD);

    while (g_running) {
        float temperature, pressure;

        if (read_sensor_data(g_i2c_handle, cal, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping sample\n");
        }

        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

