        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n", I2C_BUS, MLX90819_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure;
        if (read_pressure(fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s] Pressure: %.2f kPa\n", ts, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting...\n");
    close(fd);
    return EXIT_SUCCESS;
}

