/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure_out)
{
    uint8_t cmd[2] = { MEASURE_CMD_0, MEASURE_CMD_1 };
    uint8_t buf[3];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x362F).\n");
        return -1;
    }

    time_sleep(MEASUREMENT_MS / 1000.0);

    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: I2C read failed (expected 3 bytes).\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on pressure data.\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure_out = (float)raw / 60.0f;
    return 0;
}

