    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int read_pressure(float *pressure)
{
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
        if (rc == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *pressure = (float)raw * PRESSURE_SCALE;
            return 0;
        }
