#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environment_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576  /* 1 MB */
#define SAMPLE_INTERVAL_SEC 5
#define MEASURE_DELAY_US 40000      /* 40 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read temperature and humidity from the HIH6130.
 * Returns 0 on success, -1 on I2C error, -2 on sensor absent.
 */
static int read_hih6130(float *temperature, float *humidity) {
    char buf[4];
    int rc;

    /* Trigger measurement by writing 0x00 */
    rc = i2cWriteByte(i2c_handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByte failed (rc=%d)\n", rc);
        return -1;
    }

    /* Wait for measurement to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 4 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    rc = i2cReadDevice(i2c_handle, buf, 4);
    if (rc != 4) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 4)\n", rc);
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC in byte 2) */
    uint8_t crc_t = (uint8_t)(buf[0] << 8 | buf[1]);
    if (crc_t != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, recv=0x%02X)\n",
                crc_t, buf[2]);
        return -2;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC in byte 5) */
    uint8_t crc_h = (uint8_t)(buf[3] << 8 | buf[4]);
    if (crc_h != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch (calc=0x%02X, recv=0x%02X)\n",
                crc_h, buf[5]);
        return -2;
    }

    uint16_t raw_t = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    uint16_t raw_h = ((uint16_t)(buf[3] & 0xFF) << 8) | (uint16_t)(buf[4] & 0xFF);

    *temperature = ((float)raw_t * 165.0f / 16383.0f) - 40.0f;
    *humidity = ((float)raw_h * 100.0f / 16383.0f);

    return 0;
}

/*
 * Append a timestamped reading to the log file.
 * If the file exceeds LOG_FILE_SIZE_LIMIT, truncate it.
 */
static void log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    /* Check file size before appending */
    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell failed");
        fclose(fp);
        return;
    }

    if (pos >= LOG_FILE_SIZE_LIMIT) {
        fseek(fp, 0, SEEK_END);
        pos = ftell(fp);
        if (pos < 0) {
            perror("ftell after truncation failed");
            fclose(fp);
            return;
        }
        fseek(fp, 0, SEEK_SET);
        fclose(fp);
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);
    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
    }

    printf("HIH6130 environmental monitor started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        float temperature, humidity;

        int rc = read_hih6130(&temperature, &humidity);
        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            log_data(temperature, humidity);
        } else if (rc == -2) {
            fprintf(stderr, "Warning: sensor absent or CRC error, skipping sample\n");
        } else {
            fprintf(stderr, "Warning: I2C read error, skipping sample\n");
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    /* Clean resource release on exit */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

