    uint16_t raw_h = ((uint16_t)(buf[3] & 0xFF) << 8) | (uint16_t)(buf[4] & 0xFF);

    *temperature = ((float)raw_t * 165.0f / 16383.0f) - 40.0f;
    *humidity = ((float)raw_h * 100.0f / 16383.0f);

    return 0;
}

/*
 * Append a timestamped reading to the log file.
 * If the file exceeds LOG_FILE_SIZE_LIMIT, truncate it.
 */
static void log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    /* Check file size before appending */
    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell failed");
        fclose(fp);
        return;
    }

    if (pos >= LOG_FILE_SIZE_LIMIT) {
        fseek(fp, 0, SEEK_END);
        pos = ftell(fp);
        if (pos < 0) {
            perror("ftell after truncation failed");
            fclose(fp);
            return;
        }
        fseek(fp, 0, SEEK_SET);
        fclose(fp);
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);
    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
    }

    printf("HIH6130 environmental monitor started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        float temperature, humidity;

        int rc = read_hih6130(&temperature, &humidity);
        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            log_data(temperature, humidity);
        } else if (rc == -2) {
            fprintf(stderr, "Warning: sensor absent or CRC error, skipping sample\n");
        } else {
            fprintf(stderr, "Warning: I2C read error, skipping sample\n");
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    /* Clean resource release on exit */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

