#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define MAX_NIBBLES 6
#define MAX_READS 100
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
}

static int read_sent_data(int gpio, float *pressure) {
    int data[MAX_NIBBLES];
    int idx = 0;
    int last_tick = gpioTick();
    int timeout = 0;

    while (idx < MAX_READS) {
        int pulse = gpioRead(gpio);
        if (pulse < 0) {
            log_error("gpioRead failed");
            return -1;
        }
        if (pulse == 1) {
            if (gpioTick() - last_tick > (SYNC_TICKS * 1000)) {
                last_tick = gpioTick();
                timeout = 0;
            }
            if (timeout == 0) {
                data[idx] = pulse;
                idx++;
                if (idx == MAX_NIBBLES) {
                    if (data[0] == 1 && data[1] == 1 && data[2] == 1) {
                        int sum = data[0] + data[1] + data[2];
                        if (sum == data[3]) {
                            int raw = (data[0] << 12) | (data[1] << 8) | data[2];
                            if (raw & 0x000F) {
                                *pressure = (float)raw * 0.0001f;
                                return 0;
                            } else {
                                log_error("Invalid SENT nibble");
                                return -1;
                            }
                        } else {
                            log_error("Checksum mismatch");
                            return -1;
                        }
                    } else {
                        log_error("Invalid SENT nibble");
                        return -1;
                    }
                }
            }
        }
        gpioDelay(100);
    }
    log_error("SENT read timeout");
    return -1;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Brake pressure monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENT_GPIO);

    while (running) {
        float pressure;
        if (read_sent_data(SENT_GPIO, &pressure) == 0) {
            log_pressure(pressure);
        } else {
            log_error("Sensor read failed");
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

