#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define EXPECTED_DEVICE_ID 0x0117
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int verify_device_id(void) {
    int id = i2cReadWordData(i2c_handle, 0x00);
    if (id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", id);
        return -1;
    }
    if (id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n",
                id, EXPECTED_DEVICE_ID);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_c) {
    char buf[2];
    int bytes = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *temp_c = (float)raw * 0.0078125f;
    return 0;
}

static int log_temperature(float temp_c) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fseek(log_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error seeking in log file\n");
        return -1;
    }
    long file_size = ftell(log_file);
    if (file_size < 4) {
        fprintf(stderr, "Log file too small for timestamp\n");
        return -1;
    }

    if (fseek(log_file, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error seeking in log file\n");
        return -1;
    }

    uint8_t timestamp_bytes[4];
    strncpy(timestamp_bytes, timestamp, 16);
    timestamp_bytes[16] = '\0';

    if (fwrite(timestamp_bytes, 1, 4, log_file) != 4) {
        fprintf(stderr, "Error writing timestamp to log file\n");
        return -1;
    }

    if (fwrite(&temp_c, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error writing temperature to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Greenhouse temperature monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading temperature. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL_SEC);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

