#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define SAMPLE_PERIOD  5
#define BUFFER_SIZE    100
#define LOG_FILE       "temperature_log.dat"

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static CircularBuffer g_buffer;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, TMP117_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature)
{
    char reg = TEMP_REG;
    char buf[2];
    int  rc;

    rc = i2cWriteDevice(g_i2c_handle, &reg, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg select): %d\n", rc);
        return -1;
    }

    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C read short: got %d bytes, expected 2\n", rc);
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static void buffer_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static int buffer_save(const CircularBuffer *cb, const char *filename)
{
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen for write");
        return -1;
    }

    size_t n = cb->count * sizeof(float);
    if (fwrite(cb->buffer, sizeof(float), n, fp) != (size_t)n) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static void buffer_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer_init(&g_buffer);

    printf("TMP117 temperature logger started. Sampling every %d s.\n", SAMPLE_PERIOD);

    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            buffer_add(&g_buffer, temperature);
            if (buffer_save(&g_buffer, LOG_FILE) != 0) {
                fprintf(stderr, "Warning: failed to save log file\n");
            }
            printf("Temperature: %.4f °C\n", temperature);
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping sample\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    buffer_save(&g_buffer, LOG_FILE);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

