#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define READ_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, float *flow_rate, float *temperature) {
    char buffer[4];
    int result;

    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        result = i2cReadDevice(handle, buffer, 4);
        if (result == 4) {
            uint16_t raw_flow = ((uint16_t)(buffer[0] & 0xFF) << 8) | (uint16_t)(buffer[1] & 0xFF);
            uint16_t raw_temp = ((uint16_t)(buffer[2] & 0xFF) << 8) | (uint16_t)(buffer[3] & 0xFF);

            *flow_rate = ((float)raw_flow / 16384.0f) - 0.1f;
            *flow_rate *= 25.0f;

            *temperature = ((float)raw_temp / 4096.0f) - 0.1f;
            *temperature *= 80.0f;
            *temperature -= 40.0f;

            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (rc=%d): %s\n",
                attempt + 1, result, strerror(errno));
        gpioDelay(100000);
    }
    return -1;
}

static void log_data(FILE *fp, float flow_rate, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Flow: %.2f SLPM, Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow_rate, temperature);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

