#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define READ_INTERVAL_SEC 2
#define DHT11_TIMEOUT_US 1000000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    if (!g_log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(g_log_fp, "%s %s\n", ts, msg);
    fflush(g_log_fp);
}

static void log_reading(float temp, float hum) {
    if (!g_log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(g_log_fp, "%s Temperature: %.1f C, Humidity: %.1f %%\n", ts, temp, hum);
    fflush(g_log_fp);
}

static void log_error(const char *msg) {
    if (!g_log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(g_log_fp, "%s ERROR: %s\n", ts, msg);
    fflush(g_log_fp);
}

static int wait_level(int target, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(DHT11_GPIO) != target) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int wait_level_high(uint32_t timeout_us) {
    return wait_level(1, timeout_us);
}

static int wait_level_low(uint32_t timeout_us) {
    return wait_level(0, timeout_us);
}

static int read_dht11(float *temp, float *hum) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i;

    /* Start signal: pull low for >= 18 ms, then high */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT11_GPIO, 0) < 0) return -1;
    gpioDelay(20000); /* 20 ms low (>= 18 ms) */
    if (gpioWrite(DHT11_GPIO, 1) < 0) return -1;
    gpioDelay(30); /* 30 us high */
    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) return -1;

    /* Sensor response: ~80 us low + ~80 us high */
    if (wait_level_low(DHT11_TIMEOUT_US) < 0) return -2;
    if (wait_level_high(DHT11_TIMEOUT_US) < 0) return -2;

    /* Read 40 data bits + 1 checksum byte */
    for (i = 0; i < 40; i++) {
        /* Each bit starts with a ~50 us low pulse */
        if (wait_level_low(DHT11_TIMEOUT_US) < 0) return -3;
        uint32_t high_start = gpioTick();
        if (wait_level_high(DHT11_TIMEOUT_US) < 0) return -3;
        uint32_t high_us = gpioTick() - high_start;

        /* High pulse duration determines bit value: ~26-28 us = '0', ~70 us = '1' */
        if (high_us > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    /* Checksum validation */
    uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
    if (checksum != data[4]) {
        return -4;
    }

    /* DHT11 data: byte 0 = temperature, byte 1 = humidity, bytes 2-3 = 0 */
    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)((data[2] << 8) | data[3]) / 10.0f;
    return 0;
}

int main(void) {
    float temp, hum;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("DHT11 sensor started");

    while (g_running) {
        int rc = read_dht11(&temp, &hum);
        if (rc == 0) {
            log_reading(temp, hum);
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "DHT11 read failed (code %d): %s",
                     rc, (rc == -1 ? "timeout" : (rc == -2 ? "stuck_high" : (rc == -3 ? "stuck_low" : "checksum_error"))));
            log_error(msg);
        }
        sleep(READ_INTERVAL_SEC);
    }

    log_message("DHT11 sensor stopped");
    fclose(g_log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

