#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT31_ADDR        0x44
#define SHT31_CMD_MEASURE 0x2C06  /* single-shot, clock-stretching, high repeatability */
#define SHT31_MEASURE_MS  15      /* max conversion time */
#define LOG_FILE          "sht31d_data.log"
#define SAMPLE_INTERVAL_S 5
#define MAX_RETRIES       3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 polynomial 0x31, initial value 0xFF (Sensirion spec) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sht31(int handle, sensor_data_t *data) {
    uint8_t cmd[2] = { (uint8_t)(SHT31_CMD_MEASURE >> 8),
                       (uint8_t)(SHT31_CMD_MEASURE & 0xFF) };
    uint8_t buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "[attempt %d] I2C write failed\n", attempt + 1);
            gpioDelay(10000); /* 10 ms backoff */
            continue;
        }

        gpioDelay(SHT31_MEASURE_MS * 1000); /* 15 ms max conversion */

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "[attempt %d] I2C read failed\n", attempt + 1);
            gpioDelay(10000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] Temperature CRC mismatch\n", attempt + 1);
            gpioDelay(10000);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[attempt %d] Humidity CRC mismatch\n", attempt + 1);
            gpioDelay(10000);
            continue;
        }

        uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

        data->temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        data->humidity    = 100.0f * (float)h_raw / 65535.0f;
        return 0;
    }

    fprintf(stderr, "SHT31 read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static void log_data(FILE *fp, float temp, float hum) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", SHT31_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t data;
    while (!terminate) {
        if (read_sht31(i2c_handle, &data) == 0) {
            log_data(log_file, data.temperature, data.humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   data.temperature, data.humidity);
        } else {
            log_error(log_file, "Sensor read failed");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

