#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR_DEFAULT 0x64
#define ADPD105_ADDR_ALTERNATE 0x65
#define ADPD105_DEVICE_ID_REG 0x00
#define ADPD105_RED_REG 0x64
#define ADPD105_GREEN_REG 0x66
#define ADPD105_BLUE_REG 0x68
#define ADPD105_DEVICE_ID 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_rgb(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t r, g, b;
    if (read_register(handle, ADPD105_RED_REG, &r) < 0) return -1;
    if (read_register(handle, ADPD105_GREEN_REG, &g) < 0) return -1;
    if (read_register(handle, ADPD105_BLUE_REG, &b) < 0) return -1;
    *red = (uint16_t)r;
    *green = (uint16_t)g;
    *blue = (uint16_t)b;
    return 0;
}

static float calculate_cct(uint16_t r, uint16_t g, uint16_t b) {
    float R = (float)r;
    float G = (float)g;
    float B = (float)b;
    float R_norm = R / 65535.0f;
    float G_norm = G / 65535.0f;
    float B_norm = B / 65535.0f;
    float cct = 0.0f;
    if (R_norm > 0.001f && G_norm > 0.001f && B_norm > 0.001f) {
        cct = 449.0f * powf(G_norm / R_norm, 1.0f / 3.0f) - 123.0f * powf(B_norm / R_norm, 1.0f / 3.0f);
    } else {
        cct = -1.0f;
    }
    return cct;
}

