    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        fseek(log_file, 0, SEEK_END);
        if (ftell(log_file) == 0) {
            fprintf(log_file, "Timestamp,Average_CCT\n");
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, cct);
    fflush(log_file);
    return 0;
}

