    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR_DEFAULT, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1 at 0x%02X: %d\n", ADPD105_ADDR_DEFAULT, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR_ALTERNATE, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2 at 0x%02X: %d\n", ADPD105_ADDR_ALTERNATE, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    uint8_t device_id;
    if (read_register(i2c_handle1, ADPD105_DEVICE_ID_REG, &device_id) < 0) {
        fprintf(stderr, "Sensor 1 (0x%02X) not detected or unresponsive\n", ADPD105_ADDR_DEFAULT);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }
    if (device_id != ADPD105_DEVICE_ID) {
        fprintf(stderr, "Sensor 1 (0x%02X) device ID mismatch: 0x%02X (expected 0x%02X)\n",
                ADPD105_ADDR_DEFAULT, device_id, ADPD105_DEVICE_ID);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (read_register(i2c_handle2, ADPD105_DEVICE_ID_REG, &device_id) < 0) {
        fprintf(stderr, "Sensor 2 (0x%02X) not detected or unresponsive\n", ADPD105_ADDR_ALTERNATE);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }
    if (device_id != ADPD105_DEVICE_ID) {
        fprintf(stderr, "Sensor 2 (0x%02X) device ID mismatch: 0x%02X (expected 0x%02X)\n",
                ADPD105_ADDR_ALTERNATE, device_id, ADPD105_DEVICE_ID);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    uint16_t red1, green1, blue1;
    uint16_t red2, green2, blue2;

    while (running) {
        if (read_rgb(i2c_handle1, &red1, &green1, &blue1) < 0) {
            fprintf(stderr, "Error reading sensor 1 data\n");
        } else {
            float cct1 = calculate_cct(red1, green1, blue1);
            if (cct1 > 0.0f) {
                log_cct(cct1);
            } else {
                fprintf(stderr, "Invalid CCT value from sensor 1\n");
            }
        }

        if (read_rgb(i2c_handle2, &red2, &green2, &blue2) < 0) {
            fprintf(stderr, "Error reading sensor 2 data\n");
        } else {
            float cct2 = calculate_cct(red2, green2, blue2);
            if (cct2 > 0.0f) {
                log_cct(cct2);
            } else {
                fprintf(stderr, "Invalid CCT value from sensor 2\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return 0;
}

