#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90824_ADDR  0x60
#define PRESSURE_REG   0x0A2C
#define TEMP_REG       0x0A2E
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  2.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_raw_pressure(int handle, uint16_t *raw) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_raw_temperature(int handle, uint16_t *raw) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static float convert_pressure(uint16_t raw) {
    const float pmin_kpa = 0.0f;
    const float pmax_kpa = 800.0f;
    const float output_min = 0;
    const float output_max = 32768;
    return (float)(raw - output_min) * (pmax_kpa - pmin_kpa) / (output_max - output_min);
}

static float convert_temperature(uint16_t raw) {
    return (float)raw * 0.01f - 40.0f;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", ts, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", MLX90824_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90824 Tire Pressure Monitor started. Logging to %s every %.1f s.\n", LOG_FILE, SAMPLE_PERIOD);

    while (running) {
        uint16_t raw_pressure = 0;
        uint16_t raw_temperature = 0;

        if (read_raw_pressure(i2c_handle, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading pressure (I2C error).\n");
        } else if (read_raw_temperature(i2c_handle, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading temperature (I2C error).\n");
        } else {
            float pressure = convert_pressure(raw_pressure);
            float temperature = convert_temperature(raw_temperature);
            log_data(pressure, temperature);
            printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure, temperature);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

