#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   26.0f
#define SAMPLE_INTERVAL_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Circular buffer */
static float g_buffer[BUFFER_SIZE];
static int   g_buf_head = 0;
static int   g_buf_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and open I2C                                        */
/* ------------------------------------------------------------------ */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for GPIO %d.\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from LM75B (9-bit signed, 0.5 °C resolution)         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_temperature(float *temperature)
{
    char buf[2];

    if (i2cReadI2CBlockData(g_i2c_handle, TEMP_REG, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed.\n");
        return -1;
    }

    /* LM75B: 9-bit signed, 0.5 °C resolution.  Bits D9-D1 carry the
     * temperature, with D0 always 0.  Shift right by 1 to get the
     * signed 9-bit value. */
    int16_t raw = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]) >> 1;
    *temperature = (float)raw / 2.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Add temperature to circular buffer                                    */
/* ------------------------------------------------------------------ */
static void add_temperature(float temperature)
{
    g_buffer[g_buf_head] = temperature;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE) {
        g_buf_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute running average over the buffer                              */
/* ------------------------------------------------------------------ */
static float calculate_average(void)
{
    if (g_buf_count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < g_buf_count; i++) {
        sum += g_buffer[i];
    }
    return sum / (float)g_buf_count;
}

/* ------------------------------------------------------------------ */
/* Control fan with hysteresis                                          */
/* ------------------------------------------------------------------ */
static void control_fan(float average_temp)
{
    static int fan_on = 0;

    if (average_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg=%.2f °C)\n", average_temp);
        } else {
            fprintf(stderr, "Error: gpioWrite failed for fan ON.\n");
        }
    } else if (average_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg=%.2f °C)\n", average_temp);
        } else {
            fprintf(stderr, "Error: gpioWrite failed for fan OFF.\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("LM75B temperature monitor started.  I2C bus %d, addr 0x%02X, fan GPIO %d.\n",
           I2C_BUS, LM75B_ADDR, FAN_GPIO);
    printf("Threshold high  %.1f °C, threshold low %.1f °C.  Press Ctrl+C to exit.\n",
           TEMP_THRESHOLD_HIGH, TEMP_THRESHOLD_LOW);

    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            add_temperature(temperature);
            float avg = calculate_average();
            printf("Temperature: %.2f °C  |  Avg: %.2f °C  |  Fan: %s\n",
                   temperature, avg, fan_on ? "ON" : "OFF");
            control_fan(avg);
        } else {
            fprintf(stderr, "Warning: temperature read failed, retrying next cycle.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

