    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (handle=%d)\n",
                SDP810_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,differential_pressure_Pa,temperature_C\n");
    fflush(g_log_file);

    fprintf(stderr, "SDP810 HVAC airflow monitor started. Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, pressure, temperature);

            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr, "WARNING: Pressure exceeds threshold (%.2f Pa > %.2f Pa)!\n",
                        pressure, PRESSURE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Error: sensor read failed; will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

