#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES    3
#define TEMP_WAIT_US   20000

/* Si7021 commands (no-hold variant) */
#define CMD_MEASURE_RH   0xF5
#define CMD_MEASURE_TEMP 0xF3
#define CMD_READ_TEMP    0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fclose(fp);
    }
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

static int i2c_write_cmd(int handle, uint8_t cmd) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteByte(handle, cmd) == 0) return 0;
        gpioDelay(1000);
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int n = i2cReadDevice(handle, (char *)buf, len);
        if (n == len) return 0;
        gpioDelay(1000);
    }
    return -1;
}

static int read_temperature(int handle, float *temp_c) {
    if (i2c_write_cmd(handle, CMD_MEASURE_TEMP) != 0) return -1;
    gpioDelay(TEMP_WAIT_US);
    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = 175.72f * raw / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *hum_pct) {
    if (i2c_write_cmd(handle, CMD_MEASURE_RH) != 0) return -1;
    gpioDelay(TEMP_WAIT_US);
    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *hum_pct = 125.0f * raw / 65536.0f - 6.0f;
    if (*hum_pct < 0.0f) *hum_pct = 0.0f;
    if (*hum_pct > 100.0f) *hum_pct = 100.0f;
    return 0;
}

static int read_sensor_data(int handle, float *temp_c, float *hum_pct) {
    if (read_temperature(handle, temp_c) != 0) return -1;
    if (read_humidity(handle, hum_pct) != 0) return -1;
    return 0;
}

static void log_data(float temp_c, float hum_pct) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
        fclose(fp);
    }
    printf("%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
    fflush(stdout);
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Validate sensor presence by reading firmware revision (0x00) */
    uint8_t id_buf[2];
    if (i2c_read_bytes(g_i2c_handle, id_buf, 2) != 0) {
        log_error("Si7021 not responding on I2C bus");
        cleanup();
        return 1;
    }
    uint16_t id = ((uint16_t)id_buf[0] << 8) | id_buf[1];
    if (id == 0) {
        fprintf(stderr, "Si7021 not detected (ID=0x%04X)\n", id);
        cleanup();
        return 1;
    }

    printf("Si7021 detected (ID=0x%04X). Logging to %s every %d seconds.\n",
           id, LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        float temp_c, hum_pct;
        if (read_sensor_data(g_i2c_handle, &temp_c, &hum_pct) == 0) {
            log_data(temp_c, hum_pct);
        } else {
            log_error("Sensor read failed; skipping sample");
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

