    char config_data[2];
    char reg_ptr[1] = {HDC1080_TEMP_REG};
    char data[4];
    int result;

    // Configure: 14-bit temp, 14-bit humidity, no heater, no clock stretching
    config_data[0] = HDC1080_CONFIG_REG;
    config_data[1] = 0x00; // 14-bit temp, 14-bit humidity, no heater, no clock stretching
    result = i2cWriteDevice(handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing config register: %d\n", result);
        return -1;
    }

