            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stdout, "\nShutting down cleanly...\n");
    fclose(log_fp);
    close(fd);
    return EXIT_SUCCESS;
}

