#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_FILE_PATH "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_PATH "/var/log/scd40_error.log"
#define CSV_FILE_PATH "/var/log/scd40_data/scd40_data.csv"
#define STOP_MEASUREMENT_CMD 0x3F86
#define START_PERIODIC_CMD 0x21B1
#define READ_MEASUREMENT_CMD 0xE000
#define READ_INTERVAL_SEC 5
#define LOGGING_INTERVAL_SEC 60
#define MEASUREMENT_DELAY_SEC 1

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t data_buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static int pigpio_initialized = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_PATH, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    }
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int send_command(uint16_t command) {
    uint8_t buf[2] = { (command >> 8) & 0xFF, command & 0xFF };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        log_error("Failed to write command to SCD40");
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        log_error("Failed to read measurement from SCD40");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CRC error in CO2 data");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("CRC error in temperature data");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("CRC error in humidity data");
        return -1;
    }
    *co2 = (buf[0] << 8) | buf[1];
    *temperature = (buf[3] << 8) | buf[4];
    *humidity = (buf[6] << 8) | buf[7];
    return 0;
}

static void add_to_buffer(circular_buffer_t *buffer, time_t timestamp, float co2, float temperature, float humidity) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].co2 = co2;
    buffer->data[buffer->head].temperature = temperature;
    buffer->data[buffer->head].humidity = humidity;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE)
        buffer->count++;
    pthread_mutex_unlock(&buffer->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    FILE *fp = fopen(CSV_FILE_PATH, "w");
    if (!fp) {
        log_error("Failed to create CSV file for logging");
        return NULL;
    }
    fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
    fflush(fp);
    while (running) {
        time_t now = time(NULL);
        pthread_mutex_lock(&data_buffer.mutex);
        int start = (data_buffer.count < BUFFER_SIZE) ? 0 : data_buffer.head;
        int end = (data_buffer.count == BUFFER_SIZE) ? (start + BUFFER_SIZE) % BUFFER_SIZE : data_buffer.head;
        int count = data_buffer.count;
        sensor_data_t *data = data_buffer.data + start;
        pthread_mutex_unlock(&data_buffer.mutex);
        for (int i = 0; i < count; i++) {
            char timestamp_str[32];
            struct tm tm = *localtime(&data[i].timestamp);
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp_str, data[i].co2, data[i].temperature, data[i].humidity);
        }
        fflush(fp);
        sleep(LOGGING_INTERVAL_SEC);
    }
    fclose(fp);
    return NULL;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(STOP_MEASUREMENT_CMD);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&data_buffer.mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }
    pigpio_initialized = 1;

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        cleanup();
        return 1;
    }

    if (send_command(START_PERIODIC_CMD) != 0) {
        log_error("Failed to start periodic measurement");
        cleanup();
        return 1;
    }
    sleep(MEASUREMENT_DELAY_SEC);

    data_buffer.head = 0;
    data_buffer.count = 0;
    pthread_mutex_init(&data_buffer.mutex, NULL);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    logging_thread = pthread_create(&logging_thread, NULL, logging_thread_func, NULL);
    if (logging_thread == 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }

    while (running) {
        time_t now = time(NULL);
        uint16_t co2, temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            add_to_buffer(&data_buffer, now, (float)co2, (float)temperature, (float)humidity);
            printf("CO2: %.2f ppm, Temp: %.2f C, Hum: %.2f %%\n", (float)co2, (float)temperature, (float)humidity);
        } else {
            log_error("Failed to read sensor data");
        }
        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

