        return -1;
    }
    return 0;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing command 0x%04X: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error reading sensor data: expected 9 bytes, got %d\n", rc);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on pressure data\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }
