#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define COEFF_REG 0x05
#define MEASURE_REG 0x00
#define MEASURE_CMD 0x00
#define MEASURE_DELAY_US 10000
#define SAMPLE_INTERVAL_S 5
#define DATA_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_coefficients(int handle, uint16_t *c0, uint16_t *c1, uint16_t *c2, uint16_t *c3) {
    char buf[8];
    if (i2cReadI2CBlockData(handle, COEFF_REG, buf, 8) != 8) {
        fprintf(stderr, "Error reading calibration coefficients: %s\n", strerror(errno));
        return -1;
    }
    *c0 = (uint16_t)((buf[1] << 8) | buf[0]);
    *c1 = (uint16_t)((buf[3] << 8) | buf[2]);
    *c2 = (uint16_t)((buf[5] << 8) | buf[4]);
    *c3 = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

static int read_measurement(int handle, float *pressure, float *temperature) {
    char cmd = MEASURE_CMD;
    if (i2cWriteI2CBlockData(handle, MEASURE_REG, &cmd, 1) != 1) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);

    char data[6];
    if (i2cReadI2CBlockData(handle, MEASURE_REG, data, 6) != 6) {
        fprintf(stderr, "Error reading measurement data: %s\n", strerror(errno));
        return -1;
    }

    int32_t raw_pressure = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8) | (int32_t)data[2];
    int32_t raw_temperature = ((int32_t)data[3] << 16) | ((int32_t)data[4] << 8) | (int32_t)data[5];

    float p = (float)raw_pressure;
    float t = (float)raw_temperature;

    *pressure = (float)p / 100.0f;
    *temperature = (float)t / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f hPa, %.2f C\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s, %.2f hPa, %.2f C\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t c0, c1, c2, c3;
    if (read_coefficients(i2c_handle, &c0, &c1, &c2, &c3) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        fclose(data_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Weather station started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float pressure, temperature;
        if (read_measurement(i2c_handle, &pressure, &temperature) == 0) {
            log_data(data_file, pressure, temperature);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    if (data_file) fclose(data_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

