#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define FAN_GPIO 18
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define READ_RETRIES 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature_raw(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        rc = i2cReadI2CBlockData(handle, reg, buf, 2);
        if (rc == 2) {
            *out = (int16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (rc=%d): %s\n",
                attempt + 1, rc, pigpio_error(rc));
        if (attempt < READ_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static float convert_to_celsius(int16_t raw) {
    return (float)raw * 0.02f - 273.15f;
}

static int log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient, object);
    fclose(fp);
    return 0;
}

static void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (Object: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to set fan GPIO %d HIGH\n", FAN_GPIO);
        }
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Object: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to set fan GPIO %d LOW\n", FAN_GPIO);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, MLX90614_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("MLX90614 monitoring started. Logging to %s every 2 s.\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw_ambient, raw_object;

        if (read_temperature_raw(i2c_handle, AMBIENT_TEMP_REG, &raw_ambient) != 0) {
            fprintf(stderr, "Failed to read ambient temperature after retries.\n");
        } else if (read_temperature_raw(i2c_handle, OBJECT_TEMP_REG, &raw_object) != 0) {
            fprintf(stderr, "Failed to read object temperature after retries.\n");
        } else {
            float ambient = convert_to_celsius(raw_ambient);
            float object = convert_to_celsius(raw_object);

            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Failed to log temperature data.\n");
            }

            control_fan(object);
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

