#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define MEASURE_DELAY_MS 10
#define SERVER_PORT 8080
#define BUFFER_SIZE 1024

static int i2c_handle = -1;
static int server_fd = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sht40(int handle, sensor_data_t *data) {
    unsigned char cmd = MEASURE_CMD;
    unsigned char buf[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        usleep(MEASURE_DELAY_MS * 1000);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        unsigned int raw_t = (buf[0] << 8) | buf[1];
        unsigned int raw_h = (buf[3] << 8) | buf[4];

        data->temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
        data->humidity = -6.0f + 125.0f * (float)raw_h / 65535.0f;

        if (data->humidity < 0.0f) data->humidity = 0.0f;
        if (data->humidity > 100.0f) data->humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", RETRY_COUNT);
    return -1;
}

static void send_response(int client_fd, const char *status, const char *headers[], const char *body) {
    char buffer[BUFFER_SIZE];
    int len = snprintf(buffer, sizeof(buffer),
        "HTTP/1.1 %s\r\n"
        "Content-Type: %s\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        status, headers[0], strlen(headers[0]), body);

    if (len > 0) {
        send(client_fd, buffer, len, 0);
    }
}

static void handle_client(int client_fd) {
    sensor_data_t data;
    if (read_sht40(i2c_handle, &data) != 0) {
        const char *error_body = "Error reading sensor data.\n";
        send_response(client_fd, "200 OK", NULL, error_body);
        return;
    }

    const char *body = "Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity;
    send_response(client_fd, "200 OK", NULL, body);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", SERVER_PORT);

    while (!terminate) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("Accept failed");
            continue;
        }

        handle_client(client_fd);
        close(client_fd);
    }

    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    printf("Server terminated.\n");
    return 0;
}

