#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define HDC2010_ADDR        0x40
#define MEASUREMENT_CONFIG  0x0E
#define CONFIG              0x0F
#define TEMP_OUT_L          0x00
#define HUMID_OUT_L         0x02

#define I2C_BUS             1
#define POLL_TIMEOUT_MS     500
#define SAMPLE_INTERVAL_S   5
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int hdc2010_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int hdc2010_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int hdc2010_init(void) {
    if (hdc2010_write_reg(CONFIG, 0x00) < 0) return -1;
    if (hdc2010_write_reg(MEASUREMENT_CONFIG, 0x01) < 0) return -1;
    return 0;
}

static int hdc2010_read_temperature(float *temp) {
    uint8_t lo, hi;
    if (hdc2010_read_reg(TEMP_OUT_L, &lo) < 0) return -1;
    if (hdc2010_read_reg(TEMP_OUT_L + 1, &hi) < 0) return -1;
    int16_t raw = (int16_t)((hi << 8) | lo);
    *temp = ((float)raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int hdc2010_read_humidity(float *hum) {
    uint8_t lo, hi;
    if (hdc2010_read_reg(HUMID_OUT_L, &lo) < 0) return -1;
    if (hdc2010_read_reg(HUMID_OUT_L + 1, &hi) < 0) return -1;
    int16_t raw = (int16_t)((hi << 8) | lo);
    *hum = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: rc=%d\n", I2C_BUS, HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (hdc2010_init() < 0) {
        fprintf(stderr, "HDC2010 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HDC2010 initialized. Logging every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL_S);

    while (g_running) {
        int retries = 0;
        int ok = 0;

        while (retries < MAX_RETRIES && g_running) {
            uint8_t cfg;
            if (hdc2010_read_reg(MEASUREMENT_CONFIG, &cfg) < 0) {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(100000); /* 100 ms backoff */
                }
                continue;
            }
            if ((cfg & 0x01) == 0) {
                ok = 1;
                break;
            }
