        while (retries < MAX_RETRIES && g_running) {
            uint8_t cfg;
            if (hdc2010_read_reg(MEASUREMENT_CONFIG, &cfg) < 0) {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(100000); /* 100 ms backoff */
                }
