            }
            if ((cfg & 0x01) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms poll interval */
        }

        if (!ok) {
            fprintf(stderr, "Measurement timeout after %d retries\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float temperature, humidity;
        if (hdc2010_read_temperature(&temperature) < 0 || hdc2010_read_humidity(&humidity) < 0) {
            fprintf(stderr, "Sensor read error after timeout\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

