#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define MAX6675_CS_PIN 8
#define SOLID_STATE_RELAY_PIN 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_TEMP 100.0
#define MIN_TEMP -50.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *relay_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, MAX6675_CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line %d: %s\n", MAX6675_CS_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "max6675_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, SOLID_STATE_RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line %d: %s\n", SOLID_STATE_RELAY_PIN, strerror(errno));
        gpiod_line_release(cs_line);
        cs_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "solid_state_relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        cs_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    return 0;
}

int read_max6675(float *temperature) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    if (raw & 0x0004) {
        fprintf(stderr, "MAX6675 open-circuit flag set\n");
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 2);
    *temperature = (float)temp_raw * 0.25;
    return 0;
}

float pid_control(float setpoint, float actual, float *integral, float *prev_error) {
    float error = setpoint - actual;
    *integral += error;
    float deriv = error - *prev_error;
    float output = KP * error + KI * (*integral) + KD * deriv;
    *prev_error = error;
    return output;
}

int log_data(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Profile file not found. Using default profile.\n");
        fp = fopen(PROFILE_FILE, "w");
        if (!fp) {
            fprintf(stderr, "Failed to create profile file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        fprintf(fp, "0,0\n");
        fclose(fp);
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *endptr;
        float temp = strtof(line, &endptr);
        if (endptr == line) {
            fprintf(stderr, "Invalid profile format. Skipping line.\n");
            continue;
        }
        if (temp < MIN_TEMP || temp > MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temp);
            continue;
        }
        fprintf(fp, "%d,%.2f\n", (int)temp, temp);
    }
    fclose(fp);

    *integral = 0.0;
    *prev_error = 0.0;

    while (running) {
        float setpoint = 0.0;
        float actual = 0.0;
        float pid_output = 0.0;
        float temp;

        if (read_max6675(&temp) < 0) {
            fprintf(stderr, "Failed to read MAX6675. Skipping cycle.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        pid_output = pid_control(setpoint, temp, &(*integral), &(*prev_error));

        if (gpiod_line_set_value(relay_line, (pid_output > 0.0) ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to set relay: %s\n", strerror(errno));
        }

        if (log_data(temp) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

