#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_RELAY_LINE 17
#define GPIO_PWM_LINE 18
#define GPIO_TEMP_LINE 4

#define LOG_FILE "greenhouse.log"
#define TEMP_READ_INTERVAL_SEC 5
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_MAX 10000000

#define KP 1.0
#define KI 0.1
#define KD 0.01

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
struct gpiod_chip *chip = NULL;
struct gpiod_line *relay_line = NULL;
struct gpiod_line *pwm_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int read_temperature(float *temperature) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/bus/w1/devices/28-000003e0e0e0/w1_slave");
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }
    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    char *temp_str = strstr(line, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found\n");
        return -1;
    }
    char *endptr;
    long temp_raw = strtol(temp_str + 2, &endptr, 10);
    if (*endptr != '\0' && *endptr != '\n' && *endptr != '\r') {
        fprintf(stderr, "Invalid temperature data: %s\n", temp_str + 2);
        return -1;
    }
    *temperature = (float)temp_raw / 1000.0;
    return 0;
}

int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_DUTY_MAX) duty_cycle = PWM_DUTY_MAX;
    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        fprintf(stderr, "Error setting PWM high: %s\n", strerror(errno));
        return -1;
    }
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = (long)duty_cycle * 1000000000L / PWM_DUTY_MAX;
    if (nanosleep(&ts, NULL) < 0) {
        fprintf(stderr, "Error during PWM high: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Error setting PWM low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int control_heater(float setpoint, float current_temp, float *pid_output) {
    float error = setpoint - current_temp;
    *pid_output = KP * error + KI * (error * error) + KD * (error * error * error);
    int duty_cycle = (int)(*pid_output);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_DUTY_MAX) duty_cycle = PWM_DUTY_MAX;
    set_pwm_duty_cycle(duty_cycle);
    return 0;
}

void log_data(float avg_temp, float setpoint, float pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %d\n", timestamp, avg_temp, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

void cleanup() {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint_temp> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }
    float setpoint_temp = atof(argv[1]);
    float kp = atof(argv[2]);
    float ki = atof(argv[3]);
    float kd = atof(argv[4]);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }
    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY_LINE);
    pwm_line = gpiod_chip_get_line(chip, GPIO_PWM_LINE);
    if (!relay_line || !pwm_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(relay_line, "heater_relay", 0) < 0 ||
        gpiod_line_request_output(pwm_line, "heater_pwm", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float integral = 0.0, previous_error = 0.0;
    float current_temp = 0.0;
    float pid_output = 0.0;
    int pwm_duty_cycle = 0;
    while (program_running) {
        if (read_temperature(&current_temp) == 0) {
            integral += current_temp;
            float error = setpoint_temp - current_temp;
            pid_output = KP * error + KI * (error * error) + KD * (error * error * error);
            if (current_temp < 20.0) {
                pwm_duty_cycle = 0;
            } else {
                pwm_duty_cycle = (int)(pid_output);
            }
            if (control_heater(setpoint_temp, current_temp, &pid_output) != 0) {
                fprintf(stderr, "Error controlling heater\n");
            }
            log_data(current_temp, setpoint_temp, pid_output, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds\n", TEMP_READ_INTERVAL_SEC);
        }
        sleep(TEMP_READ_INTERVAL_SEC);
    }
    cleanup();
    return 0;
}

