#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define HUMIDITY_THRESHOLD 60.0f
#define DRY_AIR_THRESHOLD 55.0f
#define POLL_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MEASURE_DELAY_MS 80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t *cmd, size_t len) {
    for (size_t i = 0; i < len; i++) {
        if (write(fd, cmd + i, 1) != 1) {
            return -1;
        }
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        return -1;
    }
    if ((size_t)n != len) {
        return -1;
    }
    return 0;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    if (i2c_write_cmd(fd, init_cmd, sizeof(init_cmd)) < 0) {
        return -1;
    }
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    uint8_t trigger_cmd[] = {0xAC, 0x33, 0x00};
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(fd, trigger_cmd, sizeof(trigger_cmd)) < 0) {
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            return -1;
        }

        usleep(MEASURE_DELAY_MS * 1000);

        if (i2c_read_data(fd, data, sizeof(data)) < 0) {
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            return -1;
        }

        if (data[0] != 0x00 && data[0] != 0x01) {
            fprintf(stderr, "AHT20 status byte mismatch: 0x%02X\n", data[0]);
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            return -1;
        }

        uint32_t raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
        *humidity = (float)raw / 1048576.0f;
        return 0;
    }

    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int i2c_fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
