#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_RH_REG 0x00
#define HTU21D_CMD_BIT 0x80
#define HTU21D_CMD_MEASURE 0x2E
#define API_URL "http://api.example.com/humidity"
#define LOG_FILE "/var/log/htu21d_logger.log"
#define POLL_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sockfd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *msg) {
    openlog("htu21d_logger", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", msg);
    closelog();
}

static int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select) failed: %s", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    unsigned char cmd = HTU21D_CMD_BIT | HTU21D_CMD_MEASURE;
    unsigned char data[3];

    if (i2c_write_byte(fd, HTU21D_RH_REG, cmd) < 0) {
        return -1;
    }

    usleep(10000);

    if (i2c_read_bytes(fd, HTU21D_RH_REG, data, 3) < 0) {
        return -1;
    }

    if (data[0] & 0x80) {
        syslog(LOG_ERR, "HTU21D NACK: sensor not present or bus error");
        return -1;
    }

    int raw = ((data[1] << 8) | data[2]) >> 2;
    *humidity = (125.0f * raw) / 65536.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static int send_http_request(const char *url, const char *json_str) {
    struct sockaddr_in server_addr;
    int ret = -1;

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, url + strlen(url) - 4, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid URL: %s", url);
        return -1;
    }

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection to %s failed: %s", url, strerror(errno));
        goto cleanup;
    }

    char request[512];
    snprintf(request, sizeof(request),
             "POST /humidity HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             url, (int)strlen(json_str), json_str);

    if (write(sockfd, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "HTTP write failed: %s", strerror(errno));
        goto cleanup;
    }

    char response[1024];
    ssize_t n = read(sockfd, response, sizeof(response) - 1);
    if (n > 0) {
        response[n] = '\0';
        syslog(LOG_INFO, "HTTP response: %s", response);
    } else if (n < 0) {
        syslog(LOG_ERR, "HTTP read failed: %s", strerror(errno));
    }

cleanup:
    close(sockfd);
    sockfd = -1;
    return ret;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device %s: %s", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    syslog(LOG_INFO, "HTU21D logger started on %s at 0x%02X", I2C_DEVICE, HTU21D_ADDR);

    while (running) {
        float humidity;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            char json_str[128];
            snprintf(json_str, sizeof(json_str), "{\"humidity\": %.2f}", humidity);
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (send_http_request(API_URL, json_str) < 0) {
                syslog(LOG_ERR, "Failed to send HTTP request");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    if (i2c_fd >= 0) close(i2c_fd);
    if (sockfd >= 0) close(sockfd);
    return 0;
}

