/*
 * Raspberry Pi 4B - Daily Temperature/Humidity Logger with PIR Motion Detection
 *
 * Sensors:
 *   - TMP117 (I2C 0x48, temp reg 0x00, 16-bit signed big-endian, LSB = 0.0078125 C)
 *   - AHT20 (I2C 0x38, init cmd 0xBE0800, measure cmd 0xAC3300, 7-byte resp, 20-bit humidity/temp)
 *
 * PIR:   GPIO 17 (libgpiod)
 *
 * Build:  gcc -o logger logger.c -lgpiod -lrt
 * Run:    ./logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_GPIO_LINE  17
#define LOG_FILE_NAME  "daily_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define I2C_RETRIES    3
#define I2C_RETRY_DELAY_MS 10
#define AHT20_MEAS_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_open(const char *bus, uint8_t addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read block from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- TMP117 ---- */

static int tmp117_read_temp(int fd, float *temp_c) {
    uint8_t buf[2];
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2c_read_block(fd, 0x00, buf, 2) == 0) {
            int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
            *temp_c = (float)raw * 0.0078125f;
            return 0;
        }
        if (attempt < I2C_RETRIES - 1) {
            usleep(I2C_RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

/* ---- AHT20 ---- */

static int aht20_init(int fd) {
    uint8_t cmd[3] = {0xBE, 0x08, 0x00};
    if (i2c_write_byte(fd, 0xAC, 0x33) < 0) return -1;
