    if (i2c_write_byte(fd, 0xAC, 0x2A) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x29) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x28) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x27) < 0) return -1;
