    if (i2c_write_byte(fd, 0xAC, 0x08) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x07) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x06) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x05) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x04) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x03) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x02) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x00) < 0) return -1;
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity_pct) {
    uint8_t cmd[3] = {0xAC, 0x33, 0x00};
    if (i2c_write_byte(fd, 0xAC, 0x33) < 0) return -1;
    usleep(AHT20_MEAS_DELAY_MS * 1000);
    uint8_t buf[7];
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2c_read_block(fd, 0x00, buf, 7) == 0) {
            uint32_t raw = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
            uint32_t hum_raw = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
            uint32_t temp_raw = ((uint32_t)buf[6] << 8) | buf[7];
            if (raw & 0x800000) {
                *humidity_pct = (float)hum_raw / 1048576.0f * 100.0f;
            } else {
                *humidity_pct = 0.0f;
            }
            return 0;
        }
        if (attempt < I2C_RETRIES - 1) {
            usleep(I2C_RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

/* ---- Logging ---- */

static void log_data(const char *filename, float temp_c, float humidity_pct, int motion) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp_c, humidity_pct, motion);
    }
    fclose(fp);
}

/* ---- Main ---- */

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C buses */
    int tmp117_fd = i2c_open(I2C_BUS, TMP117_ADDR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "TMP117 init failed; continuing without it.\n");
    }
    int aht20_fd = i2c_open(I2C_BUS, AHT20_ADDR);
    if (aht20_fd < 0) {
        fprintf(stderr, "AHT20 init failed; continuing without it.\n");
    }

    /* Open GPIO chip and request PIR line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        goto cleanup;
    }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", PIR_GPIO_LINE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(pir, "pir-logger") < 0) {
        fprintf(stderr, "gpiod_line_request_input failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Daily timestamped log file */
    time_t last_midnight = 0;
    char log_filename[64];
    snprintf(log_filename, sizeof(log_filename), "%s", LOG_FILE_NAME);
    FILE *fp = fopen(log_filename, "r");
    if (!fp) {
        /* File does not exist yet; create it */
        fp = fopen(log_filename, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Failed to create log file: %s\n", strerror(errno));
            goto cleanup;
        }
        last_midnight = time(NULL);
    } else {
        fclose(fp);
    }
    last_midnight = time(NULL);

    printf("Logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        time_t now = time(NULL);
        int motion = gpiod_line_get_value(pir);

        float temp_c = 0.0f, humidity_pct = 0.0f;
        int tmp117_ok = 0, aht20_ok = 0;

        if (tmp117_fd >= 0) {
            if (tmp117_read_temp(tmp117_fd, &temp_c) == 0) tmp117_ok = 1;
        }
        if (aht20_fd >= 0) {
            if (aht20_init(aht20_fd) < 0) {
                fprintf(stderr, "AHT20 init failed; skipping.\n");
            } else {
                if (aht20_read_humidity(aht20_fd, &humidity_pct) == 0) aht20_ok = 1;
            }
        }

        if (tmp117_ok && aht20_ok) {
            log_data(log_filename, temp_c, humidity_pct, motion);
        } else {
            fprintf(stderr, "Sensor read error; skipping log.\n");
        }

        /* Midnight check */
        if (now == last_midnight) {
            if (fseek(fp, 0, SEEK_END) == 0) {
                long sz = ftell(fp);
                if (sz > 0) {
                    fseek(fp, 0, SEEK_SET);
                    if (ftruncate(fileno(fp), 0) == 0) {
                        fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
                    }
                }
            }
            last_midnight = now + 86400;
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

cleanup:
    if (pir) gpiod_line_release(pir);
    if (chip) gpiod_chip_close(chip);
    if (tmp117_fd >= 0) close(tmp117_fd);
    if (aht20_fd >= 0) close(aht20_fd);
    printf("\nClean shutdown.\n");
    return EXIT_SUCCESS;
}

