/*
 * Raspberry Pi 4B - Daily Temperature/Humidity Logger with PIR Motion Detection
 *
 * Sensors:
 *   - TMP117 (I2C 0x48, temp reg 0x00, 16-bit signed big-endian, LSB = 0.0078125 C)
 *   - AHT20 (I2C 0x38, init cmd 0xBE0800, measure cmd 0xAC3300, 7-byte resp, 20-bit humidity/temp)
 *
 * PIR:   GPIO 17 (libgpiod)
 *
 * Build:  gcc -o logger logger.c -lgpiod -lrt
 * Run:    ./logger
 */

#include <stdio.h>
