#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define SPI_FLAGS       0
#define PWM_FREQ        1000
#define PWM_RANGE       255
#define BUFFER_SIZE     20
#define SAMPLE_PERIOD_S 1

#define TEMP_MIN        25.0f
#define TEMP_RAMP_25_40 50.0f
#define TEMP_RAMP_40_60 100.0f
#define TEMP_MAX        60.0f

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int    spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

static void print_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&log_buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Temp: %.2f C, PWM: %d\n", ts, log_buffer[idx].temperature, log_buffer[idx].pwm_duty);
    }
    printf("--- End of Log Buffer ---\n\n");
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault bit set (0x%08X)\n", raw);
        return -1;
    }

    if (raw & 0x00000004) {
        fprintf(stderr, "MAX31855 OC fault\n");
        return -1;
    }
    if (raw & 0x00000002) {
        fprintf(stderr, "MAX31855 SCG fault\n");
        return -1;
    }
    if (raw & 0x00000001) {
        fprintf(stderr, "MAX31855 SCV fault\n");
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000;
    }
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < TEMP_MIN) {
        return 0;
    }
    if (temperature < TEMP_RAMP_25_40) {
        return (int)(TEMP_RAMP_25_40 - temperature);
    }
    if (temperature < TEMP_RAMP_40_60) {
        return (int)(TEMP_RAMP_25_40 + (temperature - TEMP_RAMP_25_40) * TEMP_RAMP_25_40 / (TEMP_RAMP_40_60 - TEMP_RAMP_25_40));
    }
    return (int)(TEMP_RAMP_40_60 + (temperature - TEMP_RAMP_40_60) * TEMP_RAMP_40_60 / (TEMP_MAX - TEMP_RAMP_40_60));
}

static void set_fan_speed(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) != 0) {
            fprintf(stderr, "Skipping cycle due to SPI/MAX31855 error\n");
        } else {
            int duty = calculate_pwm_duty(temperature);
            set_fan_speed(duty);

            time_t now = time(NULL);
            log_buffer[buffer_index].timestamp = now;
            log_buffer[buffer_index].temperature = temperature;
            log_buffer[buffer_index].pwm_duty = duty;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) buffer_count++;

            printf("Temp: %.2f C, PWM: %d\n", temperature, duty);
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

