#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5

#define MAX31865_RTD_MSB 0x00
#define MAX31865_RTD_LSB 0x01
#define MAX31865_RTD_XLSB 0x02
#define MAX31865_RTD_FAULT 0x03
#define MAX31865_RTD_CONFIG 0x04

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

int spi_xfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

int read_max31865(float *temperature) {
    uint8_t tx[4] = {MAX31865_RTD_MSB, MAX31865_RTD_LSB, MAX31865_RTD_XLSB, 0x00};
    uint8_t rx[4] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (spi_xfer(tx, rx, 4) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) | ((uint32_t)rx[2] << 8) | rx[3];

    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31865 Fault: Open circuit\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31865 Fault: Short circuit\n");
        } else if (raw & 0x00000004) {
            fprintf(stderr, "MAX31865 Fault: RTD overloaded\n");
        } else if (raw & 0x00000008) {
            fprintf(stderr, "MAX31865 Fault: RTD not connected\n");
        } else {
            fprintf(stderr, "MAX31865 Fault: Unknown\n");
        }
        return -1;
    }

    uint32_t rtd_raw = (raw >> 18) & 0x3FFFF;
    if (rtd_raw == 0) {
        fprintf(stderr, "MAX31865 RTD value is zero, invalid reading\n");
        return -1;
    }

    float rtd_resistance = (float)rtd_raw * 0.000025;
    float r0 = 50.0;
    float rs = rtd_resistance / 1000.0;
    float rtd_fraction = (rs - r0) / r0;
    float temperature = 0.0;

    if (rtd_fraction < 0.0) rtd_fraction = 0.0;
    if (rtd_fraction > 1.0) rtd_fraction = 1.0;

    temperature = (-45.0 + 175.0 * rtd_fraction) / 100.0;

    return 0;
}

int log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Failed to open log file");
            return -1;
        }
    }

    fprintf(log_fp, "%s,%.2f\n", timestamp, temperature);
    fflush(log_fp);
    return 0;
}

void cleanup(void) {
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("Failed to open gpiochip4");
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (cs_line == NULL) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "max31865_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    printf("MAX31865 RTD logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31865(&temperature) == 0) {
            if (log_data(temperature) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

