        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    printf("MAX31865 RTD logger started. Press Ctrl+C to exit.\n");

