#define BMP180_OSS 0
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;
static int32_t b5_lag = 0;
static int32_t b6_lag = 0;
static int32_t p_raw = 0;
static int32_t p_dev = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration(void) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START, buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }
    cal.ac1 = (buf[0] << 8) | buf[1];
    cal.ac2 = (buf[2] << 8) | buf[3];
    cal.ac3 = (buf[4] << 8) | buf[5];
    cal.ac4 = (buf[6] << 8) | buf[7];
    cal.ac5 = (buf[8] << 8) | buf[9];
    cal.ac6 = (buf[10] << 8) | buf[11];
    cal.b1 = (buf[12] << 8) | buf[13];
    cal.b2 = (buf[14] << 8) | buf[15];
    cal.mb = (buf[16] << 8) | buf[17];
    cal.mc = (buf[18] << 8) | buf[19];
    cal.md = (buf[20] << 8) | buf[21];
    return 0;
}

static int read_raw_temp(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error: failed to write temp command\n");
        return -1;
    }
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: failed to read temp MSB/LSB\n");
        return -1;
    }
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 2);
    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error: failed to read pressure MSB/LSB/XXSB\n");
        return -1;
    }
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    b5_lag = x1 + x2;
    return b5_lag;
}

static int32_t compute_b6(int32_t up) {
    int32_t b5 = compute_b5(p_raw);
    int32_t x1 = ((int32_t)cal.b2 * ((b5 * b5) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal.ac2 * b5) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b5) >> 13;
    x2 = ((int32_t)cal.b1 * ((b5 * b5) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void add_to_buffer(int32_t pressure) {
    static int32_t buffer[BUFFER_SIZE];
    static int head = 0;
    buffer[head] = pressure;
    head = (head + 1) % BUFFER_SIZE;
}

static double calculate_rolling_average(void) {
    static int32_t sum = 0;
    static int count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        sum -= buffer[idx];
    }
    sum += buffer[head - 1];
    count++;
    return (double)sum / count;
}

static void check_alert(double avg_pressure) {
    if (avg_pressure > 0.0 && fabs(avg_pressure - 0.0) > 5.0) {
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(1000000);
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void timer_callback(void *user) {
    (void)user;
    int32_t ut, up;
    if (read_raw_temp(&ut) < 0) return;
    if (read_raw_pressure(&up) < 0) return;
    int32_t b5 = compute_b5(ut);
    int32_t b6 = compute_b6(up);
    p_raw = b6;
    p_dev = b5 - 4000;
    add_to_buffer(p_dev);
    double avg = calculate_rolling_average();
    check_alert(avg);
    printf("Pressure: %d hPa, Rolling Average: %.2f hPa\n", p_dev, avg);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

