#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature");
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "fscanf temperature failed\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int calculate_duty(float temp) {
    if (temp < TEMP_MIN) temp = TEMP_MIN;
    if (temp > TEMP_MAX) temp = TEMP_MAX;
    float frac = (temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN);
    return (int)(frac * (float)PWM_RANGE);
}

static int set_fan_speed(int duty) {
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static int log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    if (!tm) {
        perror("localtime");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(log_fp, "%s, Temp: %.2f C, Duty: %d\n", ts, temp, duty) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Temperature read failed; skipping cycle\n");
        } else {
            int duty = calculate_duty(temp);
            if (set_fan_speed(duty) != 0) {
                fprintf(stderr, "Failed to set fan speed\n");
            }
            if (log_data(temp, duty) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return 0;
}

