#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define TARGET_TEMP 25.0
#define MAX_TEMP 80.0
#define CONFIG_FILE "config.json"

#define RREF 430.0
#define R0 100.0
#define A 0.0039082
#define B 0.00000070

#define CONFIG_KEY_TARGET_TEMP 0
#define CONFIG_KEY_PID_KP 1
#define CONFIG_KEY_PID_KI 2
#define CONFIG_KEY_PID_KD 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    float target_temp;
    float Kp;
    float Ki;
    float Kd;
} PIDConfig;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, PIDConfig *config) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open config file %s; using defaults\n", filename);
        config->target_temp = TARGET_TEMP;
        config->Kp = 1.0;
        config->Ki = 0.1;
        config->Kd = 0.01;
        return 0;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\n")] = 0;
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (!key || !value) continue;

        if (strcmp(key, "target_temp") == 0) {
            config->target_temp = strtof(value, NULL);
        } else if (strcmp(key, "PID_KP") == 0) {
            config->Kp = strtof(value, NULL);
        } else if (strcmp(key, "PID_KI") == 0) {
            config->Ki = strtof(value, NULL);
        } else if (strcmp(key, "PID_KD") == 0) {
            config->Kd = strtof(value, NULL);
        }
    }
    fclose(fp);
    return 0;
}

static int spi_read_max31865(int handle, float *temperature) {
    unsigned char tx[4] = {0x80, 0x80, 0x00, 0x00};
    unsigned char rx[4] = {0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    if (rx[0] & 0x01) {
        fprintf(stderr, "MAX31865 fault detected (D0=1)\n");
        return -2;
    }

    int rtd_code = ((rx[0] << 8) | rx[1]) & 0x3FFF;
    if (rtd_code & 0x0001) {
        fprintf(stderr, "MAX31865 fault: under-voltage\n");
        return -3;
    }
    if (rtd_code & 0x0002) {
        fprintf(stderr, "MAX31865 fault: over-voltage\n");
        return -4;
    }
    if (rtd_code & 0x0004) {
        fprintf(stderr, "MAX31865 fault: open circuit\n");
        return -5;
    }

    int fault_status = rx[2];
    if (fault_status & 0x01) {
        fprintf(stderr, "MAX31865 fault: open circuit\n");
        return -5;
    }
    if (fault_status & 0x02) {
        fprintf(stderr, "MAX31865 fault: short circuit\n");
        return -6;
    }

    *temperature = ((float)rtd_code / 32768.0f) * RREF;
    return 0;
}

static float calculate_temperature(float rtd_code) {
    if (rtd_code <= 0.0f) return -1000.0f;
    float r = 1.0f / rtd_code;
    float temp = (A * r - B * r * r) / (r * (1.0f + A * 1.0f + B * 1.0f));
    return temp;
}

static int pid_control(float setpoint, float actual, PIDConfig *cfg, float *integral, float *prev_error) {
    float error = setpoint - actual;
    *integral += error;
    float derivative = error - *prev_error;
    float output = cfg->Kp * error + cfg->Ki * (*integral) + cfg->Kd * derivative;
    *prev_error = error;
    if (output < 0.0f) output = 0.0f;
    if (output > 100.0f) output = 100.0f;
    return (int)output;
}

static int set_pwm(int gpio, int duty) {
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    PIDConfig cfg = {TARGET_TEMP, cfg->Kp, cfg->Ki, cfg->Kd};
    read_config(CONFIG_FILE, &cfg);

    float integral = 0.0f, prev_error = 0.0f;
    float rtd_code = 0.0f;
    float temperature = -1000.0f;

    while (running) {
        int rc = spi_read_max31865(spi_handle, &temperature);
        if (rc == 0) {
            rtd_code = (float)rc;
            temperature = calculate_temperature(rtd_code);
            if (temperature < -999.0f) {
                fprintf(stderr, "Invalid temperature reading\n");
                set_pwm(HEATER_GPIO, 0);
                running = 0;
            }
        } else if (rc == -1) {
            set_pwm(HEATER_GPIO, 0);
            running = 0;
        } else if (rc == -2) {
            set_pwm(HEATER_GPIO, 0);
            running = 0;
        } else if (rc == -3) {
            set_pwm(HEATER_GPIO, 0);
            running = 0;
        } else if (rc == -4) {
            set_pwm(HEATER_GPIO, 0);
            running = 0;
        } else if (rc == -5) {
            set_pwm(HEATER_GPIO, 0);
            running = 0;
        } else if (rc == -6) {
            set_pwm(HEATER_GPIO, 0);
            running = 0;
        }

        float duty = pid_control(cfg.target_temp, temperature, &cfg, &integral, &prev_error);
        if (temperature > MAX_TEMP) {
            set_pwm(HEATER_GPIO, 0);
            running = 0;
        } else {
            set_pwm(HEATER_GPIO, (int)duty);
        }

        gpioDelay(100000);
    }

    set_pwm(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

