    fprintf(fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", ts, temp, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(fd, &cal) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(fd);
        return 1;
    }

    printf("BMP180 initialized. Monitoring temperature and pressure every %d second(s).\n", SAMPLE_INTERVAL_SEC);

    while (running) {
        int32_t ut, up;
        if (read_raw_temp(fd, &ut) < 0 || read_raw_pressure(fd, &up) < 0) {
            fprintf(stderr, "Sensor read error, retrying in %d second(s)...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        int32_t temp = compute_temp(ut, &cal);
        float temp_c = temp / 10.0f;
        int32_t press = compute_pressure(up, ut, &cal);
        float press_hpa = press / 100.0f;

        if (check_breach(temp_c, press_hpa)) {
            log_breach(temp_c, press_hpa);
            printf("Breach detected: Temp=%.2f C, Pressure=%.2f hPa\n", temp_c, press_hpa);
        } else {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp_c, press_hpa);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

