#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 500000
#define OSS 0

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

static sensor_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_word(int handle, uint8_t reg, int16_t *out) {
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

static int i2c_read_word_u(int handle, uint8_t reg, uint16_t *out) {
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_calibration(int handle) {
    if (i2c_read_word_u(handle, BMP180_REG_CAL_AC1, &cal.ac1) < 0) return -1;
    if (i2c_read_word_u(handle, 0xAC, &cal.ac2) < 0) return -1;
    if (i2c_read_word_u(handle, 0xAE, &cal.ac3) < 0) return -1;
    if (i2c_read_word_u(handle, 0xB0, &cal.ac4) < 0) return -1;
    if (i2c_read_word_u(handle, 0xB2, &cal.ac5) < 0) return -1;
    if (i2c_read_word_u(handle, 0xB4, &cal.ac6) < 0) return -1;
    if (i2c_read_word_u(handle, 0xB6, &cal.b1) < 0) return -1;
