#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define SPI_FLAGS 0
#define TARGET_TEMPERATURE 25.0
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define PI_GAIN 0.1
#define MAX_DUTY_CYCLE 800
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0x00, 0x00, 0x00, 0x00};
    char rx[4] = {0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: Open circuit\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: Short to GND\n");
        } else if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 fault: Unknown\n");
        }
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    if (thermocouple_raw & 0x0800) {
        thermocouple_raw |= 0xF000;
    }
    *temperature = thermocouple_raw * 0.25;
    return 0;
}

static int set_heater_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "gpioPWM failed for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float temperature, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        set_heater_pwm(HEATER_GPIO, 0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    float current_temperature = TARGET_TEMPERATURE;
    float integral = 0.0;
    float previous_error = 0.0;
    int duty_cycle = 0;

    while (running) {
        if (read_max31855(spi_handle, &current_temperature) != 0) {
            fprintf(stderr, "SPI read error, setting heater to 0%%\n");
            set_heater_pwm(HEATER_GPIO, 0);
            duty_cycle = 0;
            log_data(log_file, 0.0, duty_cycle);
            gpioDelay(100000);
            continue;
        }

        float error = current_temperature - TARGET_TEMPERATURE;
        integral += error;
        float derivative = error - previous_error;
        float output = PI_GAIN * (integral + derivative);

        if (output < 0) {
            output = 0;
        } else if (output > MAX_DUTY_CYCLE) {
            output = MAX_DUTY_CYCLE;
        }

        duty_cycle = (int)output;
        if (set_heater_pwm(HEATER_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Failed to set heater PWM\n");
        }

        if (log_data(log_file, current_temperature, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        previous_error = error;
        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

