#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define PWM_RANGE  255
#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define POLL_US   500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }

    int millideg;
    if (fscanf(fp, "%d", &millideg) != 1) {
        fprintf(stderr, "fscanf temperature failed\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose temperature file");
        return -1;
    }

    if (millideg < 0 || millideg > 200000) {
        fprintf(stderr, "Temperature out of range: %d m°C\n", millideg);
        return -1;
    }
    return millideg;
}

static void set_led_color(int r, int g, int b)
{
    /* Common-anode: duty 0 = fully on, duty 255 = fully off.
     * Invert so that 255 = fully off, 0 = fully on. */
    int r_inv = 255 - r;
    int g_inv = 255 - g;
    int b_inv = 255 - b;

    if (gpioPWM(RED_PIN, r_inv) < 0)
        fprintf(stderr, "gpioPWM(RED_PIN) failed\n");
    if (gpioPWM(GREEN_PIN, g_inv) < 0)
        fprintf(stderr, "gpioPWM(GREEN_PIN) failed\n");
    if (gpioPWM(BLUE_PIN, b_inv) < 0)
        fprintf(stderr, "gpioPWM(BLUE_PIN) failed\n");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs and set PWM range. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all LED cathodes start in the off state (common anode). */
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Mood light started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            /* Read error: turn off LED and continue. */
            gpioPWM(RED_PIN, 255);
            gpioPWM(GREEN_PIN, 255);
            gpioPWM(BLUE_PIN, 255);
            gpioDelay(POLL_US);
            continue;
        }

        printf("Temperature: %d m°C\n", temp);

        if (temp < 40000) {
            set_led_color(0, 0, 255);
        } else if (temp < 60000) {
            set_led_color(0, 255, 0);
        } else {
            set_led_color(255, 0, 0);
        }

        printf("RGB: R=%d G=%d B=%d\n",
               gpioRead(RED_PIN),
               gpioRead(GREEN_PIN),
               gpioRead(BLUE_PIN));

        gpioDelay(POLL_US);
    }

    /* Clean shutdown: turn off all LED cathodes. */
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();
    printf("\nMood light stopped.\n");
    return EXIT_SUCCESS;
}

