#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <jansson.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 100000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_BIT_THRESHOLD 50
#define DHT22_BIT_LOW_US 50
#define DHT22_BIT_HIGH_US 50

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int last_state = PI_HIGH;
    uint32_t start_tick, end_tick;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(gpio, PI_INPUT);

    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_HIGH) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_LOW) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_HIGH) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }

    for (int i = 0; i < 40; i++) {
        bit_count = 0;
        while (gpioRead(gpio) == last_state) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
            bit_count++;
            start_tick = gpioTick();
        }
        last_state = gpioRead(gpio);

        if (bit_count > DHT22_BIT_THRESHOLD) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0;
}

int post_data(const char *url, const char *json_string) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else if (http_code < 200 || http_code >= 300) {
        fprintf(stderr, "Error: HTTP request failed with code %ld\n", http_code);
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return (res == CURLE_OK && http_code >= 200 && http_code < 300) ? 0 : -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int retries = 0;

    while (!terminate) {
        int result = read_dht22(DHT22_GPIO, &temperature, &humidity);
        if (result == 0) {
            retries = 0;
            char json_string[256];
            snprintf(json_string, sizeof(json_string),
                     "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);

            if (post_data("http://yourserver.com/api/humidity", json_string) == 0) {
                printf("Data sent successfully: %s\n", json_string);
            } else {
                fprintf(stderr, "Error: Failed to post data\n");
            }
        } else {
            retries++;
            fprintf(stderr, "Error: DHT22 read failed (attempt %d/%d)\n", retries, MAX_RETRIES);
            if (retries < MAX_RETRIES) {
                sleep(1);
            }
        }
    }

    gpioTerminate();
    return 0;
}

