#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 2000
#define SLEEP_INTERVAL_S 10
#define MAX_URL_LEN 256
#define MAX_PAYLOAD_LEN 256

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int read_dht22(int gpio, float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int last_state = 1;
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    sleep_ms(1);
    gpioWrite(gpio, 1);
    sleep_ms(30);
    gpioSetMode(gpio, PI_INPUT);

    for (i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(gpio) == last_state) {
            count++;
            sleep_ms(1);
            if (count == 255) return -1;
        }
        last_state = gpioRead(gpio);
        if (i >= 4 && data[bit_idx] == 0) {
            if (count > 30) {
                data[bit_idx] = 1;
            }
        }
        bit_idx++;
        if (bit_idx == 5) {
            bit_idx = 0;
            if (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
                *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
                *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
                return 0;
            }
        }
    }
    return -1;
}

static int post_humidity(const char *url, float humidity) {
    CURL *curl = NULL;
    CURLcode res;
    char json[MAX_PAYLOAD_LEN];
    int retry_count = 0;

    snprintf(json, sizeof(json), "{\"humidity\":%.2f}", humidity);

    while (retry_count < MAX_RETRIES) {
        curl_global_init(CURL_GLOBAL_ALL);
        curl = curl_easy_init();
        if (!curl) {
            syslog(LOG_ERR, "curl_easy_init() failed");
            retry_count++;
            sleep_ms(RETRY_DELAY_MS);
            continue;
        }

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
        curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                syslog(LOG_INFO, "Humidity POSTed: %s", json);
                return 0;
            } else {
                syslog(LOG_ERR, "HTTP %ld returned; retrying...", http_code);
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        retry_count++;
        sleep_ms(RETRY_DELAY_MS);
    }

    syslog(LOG_ERR, "Failed to post humidity after %d retries", MAX_RETRIES);
    curl_global_cleanup();
    return -1;
}

int main(int argc, char *argv[]) {
    char url[MAX_URL_LEN];
    float humidity;
    int ret = 1;

    if (argc > 1) {
        strncpy(url, argv[1], MAX_URL_LEN - 1);
        url[MAX_URL_LEN - 1] = '\0';
    } else {
        url[0] = '\0';
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Starting humidity monitor on GPIO %d", DHT22_GPIO);

    while (program_running) {
        if (read_dht22(DHT22_GPIO, &humidity, NULL) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(url, humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from DHT22");
        }

        for (int i = 0; i < SLEEP_INTERVAL_S && program_running; i++) {
            sleep_ms(1000);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    curl_global_cleanup();
    return ret;
}

