    if (speed < 0 || speed > 3) {
        fprintf(stderr, "Invalid fan speed %d (must be 0-3)\n", speed);
        return -1;
    }

    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", speed);
    if (len < 0 || len >= (int)sizeof(buf)) {
        fprintf(stderr, "Error formatting fan speed %d\n", speed);
        return -1;
    }

    FILE *fp = fopen(FAN_CONTROL_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_CONTROL_FILE, strerror(errno));
        return -1;
