#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define TARGET_TEMP 50.0
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_TEMP 100.0
#define MIN_TEMP -50.0

#define MAX31855_FAULT_OPEN 0x01
#define MAX31855_FAULT_GND 0x02
#define MAX31855_FAULT_VCC 0x04

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double Kp = 1.0, Ki = 0.1, Kd = 0.01;
static double integral = 0.0, previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

static void log_data(double temp, double duty, double pid_out) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f, %.2f, %.2f\n", ts, temp, duty, pid_out);
    fclose(fp);
}

static int read_max31855(double *temp) {
    char rx[4] = {0, 0, 0, 0};
    int ret = spiRead(spi_handle, rx, 4);
    if (ret != 4) {
        log_message("SPI read failed");
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        if (raw & MAX31855_FAULT_OPEN) log_message("Thermocouple open circuit");
        if (raw & MAX31855_FAULT_GND) log_message("Thermocouple short to GND");
        if (raw & MAX31855_FAULT_VCC) log_message("Thermocouple short to VCC");
        return -2;
    }
    int16_t mc = (int16_t)(raw >> 18);
    *temp = (double)mc * 0.25;
    return 0;
}

static double pid_control(double setpoint, double actual) {
    double error = setpoint - actual;
    integral += error;
    double deriv = error - previous_error;
    double out = Kp * error + Ki * integral + Kd * deriv;
    previous_error = error;
    if (out > 100.0) out = 100.0;
    if (out < 0.0) out = 0.0;
    return out;
}

static void cleanup(void) {
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_message("PID controller started");
    double setpoint = TARGET_TEMP;
    double integral_buf = 0.0;
    double prev_err = 0.0;
    while (running) {
        double temp;
        if (read_max31855(&temp) == 0) {
            if (temp > MAX_TEMP) {
                log_message("Failsafe: temp exceeds max");
                gpioPWM(HEATER_GPIO, 0);
                log_data(temp, 0.0, 0.0);
            } else if (temp < MIN_TEMP) {
                log_message("Failsafe: temp below min");
                gpioPWM(HEATER_GPIO, 0);
                log_data(temp, 0.0, 0.0);
            } else {
                double pid = pid_control(setpoint, temp);
                int duty = (int)(pid * 100.0);
                if (duty < 0) duty = 0;
                if (duty > PWM_RANGE) duty = PWM_RANGE;
                gpioPWM(HEATER_GPIO, duty);
                log_data(temp, duty, pid);
                integral_buf += pid;
            }
        } else {
            log_message("Thermocouple fault, disabling heater");
            gpioPWM(HEATER_GPIO, 0);
            log_data(0.0, 0.0, 0.0);
        }
        sleep(1);
    }
    cleanup();
    log_message("PID controller stopped");
    return 0;
}

