#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define SLF3S_CONT_MEAS_CMD 0x3608
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = { (SLF3S_CONT_MEAS_CMD >> 8) & 0xFF, SLF3S_CONT_MEAS_CMD & 0xFF };
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Error: I2C write failed (handle %d, attempt %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(10000);

        if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
            fprintf(stderr, "Error: I2C read failed (handle %d, attempt %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Error: CRC mismatch on handle %d (attempt %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        int16_t raw = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw * 0.01f;
        return 0;
    }

    fprintf(stderr, "Error: Failed to read flow rate from handle %d after %d retries\n", handle, MAX_RETRIES);
    return -1;
}

static int log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 1 (addr 0x%02X)\n", SENSOR1_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 2 (addr 0x%02X)\n", SENSOR2_ADDR);
        i2cClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ret1 = read_flow_rate(handle1, &flow1);
        int ret2 = read_flow_rate(handle2, &flow2);

        if (ret1 == 0 && ret2 == 0) {
            if (log_flow_rates(flow1, flow2) != 0) {
                fprintf(stderr, "Error: Failed to log flow rates\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor read failure (s1=%d, s2=%d)\n", ret1, ret2);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

