        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_B_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int read_sensor(int pin) {
    int a = gpioRead(pin);
    gpioDelay(1000);
    int b = gpioRead(pin);
    return (a << 1) | b;
}

int calculate_angle(int a, int b) {
    int state = (a << 1) | b;
    if (state == 0) {
        return 0;
    }
    if (state == 1) {
        return 90;
    }
    if (state == 2) {
        return 180;
