#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ADPD144RI_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LED 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL_MS 100

#define REG_PART_ID 0x00
#define REG_FIFO_DATA 0x01
#define REG_FIFO_CONFIG 0x02

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int adpd144ri_init(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID — sensor may be absent or bus error.\n");
        return -1;
    }
    printf("ADPD144RI detected (PART_ID = 0x%02X).\n", part_id);
    return 0;
}

static int adpd144ri_read_ir(int fd, uint16_t *ir_value) {
    return i2c_read_reg16(fd, REG_FIFO_DATA, ir_value);
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

