#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_OUT_PIN 18
#define GPIO_IN_PIN 17
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_audio_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s LEVEL\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *out_line = NULL;
    struct gpiod_line *in_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    out_line = gpiod_chip_get_line(chip, GPIO_OUT_PIN);
    if (!out_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_OUT_PIN, strerror(errno));
        goto cleanup;
    }

    in_line = gpiod_chip_get_line(chip, GPIO_IN_PIN);
    if (!in_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_IN_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(out_line, "max9814-gain", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_OUT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(in_line, "max9814-input") < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", GPIO_IN_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    int prev_value = 0;
    int first_sample = 1;

    while (program_running) {
        int value = gpiod_line_get_value(in_line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_IN_PIN, strerror(errno));
            break;
        }

        if (value != prev_value) {
            if (first_sample || value == 1) {
                if (log_audio_event() == 0) {
                    printf("Audio peak detected and logged.\n");
                }
            }
            prev_value = value;
            first_sample = 0;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (out_line) {
        gpiod_line_release(out_line);
    }
    if (in_line) {
        gpiod_line_release(in_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Audio peak detection stopped.\n");
    return ret;
}

