#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000

/* Sensirion CRC-8: polynomial 0x31, initial value 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_sensor(int handle) {
    /* Start continuous measurement: command 0x3608 */
    uint8_t cmd[2] = {0x36, 0x08};
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing init command to I2C: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading flow data: expected 3 bytes, got %d\n", rc);
        return -1;
    }

    /* Validate CRC over the two data bytes */
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 1000.0f;
    return 0;
}

static void log_flow_rate(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate);
    fflush(fp);
}

static void cleanup(int handle, FILE *fp) {
    if (handle >= 0)
        i2cClose(handle);
    if (fp) {
        fflush(fp);
        fclose(fp);
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    cleanup(handle, fp);
    exit(0);
}

int main(void) {
    int handle = -1;
    FILE *fp = NULL;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SLF3S_ADDR, handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup(handle, fp);
        return 1;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup(handle, fp);
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        float flow_rate;
        if (read_flow_rate(handle, &flow_rate) == 0) {
            log_flow_rate(fp, flow_rate);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup(handle, fp);
    return 0;
}

