        if (read_sensor_data(i2c_handle, &tvoc, &eco2) == 0) {
            iaq = calculate_iaq(tvoc, eco2);
            log_data(log_file, iaq, tvoc, eco2);
            printf("TVOC: %u ppb, eCO2: %u ppm, IAQ: %.2f\n", tvoc, eco2, iaq);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

