#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS  100
#define TOUCH_THRESHOLD_S 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        printf("[%ld.%09ld] ", (long)ts.tv_sec, ts.tv_nsec);
    } else {
        printf("[?] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as input with consumer label */
    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (chip %s). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);

    int last_state = 0;
    struct timespec touch_start;
    clock_gettime(CLOCK_MONOTONIC, &touch_start);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        if (value == 1 && last_state == 0) {
            print_timestamp();
            printf("Intrusion alert: TTP223B touched for more than %d seconds!\n", TOUCH_THRESHOLD_S);
            fflush(stdout);
        }

        last_state = value;

        /* Check if the sensor has been continuously touched for TOUCH_THRESHOLD_S seconds */
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - touch_start.tv_sec) * 1000L +
                          (now.tv_nsec - touch_start.tv_nsec) / 1000000L;

        if (elapsed_ms >= TOUCH_THRESHOLD_S * 1000L) {
            print_timestamp();
            printf("Intrusion alert: TTP223B touched for more than %d seconds!\n", TOUCH_THRESHOLD_S);
            fflush(stdout);
            touch_start = now;  /* Reset the timer on release */
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

