#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/soundcard.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define SAMPLE_RATE 48000
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "inmp441_l", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static int init_soundcard(void) {
    int fd = open("/dev/snd/pcmC0D0c", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open soundcard device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SNDCTL_DSP_SELECT, GPIO_LINE_OFFSET) < 0) {
        fprintf(stderr, "Failed to select GPIO line for I2S: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_audio_data(int fd, int16_t *buffer, int num_samples) {
    if (num_samples <= 0) return -1;

    for (int i = 0; i < num_samples; i++) {
        uint8_t buffer_bytes[BUFFER_SIZE * 2];
        ssize_t bytes_read = read(fd, buffer_bytes, sizeof(buffer_bytes));

        if (bytes_read < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading audio data: %s\n", strerror(errno));
            return -1;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "Unexpected EOF reading audio data\n");
            return -1;
        }

        for (int j = 0; j < BUFFER_SIZE; j++) {
            int32_t raw_sample = (int32_t)buffer_bytes[j * 2] << 16 | (int32_t)buffer_bytes[j * 2 + 1];
            buffer[i * 2] = (int16_t)(raw_sample >> 16);
            buffer[i * 2 + 1] = (int16_t)(raw_sample >> 8);
        }
    }

    return 0;
}

static int write_audio_data(const char *filename, const int16_t *buffer, int num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t elements_written = fwrite(buffer, sizeof(int16_t), num_samples, fp);
    if (elements_written != num_samples) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    int soundcard_fd = init_soundcard();
    if (soundcard_fd < 0) {
        gpiod_line_release(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    int16_t *audio_buffer = (int16_t *)malloc(BUFFER_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Failed to allocate memory for audio buffer\n");
        close(soundcard_fd);
        gpiod_line_release(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_audio_data(soundcard_fd, audio_buffer, BUFFER_SIZE) < 0) {
            break;
        }

        if (write_audio_data("audio_capture.pcm", audio_buffer, BUFFER_SIZE) < 0) {
            break;
        }

        usleep(100000);
    }

    free(audio_buffer);
    close(soundcard_fd);
    gpiod_line_release(gpiod_line);
    gpiod_chip_close(gpiod_chip);

    printf("\nAudio capture stopped.\n");
    return 0;
}

