#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_PWM_GPIO 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 50000
#define LOG_FILE "flame_log.txt"
#define FLAME_TIMEOUT_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    }
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(FAN_PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan GPIO mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(FAN_PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_PWM_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize fan PWM to 0\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int val = gpioRead(FLAME_SENSOR_GPIO);
    if (val < 0) {
        fprintf(stderr, "Failed to read flame sensor GPIO\n");
        return -1;
    }
    return val;
}

static int control_fan(int flame_detected) {
    if (flame_detected) {
        int duty = 0;
        for (int i = 0; i <= 80 && program_running; i++) {
            duty += i;
            if (gpioPWM(FAN_PWM_GPIO, duty) != 0) {
                fprintf(stderr, "Failed to set fan PWM duty cycle\n");
                return -1;
            }
            gpioDelay(10000);
        }
        if (gpioPWM(FAN_PWM_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to turn off fan PWM\n");
            return -1;
        }
    } else {
        if (gpioPWM(FAN_PWM_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to turn off fan PWM\n");
            return -1;
        }
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(FAN_PWM_GPIO, 0);
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_PWM_GPIO, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("System started");

    int last_flame_state = -1;
    uint32_t flame_start_tick = 0;
    uint32_t flame_end_tick = 0;

    while (program_running) {
        int flame_val = read_flame_sensor();
        if (flame_val < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick();
        if (flame_val != last_flame_state) {
            if (flame_val == 0) {
                if (flame_start_tick == 0) {
                    flame_start_tick = now;
                } else {
                    uint32_t diff = now - flame_start_tick;
                    if (diff > FLAME_TIMEOUT_US) {
                        if (flame_end_tick == 0) {
                            flame_end_tick = now;
                        }
                        if (flame_end_tick != 0) {
                            int duration = flame_end_tick - flame_start_tick;
                            int duty = (int)(((float)duration / 100000.0) * 80.0);
                            if (control_fan(1) != 0) {
                                log_event("Error: Failed to control fan");
                            }
                            if (duty > 0) {
                                log_event("Flame detected, fan activated");
                            }
                        }
                    }
                }
                last_flame_state = flame_val;
            } else {
                if (flame_end_tick != 0) {
                    uint32_t diff = now - flame_end_tick;
                    if (diff > FLAME_TIMEOUT_US) {
                        if (control_fan(0) != 0) {
                            log_event("Error: Failed to control fan");
                        }
                        log_event("Flame ended, fan deactivated");
                    }
                    flame_end_tick = 0;
                }
            }
        }
        gpioDelay(DEBOUNCE_DELAY_US);
    }

    log_event("System shutting down");
    cleanup();
    return 0;
}

