#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_MODE    0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24

#define MAGIC_NUMBER 0x52444144
#define LOG_FILE     "radar_data.log"
#define FRAME_SIZE   32768
#define FRAME_PERIOD_MS 100

typedef struct {
    float start_freq;
    float end_freq;
    int    chirps;
    int    samples;
    int    frame_period_ms;
} RadarConfig;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting trigger pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error writing trigger pin\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting data ready pin mode\n");
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "0x%08X\n", MAGIC_NUMBER);
        fflush(log_file);
    }
    return 0;
}

static int log_frame(int frame_number, const uint8_t *data, int frame_size) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%d\n", timestamp, frame_number, frame_size) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int read_radar_data(uint8_t *data, int frame_size) {
    if (spi_handle < 0) {
        fprintf(stderr, "SPI handle invalid\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error asserting trigger pin\n");
        return -1;
    }
    gpioDelay(1000);

    if (gpioSetAlertFunc(DATA_READY_PIN, data_ready_callback) != 0) {
        fprintf(stderr, "Error setting data ready callback\n");
        return -1;
    }

    int bytes_read = 0;
    while (bytes_read < frame_size) {
        int ret = spiXfer(spi_handle, (char *)data + bytes_read, (char *)data, frame_size - bytes_read);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer error: %d\n", ret);
            return -1;
        }
        bytes_read += ret;
    }

    if (gpioSetAlertFunc(DATA_READY_PIN, NULL) != 0) {
        fprintf(stderr, "Error clearing data ready callback\n");
        return -1;
    }
    return 0;
}

static void data_ready_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        uint8_t *data = malloc(FRAME_SIZE);
        if (data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        if (read_radar_data(data, FRAME_SIZE) == 0) {
            log_frame(0, data, FRAME_SIZE);
            free(data);
        } else {
            fprintf(stderr, "Failed to read radar data\n");
        }
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (init_log() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    RadarConfig config = {
        .start_freq = 77.0f,
        .end_freq = 79.0f,
        .chirps = 64,
        .samples = 256,
        .frame_period_ms = FRAME_PERIOD_MS
    };

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_radar_data(NULL, FRAME_SIZE) == 0) {
            int frame_number = 0;
            uint8_t *data = malloc(FRAME_SIZE);
            if (data != NULL) {
                log_frame(frame_number, data, FRAME_SIZE);
                free(data);
            }
        }
        gpioDelay(FRAME_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

