    if (spi_handle < 0) {
        fprintf(stderr, "SPI handle invalid\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error asserting trigger pin\n");
        return -1;
    }
    gpioDelay(1000);

    if (gpioSetAlertFunc(DATA_READY_PIN, data_ready_callback) != 0) {
        fprintf(stderr, "Error setting data ready callback\n");
        return -1;
    }

    int bytes_read = 0;
    while (bytes_read < frame_size) {
        int ret = spiXfer(spi_handle, (char *)data + bytes_read, (char *)data, frame_size - bytes_read);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer error: %d\n", ret);
            return -1;
        }
        bytes_read += ret;
    }

    if (gpioSetAlertFunc(DATA_READY_PIN, NULL) != 0) {
        fprintf(stderr, "Error clearing data ready callback\n");
        return -1;
    }
    return 0;
}

static void data_ready_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        uint8_t *data = malloc(FRAME_SIZE);
        if (data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        if (read_radar_data(data, FRAME_SIZE) == 0) {
            log_frame(0, data, FRAME_SIZE);
            free(data);
        } else {
            fprintf(stderr, "Failed to read radar data\n");
        }
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (init_log() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    RadarConfig config = {
        .start_freq = 77.0f,
        .end_freq = 79.0f,
        .chirps = 64,
        .samples = 256,
        .frame_period_ms = FRAME_PERIOD_MS
    };

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_radar_data(NULL, FRAME_SIZE) == 0) {
            int frame_number = 0;
            uint8_t *data = malloc(FRAME_SIZE);
            if (data != NULL) {
                log_frame(frame_number, data, FRAME_SIZE);
                free(data);
            }
        }
        gpioDelay(FRAME_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

