#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define REG_PART_ID 0x02
#define EXPECTED_PART_ID 0x3001
#define I2C_BUS 1
#define CONVERSION_TIME_MS 100
#define LOG_FILE "light_data.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_part_id(uint16_t *part_id) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, REG_PART_ID, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading PART_ID: %d\n", rc);
        return -1;
    }
    *part_id = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    if (*part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%04X (expected 0x%04X)\n", *part_id, EXPECTED_PART_ID);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    uint16_t config = 0x0000;
    config |= (0x01 << 15); /* Continuous conversion, 100 ms */
    config |= (0x00 << 12); /* Automatic full-scale range */
    config |= (0x00 << 9);  /* No averaging */
    config |= (0x00 << 6);  /* No interrupt */
    config |= (0x00 << 3);  /* No gain adjustment */
    config |= (0x00 << 0);  /* No power-down */

    char buf[3];
    buf[0] = REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    int rc = i2cWriteI2CBlockData(i2c_handle, buf[0], &buf[1], 2);
    if (rc != 2) {
        fprintf(stderr, "Error writing CONFIG: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *raw) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, REG_RESULT, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading result: %d\n", rc);
        return -1;
    }
    *raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    return 0;
}

static float calculate_lux(uint16_t raw) {
    uint8_t exponent = (raw >> 12) & 0x0F;
    uint8_t mantissa = raw & 0x0FFF;
    return 0.01f * (1 << exponent) * (float)mantissa;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f\n", ts, lux);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_part_id(&EXPECTED_PART_ID) != 0) {
        fprintf(stderr, "OPT3001 not detected on I2C bus %d at address 0x%02X\n", I2C_BUS, OPT3001_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting continuous light measurements. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t raw;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_sensor_data(&raw) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying sensor read (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(100000); /* 100 ms backoff */
            }
        }

        if (success) {
            float lux = calculate_lux(raw);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(CONVERSION_TIME_MS * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

