/*
 * Flame Detection System using SainSmart IR Flame Detection Module
 * Board: Raspberry Pi 3 Model B+
 * Sensor: SainSmart IR Flame Detection Module (DOUT pin)
 * Wiring: Module VCC -> 3.3V (Pin 1), GND -> GND (Pin 6), DOUT -> GPIO17 (Pin 11)
 * DOUT is active-low: 0 = flame detected, 1 = no flame
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s", buffer);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *line_req = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_config = NULL;
    struct gpiod_line_config *line_config = NULL;
    int ret;

    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
