#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 18
#define RIGHT_SENSOR_PIN 27
#define POLL_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor outputs to settle */
    usleep(100000);  /* 100 ms */

    /* Main polling loop */
    while (g_running) {
        int left_val = gpioRead(LEFT_SENSOR_PIN);
        int center_val = gpioRead(CENTER_SENSOR_PIN);
        int right_val = gpioRead(RIGHT_SENSOR_PIN);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: failed to read GPIO pins\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    return EXIT_SUCCESS;
}

