#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int init_gpio(void)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = touch_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", pin);
            return -1;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", pin);
            return -1;
        }
    }
    return 0;
}

static int read_touch_data(int *data)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        data[i] = gpioRead(touch_pins[i]);
        if (data[i] < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", touch_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void log_data(const int *data)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] ", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("CH%d=%d ", i + 1, data[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int data[NUM_CHANNELS];

    while (!terminate) {
        if (read_touch_data(data) == 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Warning: read_touch_data failed, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

