/*
 * TMAG5110 Hall-Effect Latch Reader for Raspberry Pi 3 Model B+
 * Library: pigpio
 *
 * Wiring:
 *   TMAG5110 OUT1 -> BCM GPIO 4 (external pull-up assumed)
 *   TMAG5110 OUT2 -> BCM GPIO 5 (external pull-up assumed)
 *
 * The TMAG5110 open-drain digital OUT pin reads HIGH when the magnet
 * is present and the sensor is de-asserted (latch closed), and LOW when
 * the magnet is absent and the sensor is asserted (latch open).
 *
 * Build: gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 * Run:   sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs --- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Enable internal pull-up resistors (external pull-ups assumed) --- */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n", SENSOR_1_PIN);
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n", SENSOR_2_PIN);
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("TMAG5110 Hall-Effect Latch Reader\n");
    printf("  Sensor 1: BCM GPIO %d\n", SENSOR_1_PIN);
    printf("  Sensor 2: BCM GPIO %d\n", SENSOR_2_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: GPIO read error (s1=%d, s2=%d).\n", s1, s2);
        } else {
            printf("Sensor 1 (BCM %d): %s\n", SENSOR_1_PIN,
                   (s1 == 0) ? "LOW" : "HIGH");
            printf("Sensor 2 (BCM %d): %s\n", SENSOR_2_PIN,
                   (s2 == 0) ? "LOW" : "HIGH");
        }

        fflush(stdout);
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

