#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_data(const int values[NUM_CHANNELS]) {
    FILE *fp = fopen("touch_data.csv", "a");
    if (!fp) {
        fprintf(stderr, "Error opening touch_data.csv: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        fprintf(fp, ",%d", values[i]);
    }
    fprintf(fp, "\n");
    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input_flags(lines[i], "ttp226-touch", GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE) < 0) {
            fprintf(stderr, "Error requesting GPIO line %u as input: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
                goto cleanup;
            }
            values[i] = val;
        }

        log_data(values);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("\nExiting gracefully...\n");
    return ret;
}

