#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_tilt_event(int tilt_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (tilt_state == 0) {
        printf("%s - Tilted\n", timestamp);
    } else {
        printf("%s - Not Tilted\n", timestamp);
    }
    fflush(stdout);
}

int main(void)
{
    int ret;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO 4 as input with internal pull-up --- */
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d.\n", TILT_SENSOR_GPIO);
    printf("Polling every %d ms. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_US / 1000);
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int tilt_state = gpioRead(TILT_SENSOR_GPIO);

        if (tilt_state < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d (code %d)\n",
                    TILT_SENSOR_GPIO, tilt_state);
            break;
        }

        log_tilt_event(tilt_state);

        /* Sleep 100 ms; gpioDelay is interruptible by signals */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

