#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR_1   0x36
#define SLF3S_ADDR_2   0x37
#define GPIO_CHIP       "gpiochip4"
#define ALARM_GPIO      17
#define FLOW_THRESHOLD  0.5f
#define SCALE_FACTOR    0.036f
#define MEAS_DELAY_MS   100
#define LOG_FILE        "flow_log.txt"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Sensirion 8-bit CRC: poly 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t reg, uint16_t cmd) {
    uint8_t buf[3] = { reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_out) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, 0x00, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on CRC data\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw_flow * SCALE_FACTOR;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }
    struct gpiod_line *alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(fd1);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(fd1, I2C_SLAVE, SLF3S_ADDR_1) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SLF3S_ADDR_1, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd2, I2C_SLAVE, SLF3S_ADDR_2) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SLF3S_ADDR_2, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_cmd(fd1, 0x08, 0x3608) < 0 || i2c_write_cmd(fd2, 0x08, 0x3608) < 0)
        goto cleanup;

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = 0, ok2 = 0;

        if (read_flow_rate(fd1, &flow1) == 0) ok1 = 1;
        if (read_flow_rate(fd2, &flow2) == 0) ok2 = 1;

        if (ok1 && ok2) {
            float avg = (flow1 + flow2) / 2.0f;
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

            FILE *fp = fopen(LOG_FILE, "a");
            if (fp) {
                fprintf(fp, "%s, %.3f ml/min\n", ts, avg);
                fclose(fp);
            } else {
                fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            }

            int alarm = (avg < FLOW_THRESHOLD) ? 1 : 0;
            if (gpiod_line_set_value(alarm_line, alarm) < 0)
                fprintf(stderr, "Failed to set alarm GPIO: %s\n", strerror(errno));
        } else {
            fprintf(stderr, "Sensor read error (s1=%s s2=%s)\n", ok1 ? "ok" : "fail", ok2 ? "ok" : "fail");
        }

        sleep(1);
    }

cleanup:
    if (alarm_line) gpiod_line_set_value(alarm_line, 0);
    if (fd1 >= 0) close(fd1);
    if (fd2 >= 0) close(fd2);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    return 0;
}

