#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55
#define D7S_REG_MODE   0x1D
#define D7S_REG_STATUS 0x1B
#define D7S_REG_X_LSB  0x2A
#define D7S_REG_X_MSB  0x2B
#define D7S_REG_Y_LSB  0x2C
#define D7S_REG_Y_MSB  0x2D
#define D7S_REG_Z_LSB  0x2E
#define D7S_REG_Z_MSB  0x2F
#define D7S_MODE_ACTIVE 0x10
#define D7S_ACTIVE_TIMEOUT_MS 1000
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILENAME "fan_health.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int d7s_init(int fd)
{
    if (i2c_write_reg8(fd, D7S_REG_MODE, D7S_MODE_ACTIVE) < 0)
        return -1;
    for (int i = 0; i < D7S_ACTIVE_TIMEOUT_MS; i++) {
        uint8_t status;
        if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(10000);
    }
    fprintf(stderr, "D7S sensor not active within %d ms\n", D7S_ACTIVE_TIMEOUT_MS);
    return -1;
}

static int d7s_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, D7S_REG_X_LSB, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_X_MSB, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Y_LSB, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Y_MSB, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Z_LSB, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Z_MSB, &zh) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%d,%d,%d\n", timestamp, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv);
    }

    while (g_running) {
        int16_t x, y, z;
        if (d7s_read_acceleration(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying next cycle\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }
        log_data(g_csv, x, y, z);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

