#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN     25
#define POLL_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
    }
    return v;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (safe_set_mode(SENSOR1_PIN, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR2_PIN, PI_INPUT) != 0 ||
        safe_set_mode(LED_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure LED starts OFF --- */
    if (safe_write(LED_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-032 obstacle avoidance monitor running.\n");
    printf("  Sensor 1: GPIO %d\n", SENSOR1_PIN);
    printf("  Sensor 2: GPIO %d\n", SENSOR2_PIN);
    printf("  LED      : GPIO %d\n", LED_PIN);
    printf("  Poll     : %d ms\n", POLL_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    int led_on = 0;

    while (g_running) {
        int s1 = safe_read(SENSOR1_PIN);
        int s2 = safe_read(SENSOR2_PIN);

        /* KY-032 OUT is active-LOW: 0 = obstacle detected */
        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;

        if (safe_write(LED_PIN, obstacle ? 1 : 0) != 0) {
            break;
        }

        if (obstacle && !led_on) {
            if (safe_write(LED_PIN, 1) == 0) {
                led_on = 1;
            }
        } else if (!obstacle && led_on) {
            if (safe_write(LED_PIN, 0) == 0) {
                led_on = 0;
            }
        }

        usleep(POLL_US);
    }

    /* --- Clean shutdown --- */
    safe_write(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

