    if (safe_set_mode(SENSOR1_PIN, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR2_PIN, PI_INPUT) != 0 ||
        safe_set_mode(LED_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure LED starts OFF --- */
    if (safe_write(LED_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-032 obstacle avoidance monitor running.\n");
    printf("  Sensor 1: GPIO %d\n", SENSOR1_PIN);
    printf("  Sensor 2: GPIO %d\n", SENSOR2_PIN);
    printf("  LED      : GPIO %d\n", LED_PIN);
    printf("  Poll     : %d ms\n", POLL_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    int led_on = 0;

    while (g_running) {
        int s1 = safe_read(SENSOR1_PIN);
        int s2 = safe_read(SENSOR2_PIN);

        /* KY-032 OUT is active-LOW: 0 = obstacle detected */
        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;

        if (safe_write(LED_PIN, obstacle ? 1 : 0) != 0) {
            break;
        }

        if (obstacle && !led_on) {
            if (safe_write(LED_PIN, 1) == 0) {
                led_on = 1;
            }
        } else if (!obstacle && led_on) {
            if (safe_write(LED_PIN, 0) == 0) {
                led_on = 0;
            }
        }

        usleep(POLL_US);
    }

    /* --- Clean shutdown --- */
    safe_write(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

