        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "GPIO read error on pin %d\n", SENSOR_GPIO);
