#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4          /* BCM 4 (physical pin 7) */
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_PERIOD_US 1000000  /* 1 second in microseconds */
#define PULSES_PER_REV 1

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of GPIO_PIN            */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;

    if (level == 1) {
        /* Rising edge: increment pulse count atomically */
        atomic_fetch_add(&pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Read current pulse count and compute RPM                          */
/* ------------------------------------------------------------------ */
static int read_rpm(void)
{
    int pulses = atomic_exchange(&pulse_count, 0);
    int rpm = (int)(pulses * 60 / PULSES_PER_REV);
    return rpm;
}

/* ------------------------------------------------------------------ */
/* Append one timestamped line to the log file                         */
/* ------------------------------------------------------------------ */
static void log_rpm(int rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s %d\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO_PIN as input with internal pull-up -------- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Start a 1-second timer to sample every 100 ms ---------- */
    if (gpioSetTimerFunc(0, SAMPLE_PERIOD_US / 1000,
                         pulse_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetTimerFunc failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file for appending -------------------------------- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        gpioSetTimerFunc(0, SAMPLE_PERIOD_US / 1000, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring RPM on GPIO %d. Press Ctrl+C to stop.\n", GPIO_PIN);

    /* ---- Main sampling loop ----------------------------------------- */
    while (running) {
        int rpm = read_rpm();
        log_rpm(rpm);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");

    /* Disable the timer so no further callbacks fire after we exit */
    gpioSetTimerFunc(0, 0, NULL, NULL);

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

