    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO_PIN as input with internal pull-up -------- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Start a 1-second timer to sample every 100 ms ---------- */
    if (gpioSetTimerFunc(0, SAMPLE_PERIOD_US / 1000,
                         pulse_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetTimerFunc failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file for appending -------------------------------- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        gpioSetTimerFunc(0, SAMPLE_PERIOD_US / 1000, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring RPM on GPIO %d. Press Ctrl+C to stop.\n", GPIO_PIN);

    /* ---- Main sampling loop ----------------------------------------- */
    while (running) {
        int rpm = read_rpm();
        log_rpm(rpm);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");

    /* Disable the timer so no further callbacks fire after we exit */
    gpioSetTimerFunc(0, 0, NULL, NULL);

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

