#include <errno.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"
#define POLL_DELAY_US 10000
#define CONSUMER "rotation_detector"

static volatile sig_atomic_t running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

/* Quadrature state machine: 0 = no rotation, 1 = CW, 2 = CCW */
typedef enum { STATE_NONE = 0, STATE_CW = 1, STATE_CCW = 2 } quadrature_state_t;
static quadrature_state_t current_state = STATE_NONE;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_rotation(const char *direction) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fprintf(log_file, "%s - %s\n", timestamp, direction);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void hall_sensor_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;

    if (level != 0 && level != 1) {
        return;
    }

    static int last_a = 0;
    static int last_b = 0;
    static int a_prev = 0;
    static int b_prev = 0;

    int a_val = (level == 1) ? 1 : 0;
    int b_val = (level == 0) ? 1 : 0;

    if (a_val != last_a) {
        if (a_val == 1) {
            current_state = STATE_CW;
        } else {
            current_state = STATE_CCW;
        }
        last_a = a_val;
    }

    if (b_val != last_b) {
        if (b_val == 1) {
            current_state = STATE_CW;
        } else {
            current_state = STATE_CCW;
        }
        last_b = b_val;
    }

    /* Only log on state change */
    if (current_state != a_prev) {
        const char *dir = (current_state == STATE_CW) ? "CW" : "CCW";
        log_rotation(dir);
        a_prev = current_state;
    }
}

