#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define TOUCH_GPIO 17
#define LED_GPIO 18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!touch_line) {
        perror("gpiod_chip_get_line(touch)");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    /* Request touch line as input with rising-edge event detection */
    if (gpiod_line_request_rising_edge_events(touch_line, "touch-sensor") < 0) {
        perror("gpiod_line_request_rising_edge_events(touch)");
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "led-output", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int led_state = 0;
    struct timespec last_event = {0, 0};

    while (running) {
        struct timespec ts = {0, 100000000}; /* 100 ms poll timeout */
        int ev = gpiod_line_event_wait(touch_line, &ts);

        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            goto cleanup;
        }

        if (ev == 0) {
            /* Timeout, no event — loop back to check running flag */
            continue;
        }

        /* Event detected — read it to clear the event queue */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            perror("gpiod_line_event_read");
            goto cleanup;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        /* Debounce: ignore events within DEBOUNCE_MS of the last accepted one */
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - last_event.tv_sec) * 1000L +
