    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!touch_line) {
        perror("gpiod_chip_get_line(touch)");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    /* Request touch line as input with rising-edge event detection */
    if (gpiod_line_request_rising_edge_events(touch_line, "touch-sensor") < 0) {
        perror("gpiod_line_request_rising_edge_events(touch)");
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "led-output", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int led_state = 0;
    struct timespec last_event = {0, 0};

    while (running) {
