#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22
#define POLL_DELAY_US 50000   /* 50 ms */
#define BUFFER_SIZE 100

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} TouchEvent;

static TouchEvent touch_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int buffer_overflow = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_2_PIN);
        return -1;
    }

    /* Start with LEDs off */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED %d to LOW\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED %d to LOW\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return v;
}

static int write_led(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void add_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }

    touch_buffer[buffer_index].sensor_pin = sensor_pin;
    touch_buffer[buffer_index].timestamp = now;
    touch_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    } else {
        buffer_overflow++;
    }
}

static void print_buffer(void) {
    printf("\n--- Touch Event Log (%d events) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Event %d: Sensor=GPIO%d, Timestamp=%ld, State=%d\n",
               i, touch_buffer[idx].sensor_pin,
               touch_buffer[idx].timestamp, touch_buffer[idx].state);
    }
    if (buffer_overflow > 0) {
        printf("Overflow: %d events overwritten (buffer %d entries)\n",
               buffer_overflow, BUFFER_SIZE);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failure, continuing...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* TTP223B is active-high: 1 = touched */
        int l1 = (s1 == 1) ? 1 : 0;
        int l2 = (s2 == 1) ? 1 : 0;

        if (write_led(LED_1_PIN, l1) != 0) {
            fprintf(stderr, "Error: failed to write LED %d\n", LED_1_PIN);
        }
        if (write_led(LED_2_PIN, l2) != 0) {
            fprintf(stderr, "Error: failed to write LED %d\n", LED_2_PIN);
        }

        add_event(SENSOR_1_PIN, l1);
        add_event(SENSOR_2_PIN, l2);

        printf("Sensor1=%s LED1=%s  Sensor2=%s LED2=%s\n",
               s1 ? "TOUCH" : "Released", l1 ? "ON" : "OFF",
               s2 ? "TOUCH" : "Released", l2 ? "ON" : "OFF");

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    write_led(LED_1_PIN, 0);
    write_led(LED_2_PIN, 0);
    gpioTerminate();
    print_buffer();
    return 0;
}

