#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_event(const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int last_state = -1;
    int current_state;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", RAIN_SENSOR_GPIO);

    while (program_running) {
        current_state = gpioRead(RAIN_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", RAIN_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                if (log_event("Rain Detected") != 0) {
                    fprintf(stderr, "Warning: failed to log rain event\n");
                }
            } else {
                if (log_event("No Rain") != 0) {
                    fprintf(stderr, "Warning: failed to log no-rain event\n");
                }
            }
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    printf("Rain sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

