#define DEBOUNCE_US 5000
#define PULSES_PER_REV 2
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    int high_count = gpioRead(gpio);
    gpioDelay(DEBOUNCE_US);
    int low_count = gpioRead(gpio);
    return (high_count == 1 && low_count == 0) ? 1 : 0;
}

static int calculate_rpm(int sensor1_state, int sensor2_state) {
    static int last_state1 = 0;
    static int last_state2 = 0;
    static uint32_t last_tick1 = 0;
    static uint32_t last_tick2 = 0;
    static int pulse_count1 = 0;
    static int pulse_count2 = 0;

    uint32_t now = gpioTick();

    if (sensor1_state != last_state1) {
        pulse_count1 = 0;
        last_state1 = sensor1_state;
    }
    if (sensor2_state != last_state2) {
        pulse_count2 = 0;
        last_state2 = sensor2_state;
    }

    if (sensor1_state == 1) {
        pulse_count1++;
    }
    if (sensor2_state == 1) {
        pulse_count2++;
    }

    uint32_t elapsed = now - last_tick1;
    if (pulse_count1 > 0) {
        int pulses = (int)(elapsed / 1000000);
        if (pulses >= PULSES_PER_REV) {
            return (pulses / PULSES_PER_REV) * 60;
        }
    }
    pulse_count1 = 0;

    elapsed = now - last_tick2;
    if (pulse_count2 > 0) {
        int pulses = (int)(elapsed / 1000000);
        if (pulses >= PULSES_PER_REV) {
            return (pulses / PULSES_PER_REV) * 60;
        }
    }
    pulse_count2 = 0;

    return 0;
}

static int log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring shaft RPM on GPIO %d and %d. Press Ctrl+C to exit.\n", SENSOR1_GPIO, SENSOR2_GPIO);

    while (running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        int rpm = calculate_rpm(sensor1_state, sensor2_state);

        if (rpm > 0) {
            printf("RPM: %d\n", rpm);
        }

        if (log_data(sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

