#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Si1182 I2C address (7-bit) */
#define SI1182_ADDR 0x28

/* Si1182 register addresses */
#define REG_PART_ID      0x00
#define REG_HW_KEY       0x07
#define REG_MEAS_RATE    0x08
#define REG_CONFIG       0x30
#define REG_HR_DATA      0x02
#define REG_SPO2_DATA    0x04

/* Expected PART_ID for Si1182 */
#define SI1182_PART_ID   0x82

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a Si1182 register; returns 0 on success, -1 on error */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a byte from a Si1182 register; returns 0 on success, -1 on error */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Initialize the Si1182 sensor: verify PART_ID and configure for continuous measurement */
static int si1182_init(int handle) {
    uint8_t part_id = 0;

    /* Verify sensor identity */
    if (si1182_read_reg(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1182_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X)\n", part_id);

    /* Write HW_KEY to enable continuous measurement */
    if (si1182_write_reg(handle, REG_HW_KEY, 0x00) != 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    /* Set measurement rate to 1 Hz (0x00) */
    if (si1182_write_reg(handle, REG_MEAS_RATE, 0x00) != 0) {
        fprintf(stderr, "Failed to write MEAS_RATE\n");
        return -1;
    }

    /* Configure for continuous measurement (example settings) */
    if (si1182_write_reg(handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Failed to write CONFIG\n");
        return -1;
    }

    return 0;
}

/* Read heart rate and SpO2 data from the Si1182 */
static int si1182_read_data(int handle, int *heart_rate, int *spo2) {
    uint8_t hr_raw = 0, spo2_raw = 0;

    if (si1182_read_reg(handle, REG_HR_DATA, &hr_raw) != 0) {
        return -1;
    }
    if (si1182_read_reg(handle, REG_SPO2_DATA, &spo2_raw) != 0) {
        return -1;
    }

    /* Convert raw values to BPM and SpO2 percentages (example conversions) */
    *heart_rate = (int)((hr_raw * 100) / 100);
    *spo2 = (int)(((spo2_raw * 100) / 100) + 50);

    return 0;
}

/* Log data to file with timestamp */
static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        return;
    }

    if (fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n",
                timestamp, heart_rate, spo2) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
    } else {
        fflush(fp);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at Si1182 address */
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (pigpio rc=%d)\n",
                SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1182_init(i2c_handle) != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not register SIGINT handler\n");
    }

    printf("Logging Si1182 data to biometric_log.txt. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        int heart_rate = 0, spo2 = 0;

        if (si1182_read_data(i2c_handle, &heart_rate, &spo2) == 0) {
            log_data(log_file, heart_rate, spo2);
            printf("Heart Rate: %d BPM, SpO2: %d%%\n", heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        sleep(1);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

