/*
 * Seismic event monitor for Raspberry Pi 3 Model B+
 * Sensor : Omron D7S-A0011 (I2C 7-bit addr 0x1D, SDA=GPIO2, SCL=GPIO3)
 * LED    : GPIO 17 (active-high)
 * Library: pigpio (C API)
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run  : sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* Omron D7S-A0011 default 7-bit addr */
#define LED_GPIO             17
#define THRESHOLD            500          /* Euclidean vibration magnitude */
#define POLL_INTERVAL_US     100000       /* 100 ms */
#define LED_ON_US            1000000       /* 1 s */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S-A0011 register addresses (16-bit, little-endian on bus) */
#define REG_CTRL1            0x1F
#define REG_STATUS           0x20
#define REG_AX_X_LSB         0x28
#define REG_AX_X_MSB         0x29
#define REG_AX_Y_LSB         0x2A
#define REG_AX_Y_MSB         0x2B
#define REG_AX_Z_LSB         0x2C
#define REG_AX_Z_MSB         0x2D

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Forward declarations ------------------------- */
static int  i2c_read_reg16(int handle, uint8_t reg, int16_t *out);
static int  i2c_write_reg8(int handle, uint8_t reg, uint8_t val);
static int  sensor_init(int handle);
static int  read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
static double calculate_vibration(int16_t x, int16_t y, int16_t z);
static void log_event(double vibration);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- I2C helpers ------------------------------ */

/*
 * Read a 16-bit little-endian register from the D7S-A0011.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_reg16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) != 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/*
 * Write a single byte to a 16-bit-addressed register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    char buf[1] = { (char)val };
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */
static int sensor_init(int handle)
{
    int16_t status;

    /* Verify sensor presence by reading STATUS (0x20).
     * A 0 indicates power-down or unknown state; a 1 indicates data-ready. */
    if (i2c_read_reg16(handle, REG_STATUS, &status) != 0) {
        fprintf(stderr, "[SENSOR] Cannot read STATUS register.\n");
        return -1;
    }
    if (status == 0) {
        fprintf(stderr, "[SENSOR] Sensor not detected (STATUS=0).\n");
        return -1;
    }

    /* Clear the power-down bit (bit 0) in CTRL1 (0x1F). */
    if (i2c_write_reg8(handle, REG_CTRL1, 0x01) != 0) {
        fprintf(stderr, "[SENSOR] Failed to clear power-down bit.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

/* --------------------------- Read acceleration --------------------------- */
static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    if (i2cReadDevice(handle, buf, 6) != 6) {
        fprintf(stderr, "[ACC] Failed to read 6-byte acceleration block.\n");
        return -1;
    }
    *x = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    *y = (int16_t)((uint16_t)buf[2] | ((uint16_t)buf[3] << 8));
    *z = (int16_t)((uint16_t)buf[4] | ((uint16_t)buf[5] << 8));
    return 0;
}

/* --------------------------- Vibration magnitude -------------------------- */
static double calculate_vibration(int16_t x, int16_t y, int16_t z)
{
    double vx = (double)x;
    double vy = (double)y;
    double vz = (double)z;
    return sqrt(vx * vx + vy * vy + vz * vz);
}

/* --------------------------- Logging ------------------------------------- */
static void log_event(double vibration)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(g_log_file, "%s - Vibration: %.2f\n", ts, vibration) < 0) {
        fprintf(stderr, "[LOG] Failed to write to log file.\n");
    }
    fflush(g_log_file);
}

/* --------------------------- Cleanup -------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Main ----------------------------------------- */
int main(void)
{
    int16_t x, y, z;
    double vibration;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (sensor_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[FATAL] sigaction failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic event monitor running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
                vibration = calculate_vibration(x, y, z);
                if (vibration > THRESHOLD) {
                    log_event(vibration);
                    printf("[ALERT] Vibration %.2f exceeded threshold %.0f\n",
                           vibration, THRESHOLD);
                    gpioWrite(LED_GPIO, 1);
                    gpioDelay(LED_ON_US);
                    gpioWrite(LED_GPIO, 0);
                    ok = 1;
                    break;
                }
            } else {
                fprintf(stderr, "[WARN] Read attempt %d/%d failed.\n",
                        attempt + 1, MAX_RETRIES);
            }
            gpioDelay(POLL_INTERVAL_US);
        }

        if (!ok) {
            fprintf(stderr, "[WARN] Sensor read failed after %d attempts. "
                            "Sensor may be disconnected or bus error.\n",
                    MAX_RETRIES);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

