    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(g_log_file, "%s - Vibration: %.2f\n", ts, vibration) < 0) {
        fprintf(stderr, "[LOG] Failed to write to log file.\n");
    }
    fflush(g_log_file);
}

/* --------------------------- Cleanup -------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Main ----------------------------------------- */
int main(void)
{
    int16_t x, y, z;
    double vibration;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (sensor_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[FATAL] sigaction failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic event monitor running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
                vibration = calculate_vibration(x, y, z);
                if (vibration > THRESHOLD) {
                    log_event(vibration);
                    printf("[ALERT] Vibration %.2f exceeded threshold %.0f\n",
                           vibration, THRESHOLD);
                    gpioWrite(LED_GPIO, 1);
                    gpioDelay(LED_ON_US);
                    gpioWrite(LED_GPIO, 0);
                    ok = 1;
                    break;
                }
            } else {
                fprintf(stderr, "[WARN] Read attempt %d/%d failed.\n",
                        attempt + 1, MAX_RETRIES);
            }
            gpioDelay(POLL_INTERVAL_US);
        }

        if (!ok) {
            fprintf(stderr, "[WARN] Sensor read failed after %d attempts. "
                            "Sensor may be disconnected or bus error.\n",
                    MAX_RETRIES);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

