#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define LED_PIN 18
#define POLL_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip4 on Raspberry Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        chip = gpiod_chip_open_lookup("gpiochip4");
    }
    if (!chip) {
        chip = gpiod_chip_open_lookup("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get sensor lines (GPIO 4, 17, 27, 22) */
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, (unsigned)i);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get sensor line %d: %s\n",
                    i, strerror(errno));
            goto cleanup;
        }
    }

    /* Get LED line (GPIO 18) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request sensor lines as inputs */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(sensor_lines[i], "ky032_sensor") < 0) {
            fprintf(stderr, "Failed to request sensor line %d as input: %s\n",
                    i, strerror(errno));
            goto cleanup;
        }
    }

    /* Request LED line as output, initial value LOW (off) */
    if (gpiod_line_request_output(led_line, "ky032_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line %d as output: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle detection running. Press Ctrl+C to exit.\n");

    while (running) {
        int any_detected = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor %d: %s\n",
                        i, strerror(errno));
                continue;
            }
            /* KY-032 OUT is active-low: 0 = object detected */
            if (val == 0) {
                any_detected = 1;
            }
        }

        /* Turn LED on if any sensor detects an object */
        if (any_detected) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Error setting LED on: %s\n", strerror(errno));
            }
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Error setting LED off: %s\n", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

