/*
 * flame_monitor.c - Monitor 5 KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27
 * using libgpiod (v1.6+).  Logs rising-edge flame events to
 * /var/log/flame_events.log once per second.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (root needed for /dev/gpiochip4 access)
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_S 1
#define LOG_FILE "/var/log/flame_events.log"
#define GPIO_CHIP "/dev/gpiochip4"   /* BCM GPIO on Pi 3B+ */

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_ids[NUM_SENSORS] = {
    "KY026-2", "KY026-3", "KY026-4", "KY026-5", "KY026-6" };

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_event(int sensor_id, int pin)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];
    int fd = -1;

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        syslog(LOG_ERR, "gmtime_r: %s", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        syslog(LOG_ERR, "strftime: buffer too small");
        return -1;
    }

    fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd == -1) {
        syslog(LOG_ERR, "open(%s): %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fd, LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX): %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (fprintf(fd, "%s - Sensor ID: %s (GPIO %u) - Flame Detected\n",
                timestamp, sensor_ids[sensor_id], pin) < 0) {
        syslog(LOG_ERR, "fprintf: %s", strerror(errno));
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }

    if (fflush(fd) == EOF) {
        syslog(LOG_ERR, "fflush: %s", strerror(errno));
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }

    if (flock(fd, LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN): %s", strerror(errno));
        close(fd);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int sensor_pins[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    sensor_pins[0] = sensor_pins[1] = sensor_pins[2] = sensor_pins[3] = sensor_pins[4] = -1;

    if (install_signal_handlers() == -1)
        goto cleanup;

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open(%s): %s", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    /* Get and request each line individually */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        /* Read initial state */
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_state[i] = val;
    }

    syslog(LOG_INFO, "Flame monitor started (GPIO %u, %u, %u, %u, %u)",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* Main polling loop */
    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%s): %s",
                       sensor_ids[i], strerror(errno));
                continue;
            }

            /* Rising-edge detection with debounce */
            if (val == 1 && prev_state[i] == 0) {
                /* Debounce: re-read after 50 ms */
                sleep(DEBOUNCE_MS / 1000);
                int debounced = gpiod_line_get_value(lines[i]);
                if (debounced < 0) {
                    syslog(LOG_ERR, "gpiod_line_get_value(debounce %s): %s",
                           sensor_ids[i], strerror(errno));
                    continue;
                }
                if (debounced == 1) {
                    if (log_event(i, sensor_pins[i]) == -1) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d", i);
                    }
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Flame monitor shutting down");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

