#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line *lines_out;
    int prev_states[NUM_CHANNELS];
    int current_states[NUM_CHANNELS];
    int ret;
    int i;

    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize line bulk to hold all 8 lines */
    lines.lines = &(lines_out = gpiod_line_bulk_init(NUM_CHANNELS));
    if (lines.lines == NULL) {
        fprintf(stderr, "Error: Failed to allocate line bulk: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request each line individually for bulk read */
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpiod_line_request_bulk_input(chip, &lines, &gpio_pins[i]);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to request line %u (BCM %u) as input: %s\n",
                    i, gpio_pins[i], strerror(errno));
            gpiod_line_bulk_free(lines.lines);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-Channel Touch Sensor Reader\n");
    printf("Polling %d channels every %d ms. Press Ctrl+C to exit.\n",
           NUM_CHANNELS, POLL_INTERVAL_MS);

    /* Initialize previous states to known (released) values */
    for (i = 0; i < NUM_CHANNELS; i++) {
        prev_states[i] = 0;
        current_states[i] = 0;
    }

    /* Main polling loop */
    while (program_running) {
        ret = gpiod_line_get_value_bulk(chip, &lines);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        /* Check for read failure (errno is set on failure) */
        if (errno != EINVAL) {
            fprintf(stderr, "Error: Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        /* Log only state changes (touch = 1, released = 0) */
        for (i = 0; i < NUM_CHANNELS; i++) {
            if (current_states[i] != prev_states[i]) {
                print_timestamp();
                printf("Channel %d (BCM %u): %s\n",
                       i + 1, gpio_pins[i],
                       current_states[i] ? "Touch detected" : "Released");
                prev_states[i] = current_states[i];
            }
        }

        /* Sleep for the poll interval, checking for shutdown every 100 ms */
        for (int ms = 0; ms < POLL_INTERVAL_MS && program_running; ms += 100) {
            struct timespec ts = {0, 100 * 1000 * 1000}; /* 100 ms */
            nanosleep(&ts, NULL);
        }
    }

    /* Clean resource release on all exit paths */
    gpiod_line_bulk_free(lines.lines);
    gpiod_chip_close(chip);

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

