#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define VEML7700_ALS_REG 0x04
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_CONFIG_ALS_GAIN_1_8 0x00
#define VEML7700_CONFIG_ALS_IT_100MS 0x00
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int handle) {
    uint8_t config = VEML7700_CONFIG_ALS_GAIN_1_8 | VEML7700_CONFIG_ALS_IT_100MS;
    uint8_t buf[2];
    buf[0] = (config >> 8) & 0xFF;
    buf[1] = config & 0xFF;
    if (i2cWriteI2CBlockData(handle, VEML7700_CONFIG_REG, (char *)buf, 2) < 0) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    char reg = VEML7700_ALS_REG;
    if (i2cWriteI2CBlockData(handle, VEML7700_ALS_REG, &reg, 1) < 0) {
        fprintf(stderr, "Error setting ALS register pointer: %s\n", strerror(errno));
        return -1;
    }
    char data[2];
    if (i2cReadI2CBlockData(handle, VEML7700_ALS_REG, data, 2) < 0) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *lux_out = (float)raw * 0.0576f;
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("VEML7700 grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        int error_code = 0;

        if (veml7700_read_lux(i2c_handle, &lux) < 0) {
            error_code = -1;
            fprintf(stderr, "Sensor read error\n");
        } else {
            int brightness = 0;
            if (lux < 100.0f) {
                brightness = 100;
            } else if (lux < 500.0f) {
                brightness = 75;
            } else if (lux < 1000.0f) {
                brightness = 50;
            } else {
                brightness = 25;
            }
            if (set_led_brightness(LED_GPIO, brightness) < 0) {
                error_code = -1;
            }
        }

        if (log_data(log_file, lux, brightness, error_code) < 0) {
            error_code = -1;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

