#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define CONVERSION_DELAY_US 100000  /* 100 ms */
#define SAMPLE_INTERVAL_US 1000000  /* 1 s */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an OPT3001 register.
 * The OPT3001 expects big-endian (MSB first) data, but pigpio's
 * i2cWriteWordData returns the value in little-endian byte order.
 * Swap the bytes to get the correct big-endian format.
 */
static int opt3001_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    uint16_t swapped = ((value & 0xFF) << 8) | ((value >> 8) & 0xFF);
    int rc = i2cWriteWordData(handle, reg, swapped);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%04X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an OPT3001 register.
 * The OPT3001 returns big-endian data; pigpio's i2cReadWordData
 * returns little-endian.  Swap the bytes to get the correct big-endian
 * format.
 */
static int opt3001_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    /* pigpio returns the word in little-endian byte order; swap to get big-endian */
    *out = ((uint16_t)rc >> 8) | ((uint16_t)rc << 8);
    return 0;
}

/*
 * Configure the OPT3001 for continuous conversion mode with
 * automatic full-scale range and a 100 ms conversion time.
 * Returns 0 on success, -1 on failure.
 */
static int opt3001_configure(int handle)
{
    if (opt3001_write_reg16(handle, CONFIG_REG, CONFIG_WORD) != 0)
        return -1;
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

/*
 * Read the 16-bit result register and compute lux.
 * The result is in big-endian format: bits 15-12 = exponent, bits 11-0 = mantissa.
 * lux = mantissa * 0.01 * (2^exponent)
 */
static float opt3001_read_lux(int handle)
{
    uint16_t raw;
    if (opt3001_read_reg16(handle, RESULT_REG, &raw) != 0)
        return -1.0f;
    int exponent = (raw >> 12) & 0x0F;
    int mantissa = raw & 0x0FFF;
    return (float)mantissa * 0.01f * (float)(1 << exponent);
}

/*
 * Log a reading to the log file and print it to stdout.
 * Returns 0 on success, -1 on failure.
 */
static int log_and_print(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    printf("%s, %.2f lux\n", timestamp, lux);
    return 0;
}

int main(void)
{
    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the OPT3001 address */
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (pigpio rc=%d)\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Configure the sensor */
    if (opt3001_configure(g_i2c_handle) != 0) {
        fprintf(stderr, "Error configuring OPT3001 sensor\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("OPT3001 greenhouse light sensor started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float lux = opt3001_read_lux(g_i2c_handle);
        if (lux >= 0.0f) {
            if (log_and_print(lux) != 0) {
                fprintf(stderr, "Error logging or printing lux value\n");
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        /* Sleep for the remainder of the 1-second interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

