#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_PERIOD  1.0
#define MEAS_DELAY_US  2000
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define RAW_MIN        -999
#define RAW_MAX        999

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- CRC-8 (Sensirion) ---- */
static uint8_t crc8_check(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Initialize I2C and sensor ---- */
static int init_sensor(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        return -1;
    }

    /* Start continuous measurement: 0x3608 */
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to send start-measurement command\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Allow first measurement to be ready */
    time_sleep(MEAS_DELAY_US / 1000000.0);
    return 0;
}

/* ---- Read 3 bytes: flow(2) + CRC ---- */
static int read_sensor(int16_t *raw_flow) {
    uint8_t buf[3];
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 3)\n", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on sensor data\n");
        return -1;
    }

    *raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- Convert raw to ml/min ---- */
static float convert_raw_to_ml_min(int16_t raw) {
    return (float)raw / 90.0f;
}

/* ---- Log a row ---- */
static int log_data(float flow, int16_t raw, const char *status) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_file, "%s,%.2f,%s\n", ts, flow, status) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ---- Log header if file is new ---- */
static int ensure_log_header(void) {
    long sz = ftell(g_log_file);
    if (sz < 0) {
        fprintf(stderr, "Error: ftell failed\n");
        return -1;
    }
    if (sz == 0) {
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_file);
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open %s for append\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    if (ensure_log_header() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SLF3S-1300F on I2C bus %d, addr 0x%02X. Press Ctrl+C to stop.\n",
           I2C_BUS, I2C_ADDR);

    while (g_running) {
        int16_t raw;
        if (read_sensor(&raw) == 0) {
            float flow = convert_raw_to_ml_min(raw);
            const char *status = "OK";
            if (flow < FLOW_MIN || flow > FLOW_MAX) {
                status = "INVALID";
                flow = -1.0f;
            }
            if (log_data(flow, raw, status) != 0) {
                fprintf(stderr, "Warning: log write failed, continuing\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, attempting re-init\n");
            if (init_sensor() != 0) {
                fprintf(stderr, "Error: re-init failed, will retry next cycle\n");
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

