    return 0;
}

/* ---- Convert raw to ml/min ---- */
static float convert_raw_to_ml_min(int16_t raw) {
    return (float)raw / 90.0f;
}

/* ---- Log a row ---- */
static int log_data(float flow, int16_t raw, const char *status) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_file, "%s,%.2f,%s\n", ts, flow, status) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ---- Log header if file is new ---- */
static int ensure_log_header(void) {
    long sz = ftell(g_log_file);
    if (sz < 0) {
        fprintf(stderr, "Error: ftell failed\n");
        return -1;
    }
    if (sz == 0) {
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_file);
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open %s for append\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    if (ensure_log_header() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SLF3S-1300F on I2C bus %d, addr 0x%02X. Press Ctrl+C to stop.\n",
           I2C_BUS, I2C_ADDR);

    while (g_running) {
        int16_t raw;
        if (read_sensor(&raw) == 0) {
            float flow = convert_raw_to_ml_min(raw);
            const char *status = "OK";
            if (flow < FLOW_MIN || flow > FLOW_MAX) {
                status = "INVALID";
                flow = -1.0f;
            }
            if (log_data(flow, raw, status) != 0) {
                fprintf(stderr, "Warning: log write failed, continuing\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, attempting re-init\n");
            if (init_sensor() != 0) {
                fprintf(stderr, "Error: re-init failed, will retry next cycle\n");
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

