#define GPIO_MIDDLE   27
#define GPIO_RIGHT    22
#define LOG_FILE      "path_log.csv"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, int left, int middle, int right)
{
    char ts[32];

    if (get_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, left, middle, right) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    struct gpiod_line_request_config req_cfg;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO_LEFT);
    lines[1] = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    lines[2] = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (lines[0] == NULL || lines[1] == NULL || lines[2] == NULL) {
        fprintf(stderr, "Error: failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    memset(&req_cfg, 0, sizeof(req_cfg));
    req_cfg.consumer = "path_logger";
    req_cfg.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req_cfg.flags = 0;

    if (gpiod_line_request(lines[0], &req_cfg, 0) != 0) {
        fprintf(stderr, "Error: failed to request GPIO%d as input: %s\n", GPIO_LEFT, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request(lines[1], &req_cfg, 0) != 0) {
        fprintf(stderr, "Error: failed to request GPIO%d as input: %s\n", GPIO_MIDDLE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request(lines[2], &req_cfg, 0) != 0) {
        fprintf(stderr, "Error: failed to request GPIO%d as input: %s\n", GPIO_RIGHT, strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int left = gpiod_line_get_value(lines[0]);
        int middle = gpiod_line_get_value(lines[1]);
        int right = gpiod_line_get_value(lines[2]);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error: failed to read GPIO lines: %s\n", strerror(errno));
            break;
        }

        if (log_data(fp, left, middle, right) != 0) {
            fprintf(stderr, "Error: failed to log data.\n");
            break;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (fp != NULL) {
        fclose(fp);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

