    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        ret = gpiod_line_event_wait(line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
