    if (!buzzer_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", BUZZER_PIN, strerror(errno));
        log_event("Failed to get buzzer line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(flame_line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request flame sensor line as input: %s\n", strerror(errno));
        log_event("Failed to request flame sensor line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        log_event("Failed to request buzzer line");
        cleanup();
        return 1;
    }

