                        fprintf(stderr, "Failed to activate buzzer: %s\n", strerror(errno));
                        log_event("Failed to activate buzzer");
                        break;
                    }
                    buzzer_active = true;
                    log_event("Flame detected!");
                }
                step_count++;
                if (step_count >= BUZZER_DURATION_MS / BUZZER_STEP_MS) {
                    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                        fprintf(stderr, "Failed to deactivate buzzer: %s\n", strerror(errno));
                        log_event("Failed to deactivate buzzer");
                        break;
                    }
                    buzzer_active = false;
                }
            } else {
                if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate buzzer: %s\n", strerror(errno));
                    log_event("Failed to deactivate buzzer");
                    break;
                }
                buzzer_active = false;
            }
            last_state = val;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("System stopped");
    cleanup();
    return 0;
}

