        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int led_state = 0;
    int last_touch_state = 0;

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge: LOW -> HIGH (touch detected) */
        if (touch_state == 1 && last_touch_state == 0) {
            led_state = !led_state;
            if (gpioWrite(LED_PIN, led_state) != 0) {
                fprintf(stderr, "Error: gpioWrite failed on GPIO%d\n", LED_PIN);
                break;
            }
            log_touch_event();
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_US);
    }

    /* Graceful shutdown */
    gpioWrite(LED_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

