#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/*
 * TMAG5110A1 Hall-effect latch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   GPIO4 -> sensor OUT1 (open-drain, pull-up enabled)
 *   GPIO17 -> sensor OUT2 (open-drain, pull-up enabled)
 *   GPIO27 -> sensor OUT3 (open-drain, pull-up enabled)
 *
 * The TMAG5110A1 open-drain OUT pin drives a GPIO input with an internal
 * pull-up.  When a south-pole magnet is present the OUT pin reads LOW (0),
 * and the sensor input reads LOW (0) because the pull-up pulls the line
 * high.  When the magnet is removed the OUT pin reads HIGH (1), and the
 * sensor input reads HIGH (1) because the pull-up pulls the line high.
 *
 * Thus:
 *   LOW  -> magnet present
 *   HIGH -> magnet absent
 */

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define LOG_FILE "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_event(int sensor_id, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (g_log_fp) {
        fprintf(g_log_fp, "%s - Sensor %d: %s\n", ts, sensor_id,
                state ? "Magnet Present" : "Magnet Absent");
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Log file not open: %s\n", ts);
    }
}

/* ------------------------------------------------------------------ */
/* Sensor read with error handling                                    */
/* ------------------------------------------------------------------ */

/*
 * Returns 0 on success, -1 on read error.
 * On success *state is set to the current sensor state (0 or 1).
 */
static int read_sensor(int pin, int *state)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(v));
        return -1;
    }
    *state = v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs with internal pull-up --- */
    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Record initial states --- */
    int prev_states[3] = {0, 0, 0};
    for (int i = 0; i < 3; ++i) {
        if (read_sensor(pins[i], &prev_states[i]) < 0) {
            fprintf(stderr, "Initial read failed on sensor %d\n", i + 1);
            prev_states[i] = -1;  /* mark as unreliable */
        }
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d...\n",
           SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int states[3];
        for (int i = 0; i < 3; ++i) {
            if (read_sensor(pins[i], &states[i]) < 0) {
                fprintf(stderr, "Sensor %d read error; skipping cycle\n", i + 1);
                continue;
            }
        }

        /* Log only on state change */
        for (int i = 0; i < 3; ++i) {
            if (states[i] != prev_states[i]) {
                log_event(i + 1, states[i]);
                prev_states[i] = states[i];
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

