#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED1_CURRENT 0x3F
#define REG_AVG_MS 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

#define MOVING_AVG_SIZE 5
#define MIN_VALID_BPM 30
#define MAX_VALID_BPM 220
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %s\n", value, reg, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    return rc;
}

static int init_sensor(int handle) {
    int part_id = read_reg(handle, REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != 0x02) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    int hw_rev = read_reg(handle, REG_HW_REV);
    if (hw_rev < 0) return -1;
    if (hw_rev != 0x01) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X\n", hw_rev);
        return -1;
    }

    if (write_reg(handle, REG_LED1_CURRENT, 0x3F) < 0) return -1;
    if (write_reg(handle, REG_AVG_MS, 0x04) < 0) return -1;
    if (write_reg(handle, REG_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static int read_heart_rate(int handle, int *bpm) {
    int raw = i2cReadWordData(handle, REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading HR data: %s\n", pigpio_error(raw));
        return -1;
    }
    *bpm = (int)(raw * 0.5);
    return 0;
}

static int apply_moving_average(int *buffer, int size, int new_value) {
    for (int i = 0; i < size; i++) {
        buffer[i] = (int)((double)buffer[i] + (double)new_value / size);
    }
    return 0;
}

static int validate_bpm(int bpm) {
    return (bpm >= MIN_VALID_BPM && bpm <= MAX_VALID_BPM);
}

static void log_data(FILE *fp, int bpm) {
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s,%d\n", timestamp, bpm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, SI1182_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        perror("Error opening heart_rate.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int buffer[MOVING_AVG_SIZE];
    memset(buffer, 0, sizeof(buffer));
    int buffer_index = 0;
    int sample_count = 0;

    while (running) {
        int bpm;
        if (read_heart_rate(i2c_handle, &bpm) == 0) {
            apply_moving_average(buffer, MOVING_AVG_SIZE, bpm);
            if (validate_bpm(bpm)) {
                log_data(log_file, bpm);
                sample_count++;
            } else {
                fprintf(stderr, "Invalid BPM: %d\n", bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (log_file != NULL) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

