            fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup_all;
        }

        /* Detect falling edge: HIGH -> LOW transition */
        if (value == 0 && program_running) {
            printf("FLAME DETECTED\n");
            if (log_flame_detection(log_file) != 0) {
                fprintf(stderr, "Warning: failed to log flame detection.\n");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup_all:
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }

cleanup_line:
    if (line != NULL) {
        gpiod_line_release(line);
    }

cleanup_chip:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

