/*
 * touch_counter.c — Raspberry Pi Zero W, libgpiod v2+ bulk/config API
 *
 * Reads an 8-channel TTP226 capacitive touch sensor module (OUT1-OUT8)
 * and drives an 8-bit binary counter on GPIO 17 (bit 0) through
 * GPIO 24 (bit 7).  Polls every 10 ms, logs touch events to
 * touch_log.txt, and prints progress to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_MS      10
#define STABILIZE_MS 200

/* BCM pin numbers for TTP226 OUT1..OUT8 -> GPIO 5..12 */
static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
/* Display bit 0 on GPIO 17 through GPIO 24 */
static const unsigned int display_pins[8]        = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_touch_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) != NULL) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
    } else {
        fprintf(fp, "<timestamp-error>, Channel: %d, Counter: %d\n",
                channel, counter);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static int set_output(struct gpiod_line_request *req,
                      unsigned int offset, int value)
{
    if (gpiod_line_request_set_value(req, offset, value) < 0) {
        fprintf(stderr, "Error: set_value(%u, %d) failed: %s\n",
                offset, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *line_req = NULL;
    int prev[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open gpiochip0 (RPi Zero W) ---- */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: gpiod_chip_open failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- line settings: input + pull-down ---- */
    line_settings = gpiod_line_settings_new();
    if (!line_settings) {
        fprintf(stderr, "Error: gpiod_line_settings_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(line_settings, GPIOD_LINE_BIAS_PULL_DOWN);

    /* ---- line config: request all 16 lines ---- */
    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "Error: gpiod_line_config_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    unsigned int touch_offsets[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_offsets[i] = touch_pins[i];
        if (gpiod_line_config_add_line_settings(line_cfg, &touch_offsets[i], 1,
                                               line_settings) < 0) {
            fprintf(stderr, "Error: add_line_settings(%u) failed: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- request config: bulk request for all 16 lines ---- */
    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "Error: gpiod_request_config_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-touch-counter");

    /* ---- request lines ---- */
    line_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!line_req) {
        fprintf(stderr, "Error: gpiod_chip_request_lines failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- stabilize: let lines settle ---- */
    usleep(STABILIZE_MS * 1000);

    /* ---- initialize previous states ---- */
    for (int i = 0; i < NUM_CHANNELS; i++)
        prev[i] = 0;

    printf("Touch sensor ready.  Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- main loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(line_req, touch_offsets[i]);
            if (val < 0) {
                fprintf(stderr, "Warning: read(%u) failed: %s\n",
                        touch_pins[i], strerror(errno));
                continue;
            }

            /* Rising-edge detection: 0 -> 1 */
            if (val == 1 && prev[i] == 0) {
                int counter = 0;
                if (set_output(line_req, 17, counter) < 0)
                    goto cleanup;
                if (set_output(line_req, 18, counter) < 0)
                    goto cleanup;
                if (set_output(line_req, 19, counter) < 0)
                    goto cleanup;
                if (set_output(line_req, 20, counter) < 0)
                    goto cleanup;
                if (set_output(line_req, 21, counter) < 0)
                    goto cleanup;
                if (set_output(line_req, 22, counter) < 0)
                    goto cleanup;
                if (set_output(line_req, 23, counter) < 0)
                    goto cleanup;
                if (set_output(line_req, 24, counter) < 0)
                    goto cleanup;

                log_touch_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                fflush(stdout);

                prev[i] = 1;
            }
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line_req)
        gpiod_line_request_release(line_req);
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (line_settings)
        gpiod_line_settings_free(line_settings);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

