                fprintf(stderr, "Failed to log event for sensor 18\n");
            }
        }
        prev18 = val18;

        struct timespec ts = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17 != NULL) {
        gpiod_line_release(line17);
    }
    if (line18 != NULL) {
        gpiod_line_release(line18);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Tilt sensor monitoring stopped.\n");
    return ret;
}

