#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22
#define LOG_FILE "obstacle_log.csv"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(FILE *fp, int s1, int s2, int led) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, s1, s2, led) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1_line = NULL, *s2_line = NULL, *led_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    s1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    s2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!s1_line || !s2_line || !led_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(s1_line, "tcrt5000_s1") < 0 ||
        gpiod_line_request_input(s2_line, "tcrt5000_s2") < 0 ||
        gpiod_line_request_output(led_line, "tcrt5000_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Starting obstacle avoidance monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpiod_line_get_value(s1_line);
        int s2 = gpiod_line_get_value(s2_line);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Error writing to LED: %s\n", strerror(errno));
            break;
        }

        if (log_data(log_fp, s1, s2, led_state) < 0) {
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
