#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SI1175_ADDR 0x49
#define I2C_BUS "/dev/i2c-1"
#define ALS_VIS_LSB_REG 0x24
#define ALS_VIS_MSB_REG 0x25
#define READ_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t lsb_reg, uint8_t msb_reg, uint16_t *value) {
    uint8_t buf[2];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr = SI1175_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &lsb_reg;

    msgs[1].addr = SI1175_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 1;
    msgs[1].buf = buf;

    data.msgs = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        return -1;
    }

    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    uint16_t als_vis_raw;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to Si1175");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Si1175 ALS Visible sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        if (i2c_read_reg16(fd, ALS_VIS_LSB_REG, ALS_VIS_MSB_REG, &als_vis_raw) == 0) {
            printf("ALS Visible Raw: 0x%04X\n", als_vis_raw);
        } else {
            fprintf(stderr, "Error reading ALS Visible data: %s\n", strerror(errno));
        }

        usleep(READ_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

