/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 * Uses libgpiod v1.x API (gpiod_line, gpiod_chip, gpiod_line_get_value).
 *
 * Wiring (TTP226 8-channel module, active-high outputs):
 *   TP1 -> BCM GPIO 5
 *   TP2 -> BCM GPIO 6
 *   TP3 -> BCM GPIO 13
 *   TP4 -> BCM GPIO 19
 *   TP5 -> BCM GPIO 26
 *   TP6 -> BCM GPIO 12
 *   TP7 -> BCM GPIO 16
 *   TP8 -> BCM GPIO 20
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 *
 * Run:
 *   ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

/* BCM GPIO numbers for TTP226 TP1-TP8 */
static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%ld.%09ld] ", (long)ts.tv_sec, ts.tv_nsec);
    } else {
        printf("[?] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure all 8 lines as inputs */
    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line individually */
    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-reader");

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(line_cfg, &touch_pins[i], 1, settings) != 0) {
            fprintf(stderr, "Failed to configure line for BCM GPIO %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!request) {
        fprintf(stderr, "Failed to request lines for BCM GPIO %u: %s\n",
                touch_pins[0], strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int values[NUM_CHANNELS];
        int read_ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(request, touch_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read BCM GPIO %u: %s\n",
                        touch_pins[i], strerror(errno));
                read_ok = 0;
                break;
            }
            values[i] = val;
        }

        if (read_ok) {
            print_timestamp();
            for (int i = 0; i < NUM_CHANNELS; i++) {
                printf("CH%d=%d", i + 1, values[i]);
                if (i < NUM_CHANNELS - 1)
                    printf(" ");
            }
            printf("\n");
            fflush(stdout);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int ms = 0; ms < POLL_INTERVAL_MS && program_running; ms += 10) {
            struct timespec ts = { .tv_sec = 0, .tv_nsec = 10 * 1000 * 1000 };
            nanosleep(&ts, NULL);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (request)
        gpiod_line_request_release(request);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nResources released. Exiting.\n");
    return ret;
}

