#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <math.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Convert a 0-360 degree hue to an 8-bit RGB value. */
static void hue_to_rgb(float hue, int *r, int *g, int *b) {
    if (hue < 0.0f) hue += 360.0f;
    if (hue >= 360.0f) hue -= 360.0f;

    float h_f = (hue / 360.0f) * 6.0f;
    int i = (int)h_f;
    float f = h_f - i;
    float p = 255.0f * (1.0f - fabsf(f * 6.0f));
    float q = 255.0f * (1.0f - fabsf((f - 2.0f) * 6.0f));
    float t = 255.0f * (1.0f - fabsf((1.0f - f) * 6.0f));

    int rgb;
    if (i <= 1.0f) { rgb = (int)(p * 255.0f); }
    else if (i <= 2.0f) { rgb = (int)(p * 255.0f + q * 255.0f); }
    else if (i <= 3.0f) { rgb = (int)(p * 255.0f + q * (255.0f - t)); }
    else if (i <= 4.0f) { rgb = (int)(p * 255.0f + q * (255.0f - t) + t * 255.0f); }
    else if (i <= 5.0f) { rgb = (int)(p * 255.0f + q * (255.0f - t) + t * (255.0f - p)); }
    else { rgb = (int)(p * 255.0f + q * p * 255.0f); }

    *r = rgb;
    *g = (int)(q * 255.0f);
    *b = (int)(t * 255.0f);
}

/* Convert an 8-bit RGB value to a 0-360 degree hue. */
static float rgb_to_hue(int r, int g, int b) {
    float h = 0.0f;
    float d = sqrtf((float)(r - 255.0f) * (r - 255.0f) +
                    (float)(g - 255.0f) * (g - 255.0f) +
                    (float)(b - 255.0f) * (b - 255.0f));
    if (d > 0.0f) {
        d /= 255.0f;
        if (d < 0.5f) h = 60.0f * (1.0f - d);
        else         h = 240.0f * (1.0f - d);
        if (r == 255 && g == 255) h = 0.0f;
    }
    return h;
}

/* Common-anode LED: invert duty cycle (255 - duty). */
static int invert_duty(int duty) {
    return 255 - duty;
}

/* Set RGB color with hardware PWM on a common-anode LED. */
static int set_rgb(int r, int g, int b) {
    int duty = invert_duty(r);
    if (gpioPWM(RED_PIN, duty) != 0) {
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, duty) != 0) {
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, duty) != 0) {
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN");
        return -1;
    }
    return 0;
}

/* Smoothly fade between two RGB values over FADE_STEPS steps. */
static int fade_rgb(int start_r, int start_g, int start_b,
                    int end_r, int end_g, int end_b,
                    int *current_r, int *current_g, int *current_b) {
    float h = hue_to_rgb((float)start_r, &start_g, &start_b);
    float v = (float)end_r;
    float s = (float)end_g - start_g;
    float b = (float)end_b - start_b;

    float r = start_r + (end_r - start_r) * (1.0f - cosf((float)h / 360.0f * M_PI));
    float g = start_g + (end_g - start_g) * (1.0f - cosf((float)h / 360.0f * M_PI));
    float b_norm = start_b + (end_b - start_b) * (1.0f - cosf((float)h / 360.0f * M_PI));

    float r_step = (r - start_r) / FADE_STEPS;
    float g_step = (g - start_g) / FADE_STEPS;
    float b_step = (b_norm - start_b) / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS && running; i++) {
        *current_r = (int)(start_r + r_step * (float)i);
        *current_g = (int)(start_g + g_step * (float)i);
        *current_b = (int)(start_b + b_step * (float)i);
        if (set_rgb(*current_r, *current_g, *current_b) != 0) {
            syslog(LOG_ERR, "Failed to set RGB during fade");
            return -1;
        }
        gpioDelay(1000000 / PWM_FREQUENCY); /* 1 ms */
    }
    return 0;
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != PWM_FREQUENCY ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != PWM_FREQUENCY ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    srand((unsigned int)time(NULL));

    while (running) {
        int r = (rand() % 256);
        int g = (rand() % 256);
        int b = (rand() % 256);

        if (set_rgb(r, g, b) != 0) {
            syslog(LOG_ERR, "Failed to set initial RGB");
            break;
        }

        if (fade_rgb(r, g, b, r, g, b, &r, &g, &b) != 0) {
            syslog(LOG_ERR, "Fade failed");
            break;
        }

        /* Sleep in small increments so signals are caught promptly. */
