#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_CMD_BIT  0x80
#define TCS34725_REG_ENABLE 0x80
#define TCS34725_REG_ATIME  0x81
#define TCS34725_REG_CONTROL 0x8F
#define TCS34725_REG_ID     0x12
#define TCS34725_REG_CDATA  0x14
#define TCS34725_REG_RDATA  0x16
#define TCS34725_REG_GDATA  0x18
#define TCS34725_REG_BDATA  0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ATIME_154MS 0x00
#define TCS34725_GAIN_1X     0x00
#define TCS34725_ID_TCS34725 0x44

#define LED_GPIO_LINE 17
#define RED_THRESHOLD 200
#define POLL_MS       200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { (uint8_t)(TCS34725_CMD_BIT | reg), val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t cmd = (uint8_t)(TCS34725_CMD_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write cmd 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd)
{
    uint16_t id = 0;
    if (i2c_read_reg16(fd, TCS34725_REG_ID, &id) < 0)
        return -1;
    if (id != TCS34725_ID_TCS34725) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%04X, expected 0x%04X\n",
                id, TCS34725_ID_TCS34725);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_REG_ATIME, TCS34725_ATIME_154MS) < 0)
        return -1;
    if (i2c_write_reg8(fd, TCS34725_REG_CONTROL, TCS34725_GAIN_1X) < 0)
        return -1;
    if (i2c_write_reg8(fd, TCS34725_REG_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;
    usleep(3000);
    return 0;
}

static int tcs34725_read_calibrated(int fd, uint16_t *c, uint16_t *r,
                                    uint16_t *g, uint16_t *b)
{
    if (i2c_read_reg16(fd, TCS34725_REG_CDATA, c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_REG_RDATA, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_REG_GDATA, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_REG_BDATA, b) < 0) return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                TCS34725_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 ready. Polling every %d ms. Ctrl+C to exit.\n", POLL_MS);

    while (g_running) {
        uint16_t c, r, g, b;
        if (tcs34725_read_calibrated(i2c_fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Sensor read error; re-initializing...\n");
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed; will retry next cycle.\n");
            }
            usleep(POLL_MS * 1000);
            continue;
        }

        printf("C=%5u  R=%5u  G=%5u  B=%5u\n", c, r, g, b);

        int led_val = (r > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_val) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n",
                    strerror(errno));
        }

        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

