#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 180
#define NUM_LEDS 10
#define MAX_LUX 1000.0
#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = BH1750_CMD_CONT_HIGH_RES;
    char buf[2];
    int rc;

    rc = i2cWriteDevice(handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: %d\n", rc);
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C short read: %d bytes\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > MAX_LUX) lux = MAX_LUX;
