#define SPI_SPEED 1000000
#define NUM_LEDS 32
#define MIN_LUX 10.0f
#define MAX_LUX 300.0f
#define MIN_BRIGHT 0
#define MAX_BRIGHT 31

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CMD_OT_HRES) < 0) {
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int apa102_send_frame(int fd, uint8_t *frame, int len) {
    if (spi_transfer(fd, frame, frame, len) < 0) {
        return -1;
    }
    return 0;
}

static int apa102_init(int fd, int num_leds) {
    uint8_t zero[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    for (int i = 0; i < num_leds; i++) {
        uint8_t led[4] = {0xE0, (uint8_t)(i * 32 / num_leds), 0, 0};
        if (apa102_send_frame(fd, led, 4) < 0) {
            return -1;
        }
    }
    if (apa102_send_frame(fd, end, 4) < 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    int spi_fd = -1;
    float lux;
    uint8_t *led_frame = NULL;
    int led_count = 0;
