        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux from BH1750\n");
            break;
        }

        if (lux < MIN_LUX || lux > MAX_LUX) {
            lux = MIN_LUX;
        }

        int brightness = (int)((lux - MIN_LUX) / (MAX_LUX - MIN_LUX) * (MAX_BRIGHT - MIN_BRIGHT) + MIN_BRIGHT);
        if (brightness < MIN_BRIGHT) brightness = MIN_BRIGHT;
        if (brightness > MAX_BRIGHT) brightness = MAX_BRIGHT;

        uint8_t *new_frame = malloc(4 * NUM_LEDS);
        if (!new_frame) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        for (int i = 0; i < NUM_LEDS; i++) {
            new_frame[i * 4] = 0xE0 | brightness;
            new_frame[i * 4 + 1] = 0;
            new_frame[i * 4 + 2] = 0;
            new_frame[i * 4 + 3] = 0;
        }

        if (apa102_send_frame(spi_fd, new_frame, 4 * NUM_LEDS) < 0) {
            fprintf(stderr, "Failed to send APA102 frame\n");
            break;
        }

        free(new_frame);
        usleep(10000);
    }

    ret = 0;

cleanup:
    if (spi_fd >= 0) {
        apa102_send_frame(spi_fd, NULL, 0);
        close(spi_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    free(led_frame);
    return ret;
}

