#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define FADE_MS 500
#define LOOP_DELAY_MS 100
#define CONVERSION_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int handle) {
    if (i2cWriteByte(handle, 0x21) < 0) {
        fprintf(stderr, "BH1750 init failed (handle %d)\n", handle);
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, float *lux_out) {
    if (i2cWriteByte(handle, 0x21) < 0) {
        fprintf(stderr, "BH1750 trigger failed (handle %d)\n", handle);
        return -1;
    }
    gpioDelay(CONVERSION_MS * 1000);
    int raw = i2cReadWordData(handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "BH1750 read failed (handle %d)\n", handle);
        return -1;
    }
    uint16_t val = (raw & 0xFF) | ((raw >> 8) & 0xFF00);
    *lux_out = (float)val / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 100000.0f) lux = 100000.0f;
    float b = 31.0f * (lux / 100000.0f);
    if (b < 0.0f) b = 0.0f;
    if (b > 31.0f) b = 31.0f;
    return (int)b;
}

static int fade_strip(int strip, int target) {
    int step = (int)(target * 6.0f / 31.0f);
    if (step < 0) step = 0;
    if (step > 31) step = 31;
    for (int i = 0; i < 32 && running; i++) {
        int val = (strip & 0x01) ? 1 : 0;
        if (gpioWrite(strip, val) < 0) {
            fprintf(stderr, "GPIO write failed\n");
            return -1;
        }
        strip = (strip + 1) & 0xFFF;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        gpioWrite(0, 0);
        i2cClose(spi_handle);
        spi_handle = -1;
