#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <errno.h>

#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int veml7700_init(int fd) {
    uint16_t config;
    if (i2c_read_reg16(fd, VEML7700_CONFIG_REG, &config) < 0) {
        fprintf(stderr, "Error: Failed to read VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    // Default config: IT=100ms, Gain=1/8, ALS_EN=1
    config = 0x0000;
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, config) < 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int veml7700_read_lux(int fd) {
    uint16_t raw;
    if (i2c_read_reg16(fd, VEML7700_ALS_DATA_REG, &raw) < 0) {
        fprintf(stderr, "Error: Failed to read ALS data: %s\n", strerror(errno));
        return -1;
    }
    // Default gain = 1/8, IT=100ms -> lux = raw * 0.0288
    return (int)(raw * 0.0288);
}

int gamma_correct(int lux) {
    if (lux <= 0) return 0;
    float lux_norm = lux / 120000.0f;
    float gamma = 1.0f / 2.2f;
    return (int)(255.0f * powf(lux_norm, gamma));
}

void bit_bang_led(struct gpiod_line *line, int brightness) {
    // 800 kHz, 50% duty cycle
    if (brightness > 0) {
        // High
        for (int i = 0; i < 800000; i += 2) {
            gpiod_line_set_value(line, 1);
            usleep(1);
            gpiod_line_set_value(line, 0);
            usleep(1);
        }
    } else {
        // Low
        for (int i = 0; i < 800000; i += 2) {
            gpiod_line_set_value(line, 0);
            usleep(1);
            gpiod_line_set_value(line, 1);
            usleep(1);
        }
    }
}

int main() {
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        goto cleanup;
    }

    // Initialize sensor
    if (veml7700_init(fd) < 0) {
        fprintf(stderr, "Error: VEML7700 initialization failed\n");
        goto cleanup;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    // Request line as output, initially low
    if (gpiod_line_request_output(line, "ws2812b-led", 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("WS2812B LED control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int lux = -1;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            lux = veml7700_read_lux(fd);
            if (lux >= 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Warning: VEML7700 read failed (attempt %d/%d), retrying...\n", retries, MAX_RETRIES);
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: VEML7700 read failed after %d retries, skipping iteration\n", MAX_RETRIES);
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        int brightness = gamma_correct(lux);
        bit_bang_led(line, brightness);
        printf("Lux: %d, Brightness: %d\n", lux, brightness);

        usleep(LOOP_DELAY_MS * 1000);
    }

    ret = 0;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (fd >= 0) close(fd);
    printf("Program terminated.\n");
    return ret;
}

