#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define POLL_INTERVAL_MS 50
#define SELF_TEST_READINGS 5
#define SELF_TEST_DELAY_MS 100
#define BLINK_ON_MS 500
#define BLINK_OFF_MS 500
#define BLINK_RAPID_MS 100
#define BEEP_SHORT_MS 200
#define BEEP_LONG_MS 600
#define BEEP_REPEATS 3
#define FLAME_FAULT_THRESHOLD 4

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static void self_test(struct gpiod_line *flame_line, struct gpiod_line *buzzer_line, struct gpiod_line *led_line) {
    log_event("Starting self-test...");

    if (gpiod_line_set_value(flame_line, 0) < 0) {
        log_event("Error: Failed to set flame sensor LOW during self-test.");
        return;
    }
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        log_event("Error: Failed to set buzzer LOW during self-test.");
        return;
    }
    if (gpiod_line_set_value(led_line, 0) < 0) {
        log_event("Error: Failed to set LED LOW during self-test.");
        return;
    }

    for (int i = 0; i < BLINK_RAPID_MS / 100; i++) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            log_event("Error: Failed to set LED HIGH during self-test.");
            return;
        }
        usleep(BLINK_ON_MS * 1000);
        if (gpiod_line_set_value(led_line, 0) < 0) {
            log_event("Error: Failed to set LED LOW during self-test.");
            return;
        }
        usleep(BLINK_OFF_MS * 1000);
    }

    for (int i = 0; i < SELF_TEST_READINGS; i++) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            log_event("Error: Failed to read flame sensor during self-test.");
            return;
        }
        if (val == 0) {
            log_event("Flame detected (sensor LOW) on reading %d.", i + 1);
            return;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("Self-test failed: sensor consistently reads HIGH.");
    return;
}

static void cleanup_resources(struct gpiod_chip *chip, struct gpiod_line *flame_line, struct gpiod_line *buzzer_line, struct gpiod_line *led_line) {
    if (flame_line) gpiod_line_release(flame_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("gpiod_line_request_input (flame)");
        goto cleanup;
