#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define LED_GPIO_PATH "/sys/class/gpio/gpio17/value"
#define CIRCULAR_BUFFER_SIZE 60
#define MIN_RATE 0.5
#define MAX_RATE 5.0
#define LUX_THRESHOLD 1000.0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_lux(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_CMD_CONT_HIGH_RES) < 0)
        return -1;

    usleep(180000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void update_circular_buffer(float *buffer, int *index, float new_value) {
    buffer[*index] = new_value;
    *index = (*index + 1) % CIRCULAR_BUFFER_SIZE;
}

static float calculate_average(const float *buffer) {
    float sum = 0.0f;
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++)
        sum += buffer[i];
    return sum / CIRCULAR_BUFFER_SIZE;
}

static int set_led_rate(int rate) {
    FILE *fp = fopen(LED_GPIO_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LED_GPIO_PATH, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", rate);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_byte(i2c_fd, BH1750_CMD_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Failed to initialize BH1750\n");
        close(i2c_fd);
        return 1;
    }

    float lux_buffer[CIRCULAR_BUFFER_SIZE];
    int buffer_index = 0;
    int led_rate = MIN_RATE;

    while (running) {
        float lux;
        if (read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed, skipping sample\n");
            sleep(1);
            continue;
        }

        update_circular_buffer(lux_buffer, &buffer_index, lux);
        float avg_lux = calculate_average(lux_buffer);

        if (avg_lux > LUX_THRESHOLD) {
            led_rate = MIN_RATE + (avg_lux / LUX_THRESHOLD) * (MAX_RATE - MIN_RATE);
            if (led_rate < MIN_RATE) led_rate = MIN_RATE;
            if (led_rate > MAX_RATE) led_rate = MAX_RATE;
        } else {
            led_rate = MIN_RATE;
        }

        if (set_led_rate(led_rate) < 0) {
            fprintf(stderr, "Failed to set LED rate\n");
        }

        printf("Lux: %.2f, Average Lux: %.2f, LED Rate: %.2f Hz\n", lux, avg_lux, led_rate);
        sleep(1);
    }

    printf("\nShutting down...\n");
    set_led_rate(MIN_RATE);
    close(i2c_fd);
    return 0;
}

