#include <unistd.h>
#include <signal.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27
#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

void shift_out(int data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        gpiod_line_set_value(clock_line, 1);
        gpiod_line_set_value(data_line, bit);
        gpiod_line_set_value(clock_line, 0);
    }
}

void display_digit(int digit) {
    int segments[] = {1, 1, 1, 1, 1, 1, 1, 0};
    for (int i = 0; i < 8; i++) {
        shift_out(segments[i]);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
    }

    if (gpiod_line_request_output(data_line, "seg_display", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seg_display", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seg_display", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(0);
    }

    while (1) {
        display_digit(5);
        usleep(500000);
        if (gpiod_line_set_value(latch_line, 0) < 0) {
            perror("gpiod_line_set_value");
            cleanup_and_exit(0);
        }
        usleep(500000);
    }

    cleanup_and_exit(0);
    return 0;
}

