#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5
#define DELAY_US 750000  /* 750 ms in microseconds */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Set GPIO5 as an output */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at startup */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d low.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Blink loop */
    while (running) {
        if (gpioWrite(LED_GPIO, 1) != 0) {
            fprintf(stderr, "Error: failed to write GPIO%d high.\n", LED_GPIO);
            break;
        }
        printf("LED ON\n");
        fflush(stdout);
        time_sleep(0.75);

        if (!running) break;

        if (gpioWrite(LED_GPIO, 0) != 0) {
            fprintf(stderr, "Error: failed to write GPIO%d low.\n", LED_GPIO);
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(0.75);
    }

    /* Clean shutdown: turn LED off and release pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

