        perror("gpiod_chip_get_line(LED)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line(BUTTON)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led-blink", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(button_line, "button-press",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
