#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000  // 10 ms = 100 Hz
#define PWM_STEPS 100

static volatile sig_atomic_t running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_value(struct gpiod_line *line, int value) {
    if (value < 0) value = 0;
    if (value > PWM_STEPS) value = PWM_STEPS;

    int on_time_ns = (PWM_PERIOD_NS * value) / PWM_STEPS;
    int off_time_ns = PWM_PERIOD_NS - on_time_ns;

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value (high)");
        return -1;
    }
    struct timespec ts = {0, on_time_ns};
    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL) < 0) {
        perror("clock_nanosleep (high)");
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value (low)");
        return -1;
    }
    struct timespec ts2 = {0, off_time_ns};
    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts2, NULL) < 0) {
        perror("clock_nanosleep (low)");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    // Set up signal handler for clean exit
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip 0 (Raspberry Pi 5 uses gpiochip0)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Request output lines
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    srand(time(NULL));

    while (running) {
        int red = rand() % PWM_STEPS;
        int green = rand() % PWM_STEPS;
        int blue = rand() % PWM_STEPS;

        if (set_pwm_value(red_line, red) < 0 ||
            set_pwm_value(green_line, green) < 0 ||
            set_pwm_value(blue_line, blue) < 0) {
            fprintf(stderr, "Error setting PWM values\n");
            break;
        }

        usleep(10000);  // 10 ms delay to avoid busy-waiting
    }

    ret = EXIT_SUCCESS;

cleanup:
    // Release lines
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

