static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) failed: reg=0x%02X\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "I2C read failed: reg=0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int init_lsm303(int handle) {
    if (i2c_write_reg(handle, CTRL_REG1_A, 0x27) != 0) return -1;
    if (i2c_write_reg(handle, CTRL_REG4_A, 0x00) != 0) return -1;
    return 0;
}

static int read_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char reg = OUT_X_L_A | 0x80;
    char data[6];
    if (i2cWriteDevice(handle, reg, 1) != 0) {
        fprintf(stderr, "I2C write (multi-byte reg select) failed\n");
        return -1;
    }
    if (i2cReadDevice(handle, data, 6) != 6) {
        fprintf(stderr, "I2C multi-byte read failed\n");
        return -1;
    }
    *x = (int16_t)(((uint8_t)data[1] << 8) | (uint8_t)data[0]);
    *y = (int16_t)(((uint8_t)data[3] << 8) | (uint8_t)data[2]);
    *z = (int16_t)(((uint8_t)data[5] << 8) | (uint8_t)data[4]);
    return 0;
}

static double calculate_g_force(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 16384.0;
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

