    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, G: %.3f\n", timestamp, x, y, z, calculate_g_force(x, y, z));
    fflush(log_file);
}

