            return 1;
        }
    }
    printf("Impact detection threshold: %.2f G\n", threshold);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", LSM303_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_lsm303(i2c_handle) != 0) {
        fprintf(stderr, "LSM303DLHC initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    log_file = fopen(IMPACT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", IMPACT_LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    int consecutive_errors = 0;

    while (running) {
        if (read_accel(i2c_handle, &x, &y, &z) == 0) {
            consecutive_errors = 0;
            double g_force = calculate_g_force(x, y, z);
            if (g_force > threshold) {
                printf("Impact detected! G-force: %.3f\n", g_force);
                impact_pulse(GPIO_PIN);
                log_impact(x, y, z);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors, aborting\n");
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

