#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ADPD188BI I2C address (7-bit) */
#define ADPD188BI_ADDR 0x39

/* Register addresses */
#define REG_MODE 0x0D
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED_LSB 0x66
#define REG_GREEN_LSB 0x68
#define REG_BLUE_LSB 0x6A

/* GPIO pin for LED (hardware PWM) */
#define LED_PIN 18

/* PWM range (0-255) */
#define PWM_RANGE 255

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Global resources for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize I2C connection to ADPD188BI */
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, ADPD188BI_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* Initialize ADPD188BI: enter normal operation mode */
static int init_sensor(void) {
    /* Write 0x01 to MODE register to enter normal operation mode */
    if (i2cWriteByteData(i2c_handle, REG_MODE, 0x01) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }
    return 0;
}

/* Read 16-bit ALS value from two consecutive registers */
static uint16_t read_als(void) {
    int lsb = i2cReadByteData(i2c_handle, REG_ALS_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB: %d\n", lsb);
        return 0;
    }
    int msb = i2cReadByteData(i2c_handle, REG_ALS_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading ALS MSB: %d\n", msb);
        return 0;
    }
    return (uint16_t)((msb << 8) | lsb);
}

/* Read 16-bit RGB values from three consecutive registers */
static uint16_t read_rgb(void) {
    int red = i2cReadByteData(i2c_handle, REG_RED_LSB);
    if (red < 0) {
        fprintf(stderr, "Error reading Red LSB: %d\n", red);
        return 0;
    }
    int green = i2cReadByteData(i2c_handle, REG_GREEN_LSB);
    if (green < 0) {
        fprintf(stderr, "Error reading Green LSB: %d\n", green);
        return 0;
    }
    int blue = i2cReadByteData(i2c_handle, REG_BLUE_LSB);
    if (blue < 0) {
        fprintf(stderr, "Error reading Blue LSB: %d\n", blue);
        return 0;
    }
    return (uint16_t)((blue << 8) | (green << 4) | red);
}

/* Log a reading to the CSV file */
static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

/* Map ALS value (0-65535) to PWM duty cycle (0-255) */
static int map_als_to_pwm(uint16_t als) {
    int duty = (int)(((float)als / 65535.0f) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return duty;
}

/* Set LED brightness using hardware PWM */
static void set_led_brightness(int duty) {
    if (gpioPWM(LED_PIN, duty) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO%d\n", LED_PIN);
    }
}

/* Cleanup all resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Turn off LED */
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    /* Set LED pin as output and initialize PWM to 0 */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioPWM(LED_PIN, 0);

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t als = read_als();
        uint16_t red = read_rgb();
        uint16_t green = read_rgb();
        uint16_t blue = read_rgb();

        if (als == 0) {
            fprintf(stderr, "Error reading ALS data, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int pwm_duty = map_als_to_pwm(als);
        set_led_brightness(pwm_duty);

        log_data(als, red, green, blue);

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

