#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_OUT_X_MSB  0x01
#define FXOS8700_XYZ_DATA_CFG 0x0E

/* Expected WHO_AM_I value for FXOS8700CQ */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* ±2g sensitivity: 4096 counts/g */
#define ACCEL_SENSITIVITY 4096.0f

/* 2g threshold: 19.62 m/s^2 */
#define IMPACT_THRESHOLD_MPS2 19.62f

/* Sampling interval in microseconds (50 ms) */
#define SAMPLE_INTERVAL_US 50000

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register; returns 0 on success, -1 on error*/
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register; returns 0 on success, -1 on error*/
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the FXOS8700CQ: verify WHO_AM_I, configure ±2g mode, then wake */
/* ------------------------------------------------------------------ */
static int initialize_fxos8700(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (read_register(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I - sensor may be absent or bus error.\n");
        return -1;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode (clear ACTIVE bit in CTRL_REG1) */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* ±2g mode: 16-bit left-justified, 1 mg/LSB */
    if (write_register(handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Wake up: ACTIVE bit in CTRL_REG1, 200 Hz ODR */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z) and convert to g/s      */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *ax, float *ay, float *az)
{
    char buffer[6];

    /* Read 6 bytes starting at OUT_X_MSB (0x01) */
    int bytes_read = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading acceleration data: expected 6 bytes, got %d\n",
                bytes_read);
        return -1;
    }

    /* Data is 14-bit left-justified; shift right by 2 */
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    /* Convert to g/s: sensitivity 4096 counts/g, multiply by 9.81 m/s^2/g */
    *ax = (float)raw_x / ACCEL_SENSITIVITY * 9.81f;
    *ay = (float)raw_y / ACCEL_SENSITIVITY * 9.81f;
    *az = (float)raw_z / ACCEL_SENSITIVITY * 9.81f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute acceleration magnitude in g/s^2                                */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(float ax, float ay, float az)
{
    return sqrtf(ax * ax + ay * ay + az * az);
}

/* ------------------------------------------------------------------ */
/* Log impact data to file                                               */
/* ------------------------------------------------------------------ */
static int log_impact(float ax, float ay, float az, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening impact_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, ax, ay, az, magnitude);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper: close I2C handle and terminate pigpio               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x1F */
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1, address 0x%02X: %s\n",
                FXOS8700_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_fxos8700(i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("FXOS8700CQ impact detection started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        float ax, ay, az;

        if (read_acceleration(i2c_handle, &ax, &ay, &az) == 0) {
            float magnitude = calculate_magnitude(ax, ay, az);

            if (magnitude > IMPACT_THRESHOLD_MPS2) {
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
                if (log_impact(ax, ay, az, magnitude) != 0) {
                    fprintf(stderr, "Warning: failed to log impact data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

