#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I_REG   0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define NUM_SAMPLES    100
#define SAMPLE_PERIOD_US 50000
#define WARNING_THRESHOLD 50.0f
#define SENSITIVITY    0.00875f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gyro(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", GYRO_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    uint8_t whoami = 0;
    if (i2c_read_block(WHO_AM_I_REG, &whoami, 1) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", whoami, WHO_AM_I_VAL);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg(CTRL_REG1, 0x0F) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg(CTRL_REG4, 0x00) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_gyro(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(OUT_X_L, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * SENSITIVITY;
    *y = (float)raw_y * SENSITIVITY;
    *z = (float)raw_z * SENSITIVITY;
    return 0;
}

static void calibrate_gyro(float *x_off, float *y_off, float *z_off) {
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        float x, y, z;
        if (read_gyro(&x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return;
        }
        x_sum += x; y_sum += y; z_sum += z;
        usleep(1000);
    }
    *x_off = x_sum / NUM_SAMPLES;
    *y_off = y_sum / NUM_SAMPLES;
    *z_off = z_sum / NUM_SAMPLES;
}

static void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s, X: %.2f, Y: %.2f, Z: %.2f\n", ts, x, y, z);
    fflush(log_file);
}

static void log_alert(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s, ALERT: X: %.2f, Y: %.2f, Z: %.2f\n", ts, x, y, z);
    fflush(log_file);
    fprintf(stderr, "ALERT: X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (init_gyro() < 0) {
        return 1;
    }
    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    if (calibrate_gyro(&x_off, &y_off, &z_off) < 0) {
        fprintf(stderr, "Calibration failed\n");
        close(i2c_fd);
        return 1;
    }
    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open gyro_log.txt: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");
    while (running) {
        float x, y, z;
        if (read_gyro(&x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        x -= x_off;
        y -= y_off;
        z -= z_off;
        if (fabsf(x) > WARNING_THRESHOLD || fabsf(y) > WARNING_THRESHOLD || fabsf(z) > WARNING_THRESHOLD) {
