#define ADXL345_ADDR        0x53
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_LED_STATUS  0x0C
#define ADXL345_DEVID_VAL   0xE5

#define THRESHOLD_G         2.0f
#define SAMPLE_PERIOD_US    100000  /* 100 ms -> 10 Hz */
#define LOG_FILE_PATH       "accel_log.txt"
#define LED_GPIO            17

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n",
                reg, val, rc);
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int adxl345_init(int handle)
{
    uint8_t devid = 0;
    if (i2c_read_byte(handle, ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Full-resolution, ±2g range */
    if (i2c_write_byte(handle, ADXL345_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Standby -> measure */
    if (i2c_write_byte(handle, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t data[6];
    if (i2c_read_block(handle, ADXL345_DATAX0, data, 6) < 0)
        return -1;

    int16_t x_raw = (int16_t)((data[1] << 8) | data[0]);
    int16_t y_raw = (int16_t)((data[3] << 8) | data[2]);
    int16_t z_raw = (int16_t)((data[5] << 8) | data[4]);

    *x = (float)x_raw / 32768.0f * 9.81f;
    *y = (float)y_raw / 32768.0f * 9.81f;
    *z = (float)z_raw / 32768.0f * 9.81f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 init failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_log_file = fopen(LOG_FILE_PATH, "a");
    if (!g_log_file) {
        perror("fopen log");
        gpioWrite(LED_GPIO, 0);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_acceleration(g_i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error; skipping sample\n");
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(g_log_file, x, y, z);

        int led_state = (fabsf(x) > THRESHOLD_G ||
                        fabsf(y) > THRESHOLD_G ||
                        fabsf(z) > THRESHOLD_G) ? 1 : 0;
        gpioWrite(LED_GPIO, led_state);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_log_file)
        fclose(g_log_file);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

