#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

#define ACCEL_OUT_X_L_A 0x28
#define MAG_OUT_X_H_M 0x03
#define ACCEL_CTRL_REG1_A 0x20
#define MAG_MR_REG_M 0x02

#define ACCEL_SENSITIVITY 0.000061f
#define MAG_SENSITIVITY 0.000014f
#define MAG_ZERO_OFFSET 0.0f

static volatile sig_atomic_t running = 1;
static int accel_handle = -1;
static int mag_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int bus, int addr) {
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", addr, h);
        return -1;
    }
    return h;
}

static int init_accelerometer(int handle) {
    if (i2cWriteByteData(handle, ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

static int init_magnetometer(int handle) {
    if (i2cWriteByteData(handle, MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buf[6];
    int ret = i2cReadI2CBlockData(handle, ACCEL_OUT_X_L_A | 0x80, buf, 6);
    if (ret != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", ret);
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_magnetometer(int handle, float *x, float *y, float *z) {
    char buf[6];
    int ret = i2cReadI2CBlockData(handle, MAG_OUT_X_H_M, buf, 6);
    if (ret != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", ret);
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float mx_corr = mx * cosf(pitch) + mz * sinf(pitch);
    float my_corr = mx * sinf(roll) * sinf(pitch) + my * cosf(roll) - mz * sinf(roll) * cosf(pitch);
