#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_ENABLE 0x80
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle, uint8_t addr) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_ENABLE) < 0) {
        fprintf(stderr, "Error writing CTRL_REG to sensor 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(int handle, int16_t *out) {
    int raw = i2cReadWordData(handle, DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading data from sensor 0x%02X: %s\n", (uint8_t)handle, strerror(errno));
        return -1;
    }
    *out = (int16_t)raw;
    return 0;
}

static int log_data(FILE *fp, int sec, int nsec, int16_t s1, int16_t s2, int tdoa) {
    if (fprintf(fp, "%d,%d,%d,%d,%d\n", sec, nsec, s1, s2, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1, SENSOR1_ADDR) != 0 || init_sensor(i2c_handle2, SENSOR2_ADDR) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("audio_log.dat", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,sensor1,sensor2,tdoa\n");

    while (running) {
        int16_t s1, s2;
        if (read_sensor(i2c_handle1, &s1) == 0 && read_sensor(i2c_handle2, &s2) == 0) {
            int tdoa = (int16_t)s1 - (int16_t)s2;
            if (log_data(log_file, time(NULL), 0, s1, s2, tdoa) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read error, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

