#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses (7-bit) */
#define REG_X_GYRO   0x04
#define REG_Y_GYRO   0x06
#define REG_Z_GYRO   0x08
#define REG_X_ACCEL  0x0A
#define REG_Y_ACCEL  0x0C
#define REG_Z_ACCEL  0x0E

/* Sensitivities (per LSB) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI configuration */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000   /* 1 MHz */
#define SPI_FLAGS      0b11000000000 /* CPOL=1, CPHA=1, aux SPI off */

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* ADIS16488A read protocol: MSB=0, then 7-bit reg addr */
#define ADIS16488_READ_MSB 0x80
#define ADIS16488_READ_LSB 0x00

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_fp        = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets flag                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — called on every exit path                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_fp != NULL) {
        fclose(g_fp);
        g_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A                           */
/* Returns 0 on success, -1 on error.                                    */
/* ------------------------------------------------------------------ */
static int adis16488_read_reg(uint8_t reg, int16_t *out)
{
    char tx[2] = { (char)(ADIS16488_READ_MSB | (reg & 0x7F)), 0x00 };
    char rx[2] = { 0, 0 };

    /* Send request: MSB=0, then 7-bit reg address */
    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI request transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Small stall between request and data-read transfer */
    gpioDelay(40);

    /* Read the 16-bit data word */
    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI data read transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* rx[0] is the dummy MSB; rx[1] is the 16-bit data word */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope X, Y, Z                                              */
/* ------------------------------------------------------------------ */
static int read_gyro(float *gx, float *gy, float *gz)
{
    int16_t raw;
    if (adis16488_read_reg(REG_X_GYRO, &raw) != 0)
        return -1;
    *gx = (float)raw * GYRO_SENSITIVITY;
    if (adis16488_read_reg(REG_Y_GYRO, &raw) != 0)
        return -1;
    *gy = (float)raw * GYRO_SENSITIVITY;
    if (adis16488_read_reg(REG_Z_GYRO, &raw) != 0)
        return -1;
    *gz = (float)raw * GYRO_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer X, Y, Z                                          */
/* ------------------------------------------------------------------ */
static int read_accel(float *ax, float *ay, float *az)
{
    int16_t raw;
    if (adis16488_read_reg(REG_X_ACCEL, &raw) != 0)
        return -1;
    *ax = (float)raw * ACCEL_SENSITIVITY;
    if (adis16488_read_reg(REG_Y_ACCEL, &raw) != 0)
        return -1;
    *ay = (float)raw * ACCEL_SENSITIVITY;
    if (adis16488_read_reg(REG_Z_ACCEL, &raw) != 0)
        return -1;
    *az = (float)raw * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper — millisecond precision                              */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                               */
/* ------------------------------------------------------------------ */
static int log_sample(float gx, float gy, float gz,
                      float ax, float ay, float az)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(g_fp, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                ts, gx, gy, gz, ax, ay, az) < 0) {
        fprintf(stderr, "fprintf to CSV failed\n");
        return -1;
    }
    fflush(g_fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, mode 3 (CPOL=1, CPHA=1) */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file in append mode */
    g_fp = fopen("imu_data.csv", "a");
