        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_fp) == 0) {
        fprintf(g_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(g_fp);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    printf("ADIS16488A IMU logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_gyro(&gx, &gy, &gz) != 0 ||
            read_accel(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Sensor read error — skipping sample\n");
        } else {
            if (log_sample(gx, gy, gz, ax, ay, az) != 0) {
