            }
        }

        /* Non-blocking 100 ms delay so SIGINT/SIGTERM respond promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    printf("\nShutting down gracefully...\n");
    return EXIT_SUCCESS;
}

