#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define CS_GPIO_CHIP    "gpiochip0"
#define CS_GPIO_LINE    8
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        3
#define SPI_BITS        8
#define SAMPLE_PERIOD_US 100000

#define REG_XGYRO_OUT   0x04
#define REG_YGYRO_OUT   0x06
#define REG_ZGYRO_OUT   0x08
#define REG_XACCL_OUT   0x0A
#define REG_YACCL_OUT   0x0C
#define REG_ZACCL_OUT   0x0E

#define GYRO_SCALE      0.02f
#define ACCEL_SCALE     0.00025f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_name(CS_GPIO_CHIP), CS_GPIO_LINE), 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_name(CS_GPIO_CHIP), CS_GPIO_LINE), 1);
        return -1;
    }

    if (gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_name(CS_GPIO_CHIP), CS_GPIO_LINE), 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }

    *value = (uint16_t)((rx[1] << 8) | rx[0]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CS_GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t gyro_x, gyro_y, gyro_z;
        uint16_t accel_x, accel_y, accel_z;

        if (read_register(spi_fd, REG_XGYRO_OUT, &gyro_x) < 0 ||
            read_register(spi_fd, REG_YGYRO_OUT, &gyro_y) < 0 ||
            read_register(spi_fd, REG_ZGYRO_OUT, &gyro_z) < 0 ||
            read_register(spi_fd, REG_XACCL_OUT, &accel_x) < 0 ||
            read_register(spi_fd, REG_YACCL_OUT, &accel_y) < 0 ||
            read_register(spi_fd, REG_ZACCL_OUT, &accel_z) < 0) {
            fprintf(stderr, "Failed to read ADIS16448 data\n");
            break;
        }

        float gx = (float)gyro_x * GYRO_SCALE;
        float gy = (float)gyro_y * GYRO_SCALE;
        float gz = (float)gyro_z * GYRO_SCALE;
        float ax = (float)accel_x * ACCEL_SCALE;
        float ay = (float)accel_y * ACCEL_SCALE;
        float az = (float)accel_z * ACCEL_SCALE;

        printf("Gyroscope: X=%.3f dps, Y=%.3f dps, Z=%.3f dps\n", gx, gy, gz);
        printf("Accelerometer: X=%.3f g, Y=%.3f g, Z=%.3f g\n", ax, ay, az);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_name(CS_GPIO_CHIP), CS_GPIO_LINE), 1);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

