#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68

#define REG_WHO_AM_I   0x75
#define WHO_AM_I_VAL   0x86
#define REG_PWR_MGMT_1 0x6B
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H 0x43
#define REG_ACCEL_CONFIG 0x1C
#define REG_GYRO_CONFIG  0x1B

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int init_mpu6886(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, REG_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU-6886: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);

    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_raw_data(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, REG_ACCEL_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    if (i2c_read_burst(fd, REG_GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read gyroscope data: %s\n", strerror(errno));
        return -1;
    }
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_mpu6886(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: MPU-6886 initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    printf("MPU-6886 initialized. Reading data every 50 ms...\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_raw_data(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: Read failed, retrying...\n");
        }
        usleep(50000);
    }

    printf("\nExiting gracefully...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

