#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS pin tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 register addresses */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_BW_RATE     0x2C

/* Expected device ID */
#define ADXL345_DEVID_VAL   0xE5

/* Impact threshold (2.5 g) */
#define IMPACT_THRESHOLD_G  2.5f

/* LED GPIO pin */
#define LED_PIN 17

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

/* LED on duration in microseconds */
#define LED_ON_DURATION_US 500000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an ADXL345 register; returns 0 on success, -1 on error*/
/* ------------------------------------------------------------------ */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): pigpio error %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an ADXL345 register; returns 0 on success, -1 on error*/
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): pigpio error %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair (low byte at reg, high at reg+1)*/
/* ------------------------------------------------------------------ */
static int adxl345_read_reg16(int handle, uint8_t reg, int16_t *value)
{
    uint8_t lo, hi;
    if (adxl345_read_reg(handle, reg, &lo) < 0)
        return -1;
    if (adxl345_read_reg(handle, reg + 1, &hi) < 0)
        return -1;
    *value = (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345: verify device ID, set full-resolution mode, etc*/
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (adxl345_read_reg(handle, ADXL345_DEVID, &devid) < 0) {
        fprintf(stderr, "Cannot read DEVID register — sensor absent or bus error.\n");
