#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICM-20602 I2C address (SA0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I       0x75
#define PWR_MGMT_1     0x6B
#define ACCEL_CONFIG   0x1C
#define GYRO_CONFIG    0x1C
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43

/* Expected device ID */
#define ICM20602_WHO_AM_I 0x12

/* Sampling interval in microseconds (10 Hz) */
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an I2C register with error checking                  */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes from an I2C register with error checking      */
/* ------------------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error: i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ICM-20602: wake from sleep, verify identity, config    */
/* ------------------------------------------------------------------ */
static int init_icm20602(int handle)
{
    /* Wake up the device: clear SLEEP bit (bit 5) in PWR_MGMT_1 */
    if (i2c_write_byte(handle, PWR_MGMT_1, 0x00) < 0)
        return -1;

    /* Verify device identity */
    int who = i2cReadByteData(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register\n");
        return -1;
    }
    if (who != ICM20602_WHO_AM_I) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, ICM20602_WHO_AM_I);
        return -1;
    }

    /* Configure accelerometer: +-2g range (AFS_SEL = 0) */
    if (i2c_write_byte(handle, ACCEL_CONFIG, 0x00) < 0)
        return -1;

    /* Configure gyroscope: +-250 dps range (FS_SEL = 0) */
    if (i2c_write_byte(handle, GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data (6 bytes) and gyroscope data (6 bytes)     */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle,
                            int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[12];

    /* Burst read 12 bytes: 6 accel + 6 gyro */
    if (i2c_read_block(handle, ACCEL_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    /* buf[6..7] are temperature; skip */
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp,
                     int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d,%d,%d,%d\n",
            timestamp, ts.tv_nsec / 1000000L,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ICM-20602 address */
    g_i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                ICM20602_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_icm20602(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: ICM-20602 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("imu_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open imu_log.csv for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Warning: sensor read failed, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(g_log_file, ax, ay, az, gx, gy, gz);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

