#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* MMA8451Q register addresses */
#define MMA8451Q_REG_WHO_AM_I    0x0D
#define MMA8451Q_WHO_AM_I_VAL    0x1A
#define MMA8451Q_REG_X_MSB       0x00
#define MMA8451Q_REG_X_LSB       0x01
#define MMA8451Q_REG_Y_MSB       0x02
#define MMA8451Q_REG_Y_LSB       0x03
#define MMA8451Q_REG_Z_MSB       0x04
#define MMA8451Q_REG_Z_LSB       0x05
#define MMA8451Q_REG_TEMP_MSB    0x06
#define MMA8451Q_REG_TEMP_LSB    0x07
#define MMA8451Q_REG_CTRL_REG1   0x2A
#define MMA8451Q_REG_CTRL_REG2   0x2B
#define MMA8451Q_REG_CTRL_REG3   0x2C
#define MMA8451Q_REG_OUT_X_MSB   0x2D
#define MMA8451Q_REG_OUT_X_LSB   0x2E
#define MMA8451Q_REG_OUT_Y_MSB   0x2F
#define MMA8451Q_REG_OUT_Y_LSB   0x30
#define MMA8451Q_REG_OUT_Z_MSB   0x31
#define MMA8451Q_REG_OUT_Z_LSB   0x32

#define I2C_BUS_NAME "/dev/i2c-1"
#define LED_GPIO_LINE 17
#define ACCEL_THRESHOLD 2.0f
#define SAMPLE_DELAY_MS 100
#define LED_ON_DURATION_MS 500
#define LOG_FILE "impact_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(const char *bus_name, int *fd_out) {
    int fd = open(bus_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", bus_name, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, 0x1D) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x1D: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    *fd_out = fd;
    return 0;
}

static int init_accelerometer(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MMA8451Q_REG_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != MMA8451Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, MMA8451Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration */
    if (i2c_write_reg8(fd, MMA8451Q_REG_CTRL_REG1, 0x00) < 0) return -1;
    usleep(1000);

    /* Enable X, Y, Z axes, 100 Hz ODR, continuous conversion */
    if (i2c_write_reg8(fd, MMA8451Q_REG_CTRL_REG2, 0x40) < 0) return -1;
    if (i2c_write_reg8(fd, MMA8451Q_REG_CTRL_REG3, 0x00) < 0) return -1;

    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, MMA8451Q_REG_OUT_X_MSB, raw, 6) < 0) {
        return -1;
    }

    int16_t x_raw = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y_raw = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z_raw = (int16_t)((raw[4] << 8) | raw[5]);

    /* Default +-2g range: 1g = 1024 counts */
    *x = (float)x_raw / 1024.0f;
    *y = (float)y_raw / 1024.0f;
    *z = (float)z_raw / 1024.0f;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.2f, Y: %.2f, Z: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    }
    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int i2c_fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(led_line, "mma8451q_impact", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        goto cleanup_chip;
    }

    if (init_i2c(I2C_BUS_NAME, &i2c_fd) < 0) {
        goto cleanup_chip;
    }

    if (init_accelerometer(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize accelerometer\n");
        goto cleanup_i2c;
    }

    printf("MMA8451Q initialized. Monitoring acceleration...\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        float mag = calculate_magnitude(x, y, z);
        if (mag > ACCEL_THRESHOLD) {
            printf("Impact detected! Magnitude: %.2f g\n", mag);
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
            }
            usleep(LED_ON_DURATION_MS * 1000);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
            }
            log_impact(x, y, z);
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup_i2c:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
cleanup_chip:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

