}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    int1_line = gpiod_chip_get_line(chip, INT1_GPIO_LINE);
    if (!int1_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", INT1_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_falling_edge_events(int1_line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Failed to request falling edge events on GPIO %d: %s\n", INT1_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(int1_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,X,Y,Z\n");
        fflush(log_fp);
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(int1_line, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        if (gpiod_line_event_read(int1_line, &event) < 0) {
            fprintf(stderr, "GPIO event read error: %s\n", strerror(errno));
            continue;
        }
        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        uint8_t int_source;
        if (i2c_read_reg(i2c_fd, ADXL345_INT_SOURCE, &int_source) < 0) continue;
        if (!(int_source & 0x04)) continue;

        int16_t x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) continue;

        log_data(log_fp, x, y, z);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    if (int1_line) gpiod_line_release(int1_line);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

