#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

#define ACCEL_SENSITIVITY 0.000061f
#define GYRO_SENSITIVITY 0.00875f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define IMPACT_WINDOW_SEC 1.0
#define SAMPLE_PERIOD_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X)\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) failed (reg 0x%02X)\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "I2C read failed (reg 0x%02X, len=%u)\n", reg, len);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(void) {
    if (i2c_write_reg(CTRL1_XL, 0x40) != 0) return -1;
    if (i2c_write_reg(CTRL2_G, 0x40) != 0) return -1;
    return 0;
}

static int read_accel_gyro(float *ax, float *ay, float *az, float *gx, float *gy, float *gz) {
    uint8_t buf[12];
    if (i2c_read_block(OUTX_L_G, buf, 12) != 0) return -1;
    int16_t raw_gx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_gy = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_gz = (int16_t)((buf[4] << 8) | buf[5]);
    int16_t raw_ax = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t raw_ay = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t raw_az = (int16_t)((buf[10] << 8) | buf[11]);
    *gx = (float)raw_gx * GYRO_SENSITIVITY;
    *gy = (float)raw_gy * GYRO_SENSITIVITY;
    *gz = (float)raw_gz * GYRO_SENSITIVITY;
    *ax = (float)raw_ax * ACCEL_SENSITIVITY;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY;
    *az = (float)raw_az * ACCEL_SENSITIVITY;
    return 0;
}

static void log_data(float ax, float ay, float az, float gx, float gy, float gz) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", ts, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

static void detect_fall(float ax, float ay, float az) {
    static int state = 0;
    static time_t last_freefall = 0;
    time_t now = time(NULL);
    if (now - last_freefall > IMPACT_WINDOW_SEC) {
        state = 0;
    }
    if (state == 0) {
        if (ax * ax + ay * ay + az * az < FREEFALL_THRESHOLD) {
            state = 1;
            last_freefall = now;
        }
    } else if (state == 1) {
        if (ax * ax + ay * ay + az * az > IMPACT_THRESHOLD) {
            state = 2;
        }
    }
    if (state == 2) {
        fprintf(log_file, "FALL DETECTED\n");
        fflush(log_file);
        state = 0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float ax, ay, az, gx, gy, gz;
    while (running) {
        if (read_accel_gyro(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
            detect_fall(ax, ay, az);
        } else {
            fprintf(stderr, "Read error, retrying...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

