#define ADIS16266_XGYRO_CMD 0x80

/* Expected device ID */
#define ADIS16266_WHOAMI_EXPECTED 0x3F5A

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    3        /* CPOL=1, CPHA=1 */

/* Gyroscope scale factor (degrees/sec per LSB) */
#define GYRO_SCALE  0.0305f

/* Log file name */
#define LOG_FILE "gyro_log.csv"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single 16-bit register from the ADIS16266                     */
/* ------------------------------------------------------------------ */
static int adis16266_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single 16-bit register to the ADIS16266                       */
/* ------------------------------------------------------------------ */
static int adis16266_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char tx[2] = { (char)(reg & 0x7F), (char)(val & 0xFF) };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADIS16266 and verify device ID                      */
/* ------------------------------------------------------------------ */
static int adis16266_init(int handle)
{
    uint16_t whoami = 0;

    if (adis16266_read_reg16(handle, ADIS16266_WHOAMI, &whoami) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (whoami != ADIS16266_WHOAMI_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                whoami, ADIS16266_WHOAMI_EXPECTED);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", whoami);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the X-axis gyroscope rate and convert to degrees/sec          */
/* ------------------------------------------------------------------ */
static float read_gyro_rate(int handle)
{
    uint16_t raw = 0;
    if (adis16266_read_reg16(handle, ADIS16266_XGYRO_OUT, &raw) != 0) {
        return 0.0f;
    }
    return (float)raw * GYRO_SCALE;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped gyroscope reading to the CSV file                  */
/* ------------------------------------------------------------------ */
static void log_gyro_data(float rate)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(g_log_file, "%s,%.4f\n", ts, rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, mode 3 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 3) | SPI_MODE);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,gyro_rate_dps\n");
        fflush(g_log_file);
    }

    /* Initialize ADIS16266 */
    if (adis16266_init(g_spi_handle) != 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging gyroscope data to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float rate = read_gyro_rate(g_spi_handle);
        log_gyro_data(rate);
        gpioDelay(10000); /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

