#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define L3G4200D_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I       0x0F
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28

/* Expected WHO_AM_I value */
#define WHO_AM_I_VAL   0xD3

/* Sensitivity: 8.75 mdps/LSB for +-250 dps range */
#define SENSITIVITY_DPS 8.75f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Retry count for I2C writes */
#define I2C_RETRY_COUNT 3

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a register with retry */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRY_COUNT, strerror(errno));
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* Read a byte from a register with retry */
static int i2c_read_reg(int handle, uint8_t reg) {
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRY_COUNT, strerror(errno));
        gpioDelay(1000);
    }
    return -1;
}

/* Initialize the L3G4200D gyroscope */
static int initialize_gyro(int handle) {
    int who_am_i = i2c_read_reg(handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    /* CTRL_REG1: 0x0F = normal mode, all axes enabled, 100 Hz ODR */
    if (i2c_write_reg(handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: 0x00 = +-250 dps full-scale range */
    if (i2c_write_reg(handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Read 6 bytes of gyroscope data (X, Y, Z) in a single block */
static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char buffer[6];

    /* Read 6 bytes starting at OUT_X_L (0x28) */
    int result = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "I2C block read failed: expected 6 bytes, got %d\n", result);
        return -1;
    }

    /* Combine high and low bytes for each axis */
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Convert raw values to degrees per second */
    *x = (float)x_raw / SENSITIVITY_DPS;
    *y = (float)y_raw / SENSITIVITY_DPS;
    *z = (float)z_raw / SENSITIVITY_DPS;

    return 0;
}

/* Log data to CSV file with nanosecond timestamp */
static int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%.3f,%.3f,%.3f\n",
                (long)ts.tv_sec, ts.tv_nsec, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, L3G4200D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, L3G4200D_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (initialize_gyro(i2c_handle) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(log_file) == 0) {
        if (fprintf(log_file, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    float x, y, z;

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Gyroscope read failed, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    cleanup();
    return EXIT_SUCCESS;
}

