#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR        0x53
#define D7S_X_LSB_REG   0x28
#define D7S_X_MSB_REG   0x29
#define D7S_Y_LSB_REG   0x2A
#define D7S_Y_MSB_REG   0x2B
#define D7S_Z_LSB_REG   0x2C
#define D7S_Z_MSB_REG   0x2D
#define LOG_FILE        "vibration_log.csv"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, D7S_X_LSB_REG, x) != 0) return -1;
    if (i2c_read_reg16(fd, D7S_Y_LSB_REG, y) != 0) return -1;
    if (i2c_read_reg16(fd, D7S_Z_LSB_REG, z) != 0) return -1;
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm tm_info;
    char ts[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    int16_t x, y, z;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
        fflush(g_log_fp);
    }

    printf("Vibration monitoring started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_log_fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

