#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_data(FILE *fp, int sensor1_value, int sensor2_value) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_value, sensor2_value) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(SENSOR_1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(SENSOR_2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line1, "conveyor_safety", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line2, "conveyor_safety", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags(line2)");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(\"conveyor_log.txt\")");
        goto cleanup;
    }

    printf("Conveyor safety monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = gpiod_line_get_value(line1);
        int sensor2_value = gpiod_line_get_value(line2);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        if (log_data(log_fp, sensor1_value, sensor2_value) != 0) {
            fprintf(stderr, "Error logging data.\n");
            break;
        }

        if (sensor1_value == 1 && sensor2_value == 1) {
            printf("Conveyor halted! Triggered.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (line1 != NULL) {
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_release(line2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Conveyor safety monitoring stopped.\n");
    return ret;
}

