#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADXL354B_REG_PARTID 0x01
#define ADXL354B_REG_XDATA 0x08
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_STATUS 0x04
#define ADXL354B_REG_RESET 0x1F
#define ADXL354B_EXPECTED_PARTID 0x1D
#define SAMPLE_INTERVAL_US 100000
#define RESET_DELAY_US 1000
#define MEASURE_DELAY_US 10000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }
    return 0;
}

static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;
    int retries = 3;

    while (retries > 0) {
        if (spi_read_register(ADXL354B_REG_XDATA, &x_msb) != 0 ||
            spi_read_register(ADXL354B_REG_XDATA + 1, &x_lsb) != 0 ||
            spi_read_register(ADXL354B_REG_YDATA, &y_msb) != 0 ||
            spi_read_register(ADXL354B_REG_YDATA + 1, &y_lsb) != 0 ||
            spi_read_register(ADXL354B_REG_ZDATA, &z_msb) != 0 ||
            spi_read_register(ADXL354B_REG_ZDATA + 1, &z_lsb) != 0) {
            retries--;
            gpioDelay(1000);
            continue;
        }
        break;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read acceleration data after retries\n");
        return -1;
    }

    *x = (int16_t)((x_msb << 8) | x_lsb) >> 2;
    *y = (int16_t)((y_msb << 8) | y_lsb) >> 2;
    *z = (int16_t)((z_msb << 8) | z_lsb) >> 2;
    return 0;
}

static float convert_to_g(int16_t raw) {
    return (float)raw * 0.0000039f;
}

static int log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, X: %.4f g, Y: %.4f g, Z: %.4f g\n", timestamp, x, y, z);
    fflush(log_file);
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int initialize_adxl354b(void) {
    uint8_t partid;
    if (spi_read_register(ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354B_EXPECTED_PARTID) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_EXPECTED_PARTID);
        return -1;
    }
    printf("ADXL354B detected (PARTID=0x%02X)\n", partid);

    if (spi_write_register(ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(RESET_DELAY_US);

    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to set RUN bit in POWER_CTL\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);

    uint8_t status;
    if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) {
        fprintf(stderr, "Failed to read STATUS\n");
        return -1;
    }
    if (!(status & 0x04)) {
        fprintf(stderr, "ADXL354B not stable (STATUS=0x%02X)\n", status);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (initialize_adxl354b() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Logging vibration data to vibration_log.txt (Ctrl+C to stop)\n");

    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            float x = convert_to_g(raw_x);
            float y = convert_to_g(raw_y);
            float z = convert_to_g(raw_z);
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

