#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses */
#define ADIS16362_X_GYRO  0x04
#define ADIS16362_Y_GYRO  0x06
#define ADIS16362_Z_GYRO  0x08
#define ADIS16362_X_ACCL  0x0A
#define ADIS16362_Y_ACCL  0x0C
#define ADIS16362_Z_ACCL  0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000  /* 1 MHz */
#define SPI_FLAGS   0x03     /* Mode 3: active-high CS, sampled on trailing edge */

/* Sampling */
#define SAMPLE_DELAY_US 10000  /* 10 ms -> ~100 Hz */

/* Scaling factors (from datasheet) */
#define GYRO_SCALE  0.05f     /* deg/sec/LSB */
#define ACCL_SCALE  0.0025f   /* g/LSB */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single 16-bit register from the ADIS16362                     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int rc;

    /*
     * ADIS16362 SPI read: send address MSB + dummy, then read 2 bytes.
     * The device returns the register data on the *next* transfer.
     */
    tx[0] = (char)(reg | 0x80);  /* MSB set => read */
    tx[1] = 0x00;                 /* dummy */
    rx[0] = 0x00;
    rx[1] = 0x00;

    rc = spiXfer(spi_handle, tx, rx, 2);
    if (rc != 2) {
        fprintf(stderr, "spiXfer failed for reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }

    *out = (int16_t)(((uint16_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 3-axis register block (X, Y, Z)                              */
/* ------------------------------------------------------------------ */
static int read_block(uint8_t reg, int16_t *x, int16_t *y, int16_t *z)
{
    char tx[3], rx[3];
    int rc;

    tx[0] = (char)(reg | 0x80);  /* MSB set => read */
    tx[1] = 0x00;
    tx[2] = 0x00;

    rc = spiXfer(spi_handle, tx, rx, 3);
    if (rc != 3) {
        fprintf(stderr, "spiXfer failed for block 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }

    *x = (int16_t)(((uint16_t)rx[0] << 8) | (uint8_t)rx[1]);
    *y = (int16_t)(((uint16_t)rx[2] << 8) | (uint8_t)rx[3]);
    *z = (int16_t)(((uint16_t)rx[4] << 8) | (uint8_t)rx[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope data (X, Y, Z) in degrees/second                      */
/* ------------------------------------------------------------------ */
static int read_gyro(float *x, float *y, float *z)
{
    int16_t raw;
    if (read_register(ADIS16362_X_GYRO, &raw) != 0) return -1;
    *x = (float)raw * GYRO_SCALE;
    if (read_register(ADIS16362_Y_GYRO, &raw) != 0) return -1;
    *y = (float)raw * GYRO_SCALE;
    if (read_register(ADIS16362_Z_GYRO, &raw) != 0) return -1;
    *z = (float)raw * GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data (X, Y, Z) in g                            */
/* ------------------------------------------------------------------ */
static int read_accel(float *x, float *y, float *z)
{
    int16_t raw;
    if (read_block(ADIS16362_X_ACCL, &raw, &raw, &raw) != 0) return -1;
    *x = (float)raw * ACCL_SCALE;
    if (read_block(ADIS16362_Y_ACCL, &raw, &raw, &raw) != 0) return -1;
    *y = (float)raw * ACCL_SCALE;
    if (read_block(ADIS16362_Z_ACCL, &raw, &raw, &raw) != 0) return -1;
    *z = (float)raw * ACCL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                               */
/* ------------------------------------------------------------------ */
static void log_sample(float gx, float gy, float gz,
                       float ax, float ay, float az)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, gx, gy, gz, ax, ay, az);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float gx, gy, gz, ax, ay, az;

    /* Initialize pigpio */
