/*
 * Collision avoidance system for Raspberry Pi 3 Model B+
 * Sensors: 2x Keyes KY-032 IR obstacle avoidance modules
 *   - Sensor 1: GPIO17 (BCM)
 *   - Sensor 2: GPIO27 (BCM)
 *
 * KY-032 output is active-low: 0 = obstacle detected, 1 = clear.
 *
 * Build:  gcc -O2 -Wall -Wextra -o collision_avoid collision_avoid.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define SENSOR_1_PIN   17
#define SENSOR_2_PIN   27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0)
            printf("[%s] ", buf);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_bulk values;
    unsigned int offsets[2] = { SENSOR_1_PIN, SENSOR_2_PIN };
    int ret;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Build a bulk of the two lines we want to read together */
    gpiod_line_bulk_init(&lines);
    if (gpiod_line_bulk_add_offset(&lines, SENSOR_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to add GPIO%d to bulk: %s\n", SENSOR_1_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_bulk_add_offset(&lines, SENSOR_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to add GPIO%d to bulk: %s\n", SENSOR_2_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as inputs together */
    ret = gpiod_line_request_bulk_input_together(&lines, GPIO_CHIP_NAME);
    if (ret != 0) {
        fprintf(stderr, "Failed to request GPIO%d and GPIO%d as input together: %s\n",
                SENSOR_1_PIN, SENSOR_2_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Collision avoidance system started. Press Ctrl+C to exit.\n");
    log_timestamp();

    while (g_running) {
        /*
         * Read both lines in a single bulk call using the v2 bulk-read API.
         * libgpiod v2 exposes a new API that allows reading multiple lines
         * with a single request, reducing the number of system calls.
         */
        ret = gpiod_line_request_values_bulk(&lines, GPIO_CHIP_NAME, &values);
        if (ret != 0) {
            fprintf(stderr, "Failed to read GPIO%d and GPIO%d: %s\n",
                    SENSOR_1_PIN, SENSOR_2_PIN, strerror(errno));
            break;
        }

        int val1 = gpiod_line_request_values_get_value(&values, SENSOR_1_PIN);
        int val2 = gpiod_line_request_values_get_value(&values, SENSOR_2_PIN);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Failed to read GPIO%d or GPIO%d: %s\n",
                    SENSOR_1_PIN, SENSOR_2_PIN, strerror(errno));
            break;
        }

        /* KY-032 is active-low: 0 = obstacle detected, 1 = clear */
        int obstacle1 = (val1 == 0);
        int obstacle2 = (val2 == 0);

        if (obstacle1 || obstacle2) {
            printf("Obstacle detected! (Sensor1=%d, Sensor2=%d)\n",
                   obstacle1, obstacle2);
        } else {
            printf("Clear path. (Sensor1=%d, Sensor2=%d)\n",
                   !obstacle1, !obstacle2);
        }

        log_timestamp();

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    /* Release the bulk and close the chip */
    gpiod_line_bulk_release(&lines);
    if (chip)
        gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

