#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_LINE_OFFSET 8
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8
#define ADIS16266_REG_XOUT 0x04
#define ADIS16266_REG_YOUT 0x06
#define ADIS16266_REG_ZOUT 0x08
#define ADIS16266_REG_CTRL 0x24
#define ADIS16266_CTRL_DATA_READY 0x01
#define ADIS16266_SCALE_FACTOR 0.02f
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(int *fd_out) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis16266_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), value };
    uint8_t rx[2] = {0};
    return spi_transfer(fd, tx, rx, 2);
}

static int adis16266_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int adis16266_read_reg16(int fd, uint8_t reg, int16_t *value) {
    uint8_t tx[3] = { (uint8_t)(reg | 0xC0), 0x00, 0x00 };
    uint8_t rx[3] = {0};
    if (spi_transfer(fd, tx, rx, 3) < 0) return -1;
    *value = (int16_t)((rx[1] << 8) | rx[2]);
    return 0;
}

static int adis16266_init(int fd) {
    if (adis16266_write_reg(fd, ADIS16266_REG_CTRL, ADIS16266_CTRL_DATA_READY) < 0) {
        fprintf(stderr, "Error writing to CTRL register\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = -1;
    if (spi_init(&spi_fd) < 0) {
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Error getting CS line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        fprintf(stderr, "Error requesting CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (adis16266_init(spi_fd) < 0) {
        fprintf(stderr, "Error initializing ADIS16266\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("ADIS16266 initialized. Reading data every 100 ms...\n");

    while (running) {
        uint8_t tx[2] = {0x00, 0x00};
        uint8_t rx[2] = {0};
        if (spi_transfer(spi_fd, tx, rx, 2) < 0) {
            fprintf(stderr, "SPI transfer error, retrying...\n");
            usleep(10000);
            continue;
        }

        if (adis16266_read_reg16(spi_fd, ADIS16266_REG_XOUT, &int16_t x) < 0) {
            fprintf(stderr, "Error reading X axis\n");
            usleep(10000);
            continue;
        }
        if (adis16266_read_reg16(spi_fd, ADIS16266_REG_YOUT, &int16_t y) < 0) {
            fprintf(stderr, "Error reading Y axis\n");
            usleep(10000);
            continue;
        }
        if (adis16266_read_reg16(spi_fd, ADIS16266_REG_ZOUT, &int16_t z) < 0) {
            fprintf(stderr, "Error reading Z axis\n");
            usleep(10000);
            continue;
        }

        float x_rate = (float)x * ADIS16266_SCALE_FACTOR;
        float y_rate = (float)y * ADIS16266_SCALE_FACTOR;
        float z_rate = (float)z * ADIS16266_SCALE_FACTOR;

        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting...\n");
    gpiod_line_set_value(cs_line, 1);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

