#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I       0x0F
#define CTRL1_XL       0x10  /* accelerometer control */
#define CTRL2_G        0x11  /* gyroscope control */
#define OUTX_L_G       0x22  /* gyro X low byte */
#define OUTX_L_XL      0x28  /* accel X low byte */

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivities at default +-2g accel and +-250 dps gyro */
#define ACCEL_SENSITIVITY 0.000061f  /* g/LSB */
#define GYRO_SENSITIVITY  0.00875f   /* dps/LSB */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int16_t read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read failed at reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return (int16_t)((uint16_t)buf[1] << 8 | buf[0]);
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at LSM6DSR address --- */
    handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", handle);
        goto cleanup_gpio;
    }

    /* --- Verify sensor identity --- */
    int who = i2cReadByteData(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        goto cleanup_i2c;
    }
    if (who != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I);
        goto cleanup_i2c;
    }

    /* --- Configure accelerometer: 104 Hz, +-2g full-scale --- */
    if (i2cWriteByteData(handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Failed to write CTRL1_XL\n");
        goto cleanup_i2c;
    }

    /* --- Configure gyroscope: 104 Hz, +-250 dps full-scale --- */
    if (i2cWriteByteData(handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Failed to write CTRL2_G\n");
        goto cleanup_i2c;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        uint8_t buf[12];
        int16_t raw_g = read_burst(handle, OUTX_L_G, buf, 12);
        int16_t raw_a = read_burst(handle, OUTX_L_XL, buf + 6, 6);

        if (raw_g == -1 || raw_a == -1) {
            fprintf(stderr, "Sensor read error; continuing\n");
            gpioDelay(100000);  /* 100 ms */
            continue;
        }

        float gyro_x = (float)raw_g / GYRO_SENSITIVITY;
        float gyro_y = (float)raw_g / GYRO_SENSITIVITY;
        float gyro_z = (float)raw_g / GYRO_SENSITIVITY;
        float accel_x = (float)raw_a / ACCEL_SENSITIVITY;
        float accel_y = (float)raw_a / ACCEL_SENSITIVITY;
        float accel_z = (float)raw_a / ACCEL_SENSITIVITY;

        printf("Gyro: X=%.3f Y=%.3f Z=%.3f dps, Accel: X=%.3f Y=%.3f Z=%.3f g\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        fflush(stdout);

        gpioDelay(100000);  /* 100 ms */
    }

    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0) {
        i2cClose(handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

