        gpioDelay(100000);  /* 100 ms */
    }

    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0) {
        i2cClose(handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

