#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* 14-bit left-aligned accelerometer data (6 bytes) */
#define ACCEL_REG_LEN 6
/* 16-bit magnetometer data (6 bytes) */
#define MAG_REG_LEN  6

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int fxos8700_init(void) {
    /* Verify sensor identity */
    int who = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register (pigpio error %d).\n", who);
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: accelerometer hybrid mode, 100 Hz ODR, normal mode */
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1.\n");
        return -1;
    }

    /* CTRL_REG2: magnetometer hybrid mode, 100 Hz ODR, normal mode */
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG2.\n");
        return -1;
    }

    /* M_CTRL_REG1: enable magnetometer, 100 Hz ODR */
    if (i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write M_CTRL_REG1.\n");
        return -1;
    }

    /* M_CTRL_REG2: enable accelerometer, 100 Hz ODR */
    if (i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write M_CTRL_REG2.\n");
        return -1;
    }

    return 0;
}

static int fxos8700_read_data(int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *mx, int16_t *my, int16_t *mz) {
    char buffer[12];

    /* Read 12 bytes starting at OUT_X_MSB (0x01) */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 12);
    if (bytes_read != 12) {
        fprintf(stderr, "Error: I2C block read failed (expected 12 bytes, got %d).\n", bytes_read);
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 */
    *ax = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    *ay = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    *az = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Magnetometer: 16-bit, little-endian */
    *mx = (int16_t)((uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8));
    *my = (int16_t)((uint16_t)buffer[8] | ((uint16_t)buffer[9] << 8));
    *mz = (int16_t)((uint16_t)buffer[10] | ((uint16_t)buffer[11] << 8));

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (pigpio error %d).\n",
                FXOS8700_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fxos8700_init() != 0) {
        fprintf(stderr, "Error: FXOS8700 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t ax, ay, az, mx, my, mz;

    while (!terminate) {
        if (fxos8700_read_data(&ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Warning: read failed, retrying next cycle.\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

