#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define I2C_DEVICE "/dev/i2c-1"
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_MS 100

#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH 0x28
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int adxl345_init(int fd) {
    uint8_t devid;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Error: Failed to read DEVID\n");
        return -1;
    }
    if (devid != 0x33) {
        fprintf(stderr, "Error: Invalid DEVID 0x%02X (expected 0x33)\n", devid);
        return -1;
    }

    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set data format\n");
        return -1;
    }

    if (i2c_write_reg8(fd, ADXL345_REG_THRESH, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to set threshold\n");
        return -1;
    }

    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set power control\n");
        return -1;
    }

    return 0;
}

int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

void check_tilt(int16_t x, int16_t y, int16_t z, float *angle_x, float *angle_y, float *angle_z) {
    float fx = (float)x;
    float fy = (float)y;
    float fz = (float)z;
    *angle_x = atan2(fy, sqrt(fx * fx + fz * fz)) * 180.0 / M_PI;
    *angle_y = atan2(-fx, sqrt(fy * fy + fz * fz)) * 180.0 / M_PI;
    *angle_z = atan2(sqrt(fx * fx + fy * fy), fz) * 180.0 / M_PI;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float angle_x, angle_y, angle_z;

    while (running) {
        if (read_accelerometer(i2c_fd, &x, &y, &z) == 0) {
            check_tilt(x, y, z, &angle_x, &angle_y, &angle_z);

            if (fabs(angle_x) > TILT_THRESHOLD ||
                fabs(angle_y) > TILT_THRESHOLD ||
                fabs(angle_z) > TILT_THRESHOLD) {
                char message[256];
                snprintf(message, sizeof(message),
                         "Tilt detected: X=%.2f, Y=%.2f, Z=%.2f",
                         angle_x, angle_y, angle_z);
                log_event(message);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_REG_POWER_CTL, 0x00);
        close(i2c_fd);
    }

    return 0;
}

