#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define WINDOW_SECONDS 5
#define SAMPLE_INTERVAL_US 1000
#define ALERT_THRESHOLD_MIN 10
#define ALERT_THRESHOLD_MAX 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int validate_threshold(int threshold) {
    if (threshold < ALERT_THRESHOLD_MIN || threshold > ALERT_THRESHOLD_MAX) {
        fprintf(stderr, "Error: threshold %d out of range [%d, %d]\n",
                threshold, ALERT_THRESHOLD_MIN, ALERT_THRESHOLD_MAX);
        return -1;
    }
    return 0;
}

static int read_sound_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

static int count_high_readings(int gpio_pin, int window_seconds) {
    int count = 0;
    for (int i = 0; i < window_seconds * 10 && running; i++) {
        if (!running) return -1;
        if (read_sound_sensor(gpio_pin) == 1) {
            count++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    return count;
}

static void print_alert(int high_count) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ALERT: Sound level exceeded threshold!\n", timestamp);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int sound_threshold = atoi(argv[1]);
    if (validate_threshold(sound_threshold) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sound sensor on GPIO%d. Threshold: %d\n", SOUND_SENSOR_GPIO, sound_threshold);
    fflush(stdout);

    while (running) {
        int high_count = count_high_readings(SOUND_SENSOR_GPIO, WINDOW_SECONDS);
        if (high_count < 0) {
            fprintf(stderr, "Error: read_sound_sensor failed during window\n");
            break;
        }

        if (high_count > sound_threshold) {
            print_alert(high_count);
        } else {
            printf("Normal: %d high readings in %d seconds\n", high_count, WINDOW_SECONDS);
        }

        if (running) {
            gpioDelay(1000000);
        }
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

