/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Uses libgpiod (modern Linux GPIO character-device API) to control two
 * 12V electromagnetic door locks via TIP120 relay modules.
 *
 * Wiring:
 *   Door A relay IN  -> GPIO17 (physical pin 11)
 *   Door B relay IN  -> GPIO27 (physical pin 13)
 *   TIP120 A        -> relay IN
 *   TIP120 E        -> relay OUT (common ground)
 *   TIP120 G        -> relay GND
 *
 * Locks energized (HIGH) = closed / locked; de-energized (LOW) = unlocked.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_A 17
#define GPIO_B 27
#define CODE_LEN 6
#define CODE_MIN 100000
#define CODE_MAX 999999
#define UNLOCK_DURATION_SEC 5
#define LOG_FILE "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(int *code)
{
    if (code == NULL)
        return -1;

    srand((unsigned int)time(NULL));
    *code = (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN;
    return 0;
}

static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, code) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == EOF) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int code = 0;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    /* Open the default gpiochip (gpiochip0 on Pi 4). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    line_a = gpiod_chip_get_line(chip, GPIO_A);
    if (line_a == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_A, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (line_b == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_B, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (locked). */
    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                GPIO_A, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                GPIO_B, strerror(errno));
        goto cleanup;
    }

    printf("Security code: %d\n", code);
    fflush(stdout);

    while (g_running) {
        printf("Enter code to access Door A: ");
        fflush(stdout);

        char input[32];
        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                fprintf(stderr, "EOF on stdin; exiting.\n");
                break;
            }
            if (errno == EINTR) {
                fprintf(stderr, "Interrupted by signal; exiting.\n");
                break;
            }
            fprintf(stderr, "Error reading stdin: %s\n", strerror(errno));
            continue;
        }

        /* Strip trailing newline. */
        input[strcspn(input, "\n")] = '\0';

        int entered = atoi(input);
        if (entered == 0) {
            fprintf(stderr, "Invalid input; please enter a number.\n");
            continue;
        }

        if (entered == code) {
            printf("Access granted.\n");
            fflush(stdout);

            if (gpiod_line_set_value(line_a, 1) < 0) {
                fprintf(stderr, "Failed to unlock Door A: %s\n",
                        strerror(errno));
                goto cleanup;
            }

            /* Keep door unlocked for UNLOCK_DURATION_SEC seconds. */
            for (int i = 0; i < UNLOCK_DURATION_SEC && g_running; i++)
                sleep(1);

            if (gpiod_line_set_value(line_a, 0) < 0) {
                fprintf(stderr, "Failed to re-lock Door A: %s\n",
                        strerror(errno));
                goto cleanup;
            }

            if (log_access(code) == -1)
                fprintf(stderr, "Warning: failed to log access attempt.\n");

            printf("Access denied.\n");
            fflush(stdout);
        } else {
            fprintf(stderr, "Access denied.\n");
            fflush(stdout);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure both locks are de-energized (locked) on exit. */
    if (line_a != NULL)
        gpiod_line_set_value(line_a, 0);
    if (line_b != NULL)
        gpiod_line_set_value(line_b, 0);

    if (line_a != NULL)
        gpiod_line_release(line_a);
    if (line_b != NULL)
        gpiod_line_release(line_b);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

