static int mpr121_read_touch_data(int handle) {
    char buf[22];
    if (i2cReadI2CBlockData(handle, 0x00, buf, 22) < 0) return -1;
    int touch_data = ((buf[1] << 8) | buf[0]) & 0x0FFF;
    if (touch_data & 0x0001) touch_data |= 0x0FFF0000;
    return touch_data;
}

static int map_touch_data_to_frequency(int touch_data) {
    if (touch_data <= 0) return 0;
    int log_value = log10((double)touch_data) * 1000.0 + 500;
    if (log_value < 0) log_value = 0;
    if (log_value > 10000) log_value = 10000;
    int frequency = MIN_FREQUENCY + (int)((log_value - 500) * 4000.0 / 9000.0);
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
    return frequency;
}

static void play_tone(int frequency) {
    if (gpioHardwarePWM(PWM_GPIO, PWM_FREQ, PWM_RANGE / 2) < 0) return;
    gpioDelay(1000000 / frequency);
    if (gpioHardwarePWM(PWM_GPIO, 0, 0) < 0) return;
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fclose(fp);
}

static void handle_client(int client_fd) {
    char buffer[1024];
    while (running) {
        int n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (n > 0) {
            buffer[n] = '\0';
            char *token = strstr(buffer, "MOTION_DETECTED:");
            if (token) {
                token += strlen("MOTION_DETECTED:");
                if (strncmp(token, "MySecretKey", 12) == 0) {
                    printf("Motion detected! Playing theremin.\n");
                    int touch_data = mpr121_read_touch_data(i2c_handle);
                    while (running) {
                        int frequency = map_touch_data_to_frequency(touch_data);
                        play_tone(frequency);
                        log_frequency(frequency);
                        touch_data = mpr121_read_touch_data(i2c_handle);
                        if (touch_data < 0) break;
                        gpioDelay(SAMPLING_INTERVAL_US);
                    }
                    printf("Theremin stopped.\n");
                }
            }
        } else if (n == 0) {
            printf("Client disconnected.\n");
            break;
        } else {
            if (errno != EINTR) break;
        }
    }
    close(client_fd);
    client_fd = -1;
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (i2c_handle >= 0) { i2cClose(i2c_handle); i2c_handle = -1; }
    gpioHardwarePWM(PWM_GPIO, 0, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM GPIO mode\n");
        cleanup();
        return 1;
    }
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioHardwarePWM(PWM_GPIO, 0, 0);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Setsockopt failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(SERVER_PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            fprintf(stderr, "Accept failed: %s\n", strerror(errno));
            continue;
        }
        printf("Connection accepted from %s:%d\n",
               inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
