static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, CTRL_REG1_M, 0x18) < 0) {
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static double calculate_magnetic_field_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt((double)x * x + (double)y * y + (double)z * z);
}

static void set_led_brightness(struct gpiod_line *line, double magnitude) {
    int duty_ns = (int)(magnitude * PWM_PERIOD_NS / 1000.0);
    if (duty_ns < 0) duty_ns = 0;
    if (duty_ns > PWM_PERIOD_NS) duty_ns = PWM_PERIOD_NS;
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
        return;
