#define HMC5883L_ADDR 0x1E
#define CONFIG_REG_A 0x00
#define CONFIG_REG_B 0x01
#define MODE_REG 0x02
#define OUT_X_MSB 0x03
#define OUT_X_LSB 0x04
#define OUT_X_2 0x05
#define OUT_Y_MSB 0x06
#define OUT_Y_LSB 0x07
#define OUT_Y_2 0x08
#define OUT_Z_MSB 0x09
#define OUT_Z_LSB 0x0A
#define OUT_Z_2 0x0B

#define WINDOW_SIZE 100
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int write_mode_register(int handle, uint8_t value) {
    int rc = i2cWriteByteData(handle, MODE_REG, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing mode register: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_raw_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, OUT_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", rc);
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void compute_hard_iron_offsets(int16_t *x_history, int16_t *y_history, int16_t *z_history,
                                       int size, int *x_offset, int *y_offset, int *z_offset) {
    int sum_x = 0, sum_y = 0, sum_z = 0;
    for (int i = 0; i < size; i++) {
        sum_x += x_history[i];
        sum_y += y_history[i];
        sum_z += z_history[i];
    }
    *x_offset = sum_x / size;
    *y_offset = sum_y / size;
    *z_offset = sum_z / size;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_config_register(i2c_handle, CONFIG_REG_A, 0x70) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (write_config_register(i2c_handle, CONFIG_REG_B, 0x20) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (write_mode_register(i2c_handle, 0x00) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t x_history[WINDOW_SIZE], y_history[WINDOW_SIZE], z_history[WINDOW_SIZE];
    int x_offset = 0, y_offset = 0, z_offset = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HMC5883L Hard-Iron Compensation Demo\n");
    printf("I2C bus 1, address 0x%02X, running at 500 ms intervals\n", HMC5883L_ADDR);

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_raw_data(i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            x_history[0] = raw_x;
            y_history[0] = raw_y;
            z_history[0] = raw_z;
            for (int i = 1; i < WINDOW_SIZE; i++) {
                x_history[i] = x_history[i - 1];
                y_history[i] = y_history[i - 1];
                z_history[i] = z_history[i - 1];
            }
            compute_hard_iron_offsets(x_history, y_history, z_history, WINDOW_SIZE,
                                       &x_offset, &y_offset, &z_offset);
            int16_t corrected_x = raw_x - x_offset;
            int16_t corrected_y = raw_y - y_offset;
            int16_t corrected_z = raw_z - z_offset;
            printf("X: %6d, Y: %6d, Z: %6d\n", corrected_x, corrected_y, corrected_z);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying in 500 ms.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

