#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR        0x1D
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49
#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_OUT_X_L_A   0x28
#define LSM303D_INT1_CFG    0x5B

#define INT1_GPIO_LINE      23          /* BCM 23, physical pin 16 */
#define INT1_THRESHOLD_MG   2000
#define INT1_DURATION_US    0
#define SAMPLE_PERIOD_US    10000       /* 10 ms */
#define BUFFER_SIZE         64
#define BUFFER_COUNT        0

/* ---- Globals for cleanup ---- */
static int               g_i2c_fd   = -1;
static struct gpiod_chip *g_chip    = NULL;
static struct gpiod_line *g_line    = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Circular buffer ---- */
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int   head;
    int   count;
} circular_buffer_t;

static circular_buffer_t g_buffer;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D init ---- */
static int init_lsm303d(int fd)
{
    uint8_t whoami;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &whoami) != 0)
        return -1;
    if (whoami != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 50 Hz ODR, all axes enabled (0x57) */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x57) != 0)
        return -1;

    /* CTRL_REG4: full-scale +/-2g, no auto-increment (0x00) */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG4, 0x00) != 0)
        return -1;

    /* INT1: threshold 2000 mg (2000/16 = 125, 0x7D) */
    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, 0x7D) != 0)
        return -1;

    return 0;
}

/* ---- Read acceleration ---- */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, LSM303D_OUT_X_L_A | 0x80, raw, 6) != 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* +/-2g full-scale => 0.061 mg/LSB => 1 LSB = 16.25 mg */
    *x = (float)rx * 16.25f;
    *y = (float)ry * 16.25f;
    *z = (float)rz * 16.25f;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_add(circular_buffer_t *buf, float x, float y, float z)
{
    buf->x[buf->head] = x;
    buf->y[buf->head] = y;
    buf->z[buf->head] = z;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_dump(const circular_buffer_t *buf, int n)
{
    printf("\n--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (buf->head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] X: %.2f Y: %.2f Z: %.2f\n",
               i, buf->x[idx], buf->y[idx], buf->z[idx]);
    }
    printf("--------------------------\n");
}

/* ---- main ---- */
int main(void)
{
    /* ---- open I2C ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- verify device identity ---- */
    uint8_t whoami;
    if (i2c_read_reg8(g_i2c_fd, LSM303D_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (whoami != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, LSM303D_WHO_AM_I_VAL);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- init LSM303D ---- */
    if (init_lsm303d(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- open GPIO chip and request INT1 line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_line = gpiod_chip_get_line(g_chip, INT1_GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

