        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (whoami != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, LSM303D_WHO_AM_I_VAL);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- init LSM303D ---- */
    if (init_lsm303d(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- open GPIO chip and request INT1 line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
