#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define CONSUMER "solenoid-actuator"
#define DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_line_value(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Failed to set line value %d: %s\n", value, strerror(errno));
        return -1;
    }
    return 0;
}

static int sleep_ms(unsigned int ms)
{
    struct timespec req = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    struct timespec rem;
    while (nanosleep(&req, &rem) < 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            return -1;
        }
        req = rem;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", SOLENOID_1_PIN, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", SOLENOID_2_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", SOLENOID_1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", SOLENOID_2_PIN, strerror(errno));
        goto cleanup;
    }

    /* Ensure both solenoids are de-energized at startup */
    if (set_line_value(line1, 0) < 0 || set_line_value(line2, 0) < 0)
        goto cleanup;

    while (g_running) {
        /* Energize solenoid 1 for DELAY_MS */
        if (set_line_value(line1, 1) < 0)
            goto cleanup;
        if (sleep_ms(DELAY_MS) < 0)
            goto cleanup;
        if (set_line_value(line1, 0) < 0)
            goto cleanup;

        /* Energize solenoid 2 for DELAY_MS */
        if (set_line_value(line2, 1) < 0)
            goto cleanup;
        if (sleep_ms(DELAY_MS) < 0)
            goto cleanup;
        if (set_line_value(line2, 0) < 0)
            goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip in reverse order to minimize race */
    if (line2) {
        set_line_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (line1) {
        set_line_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

