#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define UART_PRIMARY 0
#define UART_SECONDARY 1
#define BAUD_RATE 9600
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"
#define UNLOCK_DURATION_MS 2000
#define POLL_INTERVAL_US 100000
#define READ_TIMEOUT_MS 5000

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd_1 = -1;
static int g_serial_fd_2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(int fd, const char *device) {
    int fd_saved = fd;
    fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        close(fd_saved);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_uart_line(int fd, char *buf, size_t buf_size) {
    static char temp[256];
    static int temp_len = 0;
    static time_t last_print_time = 0;

    char ch;
    while (temp_len < buf_size - 1) {
        fd_set fds;
        struct timeval tv;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 0;
        tv.tv_usec = 0;

        int ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select error: %s\n", strerror(errno));
            return -1;
        }
        if (ret == 0) {
            last_print_time = time(NULL);
            continue;
        }

        int c = read(fd, &ch, 1);
        if (c < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read error: %s\n", strerror(errno));
            return -1;
        }
        if (c == 0) continue;

        if (ch == '\n') {
            temp[temp_len] = '\0';
            if (temp_len > 0) {
                buf[temp_len] = '\0';
                return 0;
            }
            temp_len = 0;
            continue;
        }

        if (temp_len < buf_size - 1) {
            temp[temp_len++] = ch;
        } else {
            fprintf(stderr, "Buffer overflow, discarding partial line\n");
            temp_len = 0;
            continue;
        }
    }

    if (temp_len > 0) {
        temp[temp_len] = '\0';
        return 0;
    }
    return -1;
}

static int read_code(int fd, char *code, size_t code_len) {
    char temp[256];
    size_t temp_len = 0;
    time_t last_print_time = 0;

    while (temp_len < code_len - 1) {
        int ret = read_uart_line(fd, temp, sizeof(temp));
        if (ret < 0) return -1;
        if (ret == 0) {
            if (time(NULL) - last_print_time > READ_TIMEOUT_MS) {
                fprintf(stderr, "Timeout waiting for code on port %d\n", UART_PRIMARY);
                return -1;
            }
            continue;
        }
        if (temp[0] == '\0') {
            fprintf(stderr, "Timeout waiting for code on port %d\n", UART_PRIMARY);
            return -1;
        }
        if (temp[0] == '\n') {
            temp[0] = '\0';
            if (temp_len > 0) {
                code[temp_len] = '\0';
                return 0;
            }
            temp_len = 0;
            continue;
        }
        if (temp_len < code_len - 1) {
            temp[temp_len++] = temp[0];
        } else {
            fprintf(stderr, "Buffer overflow, discarding partial line\n");
            temp_len = 0;
            continue;
        }
    }

    if (temp_len > 0) {
        code[temp_len] = '\0';
        return 0;
    }
    return -1;
}

static int compare_code(const char *code1, const char *code2, const char *expected) {
    if (strcmp(code1, expected) == 0 && strcmp(code2, expected) == 0) {
        return 0;
    }
    return 1;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK_GPIO_1, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", LOCK_GPIO_1);
        return -1;
    }
    if (gpioWrite(LOCK_GPIO_2, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", LOCK_GPIO_2);
        return -1;
    }
    printf("Doors unlocked!\n");
    return 0;
}

static int lock_doors(void) {
    if (gpioWrite(LOCK_GPIO_1, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", LOCK_GPIO_1);
        return -1;
    }
    if (gpioWrite(LOCK_GPIO_2, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", LOCK_GPIO_2);
        return -1;
    }
    printf("Doors locked!\n");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK_GPIO_1, PI_OUTPUT) != 0 || gpioSetMode(LOCK_GPIO_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(LOCK_GPIO_1, 0) != 0 || gpioWrite(LOCK_GPIO_2, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO states\n");
        gpioTerminate();
        return 1;
    }

    g_serial_fd_1 = init_uart(g_serial_fd_1, "/dev/serial0");
    if (g_serial_fd_1 < 0) {
        gpioTerminate();
        return 1;
    }

    g_serial_fd_2 = init_uart(g_serial_fd_2, "/dev/serial1");
    if (g_serial_fd_2 < 0) {
        close(g_serial_fd_1);
        gpioTerminate();
        return 1;
    }

    printf("Dual-factor authentication system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        char code1[CODE_LENGTH + 1];
        char code2[CODE_LENGTH + 1];
        char expected[CODE_LENGTH + 1];

        if (read_code(g_serial_fd_1, code1, sizeof(code1)) < 0) {
            fprintf(stderr, "Error reading code from primary UART\n");
        } else if (read_code(g_serial_fd_2, code2, sizeof(code2)) < 0) {
            fprintf(stderr, "Error reading code from secondary UART\n");
        } else {
            if (strcmp(code1, EXPECTED_CODE) == 0 && strcmp(code2, EXPECTED_CODE) == 0) {
                if (compare_code(code1, code2, EXPECTED_CODE) == 0) {
                    printf("Both codes match! Unlocking doors...\n");
                    if (unlock_doors() == 0) {
                        gpioDelay(UNLOCK_DURATION_MS * 1000);
                        if (lock_doors() == 0) {
                            printf("Doors locked again.\n");
                        } else {
                            fprintf(stderr, "Failed to lock doors.\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to unlock doors.\n");
                    }
                } else {
                    fprintf(stderr, "Codes do not match.\n");
                }
            } else {
                fprintf(stderr, "Codes do not match.\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LOCK_GPIO_1, 0);
    gpioWrite(LOCK_GPIO_2, 0);
    if (g_serial_fd_1 >= 0) close(g_serial_fd_1);
    if (g_serial_fd_2 >= 0) close(g_serial_fd_2);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

