#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define CHIP_NAME "gpiochip0"
#define RELAY_ON_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int priority, const char *message) {
    openlog("door_strike_control", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret;
    int relay_state = 0;
    time_t relay_strike_start_time = 0;
    int relay_strike_active = 0;
    int failsafe_active = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open %s: %s", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_request_input(pir_line, "door_strike_control");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_request_output(relay_line, "door_strike_control", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto cleanup;
    }

    relay_state = 0;
    relay_strike_active = 0;
    relay_strike_start_time = 0;
    failsafe_active = 0;

    log_event(LOG_INFO, "Door strike control started.");

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
            break;
        }

        if (pir_value == 1) {
            relay_state = !relay_state;
            relay_line_set_value(relay_line, relay_state);
            relay_strike_active = 1;
            relay_strike_start_time = time(NULL);
            log_event(LOG_INFO, "Motion detected, relay ON.");
        } else {
            relay_strike_active = 0;
            relay_state = 0;
            log_event(LOG_INFO, "Motion stopped, relay OFF.");
        }

        if (relay_strike_active) {
            time_t now = time(NULL);
            if (difftime(now, relay_strike_start_time) >= RELAY_ON_DURATION_MS) {
                relay_line_set_value(relay_line, 0);
