#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define RELAY_ON_TIME_SEC 300
#define PAUSE_TIME_SEC    60
#define TIMER_INTERVAL_SEC 60

static volatile sig_atomic_t program_running = 1;

static const int relay_gpios[] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};
static const int num_relays = sizeof(relay_gpios) / sizeof(relay_gpios[0]);

static const char *relay_names[] = {"relay1", "relay2", "relay3", "relay4"};

static volatile sig_atomic_t relay_state = 0; /* 0 = OFF (HIGH), 1 = ON (LOW) */
static volatile sig_atomic_t current_action = 0; /* 0 = idle, 1 = activation, 2 = deactivation, 3 = pause */

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s", message);
}

static void log_relay_state(int gpio, int state) {
    char msg[128];
    snprintf(msg, sizeof(msg), "Relay on GPIO %d: %s", gpio, state ? "ON" : "OFF");
    log_message(msg);
}

static void relay_on(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        log_message("Failed to set relay GPIO low (write failed)");
        return;
    }
    log_relay_state(gpio, 1);
    current_action = 1;
}

static void relay_off(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        log_message("Failed to set relay GPIO high (write failed)");
        return;
    }
    log_relay_state(gpio, 0);
    current_action = 0;
}

static void relay_pause(void) {
    log_message("Pausing irrigation system");
    current_action = 3;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    if (current_action == 0) {
        for (int i = 0; i < num_relays; i++) {
            if (gpioWrite(relay_gpios[i], relay_state) != 0) {
                log_message("Failed to write relay GPIO");
            }
        }
        relay_state = !relay_state;
        current_action = 1;
    } else if (current_action == 1) {
        for (int i = 0; i < num_relays; i++) {
            if (gpioWrite(relay_gpios[i], 0) != 0) {
                log_message("Failed to set relay GPIO low (write failed)");
            }
        }
        relay_state = 1;
        current_action = 0;
    } else if (current_action == 2) {
        for (int i = 0; i < num_relays; i++) {
            if (gpioWrite(relay_gpios[i], 1) != 0) {
                log_message("Failed to set relay GPIO high (write failed)");
            }
        }
        relay_state = 0;
        current_action = 3;
    } else if (current_action == 3) {
        for (int i = 0; i < num_relays; i++) {
            if (gpioWrite(relay_gpios[i], 1) != 0) {
                log_message("Failed to set relay GPIO high (write failed)");
            }
        }
        relay_state = 1;
        current_action = 0;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            log_message("Failed to set GPIO mode");
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_gpios[i], 1) != 0) {
            log_message("Failed to initialize relay GPIO HIGH");
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_gpios[i], 1); /* Deactivate relays (HIGH = OFF) */
    }
    gpioTerminate();
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message("Failed to register signal handlers");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC, timer_callback, NULL) != 0) {
        log_message("Failed to set up timer callback");
        cleanup_gpio();
        closelog();
        return 1;
    }

    log_message("Irrigation system started");

    while (program_running) {
        sleep(1);
    }

    log_message("Shutting down irrigation system");
    cleanup_gpio();
    closelog();
    return 0;
}

