#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/timerfd.h>

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define ACCEL_SCALE 16384.0f
#define SAMPLE_RATE_HZ 100
#define BUFFER_SIZE 100
#define TIMER_FD -1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sysfs_fd = -1;
static struct timespec timer_ts;
static float accel_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_byte(MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_byte(MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_accel_data(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(MPU6050_ACCEL_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    accel_buffer[buffer_index] = x;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static int read_sysfs_data(float *x, float *y, float *z) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open sysfs file %s: %s\n", path, strerror(errno));
        return -1;
    }
    char buf[16];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    close(fd);
    if (n <= 0) {
        fprintf(stderr, "Failed to read sysfs data\n");
        return -1;
    }
    buf[n] = '\0';
    char *endptr;
    long val = strtol(buf, &endptr, 10);
    if (endptr == buf) {
        fprintf(stderr, "Invalid sysfs data format\n");
        return -1;
    }
    *x = (float)val / ACCEL_SCALE;
    *y = (float)val / ACCEL_SCALE;
    *z = (float)val / ACCEL_SCALE;
    return 0;
}

static void timer_callback(int sig, struct sigevent *sev, void *ctx) {
    (void)sig;
    (void)sev;
    (void)ctx;
    float x, y, z;
    if (read_sysfs_data(&x, &y, &z) < 0) {
        return;
    }
    add_to_buffer(x, y, z);
}

static void cleanup(void) {
    if (sysfs_fd >= 0) {
        close(sysfs_fd);
        sysfs_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (TIMER_FD >= 0) {
        timer_delete(TIMER_FD);
        TIMER_FD = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        return 1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    TIMER_FD = timer_create(CLOCK_MONOTONIC, &sev, NULL);
    if (TIMER_FD < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 1000000000L / SAMPLE_RATE_HZ;
    its.it_value = its.it_interval;
    if (timer_settime(TIMER_FD, 0, &its, NULL) < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU6050 initialized. Reading at %d Hz. Press Ctrl+C to exit.\n", SAMPLE_RATE_HZ);

    while (running) {
        float x, y, z;
        if (read_accel_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        } else {
            add_to_buffer(x, y, z);
        }
        struct timespec req = {0, 10000000L / SAMPLE_RATE_HZ};
        if (nanosleep(&req, NULL) < 0 && errno != EINTR) {
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
        }
    }

    printf("\nExiting...\n");
    cleanup();
    return 0;
}

