#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {18, 23, 24, 25}
#define NUM_INTERVALS 4

static const int interval_seconds[NUM_INTERVALS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set relay value");
        return -1;
    }
    return 0;
}

static int toggle_relay(struct gpiod_line *line) {
    return set_relay(line, !gpiod_line_get_value(line));
}

static int get_monotonic_seconds(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
        perror("clock_gettime failed");
        return -1;
    }
    return (int)ts.tv_sec;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handlers");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", RELAY_PINS[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "smart_lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", RELAY_PINS[i]);
            goto cleanup;
        }
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            int interval = interval_seconds[i];
            int elapsed = 0;
            int toggle_state = 0;

            while (running && elapsed < interval) {
                int val = toggle_relay(lines[i]);
                if (val < 0) {
                    fprintf(stderr, "Error toggling relay on pin %d\n", RELAY_PINS[i]);
                    goto cleanup;
                }
                if (gpiod_line_get_value(lines[i]) == 1) {
                    toggle_state = 1;
                } else {
                    toggle_state = 0;
                }
                elapsed = get_monotonic_seconds();
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Smart Lighting System stopped.\n");
    return ret;
}

