#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Gyroscope Sensitivity (default +-250 dps)
#define GYRO_SENSITIVITY 131.0f

// Circular Buffer Size
#define BUFFER_SIZE 100

// Angular Velocity Threshold
#define ANGULAR_VELOCITY_THRESHOLD 50.0f

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure to hold circular buffer data
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_mpu6050(void);
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
float calculate_angular_velocity(gyro_data_t data);
void check_angular_velocity_threshold(float angular_velocity);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Initialize MPU-6050
int init_mpu6050(void) {
    // Verify device identity
    int who_am_i = i2cReadByteData(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        perror("Failed to read WHO_AM_I register");
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x68, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake up MPU-6050");
        return -1;
    }
    usleep(100000); // Wait 100ms for sensor to stabilize

    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(gyro_data_t *data) {
    uint8_t buffer[6];
    // Read 6 bytes starting from GYRO_XOUT_H
    if (i2cReadI2CBlockData(i2c_fd, GYRO_XOUT_H, (char *)buffer, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    // Combine high and low bytes (little-endian)
    int16_t x_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t y_raw = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t z_raw = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to angular velocity (LSB per deg/s)
    data->x = (float)x_raw / GYRO_SENSITIVITY;
    data->y = (float)y_raw / GYRO_SENSITIVITY;
    data->z = (float)z_raw / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the angular velocity magnitude
float calculate_angular_velocity(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Check if the angular velocity exceeds the threshold
void check_angular_velocity_threshold(float angular_velocity) {
    if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
        printf("Angular velocity threshold exceeded! Velocity: %.2f deg/s\n", angular_velocity);
        // Trigger callback function here
        // For simplicity, we just print a message; in a real application,
        // you would call a user-defined callback function.
    }
}

int main(void) {
    // Initialize I2C
    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(&gyro_data) == 0) {
            float angular_velocity = calculate_angular_velocity(gyro_data);
            add_to_buffer(&gyro_buffer, gyro_data);
            check_angular_velocity_threshold(angular_velocity);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }
        usleep(10000); // 10ms delay
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

