#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define READ_CMD_LEN 9
#define READ_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static FILE *co2_log_fp = NULL;
static FILE *error_log_fp = NULL;
static int uart_handle = -1;

static void log_error(const char *msg) {
    if (!error_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(error_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(error_log_fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        log_error("Failed to open UART");
        return -1;
    }
    return 0;
}

static int read_co2_ppm(int *ppm_out) {
    char read_cmd[READ_CMD_LEN] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    int rc = serWrite(uart_handle, read_cmd, sizeof(read_cmd));
    if (rc < 0) {
        log_error("Failed to write read command");
        return -1;
    }
    gpioDelay(100000);
    char buf[READ_CMD_LEN];
    int avail = 0;
    int total = 0;
    int timeout = 0;
    while (total < sizeof(read_cmd) && running) {
        int n = serRead(uart_handle, buf + total, sizeof(read_cmd) - total);
        if (n < 0) {
            log_error("Failed to read from UART");
            return -1;
        }
        if (n == 0) {
            gpioDelay(1000);
            if (++timeout > READ_TIMEOUT_MS) {
                log_error("Timeout waiting for response");
                return -1;
            }
            continue;
        }
        if (n < (sizeof(read_cmd) - total)) {
            break;
        }
        total += n;
        avail += n;
        if (total == sizeof(read_cmd)) {
            break;
        }
    }
    if (total < sizeof(read_cmd)) {
        log_error("Incomplete read");
        return -1;
    }
    uint8_t sum = 0;
    for (int i = 1; i < 8; i++) sum += read_cmd[i];
    sum = ~sum + 1;
    if (sum != read_cmd[8]) {
        log_error("Checksum mismatch");
        return -1;
    }
    uint16_t co2 = ((uint16_t)read_cmd[2] << 8) | read_cmd[3];
    *ppm_out = co2;
    return 0;
}

static void log_co2_data(int ppm, int error) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(co2_log_fp, "{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": %d}\n",
            ts, ppm, error);
    fflush(co2_log_fp);
    printf("%s\n", ts);
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (co2_log_fp) {
        fclose(co2_log_fp);
        co2_log_fp = NULL;
    }
    if (error_log_fp) {
        fclose(error_log_fp);
        error_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }
    co2_log_fp = fopen(CO2_LOG_FILE, "a");
    if (!co2_log_fp) {
        log_error("Failed to open co2_log.json");
        cleanup();
        return 1;
    }
    error_log_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_fp) {
        log_error("Failed to open co2_error.log");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("CO2 monitor started. Press Ctrl+C to exit.\n");
    while (running) {
        int ppm = 0;
        if (read_co2_ppm(&ppm) == 0) {
            log_co2_data(ppm, 0);
        } else {
            log_co2_data(0, 1);
        }
        sleep(READ_INTERVAL_SEC);
    }
    cleanup();
    printf("CO2 monitor stopped.\n");
    return 0;
}

