#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "lighting_log.txt"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_lux(int fd, float *lux_out) {
    uint16_t raw;
    if (i2c_read_word(fd, 0x00, &raw) < 0) {
        return -1;
    }
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Failed to set relay line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(FILE *log_file, float lux, int red, int green, int blue) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n",
            timestamp, lux, red, green, blue);
    fflush(log_file);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int i2c_fd = -1;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(green_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(blue_line, "smart_lighting", 0) < 0) {
        fprintf(stderr, "Failed to request relay lines as outputs: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_byte(i2c_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to reset BH1750\n");
        goto cleanup;
    }
    if (i2c_write_byte(i2c_fd, 0x00, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Failed to configure BH1750\n");
        goto cleanup;
    }
    usleep(120000);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int red = (lux >= 50.0f) ? 1 : 0;
        int green = (lux >= 50.0f && lux <= 150.0f) ? 1 : 0;
        int blue = (lux >= 150.0f && lux <= 300.0f) ? 1 : 0;

        if (set_relay(red_line, red) < 0 ||
            set_relay(green_line, green) < 0 ||
            set_relay(blue_line, blue) < 0) {
            fprintf(stderr, "Relay control error\n");
        }

        log_data(log_file, lux, red, green, blue);
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

