#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Map distance (10-100 cm) to a PWM duty cycle (0-255).
 * Closer -> higher duty, clamped to [0,255].
 */
static int distance_to_pwm(int distance)
{
    if (distance < 10) distance = 10;
    if (distance > 100) distance = 100;
    int duty = (int)(((float)(distance - 10) / 90.0f) * (float)PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return duty;
}

static void motor_forward(int in1, int in2)
{
    gpioWrite(in1, 1);
    gpioWrite(in2, 0);
}

static void motor_backward(int in1, int in2)
{
    gpioWrite(in1, 0);
    gpioWrite(in2, 0);
}

