#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500
#define SERVO_RANGE 18000
#define LOG_FILE "solar_tracker.log"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int init_pwm(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error exporting PWM: %s\n", strerror(errno));
        return -1;
    }
    if (fputs(PWM_CHIP, fp) == EOF) {
        fprintf(stderr, "Error writing to PWM export: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    usleep(100000);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    int period_ns = 0;
    if (access(path, F_OK) != 0) {
        if (errno != ENOENT) {
            fprintf(stderr, "Error creating PWM period: %s\n", strerror(errno));
            return -1;
        }
        period_ns = PWM_PERIOD_NS;
    } else {
        FILE *fp = fopen(path, "w");
        if (!fp) {
            fprintf(stderr, "Error writing PWM period: %s\n", strerror(errno));
            return -1;
        }
        if (fputs(to_string(period_ns), fp) == EOF) {
            fprintf(stderr, "Error writing PWM period: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
        fclose(fp);
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    if (access(path, F_OK) != 0) {
        if (errno != ENOENT) {
            fprintf(stderr, "Error creating PWM duty cycle: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error writing PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    if (fputs(to_string(0), fp) == EOF) {
        fprintf(stderr, "Error writing PWM duty cycle: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    if (access(path, F_OK) != 0) {
        if (errno != ENOENT) {
            fprintf(stderr, "Error enabling PWM: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error enabling PWM: %s\n", strerror(errno));
        return -1;
    }
    if (fputs("1", fp) == EOF) {
        fprintf(stderr, "Error enabling PWM: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int init_mpu6050(int fd) {
    uint8_t buf[2];
    if (i2c_read_burst(fd, 0x75, buf, 2) < 0) {
        fprintf(stderr, "Error reading MPU6050 device ID: %s\n", strerror(errno));
        return -1;
    }
    if (buf[0] != 0x68 || buf[1] != 0x6A) {
        fprintf(stderr, "Unexpected MPU6050 device ID: 0x%02X 0x%02X\n", buf[0], buf[1]);
        return -1;
    }
    if (i2c_write_reg8(fd, 0x1F, 0x00) < 0) {
        fprintf(stderr, "Error writing MPU6050 temp sensor enable: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, 0x1E, 0x00) < 0) {
        fprintf(stderr, "Error writing MPU6050 accelerometer range: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, 0x1D, 0x00) < 0) {
        fprintf(stderr, "Error writing MPU6050 gyroscope range: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, 0x1C, 0x00) < 0) {
        fprintf(stderr, "Error writing MPU6050 power mode: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, 0x1A, 0x00) < 0) {
        fprintf(stderr, "Error writing MPU6050 accelerometer cutoff: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, 0x19, 0x00) < 0) {
        fprintf(stderr, "Error writing MPU6050 gyroscope cutoff: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error writing MPU6050 reset: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel_data(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, 0x42, buf, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int read_gyro_data(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, 0x43, buf, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
