#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_1 4
#define RELAY_2 17
#define RELAY_3 27
#define RELAY_4 22

#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION_SEC 30
#define FADE_STEPS 1800

#define SCHEDULE_FILE "lighting_schedule.txt"

typedef struct {
    int gpio;
    int relay_number;
    int is_on;
} RelayConfig;

static volatile sig_atomic_t running = 1;
static int pwm_enabled = 0;

static RelayConfig relays[] = {
    {RELAY_1, 1, 0},
    {RELAY_2, 2, 0},
    {RELAY_3, 3, 0},
    {RELAY_4, 4, 0}
};

static int num_relays = sizeof(relays) / sizeof(relays[0]);

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, RelayConfig *relays, int *num_relays) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *start = line;
        while (*start && (*start == ':' || *start == ' ' || *start == '\t')) start++;
        if (*start == '\0') continue;

        char *end = NULL;
        long val = strtol(start, &end, 10);
        if (end == start && val > 0 && val <= FADE_DURATION_SEC) {
            int relay_num = (int)(end - start);
            if (relay_num < 1 || relay_num > *num_relays) continue;

            char on_off[2] = {0};
            if (fscanf(line, "%1s %1s", on_off, on_off + 1) == 2) {
                relays[relay_num - 1].is_on = (on_off[0] == '1');
            } else {
                fprintf(stderr, "Invalid schedule entry: %s\n", line);
            }
        }
    }

    fclose(fp);
    return 0;
}

static void fade_lamp(int gpio, int duration_sec) {
    if (!pwm_enabled) return;

    if (duration_sec <= 0) return;

    int step_delay_us = (duration_sec * 1000000) / FADE_STEPS;
    int duty = 0;
    for (int i = 0; i <= FADE_STEPS && running; i++) {
        duty = (i * PWM_RANGE) / FADE_STEPS;
        if (gpioPWM(gpio, duty) < 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", gpio);
            return;
        }
        gpioDelay(step_delay_us);
    }

    gpioPWM(gpio, 0);
}

static void set_relay(int gpio, int relay_number, int is_on) {
    if (gpio < 0 || gpio >= num_relays) return;
    if (relay_number < 1 || relay_number > num_relays) return;
    relays[gpio].is_on = is_on;
    gpioPWM(gpio, is_on ? PWM_RANGE : 0);
}

static void cleanup(void) {
    for (int i = 0; i < num_relays; i++) {
        gpioPWM(relays[i].gpio, 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relays[i].gpio, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relays[i].gpio);
            cleanup();
            return 1;
        }
    }

    if (pwm_enabled = gpioSetPWMfrequency(RELAY_1, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", RELAY_1);
        cleanup();
        return 1;
    }
    if (pwm_enabled = gpioSetPWMrange(RELAY_1, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", RELAY_1);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        cleanup();
        return 1;
    }

    if (read_schedule(SCHEDULE_FILE, relays, &num_relays) < 0) {
        fprintf(stderr, "Failed to read schedule. Using default off state.\n");
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        if (!t) {
            fprintf(stderr, "localtime failed\n");
            sleep(1);
            continue;
        }

        int current_hour = t->tm_hour;
        int current_minute = t->tm_min;
        int current_second = t->tm_sec;

        for (int i = 0; i < num_relays; i++) {
            if (!relays[i].is_on) continue;

            int target_hour = t->tm_hour;
            int target_minute = t->tm_min;
            int target_second = t->tm_sec;

            if (current_hour == target_hour && current_minute == target_minute && current_second == target_second) {
                fade_lamp(relays[i].gpio, FADE_DURATION_SEC);
            }
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

