#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE  2.0f
#define MAX_DISTANCE  30.0f
#define MIN_FREQUENCY 200.0f
#define MAX_FREQUENCY 2000.0f

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   30000   /* 30 ms max echo wait */
#define LOOP_DELAY_US     60000   /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns -1.0 on timeout or out-of-range.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t pulse_us;

    /* Issue 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if sensor absent) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck low (sensor absent or not responding)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck high (timeout)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    pulse_us = end_tick - start_tick;

    if (pulse_us == 0) {
        fprintf(stderr, "Error: Zero pulse width\n");
        return -1.0f;
    }

    /* distance = (pulse_us * 34300 cm/s) / 2 / 1000000 */
    float distance = (float)pulse_us * 0.0343f / 2.0f / 1000000.0f;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0f;
    }

    return distance;
}

static float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    return MIN_FREQUENCY +
           (distance - MIN_DISTANCE) *
           (MAX_FREQUENCY - MIN_FREQUENCY) /
           (MAX_DISTANCE - MIN_DISTANCE);
}

static void set_buzzer_frequency(int frequency)
{
    if (frequency < 0) frequency = 0;
    if (frequency > 10000) frequency = 10000;

    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
        return;
    }
    gpioPWM(BUZZER_PIN, 128);  /* 50% duty cycle */
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);  /* 100 ms settle */

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: Invalid distance measurement, skipping cycle\n");
        } else {
            float frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency((int)frequency);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

