#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN,   0) < 0) return -1;
    if (gpioPWM(GREEN_PIN, 0) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  0) < 0) return -1;

    if (gpioPWM(RED_PIN,   red) < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue) < 0) return -1;

    return 0;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(RED_PIN,   0) < 0 ||
        gpioPWM(GREEN_PIN, 0) < 0 ||
        gpioPWM(BLUE_PIN,  0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM to 0.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    float proximity = 0.0;
    int   red_val   = 0;
    int   green_val = 0;
    int   blue_val  = 0;

    while (running) {
        proximity += 0.01 * (float)sin(2.0 * M_PI * 10.0 * proximity);
        if (proximity > 1.0) proximity = 1.0;
        if (proximity < 0.0) proximity = 0.0;

        float r = (proximity / 1.0f) * 255.0f;
        float g = (proximity / 1.0f) * 255.0f;
        float b = (proximity / 1.0f) * 255.0f;

        if (r > 255) r = 255;
        if (g > 255) g = 255;
        if (b > 255) b = 255;

        if (set_led_color(red_val, green_val, blue_val) < 0) {
            fprintf(stderr, "Error: gpioPWM failed.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

