#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define MELODY_SIZE 16
#define DEBOUNCE_US 50000
#define LOOP_DELAY_US 100000
#define PWM_DUTY 128  /* 50% of 255 */

static const int melody[MELODY_SIZE] = {
    69, 72, 74, 76, 79, 82, 85, 87,
    90, 93, 95, 97, 100, 103, 105, 108
};

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t melody_playing = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void melody_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == 0) {
        melody_playing = 1;
        gpioHardwarePWM(BUZZER_PIN, PWM_DUTY, 0);
    } else if (level == 1) {
        melody_playing = 0;
        gpioHardwarePWM(BUZZER_PIN, PWM_DUTY, 0);
    }
}

static int play_melody(void) {
    if (gpioHardwarePWM(BUZZER_PIN, PWM_DUTY, 0) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed\n");
        return -1;
    }
    for (int i = 0; i < MELODY_SIZE && running; i++) {
        if (gpioHardwarePWM(BUZZER_PIN, melody[i], 0) < 0) {
            fprintf(stderr, "Error: gpioHardwarePWM failed\n");
            return -1;
        }
        gpioDelay(LOOP_DELAY_US);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, melody_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Musical doorbell ready. Press the button (GPIO17) to play melody.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (melody_playing) {
            if (play_melody() < 0) {
                break;
            }
        }
        gpioDelay(100000); /* 100 ms idle poll */
    }

    /* Graceful shutdown */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

