#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define LOG_FILE "relay_log.json"
#define DEBOUNCE_US 200000  /* 200 ms */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t relay_state = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleans up.        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a JSON entry to the log file.                               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(const char *state)
{
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            perror("fopen(LOG_FILE)");
            return -1;
        }
        fprintf(fp, "[]");
        fclose(fp);
        return 0;
    }

    /* Read existing JSON array, remove the last element, then insert */
    /* the new state as the last element.                             */
    char *buf = malloc(128);
    if (buf == NULL) {
        perror("malloc");
        fclose(fp);
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    if (sz <= 0) {
        fclose(fp);
        free(buf);
        return 0;
    }

    fseek(fp, -1, SEEK_END);
    char *last = fgetc(fp);
    if (last == '\0') {
        fclose(fp);
        free(buf);
        return 0;
    }

    /* Remove last element (newline if present) */
    if (last == '\n') {
        fseek(fp, -1, SEEK_END);
        char *last2 = fgetc(fp);
        if (last2 == '\0') {
            fclose(fp);
            free(buf);
            return 0;
        }
        /* else: last was a newline — just remove it */
    }

    fclose(fp);

    /* Build the new JSON array with the new state */
    int idx = 0;
    while (1) {
        int c = fgetc(fp);
        if (c == '\0') break;
        if (c == ',') {
            buf[idx++] = ',';
        } else if (c == ']') {
            buf[idx++] = ']';
            break;
        } else {
            buf[idx++] = (char)c;
        }
    }

    buf[idx] = '\0';

    if (fprintf(fp, "%s", buf) < 0) {
        perror("fprintf");
        free(buf);
        return -1;
    }

    fclose(fp);
    free(buf);
    return 0;
}

/* ------------------------------------------------------------------ */
/* ISR callback — runs in pigpio thread, must be fast.                 */
/* ------------------------------------------------------------------ */
static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != 1) {
        return;  /* only act on rising edge (touch) */
    }

    /* Debounce: ignore touches within DEBOUNCE_US of the last one */
    static uint32_t last_tick = 0;
    uint32_t now = tick;
    if (now - last_tick < DEBOUNCE_US) {
        return;
    }
    last_tick = now;

    /* Software debounce: ignore touches within 200 ms of the last */
    /* confirmed touch. This is a simple heuristic; a real system    */
    /* might use a hardware debounce or a more sophisticated timer. */
    static uint32_t last_confirmed = 0;
    if (now - last_confirmed < DEBOUNCE_US) {
        return;
    }
    last_confirmed = now;

    /* Toggle relay */
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN) failed\n");
        return;
    }

    /* Log the event */
    if (log_event(relay_state ? "ON" : "OFF") != 0) {
        fprintf(stderr, "Failed to log event\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with pull-down */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_isr) != 0) {
        fprintf(stderr, "gpioSetISRFunc failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control ready. Touch GPIO4 to toggle relay on GPIO17.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop — sleep until signal received */
    while (running) {
        gpioDelay(100000);  /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);  /* best-effort relay OFF */
    if (log_event(relay_state) != 0) {
        fprintf(stderr, "Failed to log final state\n");
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

