#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define RELAY_GAP_SEC 1
#define LOG_FILE "irrigation_log.txt"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, RELAY1_PIN + i);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", RELAY1_PIN + i, strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n",
                    RELAY1_PIN + i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int log_event(int relay_num, int moisture) {
    if (!log_fp) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s - Relay %d activated (Moisture: %d)\n",
                timestamp, relay_num, moisture) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void activate_relay(int relay_num) {
    if (relay_num < 0 || relay_num >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number %d\n", relay_num);
        return;
    }
    if (gpiod_line_set_value(relay_lines[relay_num], 0) < 0) {
        fprintf(stderr, "Failed to set relay %d low: %s\n",
                relay_num, strerror(errno));
        return;
    }
    printf("Relay %d activated\n", relay_num);
}

static void deactivate_relay(int relay_num) {
    if (relay_num < 0 || relay_num >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number %d\n", relay_num);
        return;
    }
    if (gpiod_line_set_value(relay_lines[relay_num], 1) < 0) {
        fprintf(stderr, "Failed to set relay %d high: %s\n",
                relay_num, strerror(errno));
        return;
    }
    printf("Relay %d deactivated\n", relay_num);
}

static int generate_moisture_level(void) {
    return rand() % 101;
}

int main(void) {
    srand(time(NULL));

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        fclose(log_fp);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup_gpio();
        fclose(log_fp);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup_gpio();
        fclose(log_fp);
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture = generate_moisture_level();
        printf("Moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS; i++) {
                activate_relay(i);
                sleep(IRRIGATION_DURATION);
                deactivate_relay(i);
                sleep(RELAY_GAP_SEC);
            }
        }

        sleep(10);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_fp) {
        fclose(log_fp);
    }
    printf("Exiting.\n");
    return 0;
}

