/*
 * Automated plant watering system for Raspberry Pi Zero W
 * Library: pigpio
 *
 * Hardware:
 *   - SG90 water valve servo  on GPIO17 (physical pin 11)
 *   - SG90 directional nozzle servo on GPIO18 (physical pin 12)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:
 *   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

#define MOISTURE_THRESHOLD 50
#define SERVO_OPEN_US 900   /* 90 degrees  */
#define SERVO_CLOSE_US  0   /* 0 degrees  */
#define SERVO_STOP_US   500 /* 0 degrees  */

#define NOZZLE_ANGLE_COUNT 5
#define NOZZLE_ANGLE_STEP  45
#define NOZZLE_STEP_DELAY_US 2000000  /* 2 seconds per step */
#define WATERING_HOLD_US   5000000    /* 5 seconds total */
#define READ_INTERVAL_US   1000000    /* 1 second between readings */
#define SERVO_RETRIES      3
#define SERVO_RETRY_DELAY_US 100000   /* 100 ms backoff */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — only set flag; do NOT call pigpio functions here  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Convert angle (0-180) to servo pulse width in microseconds          */
/* ------------------------------------------------------------------ */
static int angle_to_pulse(int angle)
{
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return SERVO_STOP_US + (angle * (SERVO_OPEN_US - SERVO_STOP_US) / 180);
}

/* ------------------------------------------------------------------ */
/* Set a servo to a given angle with retry on transient failures       */
/* ------------------------------------------------------------------ */
static int set_servo_angle(int pin, int angle)
{
    int pulse = angle_to_pulse(angle);
    for (int attempt = 0; attempt < SERVO_RETRIES; attempt++) {
        if (gpioServo(pin, pulse) == 0)
            return 0;
        fprintf(stderr, "Warning: gpioServo(%d, %d) failed (attempt %d/%d)\n",
                pin, angle, attempt + 1, SERVO_RETRIES);
        gpioDelay(SERVO_RETRY_DELAY_US);
    }
    fprintf(stderr, "Error: gpioServo(%d, %d) failed after %d attempts\n",
            pin, angle, SERVO_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Open the water valve to the open position                          */
/* ------------------------------------------------------------------ */
static int open_valve(void)
{
    if (gpioServo(VALVE_SERVO_PIN, SERVO_OPEN_US) != 0) {
        fprintf(stderr, "Error: failed to open valve servo\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Close the water valve to the closed position                        */
/* ------------------------------------------------------------------ */
static int close_valve(void)
{
    if (gpioServo(VALVE_SERVO_PIN, SERVO_CLOSE_US) != 0) {
        fprintf(stderr, "Error: failed to close valve servo\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sweep the nozzle through NOZZLE_ANGLE_COUNT angles                 */
/* ------------------------------------------------------------------ */
static int water_nozzle(int pin, int *angles, int count)
{
    for (int i = 0; i < count; i++) {
        if (set_servo_angle(pin, angles[i]) != 0)
            return -1;
        gpioDelay(NOZZLE_STEP_DELAY_US);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Water a plant given a simulated moisture reading                    */
/* ------------------------------------------------------------------ */
static int water_plant(int moisture_level)
{
    if (moisture_level >= MOISTURE_THRESHOLD) {
        fprintf(stderr, "Info: moisture level %d >= threshold %d — skipping watering\n",
                moisture_level, MOISTURE_THRESHOLD);
        return 0;
    }

    /* Open valve and let water flow for WATERING_HOLD_US */
    if (open_valve() != 0)
        return -1;

    /* Sweep nozzle through all angles */
    int angles[NOZZLE_ANGLE_COUNT];
    for (int i = 0; i < NOZZLE_ANGLE_COUNT; i++)
        angles[i] = i * NOZZLE_ANGLE_STEP;

    if (water_nozzle(NOZZLE_SERVO_PIN, angles, NOZZLE_ANGLE_COUNT) != 0)
        return -1;

    /* Hold watering for WATERING_HOLD_US */
    gpioDelay(WATERING_HOLD_US);

    /* Close valve */
    if (close_valve() != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure servo pins as outputs --- */
    if (gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", VALVE_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", NOZZLE_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure servos start in a known position --- */
    if (open_valve() != 0 || close_valve() != 0) {
        fprintf(stderr, "Error: failed to initialise valve/nozzle position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop: cycle through moisture readings --- */
    int moisture_levels[] = {20, 40, 60, 80, 100};
    int num_levels = (int)(sizeof(moisture_levels) / sizeof(moisture_levels[0]));

    while (g_running) {
        for (int i = 0; i < num_levels && g_running; i++) {
            int level = moisture_levels[i];
            printf("Moisture level: %d\n", level);

            if (water_plant(level) != 0) {
                fprintf(stderr, "Error: watering cycle failed at level %d\n", level);
            }

            /* Wait before next reading (interruptible by signals) */
            gpioDelay(READ_INTERVAL_US);
        }
    }

    /* --- Cleanup --- */
    gpioServo(VALVE_SERVO_PIN, SERVO_STOP_US);
    gpioServo(NOZZLE_SERVO_PIN, SERVO_STOP_US);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

