    }

    /* Open valve and let water flow for WATERING_HOLD_US */
    if (open_valve() != 0)
        return -1;

    /* Sweep nozzle through all angles */
    int angles[NOZZLE_ANGLE_COUNT];
    for (int i = 0; i < NOZZLE_ANGLE_COUNT; i++)
        angles[i] = i * NOZZLE_ANGLE_STEP;

    if (water_nozzle(NOZZLE_SERVO_PIN, angles, NOZZLE_ANGLE_COUNT) != 0)
        return -1;

    /* Hold watering for WATERING_HOLD_US */
    gpioDelay(WATERING_HOLD_US);

    /* Close valve */
    if (close_valve() != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure servo pins as outputs --- */
    if (gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", VALVE_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", NOZZLE_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure servos start in a known position --- */
    if (open_valve() != 0 || close_valve() != 0) {
        fprintf(stderr, "Error: failed to initialise valve/nozzle position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop: cycle through moisture readings --- */
    int moisture_levels[] = {20, 40, 60, 80, 100};
    int num_levels = (int)(sizeof(moisture_levels) / sizeof(moisture_levels[0]));

    while (g_running) {
        for (int i = 0; i < num_levels && g_running; i++) {
            int level = moisture_levels[i];
            printf("Moisture level: %d\n", level);

            if (water_plant(level) != 0) {
                fprintf(stderr, "Error: watering cycle failed at level %d\n", level);
            }

            /* Wait before next reading (interruptible by signals) */
            gpioDelay(READ_INTERVAL_US);
        }
    }

    /* --- Cleanup --- */
    gpioServo(VALVE_SERVO_PIN, SERVO_STOP_US);
    gpioServo(NOZZLE_SERVO_PIN, SERVO_STOP_US);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

