#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000

static volatile sig_atomic_t g_running = 1;

static const int coil_pins[4] = {IN1, IN2, IN3, IN4};

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_coils(int a, int b, int c, int d)
{
    if (gpioWrite(IN1, a) < 0) return -1;
    if (gpioWrite(IN2, b) < 0) return -1;
    if (gpioWrite(IN3, c) < 0) return -1;
    if (gpioWrite(IN4, d) < 0) return -1;
    return 0;
}

static int deenergize(void)
{
    int rc = 0;
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(coil_pins[i], 0) < 0) {
            fprintf(stderr, "Warning: gpioWrite failed on pin %d\n", coil_pins[i]);
            rc = -1;
        }
    }
    return rc;
}

static int rotate_steps(int direction)
{
    int a, b, c, d;
    if (direction == 1) {
        a = 1; b = 0; c = 0; d = 1;
    } else {
        a = 0; b = 1; c = 1; d = 0;
    }
    for (int i = 0; i < STEPS_PER_ROTATION && g_running; i++) {
        if (set_coils(a, b, c, d) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return deenergize();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(coil_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", coil_pins[i]);
            deenergize();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on button pin\n");
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed on button pin\n");
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automatic Door Lock System\n");
    printf("Press LOCK (GPIO24) to rotate clockwise 512 steps.\n");
    printf("Press UNLOCK (GPIO23) to rotate counter-clockwise 512 steps.\n");
    printf("Press Ctrl+C to exit.\n");
    printf("De-energizing coils...\n");
    if (deenergize() < 0) {
        fprintf(stderr, "Error: failed to de-energize coils\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Lock button pressed. Rotating clockwise...\n");
            if (rotate_steps(1) < 0) {
                fprintf(stderr, "Error: rotation failed\n");
                break;
            }
        } else if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlock button pressed. Rotating counter-clockwise...\n");
            if (rotate_steps(0) < 0) {
                fprintf(stderr, "Error: rotation failed\n");
                break;
            }
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    deenergize();
    gpioTerminate();
    return EXIT_SUCCESS;
}

