#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define DISTANCE_THRESHOLD 50
#define POLL_DELAY_US  100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET          0x0000
#define REG_SYSTEM_MODE         0x0080
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_DISTANCE_MSB  0x0096
#define REG_RESULT_DISTANCE_LSB  0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)data, len) != (int)len)
        return -1;
    return 0;
}

static int vl53l1x_init(int handle)
{
    /* Software reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Set ranging mode (0x01 = continuous ranging) */
    if (i2c_write_reg16(handle, REG_SYSTEM_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: failed to set ranging mode\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status;
    uint8_t msb, lsb;

    /* Poll interrupt status for data ready */
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Warning: data not ready after 20 ms\n");
        return -1;
    }

    /* Read 16-bit distance: MSB at 0x0096, LSB at 0x0097 */
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE_MSB, &msb, 1) < 0)
        return -1;
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE_LSB, &lsb, 1) < 0)
        return -1;

    *distance = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set relay GPIO mode\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    printf("Proximity door system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error: I2C read failed\n");
            gpioWrite(RELAY_GPIO, 0);
        } else {
            printf("Distance: %u cm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
                printf("Door OPEN\n");
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

