                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, 0) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        if (log_watering_start(relay_labels[0]) != 0) {
            fprintf(stderr, "Warning: failed to log start time for relay %s\n",
                    relay_labels[0]);
        }

        for (int s = 0; s < WATERING_DURATION_SEC && program_running; s++)
            sleep(1);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, 1) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        if (log_watering_end(relay_labels[0]) != 0) {
            fprintf(stderr, "Warning: failed to log end time for relay %s\n",
                    relay_labels[0]);
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, 0) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        if (program_running)
            sleep(WATERING_INTERVAL_SEC - WATERING_DURATION_SEC);
    }

    ret = EXIT_SUCCESS;

