#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 30
#define STEP_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening smart_lighting.log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < 4; i++) {
        gpioPWM(RELAY1_PIN, 0);
        gpioPWM(RELAY2_PIN, 0);
        gpioPWM(RELAY3_PIN, 0);
        gpioPWM(RELAY4_PIN, 0);
    }
    gpioTerminate();
}

static void sunrise_simulation(int duration_minutes) {
    time_t start_time = time(NULL);
    time_t current_time;
    int duty_cycle = 0;
    int step_delay_us = STEP_DELAY_US;

    while (running && (time(NULL) - start_time) < duration_minutes * 60) {
        duty_cycle += 1;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        for (int i = 0; i < 4; i++) {
            if (gpioPWM(RELAY1_PIN, duty_cycle) != 0 ||
                gpioPWM(RELAY2_PIN, duty_cycle) != 0 ||
                gpioPWM(RELAY3_PIN, duty_cycle) != 0 ||
                gpioPWM(RELAY4_PIN, duty_cycle) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", i);
                cleanup_gpio();
                return;
            }
        }

        log_event("Sunrise simulation: increasing duty cycle");
        gpioDelay(step_delay_us);
    }

    log_event("Sunrise simulation complete");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Smart lighting simulation started");
    sunrise_simulation(SUNRISE_DURATION);

    log_event("Smart lighting simulation stopped");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

