            fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < 4; i++) {
        gpioPWM(RELAY1_PIN, 0);
        gpioPWM(RELAY2_PIN, 0);
        gpioPWM(RELAY3_PIN, 0);
        gpioPWM(RELAY4_PIN, 0);
    }
    gpioTerminate();
}

static void sunrise_simulation(int duration_minutes) {
    time_t start_time = time(NULL);
    time_t current_time;
    int duty_cycle = 0;
    int step_delay_us = STEP_DELAY_US;

    while (running && (time(NULL) - start_time) < duration_minutes * 60) {
        duty_cycle += 1;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        for (int i = 0; i < 4; i++) {
            if (gpioPWM(RELAY1_PIN, duty_cycle) != 0 ||
                gpioPWM(RELAY2_PIN, duty_cycle) != 0 ||
                gpioPWM(RELAY3_PIN, duty_cycle) != 0 ||
                gpioPWM(RELAY4_PIN, duty_cycle) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", i);
                cleanup_gpio();
                return;
            }
        }

        log_event("Sunrise simulation: increasing duty cycle");
        gpioDelay(step_delay_us);
    }

    log_event("Sunrise simulation complete");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Smart lighting simulation started");
    sunrise_simulation(SUNRISE_DURATION);

    log_event("Smart lighting simulation stopped");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

