#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75

/* Expected WHO_AM_I value */
#define MPU6050_WHO_AM_I_VAL 0x68

/* LED GPIO pin */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling period in microseconds (20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* Gyroscope full-scale range (LSB/deg/s) */
#define GYRO_SCALE 131.0f

/* Threshold for angular velocity (deg/s) */
#define THRESHOLD 250.0f

/* Structure to hold gyroscope data and timestamp */
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    time_t timestamp;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* Global variables */
static int i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_mpu6050(void);
static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z);
static void add_to_buffer(circular_buffer_t *buffer, float gyro_x, float gyro_y, float gyro_z);
static bool check_threshold(float gyro_x, float gyro_y, float gyro_z);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize the MPU-6050 sensor */
static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1 register\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time after wake-up */

    /* Set sample rate divider to 1 kHz (1 kHz / (1 + 1) = 500 Hz) */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to write SMPLRT_DIV register\n");
        return -1;
    }

    /* Set gyroscope full-scale range to +/- 250 deg/s */
    if (i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write GYRO_CONFIG register\n");
        return -1;
    }

    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, MPU6050_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    return 0;
}

/* Read gyroscope data from the MPU-6050 */
static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z) {
    char buffer[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    int16_t raw_gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    /* Convert to degrees per second */
    *gyro_x = (float)raw_gyro_x / GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y / GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z / GYRO_SCALE;

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(circular_buffer_t *buffer, float gyro_x, float gyro_y, float gyro_z) {
    buffer->data[buffer->head].gyro_x = gyro_x;
    buffer->data[buffer->head].gyro_y = gyro_y;
    buffer->data[buffer->head].gyro_z = gyro_z;
    buffer->data[buffer->head].timestamp = time(NULL);

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

/* Check if any axis exceeds the threshold */
static bool check_threshold(float gyro_x, float gyro_y, float gyro_z) {
    return (fabsf(gyro_x) > THRESHOLD ||
            fabsf(gyro_y) > THRESHOLD ||
            fabsf(gyro_z) > THRESHOLD);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection on bus 1 */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Initialize circular buffer */
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float gyro_x, gyro_y, gyro_z;
    bool led_state = false;

    /* Main loop */
    while (program_running) {
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            add_to_buffer(&gyro_buffer, gyro_x, gyro_y, gyro_z);

            if (check_threshold(gyro_x, gyro_y, gyro_z)) {
                if (!led_state) {
                    gpioWrite(LED_PIN, 1);
                    led_state = true;
                }
            } else {
                if (led_state) {
                    gpioWrite(LED_PIN, 0);
                    led_state = false;
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Attempting re-initialization...\n");
            gpioWrite(LED_PIN, 0);
            led_state = false;

            /* Attempt re-initialization up to 3 times */
            for (int i = 0; i < 3 && program_running; i++) {
                if (init_mpu6050() == 0) {
                    break;
                }
                gpioDelay(1000000); /* 1 second between retries */
            }

            if (!program_running) {
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    cleanup();
    return 0;
}

