#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP        "/dev/gpiochip0"
#define CS_LINE_OFFSET   8
#define SPI_SPEED_HZ     1000000
#define SPI_BITS          8
#define SPI_MODE          0
#define GYRO_XOUT_H       0x43
#define GYRO_XOUT_L       0x44
#define GYRO_YOUT_H       0x45
#define GYRO_YOUT_L       0x46
#define GYRO_ZOUT_H       0x47
#define GYRO_ZOUT_L       0x48
#define GYRO_SENSITIVITY  131.0f
#define RETRY_COUNT       3
#define SAMPLE_PERIOD_US  10000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t lsb = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_LSBS, &lsb) < 0) {
        fprintf(stderr, "Error setting SPI lsb: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t msb = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MSB, &msb) < 0) {
        fprintf(stderr, "Error setting SPI msb: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(gpio_chip); gpio_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(gpio_chip); gpio_chip = NULL; cs_line = NULL;
        return -1;
    }

    return 0;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS high: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t tx[7] = { GYRO_XOUT_H, GYRO_XOUT_L, GYRO_YOUT_H, GYRO_YOUT_L, GYRO_ZOUT_H, GYRO_ZOUT_L, 0x00 };
    uint8_t rx[7] = { 0 };

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (spi_transfer(tx, rx, 7) == 0) {
            int16_t raw_x = (int16_t)((rx[1] << 8) | rx[0]);
            int16_t raw_y = (int16_t)((rx[3] << 8) | rx[2]);
            int16_t raw_z = (int16_t)((rx[5] << 8) | rx[4]);

            *x = (float)raw_x / GYRO_SENSITIVITY;
            *y = (float)raw_y / GYRO_SENSITIVITY;
            *z = (float)raw_z / GYRO_SENSITIVITY;
            return 0;
        }
        usleep(1000);
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", RETRY_COUNT);
    return -1;
}

static void log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return;
    }

