static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_led_line = NULL;
static struct gpiod_line *g_cs_line = NULL;

/* Circular buffer entry */
typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t g_buffer[BUFFER_SIZE];
static int g_buffer_index = 0;

/* Function prototypes */
static int  spi_init(void);
static int  spi_read_register(uint8_t reg, uint8_t *value);
static int  spi_write_register(uint8_t reg, uint8_t value);
static int  mpu6050_init(void);
static int  read_gyro_data(float *x, float *y, float *z);
static void buffer_add(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/* Initialize SPI device */
static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* Read a single register from the MPU-6050 via SPI */
static int spi_read_register(uint8_t reg, uint8_t *value) {
    if (value == NULL) {
        return -1;
    }

    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS line: %s\n", strerror(errno));
        return -1;
    }

    *value = rx[1];
    return 0;
}

/* Write a single register to the MPU-6050 via SPI */
static int spi_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Initialize the MPU-6050 */
static int mpu6050_init(void) {
    uint8_t id;
    if (spi_read_register(MPU6050_REG_PWR_MGMT_1, &id) < 0) {
        fprintf(stderr, "Error reading PWR_MGMT_1 register\n");
        return -1;
    }

    if (id != 0x68) {
        fprintf(stderr, "Error: MPU-6050 not detected (ID=0x%02X, expected 0x68)\n", id);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (spi_write_register(MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }

    /* Set sample rate divider to 100 Hz (0x00) */
    if (spi_write_register(MPU6050_REG_SMPLRT_DIV, 0x00) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data from the MPU-6050 */
static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t x_h, x_l, y_h, y_l, z_h, z_l;

    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H, &x_h) < 0) return -1;
    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H + 1, &x_l) < 0) return -1;
    if (spi_read_register(MPU6050_REG_GYRO_YOUT_H, &y_h) < 0) return -1;
    if (spi_read_register(MPU6050_REG_GYRO_YOUT_H + 1, &y_l) < 0) return -1;
    if (spi_read_register(MPU6050_REG_GYRO_ZOUT_H, &z_h) < 0) return -1;
    if (spi_read_register(MPU6050_REG_GYRO_ZOUT_H + 1, &z_l) < 0) return -1;

    int16_t raw_x = (int16_t)((x_h << 8) | x_l);
    int16_t raw_y = (int16_t)((y_h << 8) | y_l);
    int16_t raw_z = (int16_t)((z_h << 8) | z_l);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* Add data to the circular buffer */
static void buffer_add(float x, float y, float z) {
    time(&g_buffer[g_buffer_index].timestamp);
    g_buffer[g_buffer_index].x = x;
    g_buffer[g_buffer_index].y = y;
    g_buffer[g_buffer_index].z = z;

    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void) {
    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize SPI */
    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    /* Initialize MPU-6050 */
    if (mpu6050_init() < 0) {
        fprintf(stderr, "Error initializing MPU-6050\n");
        cleanup();
        return 1;
    }

    /* Initialize GPIO using libgpiod */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    g_led_line = gpiod_chip_get_line(g_chip, LED_GPIO_LINE);
    if (!g_led_line) {
        fprintf(stderr, "Error getting LED GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_GPIO_LINE);
    if (!g_cs_line) {
        fprintf(stderr, "Error getting CS GPIO line %d: %s\n", CS_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(g_led_line, "mpu6050_led", 0) < 0) {
        fprintf(stderr, "Error requesting LED GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu6050_cs", 1) < 0) {
        fprintf(stderr, "Error requesting CS GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU-6050 stability monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            break;
        }

        buffer_add(x, y, z);

        if (fabsf(x) > GYRO_THRESHOLD_X || fabsf(y) > GYRO_THRESHOLD_Y || fabsf(z) > GYRO_THRESHOLD_Z) {
            printf("Threshold exceeded! X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
            gpiod_line_set_value(g_led_line, 1);
            usleep(500000);
            gpiod_line_set_value(g_led_line, 0);
            usleep(500000);
        }

        printf("X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
        usleep(10000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

