#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt thresholds (degrees) */
#define TILT_ROLL_THRESHOLD 45.0
#define TILT_PITCH_THRESHOLD 45.0

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to an MPU-6050 register */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* Read N bytes starting from an MPU-6050 register */
static int mpu_read_regs(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select) failed for reg 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%02X (got %d of %u)\n",
                reg, len, len);
        return -1;
    }
    return 0;
}

/* Initialize the MPU-6050: wake up and set accelerometer range to +/-2g */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (mpu_write_reg(handle, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to wake MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set accelerometer full-scale range to +/-2g (AFS_SEL = 0) */
    if (mpu_write_reg(handle, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set accelerometer range\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    return 0;
}

/* Read 6 bytes of accelerometer data (X, Y, Z) */
static int read_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (mpu_read_regs(handle, ACCEL_XOUT_H, buf, 6) != 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Compute roll and pitch from accelerometer data */
static void compute_tilt(int16_t x, int16_t y, int16_t z,
                         float *roll, float *pitch) {
    *roll = atan2f((float)y, (float)z) * 180.0f / M_PI;
    *pitch = atan2f(-(float)x, sqrtf((float)y * y + (float)z * z)) * 180.0f / M_PI;
}

/* Log a tilt reading to tilt_log.txt */
static void log_tilt(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for appending\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus 1 at 0x%02X (err=%d)\n",
                MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not register SIGINT handler\n");
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t x, y, z;
        if (read_accel(i2c_handle, &x, &y, &z) == 0) {
            float roll, pitch;
            compute_tilt(x, y, z, &roll, &pitch);

            /* Check tilt thresholds */
            if (fabsf(roll) > TILT_ROLL_THRESHOLD || fabsf(pitch) > TILT_PITCH_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }

            /* Log the reading */
            log_tilt(roll, pitch);

            /* Print to console */
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

