#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define ALS_REG 0x20
#define PROX_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define PROX_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    int retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, 2) != 2) {
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }
    return -1;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    int retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        if (write(fd, buf, 2) == 2) return 0;
        retries--;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

