    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "biometric_led", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1145 biometric logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t ambient_light = 0, proximity = 0;
        int als_ok = i2c_read_reg16(i2c_fd, ALS_REG, &ambient_light);
        int prox_ok = i2c_read_reg16(i2c_fd, PROX_REG, &proximity);

        if (als_ok == 0 && prox_ok == 0) {
            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
            if (proximity > PROX_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "I2C read error (ALS=%d, PROX=%d). Retrying...\n", als_ok, prox_ok);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

