#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

/* ADXRS290 register addresses (X and Y angular-rate axes) */
#define ADXRS290_REG_X_RATE 0x02
#define ADXRS290_REG_Y_RATE 0x04

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0f

/* Sampling interval: 10 ms -> 100 Hz */
#define SAMPLE_DELAY_US 10000

/* Reinitialise SPI on read failure up to 3 times */
#define MAX_REINIT_ATTEMPTS 3

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (high byte first) via SPI                       */
/* Returns 0 on success, -1 on failure.                                  */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* ADXRS290 returns high byte first */
    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read both axes and convert to degrees per second                   */
/* ------------------------------------------------------------------ */
static int read_gyro_data(float *x_rate, float *y_rate)
{
    int16_t raw_x, raw_y;

    if (read_register(ADXRS290_REG_X_RATE, &raw_x) != 0)
        return -1;
    if (read_register(ADXRS290_REG_Y_RATE, &raw_y) != 0)
        return -1;

    *x_rate = (float)raw_x / SENSITIVITY;
    *y_rate = (float)raw_y / SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                               */
/* ------------------------------------------------------------------ */
static int log_data(float x_rate, float y_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec, x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Reinitialise SPI: close current handle, wait, open new             */
/* ------------------------------------------------------------------ */
static int reinit_spi(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    /* Wait for the bus to settle after a power-cycle / reinit */
    gpioDelay(100000);  /* 100 ms */

    for (int attempt = 1; attempt <= MAX_REINIT_ATTEMPTS; attempt++) {
        spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
        if (spi_handle >= 0) {
            fprintf(stderr, "SPI reinitialised (attempt %d/%d)\n",
                    attempt, MAX_REINIT_ATTEMPTS);
            return 0;
        }
        fprintf(stderr, "SPI reinit failed (attempt %d/%d): %s\n",
                attempt, MAX_REINIT_ATTEMPTS, strerror(errno));
        gpioDelay(100000);  /* 100 ms */
    }

    fprintf(stderr, "SPI reinit failed after %d attempts\n", MAX_REINIT_ATTEMPTS);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        perror("fopen gyro_data.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(fp, "timestamp,x_rate_dps,y_rate_dps\n") < 0) {
        perror("fprintf header");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "ADXRS290 gyro data logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float x_rate, y_rate;

        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            if (log_data(x_rate, y_rate) != 0) {
                fprintf(stderr, "Logging failed; aborting.\n");
                break;
            }
        } else {
            fprintf(stderr, "Gyro read failed; reinitialising SPI.\n");
            if (reinit_spi() != 0) {
                fprintf(stderr, "Reinit failed; aborting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    fprintf(stderr, "Shutting down...\n");
    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return EXIT_SUCCESS;
}

