    (void)sig;
    running = 0;
}

static void log_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void seismic_alert(void) {
