        fprintf(stderr, "Failed to set alert pin HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set alert pin LOW\n");
    }
}

static void seismic_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick_1 = 0;
    static uint32_t last_tick_2 = 0;
    static int have_1 = 0;
    static int have_2 = 0;

    if (level == 1) {
        if (!have_1) {
            last_tick_1 = tick;
            have_1 = 1;
        } else if (!have_2) {
            last_tick_2 = tick;
            have_2 = 1;
        } else {
            uint32_t diff = last_tick_2 - last_tick_1;
            if (diff > SEISMIC_DURATION_MS * 1000) {
                log_event();
                seismic_alert();
            }
        }
    } else if (level == 0) {
        if (have_1) {
