#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 register addresses */
#define ADXRS290_REG_RATE_XL  0x02
#define ADXRS290_REG_RATE_XH  0x03

/* SPI configuration */
#define SPI_CHANNEL 0          /* CE0 (GPIO8) */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_MODE    0          /* CPOL=0, CPHA=0 */

/* Threshold for angular velocity */
#define THRESHOLD_DEG_PER_S 20.0

/* Circular buffer capacity */
#define BUFFER_SIZE 100

/* Global state */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer */
typedef struct {
    struct timespec timestamps[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

static CircularBuffer gyro_buffer;

/* Function prototypes */
static int  spi_read_register(uint8_t reg, int16_t *out);
static void buffer_init(CircularBuffer *cb);
static void buffer_add(CircularBuffer *cb, struct timespec ts);
static void signal_handler(int sig);
static void cleanup(void);

/*
 * Read a 16-bit register from the ADXRS290.
 * The register address is sent with the MSB set (bit 7 = 1) to indicate a read.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int spi_read_register(uint8_t reg, int16_t *out) {
    char tx_buf[3];
    char rx_buf[3];
    int  ret;

    /* Build the SPI message: [reg | 0x80] [0x00] [0x00] */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Extract the two data bytes */
    *out = (int16_t)(((uint8_t)rx_buf[1] << 8) | (uint8_t)rx_buf[2]);
    return 0;
}

/* Initialize the circular buffer */
static void buffer_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->tail  = 0;
    cb->count = 0;
}

/* Add a timestamped reading to the circular buffer */
static void buffer_add(CircularBuffer *cb, struct timespec ts) {
    cb->timestamps[cb->head] = ts;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(17, 0);
    gpioTerminate();
}

int main(void) {
    int16_t rate_xl, rate_xh;
    struct timespec ts;
    double angular_velocity;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 (CE0) at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    buffer_init(&gyro_buffer);

    /* Configure LED pin */
    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(17, 0);

    /* Register signal handlers */
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADXRS290 gyroscope monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (spi_read_register(ADXRS290_REG_RATE_XL, &rate_xl) != 0) {
            fprintf(stderr, "Failed to read X-axis rate register\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        if (spi_read_register(ADXRS290_REG_RATE_XH, &rate_xh) != 0) {
            fprintf(stderr, "Failed to read Y-axis rate register\n");
            gpioDelay(100000);
            continue;
        }

        /* Combine the two bytes into a 16-bit two's-complement value */
        int16_t raw_rate = (int16_t)((rate_xh << 8) | rate_xl);

        /* Convert to degrees per second (200 LSB/deg/s) */
        angular_velocity = (double)raw_rate / 200.0;

        /* Timestamp the reading */
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
            buffer_add(&gyro_buffer, ts);
        } else {
            fprintf(stderr, "clock_gettime failed\n");
        }

        /* Check threshold and control LED */
        if (fabs(angular_velocity) > THRESHOLD_DEG_PER_S) {
            gpioWrite(17, 1); /* Turn LED on */
        } else {
            gpioWrite(17, 0); /* Turn LED off */
        }

        printf("X: %6d  Y: %6d  Rate: %7.2f deg/s  LED: %s\n",
               rate_xl, rate_xh, angular_velocity,
               (fabs(angular_velocity) > THRESHOLD_DEG_PER_S) ? "ON" : "OFF");

        gpioDelay(10000); /* 10 ms sampling interval */
    }

    /* Graceful cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

