#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

#define PWM_RANGE 255
#define PWM_FREQ 100
#define MIN_DUTY 0
#define MAX_DUTY 255

#define MIN_FADE_DURATION 1
#define MAX_FADE_DURATION 3600

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LAMP1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP3_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(LAMP1_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty on GPIO%d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(LAMP2_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty on GPIO%d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(LAMP3_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty on GPIO%d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);
    gpioTerminate();
}

static void fade_lamp(int gpio, int duration_sec) {
    if (duration_sec <= 0) {
