#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24

#define RED_TIME 10
#define RED_YELLOW_TIME 2
#define GREEN_TIME 10
#define YELLOW_TIME 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    int pins[4] = {RED_PIN, YELLOW_PIN, GREEN_PIN, BLUE_PIN};
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "traffic-light", 1) < 0) {
            fprintf(stderr, "Failed to request line %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    printf("Traffic light simulator started. Press Ctrl+C to exit.\n");

    while (running) {
        printf("Red\n");
        fflush(stdout);
        gpiod_line_set_value(lines[0], 0);
        sleep(RED_TIME);

        printf("Red + Yellow\n");
        fflush(stdout);
        gpiod_line_set_value(lines[0], 0);
        sleep(RED_YELLOW_TIME);

        printf("Green\n");
        fflush(stdout);
        gpiod_line_set_value(lines[1], 0);
        sleep(GREEN_TIME);

        printf("Yellow\n");
        fflush(stdout);
        gpiod_line_set_value(lines[2], 0);
        sleep(YELLOW_TIME);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

