#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5D
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CHARGE_TIME 0x5C
#define MPR121_MODE 0x5E
#define MPR121_RESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X", reg, value);
        log_message(msg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_RESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_MODE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_DEBOUNCE, 0x21) < 0) return -1;
    if (mpr121_write(MPR121_CHARGE_TIME, 0x0D) < 0) return -1;
    if (mpr121_write(MPR121_ELECTRODE_CONFIG, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_MODE, 0x0D) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: reg=0x%02X", MPR121_TOUCHSTATUS_L);
        log_message(msg);
        return -1;
    }
    *status = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_message("Cleanup complete.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started.");

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C device at 0x%02X: %d", MPR121_ADDR, i2c_handle);
        log_message(msg);
        cleanup();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "MPR121 initialisation failed");
        log_message(msg);
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t touch_status = 0;
    int relay_state = 0;

    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & 0x0001) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                log_message(relay_state ? "Relay ON" : "Relay OFF");
                gpioDelay(100000);
            }
            gpioDelay(10000);
        } else {
            gpioDelay(100000);
        }
    }

    log_message("Program exiting.");
    cleanup();
    return EXIT_SUCCESS;
}

