#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define LOOP_DELAY_MS 5000
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_dispense(int sol1_pin, int sol2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Solenoid 1: GPIO%d, Solenoid 2: GPIO%d, Duration: %d ms\n",
            timestamp, sol1_pin, sol2_pin, duration_ms);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", pin);
        return -1;
    }
    return 0;
}

static int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO%d\n", pin);
        return -1;
    }
    return 0;
}

static int dispense(int duration_ms) {
    if (activate_solenoid(SOLENOID_1_PIN) != 0) return -1;
    gpioDelay(duration_ms / 2 * 1000);
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) return -1;

    if (activate_solenoid(SOLENOID_2_PIN) != 0) return -1;
    gpioDelay(duration_ms / 2 * 1000);
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) return -1;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense(DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Error during dispense cycle\n");
        }
        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Error logging dispense event\n");
        }

        if (running) {
            gpioDelay(LOOP_DELAY_MS * 1000);
        }
    }

    printf("\nShutting down gracefully...\n");
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();
    return EXIT_SUCCESS;
}

