#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD  22
#define MOTOR_B_BACKWARD 23
#define MOTOR_ENA 24
#define MOTOR_ENB 25

#define PWM_RANGE 255
#define PWM_FREQ 1000
#define OBSTACLE_THRESHOLD 20.0
#define OBSTACLE_REVERSE_SPEED 50
#define TILT_MIN -10.0
#define TILT_MAX 10.0
#define TILT_DT 0.05
#define LOG_FILE "balance_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

static int set_motor_speed(int motor_a_pin, int motor_b_pin, int speed) {
    if (speed < -PWM_RANGE || speed > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid speed %d for motor %s\n", speed, motor_a_pin == MOTOR_A_FORWARD ? "Motor A" : "Motor B");
        return -1;
    }
    if (motor_a_pin == MOTOR_A_FORWARD) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
    } else if (motor_a_pin == MOTOR_A_BACKWARD) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
    } else if (motor_b_pin == MOTOR_B_FORWARD) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
    } else if (motor_b_pin == MOTOR_B_BACKWARD) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
    } else {
        fprintf(stderr, "Error: Invalid motor pin %d\n", motor_a_pin);
        return -1;
    }
    gpioPWM(MOTOR_ENA, speed);
    gpioPWM(MOTOR_ENB, speed);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR_ENB, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_ENA, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR_ENB, PWM_FREQ);
    gpioSetPWMrange(MOTOR_ENA, PWM_RANGE);
    gpioSetPWMrange(MOTOR_ENB, PWM_RANGE);

    return 0;
}

static void cleanup(void) {
    set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, 0);
    set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int simulate_tilt_error(float *tilt_error) {
    *tilt_error = (float)(rand() % 21) - 9.0;
    return 0;
}

static int simulate_distance(float *distance) {
    *distance = (float)(rand() % 381) + 2.0;
    return 0;
}

static int control_motors(float tilt_error, float distance) {
    float error_rate = tilt_error / 10.0;
    float kp = 1.0;
    float ki = 0.01;
    float kd = 0.1;
    float integral = 0.0;
    float derivative = 0.0;
    float pid_output = 0.0;

    pid_output = kp * error_rate + integral + ki * derivative;
    integral += error_rate;
    derivative = error_rate - 0.5;

    int motor_a_speed = (int)(pid_output + 0.5);
    int motor_b_speed = (int)(pid_output - 0.5);

    if (distance < OBSTACLE_THRESHOLD) {
        motor_a_speed = -OBSTACLE_REVERSE_SPEED;
        motor_b_speed = -OBSTACLE_REVERSE_SPEED;
    }

    if (set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, motor_a_speed) != 0) {
        return -1;
    }
    if (set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, motor_b_speed) != 0) {
        return -1;
    }

    log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
    return 0;
}

int main(void) {
    float tilt_error, distance;
    int motor_a_speed, motor_b_speed;

    srand(time(NULL));

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (init_gpio() != 0) {
        fclose(log_file);
        return 1;
