#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d\n", TOUCH_SENSOR_PIN);
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure relay starts in OFF state */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO%d\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void toggle_relay(void) {
    int current = gpioRead(RELAY_PIN);
    if (current < 0) {
        fprintf(stderr, "Error: failed to read relay state on GPIO%d\n", RELAY_PIN);
        return;
    }

    int new_state = !current;
    if (gpioWrite(RELAY_PIN, new_state) != 0) {
        fprintf(stderr, "Error: failed to write relay state on GPIO%d\n", RELAY_PIN);
        return;
    }

    printf("Relay toggled to %s\n", new_state ? "ON" : "OFF");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart light switch started. Touch GPIO%d to toggle relay on GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;

    while (running) {
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_detected < 0) {
            fprintf(stderr, "Error: failed to read touch sensor on GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_detected) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
                toggle_relay();
                gpioDelay(DEBOUNCE_DELAY_US);
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nSmart light switch stopped.\n");
    return EXIT_SUCCESS;
}

