#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define DEFAULT_SENSITIVITY 1.0
#define SAMPLE_RATE         8000
#define NUM_CHANNELS        1
#define NUM_FRAMES          1024
#define UPDATE_DELAY_US     10000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ALSA capture                                                             */
/* ------------------------------------------------------------------ */

static int alsa_init(void) {
    struct snd_pcm_t *handle = NULL;
    snd_pcm_hw_params_t *hw_params = NULL;
    snd_pcm_period_t period;
    snd_pcm_frame_t frame;
    int ret;

    /* Open the default capture device */
    handle = snd_pcm_open(&snd_pcm_stream, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening ALSA stream: %s\n", snd_strerror(errno));
        return -1;
    }

    /* Configure hardware parameters */
    hw_params = snd_pcm_hw_params_new(&snd_pcm_stream);
    if (!hw_params) {
        fprintf(stderr, "Error allocating hardware parameters\n");
        goto fail;
    }

    snd_pcm_hw_params_any(hw_params);
    snd_pcm_hw_params_set_access(hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(hw_params, SND_PCM_FORMAT_S16_LE);
    snd_pcm_hw_params_set_rate_near(hw_params, SAMPLE_RATE, 0);
    snd_pcm_hw_params_set_channels(hw_params, NUM_CHANNELS);
    snd_pcm_hw_params_set_period_size(hw_params, &period);
    snd_pcm_hw_params_set_period_bytes(hw_params, period.elem_size);
    snd_pcm_hw_params_set_stream_mode(hw_params, SND_PCM_STREAM_MODE_CAPTURE);

    ret = snd_pcm_hw_params(hw_params);
    if (ret < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(errno));
        goto fail;
    }

    /* Prepare the stream */
    snd_pcm_prepare(handle);
    if (snd_pcm_prepare(handle) < 0) {
        fprintf(stderr, "Error preparing ALSA stream: %s\n", snd_strerror(errno));
        goto fail;
    }

    /* Open the output device (optional, but good practice) */
    snd_pcm_t *out_handle = snd_pcm_open(&snd_pcm_stream, "default", SND_PCM_STREAM_OUTPUT, 0);
    if (out_handle) {
        snd_pcm_drain(out_handle);
        snd_pcm_close(out_handle);
    }

    /* Set up signal handlers for stream events */
    snd_pcm_set_callback(handle);
    snd_pcm_set_start_callback(handle);
    snd_pcm_set_stop_callback(handle);
    snd_pcm_set_drain_callback(handle);

    return handle;

fail:
    snd_pcm_drain(handle);
    snd_pcm_close(handle);
    return -1;
}

static int alsa_read_sample(snd_pcm_t *handle, short *sample) {
    snd_pcm_frame_t frame;
    int ret;

    ret = snd_pcm_readi(handle, &frame);
    if (ret < 0) {
        fprintf(stderr, "Error reading ALSA frame: %s\n", snd_strerror(errno));
        return -1;
    }
    *sample = (short)frame;
    return 0;
}

static void alsa_close(snd_pcm_t *handle) {
    if (handle) {
        snd_pcm_drain(handle);
        snd_pcm_close(handle);
    }
}

/* ------------------------------------------------------------------ */
/* RGB color mapping                                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    float r, g, b;
} RGBColor;

static RGBColor map_amplitude_to_color(float amplitude) {
    RGBColor color;
    float norm = amplitude / 32767.0f; /* 2^15 */

    if (norm < 0.0f) norm = 0.0f;
    if (norm > 1.0f) norm = 1.0f;

    color.r = 1.0f - norm * 0.5f;
    color.g = norm * 0.5f;
    color.b = norm * 0.5f;
    return color;
}

static void set_rgb_led(int red_pin, int green_pin, int blue_pin,
                         const RGBColor *color) {
    gpioPWM(red_pin, (int)color->r * 255.0f);
    gpioPWM(green_pin, (int)color->g * 255.0f);
    gpioPWM(blue_pin, (int)color->b * 255.0f);
}

/* ------------------------------------------------------------------ */
/* Sine-wave fallback for ALSA-less environments                          */
/* ------------------------------------------------------------------ */

static void simulate_audio_input(int red_pin, int green_pin, int blue_pin) {
    float amplitude = 0.0f;
    float phase = 0.0f;

    for (int i = 0; i < NUM_FRAMES; i++) {
        amplitude = (float)sin(2.0f * M_PI * phase) * 32767.0f;
        phase += 0.01f;

        set_rgb_led(red_pin, green_pin, blue_pin,
                     map_amplitude_to_color(amplitude));

        gpioDelay(UPDATE_DELAY_US);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                         */
/* ------------------------------------------------------------------ */

static void cleanup(void) {
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    alsa_close(snd_pcm_stream);
}

/* ------------------------------------------------------------------ */
/* main                                                                 */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[]) {
    float sensitivity = DEFAULT_SENSITIVITY;
    int opt;

    /* Parse optional sensitivity argument */
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0f) {
                    fprintf(stderr, "Invalid sensitivity value. Using default: %.2f\n", DEFAULT_SENSITIVITY);
                    sensitivity = DEFAULT_SENSITIVITY;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins for PWM output */
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    /* Initialize ALSA if available */
    if (alsa_init() < 0) {
        fprintf(stderr, "ALSA initialization failed. Using sine-wave simulation.\n");
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Mood light started. Sensitivity: %.2f\n", sensitivity);

    /* Main loop */
    while (g_running) {
        short sample;
        if (alsa_read_sample(snd_pcm_stream, &sample) < 0) {
            fprintf(stderr, "Error reading ALSA sample. Re-initializing...\n");
            alsa_close(snd_pcm_stream);
            if (alsa_init() < 0) {
                fprintf(stderr, "ALSA re-initialization failed. Exiting.\n");
                break;
            }
            continue;
        }

        float amplitude = (float)abs(sample);
        RGBColor color = map_amplitude_to_color(amplitude);
        set_rgb_led(RED_PIN, GREEN_PIN, BLUE_PIN, &color);

        printf("Amplitude: %.2f, Color: R=%.2f G=%.2f B=%.2f\n",
               amplitude, color.r, color.g, color.b);

        gpioDelay(UPDATE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

