#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* TCS34725 I2C address (0x29 for ADDR pin low) */
#define TCS34725_ADDR 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME  0x81
#define TCS34725_ID     0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

/* Expected device ID */
#define TCS34725_ID_VALUE 0x44

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a TCS34725 register */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n",
                value, reg, strerror(errno));
    }
    return result;
}

/* Read a single byte from a TCS34725 register */
static int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

/* Initialize the TCS34725 sensor */
static int initialize_sensor(int handle) {
    /* Power on the sensor */
    if (write_register(handle, TCS34725_ENABLE, 0x01) < 0) {
        return -1;
    }
    gpioDelay(3000); /* 3 ms power-on delay */

    /* Enable RGBC (0x03) */
    if (write_register(handle, TCS34725_ENABLE, 0x03) < 0) {
        return -1;
    }
    gpioDelay(3000);

    /* Set integration time to 154 ms (0xD5) */
    if (write_register(handle, TCS34725_ATIME, 0xD5) < 0) {
        return -1;
    }
    gpioDelay(3000);

    return 0;
}

/* Read calibrated RGBC values from the sensor */
static int read_sensor_data(int handle, uint16_t *clear, uint16_t *red,
                            uint16_t *green, uint16_t *blue) {
    int cl, r, g, b;

    cl = read_register(handle, TCS34725_CDATA);
    r  = read_register(handle, TCS34725_RDATA);
    g  = read_register(handle, TCS34725_GDATA);
    b  = read_register(handle, TCS34725_BDATA);

    if (cl < 0 || r < 0 || g < 0 || b < 0) {
        return -1;
    }

    /* Clear value is the low byte of the CDATA register */
    *clear = (uint16_t)cl;

    /* Red value is the high byte of the RDATA register */
    *red = (uint16_t)((r & 0x0F) << 8 | (r >> 4));

    /* Green value is the high byte of the GDATA register */
    *green = (uint16_t)((g & 0x0F) << 8 | (g >> 4));

    /* Blue value is the high byte of the BDATA register */
    *blue = (uint16_t)((b & 0x0F) << 8 | (b >> 4));

    return 0;
}

/* Log data to CSV file */
static int log_data(FILE *fp, time_t timestamp, uint16_t clear,
                    uint16_t red, uint16_t green, uint16_t blue) {
    if (fprintf(fp, "%ld,%u,%u,%u,%u\n",
                (long)timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "Error writing to data file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    uint16_t clear, red, green, blue;
    time_t current_time;
    int result;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at TCS34725 address */
    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                TCS34725_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    int id = read_register(i2c_handle, TCS34725_ID);
    if (id < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open data file in append mode */
    data_file = fopen("color_data.csv", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(data_file, 0, SEEK_END);
    if (ftell(data_file) == 0) {
        fprintf(data_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(data_file);
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (!terminate) {
        result = read_sensor_data(i2c_handle, &clear, &red, &green, &blue);
        if (result == 0) {
            current_time = time(NULL);
            if (log_data(data_file, current_time, clear, red, green, blue) == 0) {
                printf("Timestamp: %ld, Clear: %u, Red: %u, Green: %u, Blue: %u\n",
                       (long)current_time, clear, red, green, blue);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, resetting values\n");
            clear = 0;
            red   = 0;
            green = 0;
            blue  = 0;
        }

        gpioDelay(500000); /* 500 ms */
    }

    /* Cleanup */
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

