    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    char command[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(filename, sizeof(filename), VIDEO_DIR "%Y%m%d_%H%M%S.h264", timeinfo) == 0) {
        return -1;
    }

    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, RECORD_DURATION_SEC);
    int ret = system(command);
    if (ret == -1) {
        return -1;
    }
    if (ret != 0) {
        fprintf(stderr, "raspivid failed with exit code %d\n", ret);
        return -1;
    }
    return 0;
}

static int log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    char filename[64];
    char command[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        return -1;
    }
    if (strftime(filename, sizeof(filename), LOG_DIR "%Y%m%d_%H%M%S_motion.log", timeinfo) == 0) {
        return -1;
    }

    snprintf(command, sizeof(command), "echo \"%s\" >> %s", timestamp, filename);
    int ret = system(command);
    if (ret == -1) {
        return -1;
    }
    if (ret != 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MOTION_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", MOTION_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_DIR "motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);

    int last_trigger_ms = 0;

    while (running) {
        int motion_detected = gpioRead(MOTION_SENSOR_GPIO);
        if (motion_detected < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", MOTION_SENSOR_GPIO);
            break;
        }

        if (motion_detected == 0) {
            if (last_trigger_ms == 0 || (int32_t)(time_diff_ms(&last_trigger_ms, time_time())) >= DEBOUNCE_DELAY_MS) {
                printf("Motion detected!\n");
                if (record_video() != 0) {
                    fprintf(stderr, "Failed to record video\n");
                }
                if (log_motion_event() != 0) {
                    fprintf(stderr, "Failed to log motion event\n");
                }
                last_trigger_ms = time_time();
            }
        }

        time_sleep(0.1);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

