#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

#define GYRO_SENSITIVITY 131.0f
#define SAMPLE_RATE_HZ   100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define I2C_BUS          1
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpu6050_init(int handle) {
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050 (PWR_MGMT_1)\n");
        return -1;
    }
    gpioDelay(100000);

    if (i2cWriteByteData(handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to set sample rate divider\n");
        return -1;
    }

    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set gyroscope full-scale range\n");
        return -1;
    }
    return 0;
}

static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read gyroscope data block\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%03ld,%.3f,%.3f,%.3f\n",
            (long)ts.tv_sec, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

int main(void) {
    float x, y, z;
    int reinit_attempts = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpu6050_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open gyro_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_degps,y_degps,z_degps\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Error: gyro read failed, re-initializing sensor...\n");
            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                if (mpu6050_init(i2c_handle) < 0) {
                    fprintf(stderr, "Error: re-init failed, retrying...\n");
                    reinit_attempts++;
                }
            } else {
                fprintf(stderr, "Error: max re-init attempts reached, logging error\n");
                log_data(log_file, 0.0f, 0.0f, 0.0f);
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

