#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define SLEEP_SECONDS 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static int control_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d to %d.\n", pin, state);
        return -1;
    }
    return 0;
}

static int log_data(int sensor_reading, int relay_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Sensor Reading: %d, Relay State: %d\n",
                timestamp, sensor_reading, relay_state) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file.\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Warning: failed to deactivate GPIO %d during cleanup.\n", pins[i]);
        }
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    srand((unsigned int)time(NULL));

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_reading = read_moisture_sensor();
        int relay_states[4];
        int error_occurred = 0;

        for (int i = 0; i < 4; i++) {
            int pin = (i == 0) ? RELAY1_PIN : (i == 1) ? RELAY2_PIN : (i == 2) ? RELAY3_PIN : RELAY4_PIN;
            int state = (sensor_reading < MOISTURE_THRESHOLD) ? 0 : 1;
            if (control_relay(pin, state) != 0) {
                error_occurred = 1;
                break;
            }
            relay_states[i] = state;
        }

        if (error_occurred) {
            fprintf(stderr, "Error: GPIO control failed during iteration.\n");
        }

        if (log_data(sensor_reading, 0) != 0) {
            fprintf(stderr, "Error: failed to log data.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Smart Greenhouse Irrigation System stopped.\n");
    return 0;
}

