#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

/* ADXL345 I2C address */
#define ADXL345_ADDR 0x53

/* ADXL345 register addresses */
#define POWER_CTL   0x2D
#define DATA_FORMAT 0x31
#define DATAX0      0x32

/* Freefall detection parameters */
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define FREEFALL_READ_DELAY_MS 500
#define FREEFALL_READ_INTERVAL_MS 100

/* GPIO pin for alarm output */
#define ALARM_PIN 27

/* Scale factor for ±2g range (full resolution) */
#define SCALE_FACTOR 256.0f

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Structure to hold accelerometer data */
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

/* Function prototypes */
static int initialize_i2c(void);
static int configure_adxl345(void);
static int read_accelerometer_data(accelerometer_data_t *data);
static int detect_freefall(accelerometer_data_t data);
static void trigger_alarm(void);
static void log_freefall_event(accelerometer_data_t data);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Initialize I2C communication */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

/* Configure ADXL345 for ±2g range and measurement mode */
static int configure_adxl345(void) {
    /* Set DATA_FORMAT to ±2g full resolution (0x0B) */
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    /* Set POWER_CTL to measure mode (0x08) */
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data from ADXL345 */
static int read_accelerometer_data(accelerometer_data_t *data) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting from DATAX0 */
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    /* Combine high and low bytes for each axis */
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Convert to g-force units */
    data->x = (float)raw_x / SCALE_FACTOR;
    data->y = (float)raw_y / SCALE_FACTOR;
    data->z = (float)raw_z / SCALE_FACTOR;

    return 0;
}

/* Detect freefall event */
static int detect_freefall(accelerometer_data_t data) {
    static uint32_t freefall_start_time = 0;
    static int freefall_active = 0;

    if (fabsf(data.x) < FREEFALL_THRESHOLD &&
        fabsf(data.y) < FREEFALL_THRESHOLD &&
        fabsf(data.z) < FREEFALL_THRESHOLD) {
        if (!freefall_active) {
            freefall_start_time = gpioTick();
            freefall_active = 1;
        }
    } else {
        if (freefall_active) {
            uint32_t current_time = gpioTick();
            uint32_t elapsed_time = current_time - freefall_start_time;
            if (elapsed_time >= (FREEFALL_DURATION_MS * 1000)) {
                freefall_active = 0;
                return 1;
            }
        }
        freefall_active = 0;
    }
    return 0;
}

/* Trigger the alarm */
static void trigger_alarm(void) {
    gpioWrite(ALARM_PIN, 1);
    gpioDelay(5000000); /* 5 seconds */
    gpioWrite(ALARM_PIN, 0);
}

/* Log freefall event to file */
static void log_freefall_event(accelerometer_data_t data) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening freefall.log for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fclose(fp);
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO27 as output */
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Configure ADXL345 */
    if (configure_adxl345() != 0) {
        cleanup();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        accelerometer_data_t data;

        if (read_accelerometer_data(&data) == 0) {
            if (detect_freefall(data)) {
                printf("Freefall detected!\n");
                trigger_alarm();
                log_freefall_event(data);
            }
        }

        gpioDelay(FREEFALL_READ_INTERVAL_MS * 1000); /* 100 ms */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

