#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400.0f
#define MAX_ECHO_US 23200
#define TIMEOUT_US 100000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 200000
#define ECHO_TIMEOUT_US 100000

static volatile uint32_t pulse_rise_tick = 0;
static volatile uint32_t pulse_fall_tick = 0;
static volatile int pulse_arrived = 0;
static volatile int echo_valid = 0;
static volatile int echo_arrived = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

static void trigger_pulse(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_rise_tick = tick;
        pulse_arrived = 1;
        pthread_mutex_unlock(&pulse_mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_fall_tick = tick;
        pulse_arrived = 1;
        echo_valid = 1;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise TRIGGER_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN rising-edge ISR\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_callback, NULL) < 0) {
