#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define SAMPLE_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_lis3dh(int handle) {
    if (i2c_write_reg(handle, LIS3DH_CTRL_REG1, 0x77) < 0) return -1;
    if (i2c_write_reg(handle, LIS3DH_CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    int rc;

    rc = i2c_read_reg(handle, LIS3DH_OUT_X_L, &x_l);
    if (rc < 0) return -1;
    rc = i2c_read_reg(handle, LIS3DH_OUT_X_L + 1, &x_h);
    if (rc < 0) return -1;
    rc = i2c_read_reg(handle, LIS3DH_OUT_X_L + 2, &y_l);
    if (rc < 0) return -1;
    rc = i2c_read_reg(handle, LIS3DH_OUT_X_L + 3, &y_h);
    if (rc < 0) return -1;
    rc = i2c_read_reg(handle, LIS3DH_OUT_X_L + 4, &z_l);
    if (rc < 0) return -1;
    rc = i2c_read_reg(handle, LIS3DH_OUT_X_L + 5, &z_h);
    if (rc < 0) return -1;

    int16_t raw_x = (int16_t)((x_h << 8) | x_l);
    int16_t raw_y = (int16_t)((y_h << 8) | y_l);
    int16_t raw_z = (int16_t)((z_h << 8) | z_l);

    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

