            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read attempt %d/%d failed, retrying...\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read acceleration after %d retries, skipping sample\n", MAX_RETRIES);
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float mag = calculate_magnitude(x, y, z);
        bool freefall = (mag < freefall_threshold);
        bool impact = (mag > impact_threshold);

        if (impact) {
            printf("Impact detected! Magnitude: %.2f g\n", mag);
            activate_buzzer(BUZZER_GPIO);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

