#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor 1 (X-axis) pins */
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

/* Motor 2 (Y-axis) pins */
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

/* 28BYJ-48: 1/64 gear ratio -> 2048 steps per revolution */
#define STEPS_PER_REV 2048.0

/* Conversion: 10 steps per mm for a 50 mm side */
#define STEPS_PER_MM 10.0

/* Step delay in microseconds (1000 us = 1 ms) */
#define STEP_DELAY_US 1000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* Signal handler for SIGINT (Ctrl+C) */
static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Drive a single step on the given motor.
 * Uses a 4-step wave drive: IN1=1, IN2=0, IN3=0, IN4=0.
 * Returns 0 on success, -1 on failure.
 */
static int motor_step(int in1, int in2, int in3, int in4) {
    int rc = gpioWrite(in1, 1);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(IN1=%d) failed: %s\n", in1, pigpio_error(rc));
        return -1;
    }
    rc = gpioWrite(in2, 0);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(IN2=%d) failed: %s\n", in2, pigpio_error(rc));
        return -1;
    }
    rc = gpioWrite(in3, 0);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(IN3=%d) failed: %s\n", in3, pigpio_error(rc));
        return -1;
    }
    rc = gpioWrite(in4, 0);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(IN4=%d) failed: %s\n", in4, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/*
 * Move a given number of steps in the specified direction.
 * Direction: +1 = forward, -1 = backward.
 * Returns 0 on success, -1 on failure.
 */
static int move_steps(int motor_pin, int steps, int direction) {
    int direction_step = (direction > 0) ? 1 : -1;
    int *pins = (int *)motor_pin;
    for (int i = 0; i < steps; i++) {
        if (motor_step(pins[0], pins[1], pins[2], pins[3]) < 0) {
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

/*
 * Draw a square with 50 mm sides.
 * Each side requires 4 steps (2 forward, 2 backward).
 * Returns 0 on success, -1 on failure.
 */
static int draw_square(void) {
    int motor1_pins[4] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4};
    int motor2_pins[4] = {MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};

    for (int side = 0; side < 4; side++) {
        if (move_steps(motor1_pins, 4, side) < 0) {
            return -1;
        }
        if (move_steps(motor2_pins, 4, side) < 0) {
            return -1;
        }
        gpioDelay(100000); /* 100 ms between sides */
    }
    return 0;
}

int main(void) {
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Set all motor GPIO pins as outputs */
    int motor1_pins[4] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4};
    int motor2_pins[4] = {MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(motor1_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode(motor1_pin=%d) failed\n", motor1_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetMode(motor2_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode(motor2_pin=%d) failed\n", motor2_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Ensure all coils are initially de-energized */
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    /* Draw the square */
    if (draw_square() < 0) {
        fprintf(stderr, "Error during square drawing\n");
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioWrite(MOTOR1_IN3, 0);
        gpioWrite(MOTOR1_IN4, 0);
        gpioWrite(MOTOR2_IN1, 0);
        gpioWrite(MOTOR2_IN2, 0);
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all coils are de-energized before exit */
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    printf("Square drawing complete.\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

