#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000

/* LIS3DH register addresses */
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

#define CTRL_REG1_VAL 0x57  /* ODR=100Hz, all axes enabled, high-resolution */
#define CTRL_REG4_VAL 0x88  /* ±2g range, 12-bit left-justified */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: got %d, expected %u\n",
                reg, len, rc, len);
        return -1;
    }
    return 0;
}

static int init_lis3dh(int handle, int address) {
    if (i2c_write_byte(handle, CTRL_REG1, CTRL_REG1_VAL) < 0) return -1;
    if (i2c_write_byte(handle, CTRL_REG4, CTRL_REG4_VAL) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, OUT_X_L, buf, 6) < 0) return -1;

    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);

    /* 12-bit left-justified, shift right 4 to get 16-bit signed value */
    *x = (float)x_raw >> 4;
    *y = (float)y_raw >> 4;
    *z = (float)z_raw >> 4;

    return 0;
}

static float calculate_g(float raw_value) {
    return raw_value / 2048.0f;
}

static void log_event(float x, float y, float z, float threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Threshold exceeded: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    }
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Threshold exceeded! Shutting down system...\n");
    fflush(stdout);
    int rc = system("sudo shutdown -h now");
    if (rc != 0) {
        fprintf(stderr, "shutdown command failed with exit code %d\n", rc);
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    float threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val < 0 || val > 2048) {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return 1;
        }
        threshold = (float)val;
    }

    if (argc > 2) {
        char *endptr;
        long addr = strtol(argv[2], &endptr, 10);
        if (*endptr != '\0' || addr < 0x08 || addr > 0x77) {
            fprintf(stderr, "Invalid I2C address: %s\n", argv[2]);
            return 1;
        }
        i2c_address = (int)addr;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(i2c_handle, i2c_address) < 0) {
        fprintf(stderr, "Failed to configure LIS3DH at 0x%02X\n", i2c_address);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring acceleration (threshold: %.2f g)...\n", threshold);
    fflush(stdout);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float g_x = calculate_g(x);
        float g_y = calculate_g(y);
        float g_z = calculate_g(z);

        if (fabsf(g_x) > threshold || fabsf(g_y) > threshold || fabsf(g_z) > threshold) {
            printf("Threshold exceeded! X=%.3f g, Y=%.3f g, Z=%.3f g\n", g_x, g_y, g_z);
            fflush(stdout);
            log_event(g_x, g_y, g_z, threshold);
            shutdown_system();
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

