#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

#define BUFFER_SIZE 5
#define LINE_FOLLOWING_THRESHOLD 5
#define ALERT_DURATION_MS 2000
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line = NULL;
static struct gpiod_line *alert_line = NULL;

static int sensor_readings[BUFFER_SIZE];
static int reading_index = 0;
static int reading_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_reading(int left, int center, int right) {
    sensor_readings[reading_index] = left;
    reading_index = (reading_index + 1) % BUFFER_SIZE;
    if (reading_count < BUFFER_SIZE) reading_count++;
}

static void cleanup(void) {
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (alert_line) gpiod_line_release(alert_line);
    if (chip) gpiod_chip_close(chip);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
            return -1;
        }
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(left_line, "line_follower") < 0 ||
        gpiod_line_request_input(center_line, "line_follower") < 0 ||
        gpiod_line_request_input(right_line, "line_follower") < 0) {
        fprintf(stderr, "Failed to request input lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(alert_line, "line_follower", 0) < 0) {
        fprintf(stderr, "Failed to request output line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Failed to read sensor: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static void move_forward(void) {
    printf("Moving forward\n");
}

static void turn_left(void) {
    printf("Turning left\n");
}

static void turn_right(void) {
    printf("Turning right\n");
}

static void stop(void) {
    printf("Stopping\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int left = read_sensor(left_line);
        int center = read_sensor(center_line);
        int right = read_sensor(right_line);

        if (left < 0 || center < 0 || right < 0) {
            usleep(POLL_INTERVAL_US);
            continue;
        }

        log_reading(left, center, right);

        if (center == 0) {
            if (reading_count >= LINE_FOLLOWING_THRESHOLD) {
                printf("Alert: No line detected for %d readings\n", LINE_FOLLOWING_THRESHOLD);
                if (gpiod_line_set_value(alert_line, 1) < 0) {
                    fprintf(stderr, "Failed to set alert HIGH: %s\n", strerror(errno));
                }
                usleep(ALERT_DURATION_MS * 1000);
                if (gpiod_line_set_value(alert_line, 0) < 0) {
                    fprintf(stderr, "Failed to set alert LOW: %s\n", strerror(errno));
                }
            }
        } else {
            reading_count = 0;
        }

        switch (center) {
            case 0:
                if (left == 0) turn_left();
                else if (right == 0) turn_right();
                else stop();
                break;
            case 1:
                stop();
                break;
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

