#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x08
#define SENSOR2_ADDR   0x09
#define RELAY_GPIO     18
#define FLOW_THRESHOLD 5.0f
#define SCALE_FACTOR   1.0f / 1500.0f
#define POLL_DELAY_US  100000
#define LOG_FILE       "flow_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_sensor(int handle)
{
    char cmd[2] = { 0x36, 0x08 };
    if (i2cWriteDevice(handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to send start-measurement command to handle %d\n", handle);
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int read_flow_rate(int handle, float *flow_out)
{
    char buf[3];
    if (i2cReadDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read 3 bytes from handle %d\n", handle);
        return -1;
    }
    if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on handle %d\n", handle);
        return -1;
    }
    int16_t raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *flow_out = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000, f1, f2);
    fflush(fp);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X\n", SENSOR1_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X\n", SENSOR2_ADDR);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(h1) != 0 || init_sensor(h2) != 0) {
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow_rate(h1, &f1) == 0);
        int ok2 = (read_flow_rate(h2, &f2) == 0);

        if (ok1 && ok2) {
            if (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
            log_flow_data(f1, f2);
        } else {
            fprintf(stderr, "Warning: sensor read error or threshold breach, skipping cycle\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

