#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s  */
#define DRY_SUPPRESS_PULSES 3      /* 3 dry polls => 600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_msg(int priority, const char *msg)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", msg);
    closelog();
}

static void log_err(const char *msg)
{
    log_msg(LOG_ERR, msg);
}

static void log_info(const char *msg)
{
    log_msg(LOG_INFO, msg);
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioWrite(%u, %u) failed", pin, level);
        log_err(buf);
        return -1;
    }
    return 0;
}

static void motor_stop(void)
{
    safe_write(MOTOR_ENA_PIN, 0);
    safe_write(MOTOR_IN1_PIN, 0);
    safe_write(MOTOR_IN2_PIN, 0);
}

static void close_window(void)
{
    log_info("Closing window...");

    if (safe_write(MOTOR_ENA_PIN, 1) < 0) return;
    if (safe_write(MOTOR_IN1_PIN, 1) < 0) return;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) return;

    gpioDelay(MOTOR_RUN_US);

    if (safe_write(MOTOR_ENA_PIN, 0) < 0) return;
    if (safe_write(MOTOR_IN1_PIN, 0) < 0) return;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) return;

    log_info("Window closed.");
}

int main(void)
