#define SERVO_PIN      18
#define BUTTON_LOCK    21
#define BUTTON_UNLOCK  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_position(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d us\n", pulse_us);
        return -1;
    }
    return 0;
}

static int lock_door(void)
{
    if (set_servo_position(LOCK_PULSE_US) != 0)
        return -1;
    printf("Door locked\n");
    return 0;
}

static int unlock_door(void)
{
    if (set_servo_position(UNLOCK_PULSE_US) != 0)
        return -1;
    printf("Door unlocked\n");
    return 0;
}

static int read_button(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for servo pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) != 0 ||
        gpioSetMode(BUTTON_UNLOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
