        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    int last_lock = -1, last_unlock = -1;

    while (g_running) {
        int lock_now = read_button(BUTTON_LOCK);
        int unlock_now = read_button(BUTTON_UNLOCK);

        if (lock_now < 0 || unlock_now < 0) {
            usleep(10000);
            continue;
        }

        if (lock_now == 0 && last_lock != 0) {
            if (lock_door() == 0) {
                last_lock = 0;
            }
        } else if (lock_now == 1 && last_lock == 1) {
            last_lock = 0;
        }

        if (unlock_now == 0 && last_unlock != 0) {
            if (unlock_door() == 0) {
                last_unlock = 0;
            }
        } else if (unlock_now == 1 && last_unlock == 1) {
            last_unlock = 0;
        }

        usleep(50000);
    }

    printf("\nShutting down...\n");
    set_servo_position(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

