#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */
#define FLOODLIGHT_ON_TIME_SEC 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, long long duration_sec)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (duration_sec >= 0) {
        fprintf(fp, "%s - %s - Duration: %lld seconds\n",
                ts, event_type, (long long)duration_sec);
    } else {
        fprintf(fp, "%s - %s\n", ts, event_type);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_floodlight(int duration_sec)
{
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, 1) failed\n");
        return -1;
    }

    if (log_event("Floodlight Activated", duration_sec) != 0) {
        fprintf(stderr, "Warning: failed to log activation event\n");
    }

    if (duration_sec > 0) {
        gpioDelay(duration_sec * 1000000);  /* pigpio microseconds */
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, 0) failed\n");
        return -1;
    }

    if (log_event("Floodlight Deactivated", duration_sec) != 0) {
        fprintf(stderr, "Warning: failed to log deactivation event\n");
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PIR pin as input */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(PIR_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(RELAY_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure floodlight is off at startup */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started.\n");
    printf("PIR sensor on GPIO %d, relay-controlled floodlight on GPIO %d.\n",
           PIR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_pir_state = gpioRead(PIR_PIN);
    if (last_pir_state < 0) {
        fprintf(stderr, "Error: initial gpioRead(PIR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Error: gpioRead(PIR_PIN) failed\n");
            break;
        }

        /* Detect rising edge (motion detected) */
        if (pir_state == 1 && last_pir_state == 0) {
            printf("Motion detected! Activating floodlight for %d seconds...\n",
                   FLOODLIGHT_ON_TIME_SEC);

            if (activate_floodlight(FLOODLIGHT_ON_TIME_SEC) != 0) {
                fprintf(stderr, "Error: floodlight activation failed\n");
                break;
            }
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: ensure floodlight is off */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nSmart Security Light System stopped.\n");
    return EXIT_SUCCESS;
}

