#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <syslog.h>
#include <syslog.h>
#include <stdarg.h>

#define SERVO_PIN 17
#define PIR_PIN  4
#define PORT 5000
#define PWM_PERIOD_US 20000  /* 50 Hz */
#define SERVO_MIN_US  500
#define SERVO_MAX_US  2000
#define SERVO_ANGLE_MAX 180
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] ",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec);
    vfprintf(log_file, fmt, args);
    fputc('\n', log_file);
    fflush(log_file);
    va_end(args);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line_p) {
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!*chip) {
        syslog(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    *line_p = gpiod_chip_get_line(*chip, SERVO_PIN);
    if (!*line_p) {
        syslog(LOG_ERR, "Failed to get GPIO%d: %s", SERVO_PIN, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }
    *line_p->request_config.consumer = "servo_control";
    if (gpiod_line_request_output(*line_p, *line_p->request_config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO%d as output: %s", SERVO_PIN, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line_p = NULL;
        return -1;
    }
    *line_p = gpiod_chip_get_line(*chip, PIR_PIN);
    if (!*line_p) {
        syslog(LOG_ERR, "Failed to get GPIO%d: %s", PIR_PIN, strerror(errno));
        gpiod_line_release(*line_p);
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line_p = NULL;
        return -1;
    }
    *line_p->request_config.consumer = "pir_sensor";
    if (gpiod_line_request_input(*line_p, *line_p->request_config) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO%d as input: %s", PIR_PIN, strerror(errno));
        gpiod_line_release(*line_p);
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line_p = NULL;
        return -1;
    }
    return 0;
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > SERVO_ANGLE_MAX) angle = SERVO_ANGLE_MAX;
    int pulse_us = SERVO_MIN_US + (angle * (SERVO_MAX_US - SERVO_MIN_US) / SERVO_ANGLE_MAX);
    gpiod_line_set_value(*line_p, 1);
    usleep(pulse_us);
    gpiod_line_set_value(*line_p, 0);
    usleep(PWM_PERIOD_US - pulse_us);
}

static int read_pir(void) {
    int val = gpiod_line_get_value(*line_p);
    if (val < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void handle_client(int client_fd) {
    char buffer[256];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        close(client_fd);
        return;
    }
    buffer[n] = '\0';
    char *token = strtok(buffer, " \r\n");
    if (!token) {
        send(client_fd, "Invalid command\n", 14, 0);
        close(client_fd);
        return;
    }
    if (strcmp(token, "SERVO") == 0) {
        token = strtok(NULL, " \r\n");
        if (!token) {
            send(client_fd, "Usage: SERVO <angle>\n", 19, 0);
            close(client_fd);
            return;
        }
        int angle = atoi(token);
        set_servo_angle(angle);
        char resp[128];
        snprintf(resp, sizeof(resp), "Servo set to %d\n", angle);
        send(client_fd, resp, strlen(resp), 0);
    } else if (strcmp(token, "PIR") == 0) {
        int pir_val = read_pir();
        if (pir_val < 0) {
            send(client_fd, "PIR read error\n", 16, 0);
        } else {
            char resp[64];
            snprintf(resp, sizeof(resp), "PIR: %d\n", pir_val);
            send(client_fd, resp, strlen(resp), 0);
        }
    } else {
        send(client_fd, "Unknown command\n", 16, 0);
    }
    close(client_fd);
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        fclose(log_file);
        closelog();
        return 1;
    }
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_p = NULL;
    if (init_gpio(&chip, &line_p) < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        fclose(log_file);
        closelog();
        return 1;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        goto cleanup;
    }
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Bind failed: %s", strerror(errno));
        goto cleanup;
    }
    if (listen(server_fd, 3) < 0) {
        syslog(LOG_ERR, "Listen failed: %s", strerror(errno));
        goto cleanup;
    }
    log_message("Server listening on port %d\n", PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            syslog(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        log_message("Connection from %s\n", client_ip);
        handle_client(client_fd);
    }
cleanup:
    if (server_fd >= 0) close(server_fd);
    if (line_p) gpiod_line_release(line_p);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    closelog();
    return 0;
}

