#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define LOG_FILE "grow_log.txt"
#define I2C_BUS 1
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x20
#define CONVERSION_DELAY_US 120000
#define SAMPLE_INTERVAL_US 2000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO %d low\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed for address 0x%02X (code %d)\n", BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    char cmd = BH1750_ONE_TIME_HIGH_RES_MODE;
    if (i2cWriteByte(i2c_handle, cmd) != 0) {
        fprintf(stderr, "Error: failed to write BH1750 command\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    char buf[2];
    int bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes, expected 2)\n", bytes);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1);
        printf("Lux: %.2f < %.2f — grow light ON\n", lux, LUX_THRESHOLD);
    } else {
        gpioWrite(RELAY_GPIO, 0);
        printf("Lux: %.2f >= %.2f — grow light OFF\n", lux, LUX_THRESHOLD);
    }
}

static void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Lux: %.2f\n", timestamp, lux);
    fflush(log_file);
    printf("%s, Lux: %.2f\n", timestamp, lux);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light controller started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float lux;
        if (read_lux(&lux) == 0) {
            log_data(lux);
            control_relay(lux);
        } else {
            fprintf(stderr, "Warning: sensor read failed, retrying next cycle\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

