#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <gpiod.h>

#define HX711_DOUT_LINE  23
#define HX711_SCK_LINE   24
#define SOLENOID_LINE    25

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE     1
#define DEFAULT_DURATION  200
#define MAX_RETRIES       3
#define READ_DELAY_US     1000
#define DOUT_TIMEOUT_US   1000000
#define POLL_INTERVAL_US  500000
#define TARE_READINGS     10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int read_hx711(struct gpiod_line *dout, struct gpiod_line *sck, int32_t *out)
{
    int32_t value = 0;
    int i;

    /* Wait for DOUT to go LOW (data ready) */
    for (i = 0; i < DOUT_TIMEOUT_US; i += 10) {
        if (gpiod_line_get_value(dout) == 0)
            break;
        sleep_us(10);
    }
    if (i >= DOUT_TIMEOUT_US) {
        syslog(LOG_ERR, "HX711 DOUT timeout (no data ready)");
        return -1;
    }

    /* Read 24 data bits MSB-first */
    for (i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "SCK high failed");
            return -1;
        }
        sleep_us(1);

        value <<= 1;
        int bit = gpiod_line_get_value(dout);
        if (bit < 0) {
            syslog(LOG_ERR, "SCK low failed");
            return -1;
        }
        if (bit)
            value |= 1;

        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "SCK low failed");
            return -1;
        }
        sleep_us(1);
    }

    /* 25th pulse: select Channel A / Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "25th SCK high failed");
        return -1;
    }
    sleep_us(1);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "25th SCK low failed");
        return -1;
    }
    sleep_us(1);

    /* Convert 24-bit two's complement to 32-bit signed */
    if (value & 0x800000)
        value |= 0xFF000000;

    *out = value;
    return 0;
}

static int average_readings(struct gpiod_line *dout, struct gpiod_line *sck, int32_t *average, int num_readings)
{
    int32_t sum = 0;
    int valid = 0;

    for (int i = 0; i < num_readings; i++) {
        int32_t val;
        if (read_hx711(dout, sck, &val) == 0) {
            sum += val;
            valid++;
        } else {
            syslog(LOG_ERR, "HX711 read failed in average");
        }
        sleep_us(READ_DELAY_US);
    }

    if (valid == 0)
        return -1;

    *average = sum / valid;
    return 0;
}

static int calculate_weight(int32_t raw, int32_t tare, int32_t scale)
{
    return (raw - tare) / scale;
}

static void control_solenoid(struct gpiod_line *sol, int duration_ms)
{
    if (gpiod_line_set_value(sol, 1) < 0)
        syslog(LOG_ERR, "Failed to set solenoid HIGH");
    sleep_us(duration_ms * 1000);
    if (gpiod_line_set_value(sol, 0) < 0)
        syslog(LOG_ERR, "Failed to set solenoid LOW");
}

static void cleanup(struct gpiod_chip *chip, struct gpiod_line *dout, struct gpiod_line *sck, struct gpiod_line *sol)
{
    if (dout) gpiod_line_release(dout);
    if (sck)  gpiod_line_release(sck);
    if (sol) gpiod_line_release(sol);
    if (chip) gpiod_line_release(chip);
    closelog();
}

int main(int argc, char *argv[])
{
    int threshold = DEFAULT_THRESHOLD;
    int scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed");
        return EXIT_FAILURE;
    }

    openlog("weight_scale", LOG_PID | LOG_CONS, LOG_USER);

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            syslog(LOG_ERR, "Threshold must be positive");
            goto cleanup;
        }
    }
    if (argc > 2) {
        scale = atoi(argv[2]);
        if (scale <= 0) {
            syslog(LOG_ERR, "Scale must be positive");
            goto cleanup;
        }
    }
    if (argc > 3) {
        duration = atoi(argv[3]);
        if (duration <= 0) {
            syslog(LOG_ERR, "Duration must be positive");
            goto cleanup;
        }
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0");
        goto cleanup;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_LINE);
    struct gpiod_line *sck  = gpiod_chip_get_line(chip, HX711_SCK_LINE);
    struct gpiod_line *sol  = gpiod_chip_get_line(chip, SOLENOID_LINE);
    if (!dout || !sck || !sol) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input");
        goto cleanup;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output");
        goto cleanup;
    }

    syslog(LOG_INFO, "Starting weight scale. Threshold=%d, Scale=%d, Duration=%dms",
           threshold, scale, duration);

    int32_t tare_sum = 0;
    int tare_ok = 0;

    for (int i = 0; i < TARE_READINGS && g_running; i++) {
        int32_t val;
        if (read_hx711(dout, sck, &val) == 0) {
            tare_sum += val;
            tare_ok++;
        } else {
            syslog(LOG_ERR, "Tare read failed");
        }
        sleep_us(READ_DELAY_US);
    }

    if (!tare_ok) {
        syslog(LOG_ERR, "Tare failed after %d readings", TARE_READINGS);
        goto cleanup;
    }

    int32_t tare_val = tare_sum / TARE_READINGS;
    syslog(LOG_INFO, "Tare offset: %d", tare_val);

    while (g_running) {
        int32_t raw;
        if (average_readings(dout, sck, &raw, TARE_READINGS) != 0) {
            syslog(LOG_ERR, "Average read failed, retrying...");
            sleep_us(POLL_INTERVAL_US);
            continue;
        }

        int32_t weight = calculate_weight(raw, tare_val, scale);
        float grams = (float)weight;

        if (grams > threshold) {
            syslog(LOG_INFO, "Weight %.2f g exceeds threshold %d g, activating solenoid",
                   grams, threshold);
            control_solenoid(sol, duration);
        }

        sleep_us(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (sol) gpiod_line_set_value(sol, 0);
    cleanup(chip, dout, sck, sol);
    return ret;
}

