#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_KEEPALIVE_INTERVAL 60
#define MQTT_CONNECT_TIMEOUT_MS 1000
#define MQTT_RECONNECT_DELAY_MS 5000
#define GPIO_RELAY 17

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *level, const char *message) {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    syslog(level, "%s", message);
    closelog();
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT connected to broker");
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to subscribe to topic");
        } else {
            log_message(LOG_INFO, "Subscribed to topic");
        }
    } else {
        log_message(LOG_ERR, "MQTT connection failed: ");
        char errbuf[128];
        mosquitto_connack_string(result, errbuf, sizeof(errbuf));
        log_message(LOG_ERR, errbuf);
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        log_message(LOG_ERR, "MQTT unexpected disconnect: ");
        char errbuf[128];
        mosquitto_connack_string(result, errbuf, sizeof(errbuf));
        log_message(LOG_ERR, errbuf);
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        if (strcmp(payload, "ON") == 0) {
            if (gpioWrite(GPIO_RELAY, 1) != 0) {
                log_message(LOG_ERR, "Failed to set relay HIGH");
            } else {
                log_message(LOG_INFO, "Relay turned ON");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (gpioWrite(GPIO_RELAY, 0) != 0) {
                log_message(LOG_ERR, "Failed to set relay LOW");
            } else {
                log_message(LOG_INFO, "Relay turned OFF");
            }
        } else {
            log_message(LOG_ERR, "Invalid command received: %s", payload);
        }
    } else {
        log_message(LOG_WARNING, "Empty message received");
    }
}

static void on_error(struct mosquitto *m, void *userdata, const char *msg) {
    (void)m;
    (void)userdata;
    log_message(LOG_ERR, msg);
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to install signal handlers");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set GPIO17 as output");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_RELAY, 0) != 0) {
        log_message(LOG_ERR, "Failed to initialize GPIO17 LOW");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_error_callback_set(mosq, on_error);

    int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CONNECT_TIMEOUT_MS);
    if (rc != MOSQ_ERR_SUCCESS) {
        char errbuf[128];
        mosquitto_connack_string(rc, errbuf, sizeof(errbuf));
        log_message(LOG_ERR, errbuf);
        cleanup();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to start mosquitto_loop_start");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        sleep(1);
        if (!running) break;

        int rc = mosquitto_loop_read(mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            if (rc == MOSQ_ERR_CONN_LOST) {
                log_message(LOG_WARNING, "MQTT connection lost, attempting reconnect");
                sleep(MQTT_RECONNECT_DELAY_MS / 1000);
                rc = mosquitto_reconnect(mosq);
                if (rc != MOSQ_ERR_SUCCESS) {
                    log_message(LOG_ERR, "Reconnect failed: ");
                    char errbuf[128];
                    mosquitto_connack_string(rc, errbuf, sizeof(errbuf));
                    log_message(LOG_ERR, errbuf);
                }
