#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>
#include <stdatomic.h>

/* Motor A */
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_A_PWM 19
#define MOTOR_A_DIR 20

/* Motor B */
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define MOTOR_B_PWM 24
#define MOTOR_B_DIR 25

/* Encoder A */
#define ENCODER_A_A 4
#define ENCODER_A_B 5

/* Encoder B */
#define ENCODER_B_A 6
#define ENCODER_B_B 12

/* Constants */
#define TICKS_PER_REV 64
#define PWM_FREQ 10000
#define PWM_RANGE 255
#define PI_CONTROLLER_PERIOD_US 100000  /* 100 ms */
#define STALL_TIMEOUT_S 2
#define KP 0.5
#define KI 0.05

/* Global state */
static volatile int encoder_a_count = 0;
static volatile int encoder_b_count = 0;
static volatile int running = 1;
static atomic_int encoder_a_prev_tick = 0;
static atomic_int encoder_b_prev_tick = 0;
static double integral_a = 0.0;
static double integral_b = 0.0;
static double last_error_a = 0.0;
static double last_error_b = 0.0;

/* Function prototypes */
static void encoder_isr(int gpio, int level, uint32_t tick, void *user);
static void motor_a_forward(void);
static void motor_a_reverse(void);
static void motor_b_forward(void);
static void motor_b_reverse(void);
static void motor_stop(void);
static void set_motor_speed(int motor, int speed);
static void set_motor_direction(int motor, int direction);
static void set_pwm_duty(int gpio, int duty);
static void pid_update(double setpoint, double actual, double *integral, double *prev_error, double dt);
static void signal_handler(int sig);

/* Encoder ISR: count rising edges (one per encoder tick) */
static void encoder_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    atomic_store(&encoder_a_count, encoder_a_count + 1);
    atomic_store(&encoder_b_count, encoder_b_count + 1);
}

/* Motor control functions */
static void motor_a_forward(void) {
    gpioWrite(MOTOR_A_IN1, 1);
    gpioWrite(MOTOR_A_IN2, 0);
    set_motor_speed(1, 100);
}

static void motor_a_reverse(void) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 1);
    set_motor_speed(1, -100);
}

static void motor_b_forward(void) {
    gpioWrite(MOTOR_B_IN3, 1);
    gpioWrite(MOTOR_B_IN4, 0);
    set_motor_speed(2, 100);
}

static void motor_b_reverse(void) {
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 1);
    set_motor_speed(2, -100);
}

static void motor_stop(void) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    set_motor_speed(3, 0);
}

static void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        set_pwm_duty(MOTOR_A_PWM, speed);
    } else if (motor == 2) {
        set_pwm_duty(MOTOR_B_PWM, speed);
    }
}

static void set_motor_direction(int motor, int direction) {
    if (motor == 1) {
        if (direction > 0) {
            set_motor_speed(motor, 100);
        } else if (direction < 0) {
            set_motor_speed(motor, -100);
        } else {
            set_motor_speed(motor, 0);
        }
    } else if (motor == 2) {
        if (direction > 0) {
            set_motor_speed(motor, 100);
        } else if (direction < 0) {
            set_motor_speed(motor, -100);
        } else {
            set_motor_speed(motor, 0);
        }
    }
}

static void set_pwm_duty(int gpio, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(gpio, duty);
}

/* PI controller with anti-windup and clamping */
static void pid_update(double setpoint, double actual, double *integral, double *prev_error, double dt) {
    double error = setpoint - actual;
    *integral += error * dt;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;
    double derivative = (error - *prev_error) / dt;
    double output = KP * error + KI * (*integral) + derivative;
    *prev_error = error;
    if (output < 0.0) output = 0.0;
    if (output > PWM_RANGE) output = PWM_RANGE;
    set_pwm_duty(MOTOR_A_PWM, (int)output);
    set_pwm_duty(MOTOR_B_PWM, (int)output);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set motor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set encoder pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register encoder ISRs */
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register encoder ISRs.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ);
    gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE);

    /* Set initial encoder counts to zero */
    atomic_store(&encoder_a_count, 0);
    atomic_store(&encoder_b_count, 0);

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Main control loop */
    double setpoint = 50.0;
    double actual_a = 0.0, actual_b = 0.0;
    double dt = 0.01;
    struct timespec last_print;
    clock_gettime(CLOCK_MONOTONIC, &last_print);

    while (running) {
        /* Read encoder counts */
        int a_count = atomic_load(&encoder_a_count);
        int b_count = atomic_load(&encoder_b_count);

        /* Calculate RPM */
        double rpm_a = (double)a_count * 60.0 / TICKS_PER_REV;
        double rpm_b = (double)b_count * 60.0 / TICKS_PER_REV;

        /* Update PI controllers */
        pid_update(setpoint, rpm_a, &integral_a, &last_error_a, dt);
        pid_update(setpoint, rpm_b, &integral_b, &last_error_b, dt);

        /* Print RPM and PWM duty */
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - last_print.tv_sec) + (now.tv_nsec - last_print.tv_nsec) / 1e9;
        if (elapsed >= 1.0) {
            printf("Motor A: RPM=%.2f, PWM=%d, Motor B: RPM=%.2f, PWM=%d\n", rpm_a, atomic_load(MOTOR_A_PWM), rpm_b, atomic_load(MOTOR_B_PWM));
            fflush(stdout);
            last_print = now;
        }

        /* Check for encoder stall */
        if (a_count == 0) {
            double time_since_last_edge = (now.tv_sec - last_print.tv_sec) + (now.tv_nsec - last_print.tv_nsec) / 1e9;
            if (time_since_last_edge > STALL_TIMEOUT_S) {
                fprintf(stderr, "Warning: Encoder A stalled for %.1f seconds (no ticks)\n", time_since_last_edge);
            }
        }
        if (b_count == 0) {
            double time_since_last_edge = (now.tv_sec - last_print.tv_sec) + (now.tv_nsec - last_print.tv_nsec) / 1e9;
            if (time_since_last_edge > STALL_TIMEOUT_S) {
                fprintf(stderr, "Warning: Encoder B stalled for %.1f seconds (no ticks)\n", time_since_last_edge);
            }
        }

        /* Update motor directions based on RPM */
        if (rpm_a > setpoint) {
            motor_a_forward();
        } else if (rpm_a < setpoint) {
            motor_a_reverse();
        }
        if (rpm_b > setpoint) {
            motor_b_forward();
        } else if (rpm_b < setpoint) {
            motor_b_reverse();
        }

        /* Sleep for control period */
        gpioDelay(PI_CONTROLLER_PERIOD_US);
    }

    /* Cleanup */
    motor_stop();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

