#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define DUSK_LUX 50.0
#define DAWN_LUX 200.0
#define LOG_FILE "chicken_coop_log.txt"
#define POLL_INTERVAL_SEC 5
#define BH1750_CONV_DELAY_US 180000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize relay GPIO %d to LOW.\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux_out) {
    char cmd[2] = {0x21, 0x00};
    char buf[2];
    int rc;

    rc = i2cWriteDevice(i2c_handle, cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C write failed (code %d).\n", rc);
        return -1;
    }

    gpioDelay(BH1750_CONV_DELAY_US);

    rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C read failed (code %d).\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "Error: I2C read returned %d bytes, expected 2.\n", rc);
        return -1;
    }

    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int control_relay(int on) {
    int rc = gpioWrite(RELAY_GPIO, on ? 1 : 0);
    if (rc != 0) {
        fprintf(stderr, "Error: Failed to write relay GPIO %d (code %d).\n", RELAY_GPIO, rc);
        return -1;
    }
    return 0;
}

static void log_event(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (log_file) {
        fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_relay_state = -1;

    while (running) {
        float lux;
        if (read_bh1750(&lux) != 0) {
            fprintf(stderr, "Warning: Sensor read failed, turning off relay for safety.\n");
            if (relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }
            gpioDelay(5000000);
            continue;
        }

        if (lux < DAWN_LUX) {
            relay_state = 0;
        } else if (lux > DUSK_LUX) {
            relay_state = 1;
        }

        if (relay_state != last_relay_state) {
            if (control_relay(relay_state) == 0) {
                log_event(lux, relay_state);
                last_relay_state = relay_state;
            }
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

