#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(stdout, "%s - Relay: %s\n", timestamp, state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf failed\n");
        return -1;
    }
    fflush(stdout);
    return 0;
}

int main(void) {
    int relay_state = 0;
    int last_touch_state = 0;
    int stabilized = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay controller started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Failed to read touch sensor on GPIO %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 1 && !last_touch_state) {
            if (stabilized) {
                if (gpioWrite(RELAY_PIN, !relay_state) == 0) {
                    relay_state = !relay_state;
                    if (log_state(relay_state) != 0) {
                        fprintf(stderr, "Failed to log state change\n");
                    }
                } else {
                    fprintf(stderr, "Failed to write relay on GPIO %d\n", RELAY_PIN);
                }
            } else {
                stabilized = 1;
                last_touch_state = 1;
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            }
        } else if (touch_state == 0) {
            stabilized = 0;
            last_touch_state = 0;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Relay turned off. Exiting.\n");
    return EXIT_SUCCESS;
}

