}

/* ------------------------------------------------------------------ */
/* ISR callback — runs in pigpio thread context                        */
/* ------------------------------------------------------------------ */
static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    pthread_mutex_lock(&pulse_mutex);
    /* pigpio already handles the 1-second debounce timeout; we just
       increment the counter atomically. */
    int pulses = 0;
    pthread_mutex_unlock(&pulse_mutex);

    if (level == 1) {
        pulses++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute LPM from the current pulse count                          */
/* ------------------------------------------------------------------ */
static double calculate_lpm(int pulses)
{
    double pulses_per_min = (double)pulses / PULSES_PER_LITER / 60.0;
    return pulses_per_min;
}

/* ------------------------------------------------------------------ */
/* Log a message with a timestamp                                    */
/* ------------------------------------------------------------------ */
static void log_message(const char *message)
{
    if (log_file == NULL)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

