                SOLENOID_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with solenoid open (safe state) */
    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to initialise solenoid state.\n");
        cleanup();
        return EXIT_FAILURE;
    }

