    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0,
                         flow_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n",
                FLOW_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    /* ---- Main loop ---- */
    int solenoid_closed = 0;   /* 0 = open, 1 = closed */
    int last_solenoid = 1;     /* 1 = closed (safe) */

    while (running) {
        int pulses = 0;
        int ret;

