#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define SERVO_MIN_PULSEWIDTH 1000
#define SERVO_MAX_PULSEWIDTH 2000
#define SERVO_STEPS_PER_REVOLUTION 255
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_STEP_DELAY_US 20
#define SERVO_SETTLE_DELAY_US 1000000
#define HX711_TIMEOUT_US 1000
#define READ_INTERVAL_US 100000
#define SERVO_STEP_DELAY_US 20
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int server_ip = "127.0.0.1";
static int server_port = 12345;
static float calibration_factor = 1.0f;

typedef struct {
    float target_weight;
    float actual_weight;
    int error_code;
    char error_message[256];
} dispensing_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, float *calibration_factor, char *server_ip, char *server_port) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s'. Using defaults.\n", filename);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "\n");
        if (key && value) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, sizeof(server_ip) - 1);
                server_ip[sizeof(server_ip) - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            }
        }
    }
    fclose(fp);

    if (calibration_factor <= 0.0f) calibration_factor = 1.0f;

    printf("Calibration factor: %.2f\n", calibration_factor);
    printf("Server IP: %s\n", server_ip);
    printf("Server Port: %d\n", server_port);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set DATA pin mode.\n");
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set SCK pin mode.\n");
        return -1;
    }
    if (gpioSetPullUpDown(HX711_DATA_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on DATA pin.\n");
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set SERVO pin mode.\n");
        return -1;
    }
    if (gpioSetPWMrange(SERVO_PIN, SERVO_MAX_PULSEWIDTH) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on SERVO pin.\n");
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO_PIN, 1000) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on SERVO pin.\n");
        return -1;
    }
    if (gpioPWM(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize SERVO to 0 PWM.\n");
        return -1;
    }
    return 0;
}

static int read_hx711(int *raw_value) {
    int timeout_count = 0;
    int data_value;

    while (1) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            fprintf(stderr, "Error: Failed to set SCK high.\n");
            return -1;
        }
        gpioDelay(1);

        data_value = gpioRead(HX711_DATA_PIN);
        if (data_value < 0) {
            fprintf(stderr, "Error: Failed to read DATA pin.\n");
            return -1;
        }

        if (data_value == 1) {
            timeout_count++;
            if (timeout_count >= HX711_TIMEOUT_US) {
                fprintf(stderr, "Error: HX711 timeout (sensor absent or not ready).\n");
                return -1;
            }
            gpioDelay(1);
            continue;
        }

        if (data_value == 0) {
            timeout_count = 0;
            break;
        }

        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            fprintf(stderr, "Error: Failed to set SCK low.\n");
            return -1;
        }
        gpioDelay(1);
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            fprintf(stderr, "Error: Failed to set SCK high.\n");
            return -1;
        }
        gpioDelay(1);

        value <<= 1;
        data_value = gpioRead(HX711_DATA_PIN);
        if (data_value < 0) {
            fprintf(stderr, "Error: Failed to read DATA pin.\n");
            return -1;
        }
        if (data_value) {
            value |= 1;
        }

        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            fprintf(stderr, "Error: Failed to set SCK low.\n");
            return -1;
        }
        gpioDelay(1);
    }

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_value = value;
    return 0;
}

static float calibrate_hx711(int *raw_value) {
    float sum = 0.0f;
    int num_samples = 100;
    for (int i = 0; i < num_samples; i++) {
        if (read_hx711(raw_value) != 0) {
            return -1.0f;
        }
        sum += (float)*raw_value;
        gpioDelay(100000);
    }
    return sum / num_samples;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulsewidth = SERVO_MIN_PULSEWIDTH + (int)(((float)angle / 180.0f) * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH));
    if (gpioPWM(SERVO_PIN, pulsewidth) < 0) {
        fprintf(stderr, "Error: Failed to set servo PWM.\n");
        return -1;
    }
    return 0;
}

static int dispense_ingredient(float target_weight, float actual_weight) {
    float error = target_weight - actual_weight;
    int angle = (int)(error * calibration_factor);
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    for (int i = 0; i < 1000; i++) {
        if (set_servo_angle(angle) != 0) {
            return -1;
        }
        gpioDelay(SERVO_STEP_DELAY_US);
    }
    return 0;
}

static int log_dispensing_event(float target_weight, float actual_weight, int error_code, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_code\": %d, \"error_message\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_code, error_message);

    fclose(fp);
    return 0;
}

static int handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error: recv failed");
        return -1;
    }
    if (bytes_received == 0) {
        printf("Client disconnected.\n");
        return 0;
    }
    buffer[bytes_received] = '\0';

    char *target_weight_str = strstr(buffer, "target_weight:");
    if (!target_weight_str) {
        fprintf(stderr, "Error: Missing target_weight in request.\n");
        return -1;
    }
    target_weight_str += strlen("target_weight:");
    target_weight_str[strlen(target_weight_str) - 1] = '\0';
    float target_weight = strtof(target_weight_str, NULL);
    if (target_weight <= 0.0f) {
        fprintf(stderr, "Error: Invalid target weight: %s\n", target_weight_str);
        return -1;
    }

    float actual_weight = 0.0f;
    int retries = 0;
    int read_ok = 0;
    while (retries < MAX_RETRIES && !read_ok) {
        if (read_hx711(&actual_weight) == 0) {
            read_ok = 1;
        } else {
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Warning: HX711 read failed, retry %d/%d\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }
    }
    if (!read_ok) {
        fprintf(stderr, "Error: HX711 read failed after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    if (dispense_ingredient(target_weight, actual_weight) != 0) {
        fprintf(stderr, "Error: Servo control failed.\n");
        return -1;
    }

    dispensing_data_t data;
    data.actual_weight = actual_weight;
    data.error_code = 0;
    snprintf(data.error_message, sizeof(data.error_message), "None");

    if (log_dispensing_event(target_weight, actual_weight, 0, data.error_message) != 0) {
        fprintf(stderr, "Error: Failed to log dispensing event.\n");
    }

    char response[256];
    snprintf(response, sizeof(response), "Actual weight: %.2f g\n", actual_weight);
    if (send(client_socket, response, strlen(response), 0) < 0) {
        perror("Error: send failed");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_config(CONFIG_FILE, &calibration_factor, &server_ip, &server_port) != 0) {
        fprintf(stderr, "Warning: Using default configuration.\n");
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Error: socket failed");
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("Error: setsockopt failed");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(server_ip);
    server_address.sin_port = htons((uint16_t)server_port);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error: bind failed");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    if (listen(server_socket, 3) < 0) {
        perror("Error: listen failed");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);

    while (running) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            if (running) perror("Error: accept failed");
            continue;
        }

        printf("Client connected.\n");
        if (handle_client(client_socket) != 0) {
            fprintf(stderr, "Error: Failed to handle client.\n");
        }

        close(client_socket);
    }

    printf("Shutting down...\n");
    gpioPWM(SERVO_PIN, 0);
    gpioTerminate();
    close(server_socket);
    return 0;
}

