        return 1;
    }

    printf("Touch-controlled desk lamp started. Touch GPIO %d to toggle relay on GPIO %d.\n", TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Debounce: %d ms. Press Ctrl+C to exit.\n", debounce_ms);

    int last_touch_state = 0;
    int stable_touch_state = 0;

