#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PULSE_MIN 500
#define PULSE_MAX 2500
#define PULSE_ANGLE_MIN 900
#define PULSE_ANGLE_MAX 2100
#define STEP 10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int restore_terminal(void) {
    struct termios oldt, newt;
    if (tcgetattr(STDIN_FILENO, &oldt) != 0) {
        perror("tcgetattr");
        return -1;
    }
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &newt) != 0) {
        perror("tcsetattr");
        return -1;
    }
    tcflush(STDIN_FILENO, TCIFLUSH);
    return 0;
}

static int restore_terminal_raw(void) {
    struct termios oldt, newt;
    if (tcgetattr(STDIN_FILENO, &oldt) != 0) {
        perror("tcgetattr");
        return -1;
    }
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    newt.c_cc[VMIN] = 0;
    newt.c_cc[VTIME] = 1;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &newt) != 0) {
        perror("tcsetattr");
        return -1;
    }
    tcflush(STDIN_FILENO, TCIFLUSH);
    return 0;
}

static int angle_to_pulse(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return PULSE_ANGLE_MIN + (int)((float)angle / 180.0f * (float)(PULSE_MAX - PULSE_MIN));
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        perror("signal");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (restore_terminal() != 0) {
        fprintf(stderr, "Warning: could not restore terminal to raw mode\n");
