#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_rpm(FILE *fp, double rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as input with internal pull-up bias.
     * The A3144 open-collector output requires a pull-up to VCC. */
    if (gpiod_line_request_input_flags(line, "conveyor-rpm",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring conveyor-belt RPM on GPIO %d (A3144 Hall sensor). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    int pulse_count = 0;
    struct timespec last_event = {0, 0};
    struct timespec now;

    while (program_running) {
        /* Block up to 1 s for a single edge event. */
        int wait_ret = gpiod_line_event_wait(line, &(struct timespec){1, 0});
        if (wait_ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (wait_ret == 0) {
            continue; /* Timeout, no event */
        }

        /* Drain any queued events to avoid losing pulses. */
        while (gpiod_line_event_wait(line, &(struct timespec){0, 0}) > 0) {
            /* discard */
        }

        if (gpiod_line_event_read(line, NULL) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Debounce: ignore events within DEBOUNCE_MS of the last accepted event. */
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - last_event.tv_sec) * 1000L +
                          (now.tv_nsec - last_event.tv_nsec) / 1000000L;

        if (elapsed_ms < DEBOUNCE_MS) {
            continue;
        }
        last_event = now;

        pulse_count++;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Pulse count: %d\n", pulse_count);
        double rpm = (double)pulse_count / SAMPLE_INTERVAL_S * 60.0;
        printf("RPM: %.2f\n", rpm);
    }

    return ret;
}

