#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10000000 /* 10 s */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    int rc = gpioWrite(pin, level);
    if (rc != 0) {
        fprintf(stderr, "gpioWrite(pin=%u, level=%u) failed: %s\n",
                pin, level, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int rc = gpioRead(pin);
    if (rc == PI_BAD_GPIO) {
        fprintf(stderr, "gpioRead(pin=%u) failed: PI_BAD_GPIO\n", pin);
        return -1;
    }
    return rc;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN=%d, PI_INPUT) failed\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN=%d, PI_OUTPUT) failed\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in the OFF state */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    uint32_t last_touch_tick = 0;
    int relay_on = 0;

    while (running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (touch == 1) {
            uint32_t now = gpioTick();
            if (relay_on) {
                if (now - last_touch_tick > FAILSAFE_TIMEOUT) {
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        gpioTerminate();
                        return EXIT_FAILURE;
                    }
                    relay_on = 0;
                    relay_state = 0;
                    last_touch_tick = now;
                }
            } else {
                relay_on = 1;
                relay_state = 1;
                last_touch_tick = now;
                if (safe_write(RELAY_PIN, relay_state) != 0) {
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    if (relay_on) {
        if (safe_write(RELAY_PIN, 0) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        relay_on = 0;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

