static FILE *log_file = NULL;

static void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pulse_count++;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set FLOW_SENSOR_GPIO %d as input.\n", FLOW_SENSOR_GPIO);
        return -1;
    }

    if (gpioSetMode(VALVE_ENABLE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set VALVE_ENABLE_GPIO %d as output.\n", VALVE_ENABLE_GPIO);
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set VALVE_PWM_GPIO %d as output.\n", VALVE_PWM_GPIO);
        return -1;
    }

    if (gpioWrite(VALVE_ENABLE_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize VALVE_ENABLE_GPIO low.\n");
        return -1;
    }

    if (gpioSetPWMrange(VALVE_PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", VALVE_PWM_GPIO);
        return -1;
    }

    if (gpioPWM(VALVE_PWM_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle to 0 on GPIO %d.\n", VALVE_PWM_GPIO);
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for FLOW_SENSOR_GPIO %d.\n", FLOW_SENSOR_GPIO);
        return -1;
    }

    return 0;
}

static void control_valve(double target_flow_rate) {
    double error = target_flow_rate - (double)pulse_count / PULSES_PER_LITER;
    int duty_cycle = (int)(KP * error);

    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(VALVE_PWM_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle to %d on GPIO %d.\n", duty_cycle, VALVE_PWM_GPIO);
    }
}

static void log_data(double flow_rate, int valve_position) {
    if (log_file == NULL) return;

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file);
}

