    if (argc != 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate_L_min>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Error: target flow rate must be positive.\n");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open flow_log.csv for appending.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp_ms,flow_rate_L_min,valve_position\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        if (!running) break;

        int pulses = pulse_count;
        pulse_count = 0;

        double flow_rate = (double)pulses / PULSES_PER_LITER;
        int valve_position = 0;

        control_valve(target_flow_rate);

        log_data(flow_rate, valve_position);
        printf("Flow rate: %.2f L/min, Valve position: %d\n", flow_rate, valve_position);
    }

    printf("\nShutting down...\n");

    if (gpioPWM(VALVE_PWM_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to set PWM to 0 during shutdown.\n");
    }

    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioWrite(VALVE_ENABLE_GPIO, 0);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    printf("Flow control system terminated.\n");
    return EXIT_SUCCESS;
}

