#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pthread.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define MOTOR1_A 5
#define MOTOR1_B 6
#define MOTOR2_A 26
#define MOTOR2_B 19

#define PWM_FREQ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ)
#define SAMPLE_PERIOD_US 10000
#define ENCODER_PULSES_PER_REV 600
#define TARGET_RPM 60
#define KP 1.0
#define KI 0.1
#define KD 0.01

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor1_ena = NULL;
static struct gpiod_line *motor1_in1 = NULL;
static struct gpiod_line *motor1_in2 = NULL;
static struct gpiod_line *motor2_ena = NULL;
static struct gpiod_line *motor2_in3 = NULL;
static struct gpiod_line *motor2_in4 = NULL;
static struct gpiod_line *motor1_a = NULL;
static struct gpiod_line *motor1_b = NULL;
static struct gpiod_line *motor2_a = NULL;
static struct gpiod_line *motor2_b = NULL;

static double motor1_rpm = 0.0;
static double motor2_rpm = 0.0;
static double motor1_error = 0.0;
static double motor2_error = 0.0;
static double motor1_integral = 0.0;
static double motor2_integral = 0.0;
static double motor1_previous_integral = 0.0;
static double motor2_previous_integral = 0.0;
static double motor1_previous_output = 0.0;
static double motor2_previous_output = 0.0;
static double motor1_previous_error = 0.0;
static double motor2_previous_error = 0.0;
static pthread_mutex_t motor1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t motor2_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (motor1_a) gpiod_line_release(motor1_a);
    if (motor1_b) gpiod_line_release(motor1_b);
    if (motor1_a) gpiod_line_release(motor1_a);
    if (motor1_b) gpiod_line_release(motor1_b);
    if (motor1_in1) gpiod_line_release(motor1_in1);
    if (motor1_in2) gpiod_line_release(motor1_in2);
    if (motor1_in1) gpiod_line_release(motor1_in1);
    if (motor1_in2) gpiod_line_release(motor1_in2);
    if (motor1_ena) gpiod_line_release(motor1_ena);
    if (motor2_a) gpiod_line_release(motor2_a);
    if (motor2_b) gpiod_line_release(motor2_b);
    if (motor2_in3) gpiod_line_release(motor2_in3);
    if (motor2_in4) gpiod_line_release(motor2_in4);
    if (motor2_ena) gpiod_line_release(motor2_ena);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static void motor_stop(void) {
    if (motor1_in1) gpiod_line_set_value(motor1_in1, 0);
    if (motor1_in2) gpiod_line_set_value(motor1_in2, 0);
    if (motor2_in3) gpiod_line_set_value(motor2_in3, 0);
    if (motor2_in4) gpiod_line_set_value(motor2_in4, 0);
}

static void motor_set_pwm(struct gpiod_line *line, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int on_us = (duty_percent * PWM_PERIOD_US) / 100;
    int off_us = PWM_PERIOD_US - on_us;
    if (line) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting line high\n");
        }
        usleep(on_us);
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting line low\n");
        }
        usleep(off_us);
    }
}

static void *encoder_thread(void *arg) {
    (void)arg;
    struct gpiod_line *a_line = NULL;
    struct gpiod_line *b_line = NULL;
    struct timespec last_time, current_time;
    int count = 0;
    int direction = 0;
    double rpm = 0.0;

    a_line = gpiod_line_get_line(gpiod_chip_get_by_name(chip, "gpiochip4")->lines[1]);
    b_line = gpiod_line_get_line(gpiod_chip_get_by_name(chip, "gpiochip4")->lines[2]);
    if (!a_line || !b_line) {
        fprintf(stderr, "Error getting encoder A/B lines\n");
        return NULL;
    }

    if (gpiod_line_request_both_edges_events(a_line, "encoder_a") < 0) {
        fprintf(stderr, "Error requesting encoder A events\n");
        return NULL;
    }
    if (gpiod_line_request_both_edges_events(b_line, "encoder_b") < 0) {
        fprintf(stderr, "Error requesting encoder B events\n");
        return NULL;
    }

    clock_gettime(CLOCK_MONOTONIC, &last_time);
    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - last_time.tv_sec) + (now.tv_nsec - last_time.tv_nsec) / 1e9;
        if (elapsed >= 1.0) {
            last_time = now;
            count = 0;
        }
        int val = gpiod_line_get_value(a_line);
        if (val < 0) {
            fprintf(stderr, "Error reading encoder A\n");
            continue;
        }
        int val2 = gpiod_line_get_value(b_line);
        if (val2 < 0) {
            fprintf(stderr, "Error reading encoder B\n");
            continue;
        }
        if (val == 1 && val2 == 0) {
            direction = 1;
        } else if (val == 0 && val2 == 1) {
            direction = -1;
        }
        if (direction != 0) {
            count++;
        }
        usleep(100);
    }
    pthread_exit(NULL);
}

static double calculate_pid(double target, double actual, double *integral, double *previous_integral, double *previous_error, double dt) {
    double error = target - actual;
    *integral += error * dt;
    if (*integral > 1000.0) *integral = 1000.0;
    if (*integral < -1000.0) *integral = -1000.0;
    double derivative = (error - *previous_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    *previous_integral = *integral;
    *previous_output = output;
    return output;
}

static void log_data(double rpm1, double rpm2, double pid1, double pid2, double out1, double out2) {
    if (!log_file) return;
    fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", rpm1, rpm2, pid1, pid2, out1, out2);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4\n");
        return 1;
    }

    motor1_a = gpiod_chip_get_line(chip, MOTOR1_A);
    motor1_b = gpiod_chip_get_line(chip, MOTOR1_B);
    motor1_ena = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1 = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2 = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor2_a = gpiod_chip_get_line(chip, MOTOR2_A);
    motor2_b = gpiod_chip_get_line(chip, MOTOR2_B);
    motor2_ena = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3 = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4 = gpiod_chip_get_line(chip, MOTOR2_IN4);

    if (!motor1_a || !motor1_b || !motor1_ena || !motor1_in1 || !motor1_in2 || !motor2_a || !motor2_b || !motor2_ena || !motor2_in3 || !motor2_in4) {
        fprintf(stderr, "Error getting GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(motor1_ena, "motor1_ena", 0) < 0 ||
        gpiod_line_request_output(motor1_in1, "motor1_in1", 0) < 0 ||
        gpiod_line_request_output(motor1_in2, "motor1_in2", 0) < 0 ||
        gpiod_line_request_output(motor2_ena, "motor2_ena", 0) < 0 ||
        gpiod_line_request_output(motor2_in3, "motor2_in3", 0) < 0 ||
        gpiod_line_request_output(motor2_in4, "motor2_in4", 0) < 0) {
        fprintf(stderr, "Error requesting output lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_both_edges_events(motor1_a, "motor1_a") < 0 ||
        gpiod_line_request_both_edges_events(motor1_b, "motor1_b") < 0 ||
        gpiod_line_request_both_edges_events(motor2_a, "motor2_a") < 0 ||
        gpiod_line_request_both_edges_events(motor2_b, "motor2_b") < 0) {
        fprintf(stderr, "Error requesting encoder A/B lines\n");
        cleanup();
        return 1;
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }
    fprintf(log_file, "RPM1,RPM2,PID1,PID2,Output1,Output2\n");

    pthread_t motor1_thread, motor2_thread;
    if (pthread_create(&motor1_thread, NULL, encoder_thread, NULL) != 0 ||
        pthread_create(&motor2_thread, NULL, encoder_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder threads\n");
        cleanup();
        return 1;
    }

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double dt = (now.tv_sec - last_time.tv_sec) + (now.tv_nsec - last_time.tv_nsec) / 1e9;
        last_time = now;

        double pid1 = calculate_pid(TARGET_RPM, motor1_rpm, &motor1_integral, &motor1_previous_integral, &motor1_previous_error, dt);
        double pid2 = calculate_pid(TARGET_RPM, motor2_rpm, &motor2_integral, &motor2_previous_integral, &motor2_previous_error, dt);

        double motor1_out = pid1;
        double motor2_out = pid2;

        pthread_mutex_lock(&motor1_mutex);
        motor1_rpm = (motor1_rpm + (pid1 - motor1_previous_output) * dt) / 60.0;
        motor1_rpm = (motor1_rpm + 60.0) / 60.0;
        motor1_previous_output = pid1;
        motor1_previous_integral = motor1_integral;
        motor1_previous_error = pid1;
        pthread_mutex_unlock(&motor1_mutex);

        pthread_mutex_lock(&motor2_mutex);
        motor2_rpm = (motor2_rpm + (pid2 - motor2_previous_output) * dt) / 60.0;
        motor2_rpm = (motor2_rpm + 60.0) / 60.0;
        motor2_previous_output = pid2;
        motor2_previous_integral = motor2_integral;
        motor2_previous_error = pid2;
        pthread_mutex_unlock(&motor2_mutex);

        motor_set_pwm(motor1_in1, (int)(motor1_out * 1000000.0 / 100.0));
        motor_set_pwm(motor1_in2, (int)(1000000.0 - motor1_out * 1000000.0 / 100.0));
        motor_set_pwm(motor2_in3, (int)(motor2_out * 1000000.0 / 100.0));
        motor_set_pwm(motor2_in4, (int)(1000000.0 - motor2_out * 1000000.0 / 100.0));

        log_data(motor1_rpm, motor2_rpm, pid1, pid2, motor1_out, motor2_out);
    }

    pthread_join(motor1_thread, NULL);
    pthread_join(motor2_thread, NULL);
    motor_stop();
    cleanup();
    return 0;
}

