#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

/* MPR121 Register Addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %s\n", value, reg, strerror(errno));
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpr121_init(void) {
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Stop mode */
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;

    /* Filtering configuration (MHDR, NHDR, NCLR, FDLR, MHDF, NHDF, NCLF, FDLF,
     * NHDT, NCLT, FDLT) */
    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1; /* Touch threshold */
        if (mpr121_write_reg(MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1; /* Release threshold */
    }

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* Config1: FFI=16 samples, CDC=16µA */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;

    /* Config2: CDT=0.5µs, SFI=4 samples */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    int lo = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    if (lo < 0) return -1;
    int hi = mpr121_read_reg(MPR121_TOUCHSTATUS_H);
    if (hi < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Relay %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            state ? "ON" : "OFF");
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("MPR121 relay controller running. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int touched = (touch_status & 0x0FFF) != 0;
        if (gpioWrite(RELAY_GPIO, touched ? 1 : 0) < 0) {
            fprintf(stderr, "Error writing GPIO %d\n", RELAY_GPIO);
        }

        log_relay_state(touched);
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

