#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define PAUSE_DURATION_S 5
#define PAUSE_DURATION_MS (PAUSE_DURATION_S * 1000)
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *valve_id, const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s - %s: %s\n", timestamp, valve_id, event);
    fflush(log_file);
}

static int activate_valve(struct gpiod_line *line, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", VALVE1_GPIO, strerror(errno));
        return -1;
    }
    log_event("Valve 1", "Activated");
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", VALVE1_GPIO, strerror(errno));
        return -1;
    }
    log_event("Valve 1", "Deactivated");
    return 0;
}

static int activate_valve2(struct gpiod_line *line, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", VALVE2_GPIO, strerror(errno));
        return -1;
    }
    log_event("Valve 2", "Activated");
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", VALVE2_GPIO, strerror(errno));
        return -1;
    }
    log_event("Valve 2", "Deactivated");
    return 0;
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Error getting GPIO %d: %s\n", VALVE1_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Error getting GPIO %d: %s\n", VALVE2_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(valve1_line, "valve1", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", VALVE1_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(valve2_line, "valve2", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", VALVE2_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Greenhouse water distribution schedule started. Press Ctrl+C to exit.\n");
    log_event("System", "Started");

    while (program_running) {
        if (activate_valve(valve1_line, VALVE1_DURATION_MS) < 0) {
            fprintf(stderr, "Error activating Valve 1.\n");
        }
        if (program_running) {
            sleep(PAUSE_DURATION_S);
        }
        if (activate_valve2(valve2_line, VALVE2_DURATION_MS) < 0) {
            fprintf(stderr, "Error activating Valve 2.\n");
        }
        if (program_running) {
            sleep(PAUSE_DURATION_S);
        }
    }

    printf("\nShutting down...\n");
    log_event("System", "Shutting down");
    cleanup();
    return 0;
}

