#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, event);
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate relay\n");
        return;
    }
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on PIR pin\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    uint32_t last_event_tick = 0;
    while (running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR pin\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (pir_state == 1 && last_event_tick == 0) {
            log_event("Motion detected");
            unlock_door();
            log_event("Door unlocked");
            gpioDelay(RATE_LIMIT_MS * 1000);
        }

        last_event_tick = gpioTick();
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    gpioWrite(RELAY_PIN, 0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

