#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15
#define STEP_DURATION_MS 50

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

int generate_pattern(int *pattern, int *pattern_size) {
    *pattern_size = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
    *pattern = (int *)malloc((*pattern_size) * sizeof(int));
    if (*pattern == NULL) {
        fprintf(stderr, "Memory allocation failed for pattern\n");
        return -1;
    }
    for (int i = 0; i < *pattern_size; i++) {
        int duty1 = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        int duty2 = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        int duration = rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1) + MIN_DURATION_MS;
        *pattern[i] = duty1;
        *pattern[i + 1] = duty2;
        *pattern[i + 2] = duration;
    }
    return 0;
}

void play_pattern(int *pattern, int pattern_size) {
    for (int i = 0; i < pattern_size; i += 3) {
        if (gpioPWM(MOTOR1_PIN, pattern[i]) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for motor 1\n");
            return;
        }
        gpioDelay(pattern[i + 1]);
        if (gpioPWM(MOTOR2_PIN, pattern[i + 1]) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for motor 2\n");
            return;
        }
        gpioDelay(pattern[i + 2]);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        return 1;
    }

    int pattern_size;
    int *pattern;
    while (!shutdown_flag) {
        if (generate_pattern(&pattern, &pattern_size) != 0) {
            fprintf(stderr, "Failed to generate pattern, exiting\n");
            break;
        }
        play_pattern(pattern, pattern_size);
        free(pattern);
        pattern = NULL;
    }

    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

