static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(const char *filename, float *scale_factor, float *offset) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s for reading; using defaults\n", filename);
        *scale_factor = 1.0f;
        *offset = 0.0f;
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;

        if (strcmp(key, "scale_factor") == 0) {
            *scale_factor = atof(value);
        } else if (strcmp(key, "offset") == 0) {
            *offset = atof(value);
        }
    }
    fclose(fp);

    if (*scale_factor <= 0.0f) {
        fprintf(stderr, "Warning: invalid scale factor; using default\n");
        *scale_factor = 1.0f;
    }
    return 0;
}

static float read_hx711(int data_pin, int clock_pin) {
    int count = 0;
    int timeout = 0;

    gpioWrite(clock_pin, 0);
    gpioDelay(10);

    while (gpioRead(data_pin) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > READ_TIMEOUT_US) {
            fprintf(stderr, "Warning: HX711 data pin stuck high (timeout)\n");
            return -1.0f;
        }
    }

    while (gpioRead(clock_pin) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > READ_TIMEOUT_US) {
            fprintf(stderr, "Warning: HX711 clock pin stuck high (timeout)\n");
            return -1.0f;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
        count = count << 1;
        if (gpioRead(data_pin)) count++;
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (count & 0x800000) count |= 0xFF000000;
    return (int16_t)count;
}

static float calibrate_hx711(int data_pin, int clock_pin, float *scale_factor, float *offset) {
    float sum = 0.0f;
    int valid = 0;
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw > 0) {
            sum += raw;
            valid++;
        }
        gpioDelay(10000);
    }
    if (valid == 0) {
        fprintf(stderr, "Error: no valid calibration readings\n");
        return -1.0f;
    }
    *offset = sum / valid;
    *scale_factor = 1.0f / (float)valid;
    return *offset;
}

static void control_solenoid(int pin, float weight) {
    if (weight > THRESHOLD_KG) {
        gpioWrite(pin, 1);
        printf("Solenoid engaged (weight: %.2f kg)\n", weight);
    } else {
        gpioWrite(pin, 0);
        printf("Solenoid released (weight: %.2f kg)\n", weight);
    }
}

static void log_weight(float weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for logging\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Weight: %.2f kg\n", ts, weight);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    float scale_factor = 1.0f, offset = 0.0f;
    if (read_calibration_data(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        fprintf(stderr, "Using defaults: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
    }

    signal(SIGINT, signal_handler);

    printf("Starting HX711 weight logging (threshold %.1f kg)...\n", THRESHOLD_KG);

    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw < 0) {
            fprintf(stderr, "Skipping iteration due to read error\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float weight = (float)(raw - offset) / scale_factor;
        control_solenoid(SOLENOID_PIN, weight);
        log_weight(weight);
        printf("Raw: %d, Weight: %.2f kg\n", raw, weight);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

