#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <string.h>
#include <unistd.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define MOTOR_RUN_TIME_SEC 5
#define CHECK_INTERVAL_SEC 60
#define LOG_FILE "/var/log/window_control.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val < 0) {
            syslog(LOG_ERR, "gpioRead failed on rain sensor pin %d", RAIN_SENSOR_PIN);
            return -1;
        }
        sum += val;
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }
    }
    return (sum >= 3) ? 0 : 1;
}

static int close_window(void) {
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) return -1;
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) return -1;
    if (gpioPWM(MOTOR_PWM_PIN, 150) < 0) return -1;
    syslog(LOG_INFO, "Closing window");
    sleep(MOTOR_RUN_TIME_SEC);
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) return -1;
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) return -1;
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) return -1;
    syslog(LOG_INFO, "Window closed");
    return 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Cannot open log file %s", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
    }
    fclose(fp);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0 || gpioWrite(MOTOR_IN2_PIN, 0) < 0 ||
        gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize motor pins LOW");
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Window control system started");

    while (running) {
        if (read_rain_sensor() == 0) {
            syslog(LOG_INFO, "Rain detected");
            if (close_window() == 0) {
                sleep(CHECK_INTERVAL_SEC);
            } else {
                syslog(LOG_ERR, "Motor control failed");
            }
        }
        sleep(CHECK_INTERVAL_SEC);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    return 0;
}

