#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define DT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define SOLENOID_DURATION_MS 5000
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(DT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set DT_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(SCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCK_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SOLENOID_PIN mode\n");
        return -1;
    }

    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise SOLENOID_PIN low\n");
        return -1;
    }

    return 0;
}

static int read_hx711(int dt_pin, int sck_pin, int *weight_out) {
    int data = 0;
    int timeout = 0;

    /* Ensure SCK is low before starting */
    if (gpioWrite(sck_pin, 0) < 0) {
        fprintf(stderr, "Failed to write SCK_PIN low\n");
        return -1;
    }

    /* Wait for DT to go low (data ready) */
    while (gpioRead(dt_pin) == 1) {
        gpioDelay(10);
        timeout += 10;
        if (timeout >= HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data ready\n");
            return -1;
        }
    }

    /* Read 24 bits of data */
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) < 0) {
            fprintf(stderr, "Failed to write SCK_PIN high\n");
            return -1;
        }
        gpioDelay(1);

        data = data << 1;
        if (gpioRead(dt_pin) == 1) {
            data |= 1;
        }

        if (gpioWrite(sck_pin, 0) < 0) {
            fprintf(stderr, "Failed to write SCK_PIN low\n");
            return -1;
        }
        gpioDelay(1);
    }

    /* 25th pulse to set gain to 128 */
    if (gpioWrite(sck_pin, 1) < 0) {
        fprintf(stderr, "Failed to write SCK_PIN high (25th pulse)\n");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(sck_pin, 0) < 0) {
        fprintf(stderr, "Failed to write SCK_PIN low (25th pulse)\n");
        return -1;
    }
    gpioDelay(1);

    /* Convert 24-bit two's complement to 32-bit signed */
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *weight_out = data;
    return 0;
}

static int activate_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Failed to activate solenoid\n");
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid\n");
        return -1;
    }
    return 0;
}

static int log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Failed to get current time\n");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Failed to convert time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: Stock level below threshold, solenoid activated\n", timestamp) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
