static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(DT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set DT_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(SCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCK_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SOLENOID_PIN mode\n");
        return -1;
    }

    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise SOLENOID_PIN low\n");
        return -1;
    }

    return 0;
}

static int read_hx711(int dt_pin, int sck_pin, int *weight_out) {
    int data = 0;
    int timeout = 0;

    /* Ensure SCK is low before starting */
    if (gpioWrite(sck_pin, 0) < 0) {
        fprintf(stderr, "Failed to write SCK_PIN low\n");
        return -1;
    }

    /* Wait for DT to go low (data ready) */
    while (gpioRead(dt_pin) == 1) {
        gpioDelay(10);
        timeout += 10;
        if (timeout >= HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data ready\n");
            return -1;
        }
    }

    /* Read 24 bits of data */
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) < 0) {
            fprintf(stderr, "Failed to write SCK_PIN high\n");
            return -1;
        }
        gpioDelay(1);

        data = data << 1;
        if (gpioRead(dt_pin) == 1) {
            data |= 1;
        }

        if (gpioWrite(sck_pin, 0) < 0) {
            fprintf(stderr, "Failed to write SCK_PIN low\n");
            return -1;
        }
        gpioDelay(1);
    }

    /* 25th pulse to set gain to 128 */
    if (gpioWrite(sck_pin, 1) < 0) {
        fprintf(stderr, "Failed to write SCK_PIN high (25th pulse)\n");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(sck_pin, 0) < 0) {
        fprintf(stderr, "Failed to write SCK_PIN low (25th pulse)\n");
        return -1;
    }
    gpioDelay(1);

    /* Convert 24-bit two's complement to 32-bit signed */
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

