        fprintf(stderr, "Failed to read raw value during calibration\n");
        return 0.0;
    }
    double calibrated = (double)raw / known_weight;
    if (calibrated < 0) calibrated = 0;
    if (calibrated > 1.0) calibrated = 1.0;
