        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int raw;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw) != 0) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = (double)raw / calibration_factor;
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
