#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int parse_duration(const char *line, int *duration_out)
{
    char buf[128];
    if (sscanf(line, "%127s", buf) != 1) {
        fprintf(stderr, "Error: malformed line in config file: %s\n", line);
        return -1;
    }
    char *endptr = NULL;
    errno = 0;
    long val = strtol(buf, &endptr, 10);
    if (errno != 0 || endptr == buf || *endptr != '\0' || val <= 0 || val > MAX_DURATION) {
        fprintf(stderr, "Error: invalid duration '%s' (expected positive integer 1-%d)\n", buf, MAX_DURATION);
        return -1;
    }
    *duration_out = (int)val;
    return 0;
}

static int set_valve(struct gpiod_line *line, int duration)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: failed to set valve line high: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve ON\n");
    fflush(stdout);

    if (duration > 0) {
        struct timespec req = { .tv_sec = duration, .tv_nsec = 0 };
        struct timespec rem;
        while (g_running && nanosleep(&req, &rem) == -1 && errno == EINTR) {
            req = rem;
        }
        if (!g_running) {
            fprintf(stderr, "Interrupted by signal during valve activation.\n");
            return -1;
        }
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: failed to set valve line low: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve OFF\n");
    fflush(stdout);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error: failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering-valve", 0) < 0) {
        fprintf(stderr, "Error: failed to request GPIO line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open config file '%s': %s\n", CONFIG_FILE, strerror(errno));
        goto cleanup;
    }

    char line_buf[256];
    int duration = 0;
    int rc = 0;

    while (fgets(line_buf, sizeof(line_buf), fp) != NULL) {
        if (parse_duration(line_buf, &duration) == 0) {
            rc = 0;
            break;
        }
    }

    if (fclose(fp) == EOF) {
        fprintf(stderr, "Warning: error closing config file: %s\n", strerror(errno));
    }

    if (rc != 0) {
        fprintf(stderr, "Error: no valid configuration found in '%s'. Exiting.\n", CONFIG_FILE);
        goto cleanup;
    }

    printf("Watering duration: %d seconds\n", duration);
    fflush(stdout);

    while (g_running) {
        if (set_valve(line, duration) == 0) {
            rc = 0;
            break;
        }
    }

    if (rc != 0) {
        fprintf(stderr, "Error: valve control failed. Exiting.\n");
        goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Program finished.\n");
    return ret;
}

