#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/*
 * Raspberry Pi Zero W - Line-Following Robot
 * Sensor : Keywish 3-Way IR Tracking Sensor (active-low)
 * Motor  : L298N dual H-bridge (PWM)
 * Wiring :
 *   Sensor 1 -> GPIO4
 *   Sensor 2 -> GPIO17
 *   Sensor 3 -> GPIO27
 *   Motor A -> GPIO22 (PWM)
 *   Motor B -> GPIO23 (PWM)
 *   Motor C -> GPIO24 (PWM)
 *            -> GPIO25 (PWM)
 *   Motor driver commons tied to Pi 3.3V
 *
 * Control law:
 *   If sensor 2 (middle) reads low, drive straight.
 *   If only sensor 1 reads low, turn right.
 *   If only sensor 3 reads low, turn left.
 *   If none reads low, stop.
 */

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define MOTOR_A_PIN  22
#define MOTOR_B_PIN  23
#define MOTOR_C_PIN  24
#define MOTOR_D_PIN  25

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define BASE_SPEED    150
#define STOP_SPEED    0

#define LOG_FILE_NAME "trace_log.txt"
#define SAMPLE_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(val));
        return -1;
    }
    return val;
}

static void set_motor_speed(int pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioPWM(pin, speed);
}

static void stop_all_motors(void) {
    set_motor_speed(MOTOR_A_PIN, STOP_SPEED);
    set_motor_speed(MOTOR_B_PIN, STOP_SPEED);
    set_motor_speed(MOTOR_C_PIN, STOP_SPEED);
    set_motor_speed(MOTOR_D_PIN, STOP_SPEED);
}

static void log_data(int s1, int s2, int s3, int l, int r) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, S1=%d, S2=%d, S3=%d, L=%d, R=%d\n",
            timestamp, s1, s2, s3, l, r);
    fflush(log_file);
}

int main(void) {
    int s1, s2, s3;
    int l, r;
    int speeds[4];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
