#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define LOG_FILE "grow_log.txt"
#define MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = 0x10;
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        log_message("Error: Failed to write measurement command to BH1750");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_message("Error: Failed to read 2 bytes from BH1750");
        return -1;
    }

    uint16_t raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    log_message("Program started");

    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char log_buf[256];
            snprintf(log_buf, sizeof(log_buf), "Lux: %.2f", lux);
            log_message(log_buf);

            int relay_state = gpioRead(RELAY_GPIO);
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(RELAY_GPIO, 1);
                log_message("Relay activated");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(RELAY_GPIO, 0);
                log_message("Relay deactivated");
            }
        } else {
            log_message("Error reading lux value");
        }

        gpioDelay(1000000);
    }

    log_message("Program terminated");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

