#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY_US 100000
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_PULSE_WIDTH_LOCK 1000
#define SERVO_PULSE_WIDTH_UNLOCK 2000

static volatile int running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed. Run with sudo or ensure pigpiod is running.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    signal(SIGINT, signal_handler);

    int lock_state = 0;
    int unlock_state = 0;

    while (running) {
        int lock_pressed = gpioRead(LOCK_BUTTON_PIN);
        int unlock_pressed = gpioRead(UNLOCK_BUTTON_PIN);

        if (lock_pressed == 0) {
            if (lock_state == 0) {
                if (gpioServo(SERVO_PIN, SERVO_PULSE_WIDTH_LOCK) == 0) {
                    lock_state = 1;
                } else {
                    fprintf(stderr, "Error: Failed to set servo to locked position.\n");
                }
            }
        } else if (lock_pressed == 1) {
            if (lock_state == 1) {
                if (gpioServo(SERVO_PIN, SERVO_PULSE_WIDTH_UNLOCK) == 0) {
                    lock_state = 0;
                } else {
                    fprintf(stderr, "Error: Failed to set servo to unlocked position.\n");
                }
            }
        }

        if (unlock_pressed == 0) {
            if (unlock_state == 0) {
                if (gpioServo(SERVO_PIN, SERVO_PULSE_WIDTH_UNLOCK) == 0) {
                    unlock_state = 1;
                } else {
                    fprintf(stderr, "Error: Failed to set servo to unlocked position.\n");
                }
            }
        } else if (unlock_pressed == 1) {
            if (unlock_state == 1) {
                if (gpioServo(SERVO_PIN, SERVO_PULSE_WIDTH_LOCK) == 0) {
                    unlock_state = 0;
                } else {
                    fprintf(stderr, "Error: Failed to set servo to locked position.\n");
                }
            }
        }

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

