#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define SOUND_POLL_INTERVAL_MS 10
#define ALARM_DURATION_SEC 1
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_SUBSCRIBE_ENDPOINT "tcp://localhost:5555"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **sensor_line, struct gpiod_line **led_line) {
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!*chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    *sensor_line = gpiod_chip_get_line(*chip, SOUND_SENSOR_GPIO);
    if (!*sensor_line) {
        perror("gpiod_chip_get_line (sensor)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    *led_line = gpiod_chip_get_line(*chip, ALARM_LED_GPIO);
    if (!*led_line) {
        perror("gpiod_chip_get_line (led)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(*sensor_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input (sensor)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*led_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output (led)");
        gpiod_line_release(*sensor_line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    return 0;
}

static int init_zmq(struct zmq_ctx **ctx, struct zmq_poll **poll) {
    *ctx = zmq_ctx_new();
    if (!*ctx) {
        perror("zmq_ctx_new");
        return -1;
    }

    *poll = zmq_poll_new(*ctx, 1);
    if (!*poll) {
        perror("zmq_poll_new");
        zmq_ctx_destroy(*ctx);
        *ctx = NULL;
        return -1;
    }

    zmq_poll_set_timeout(*poll, 1000);
    zmq_poll_set_events(*poll, ZMQ_POLLIN);
    return 0;
}

static int publish_sound_alert(struct zmq_poll *poll, struct gpiod_line *sensor_line) {
    char buffer[256];
    int n = snprintf(buffer, sizeof(buffer), "SOUND_DETECTED");
    if (n < 0 || (size_t)n >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }

    if (zmq_send(poll, buffer, strlen(buffer), 0) < 0) {
        perror("zmq_send");
        return -1;
    }

    return 0;
}

static int consume_sound_alert(struct zmq_poll *poll, struct gpiod_line *sensor_line) {
    char buffer[256];
    int n = zmq_recv(poll, buffer, sizeof(buffer) - 1, 0);
    if (n < 0) {
        perror("zmq_recv");
        return -1;
    }
    buffer[n] = '\0';

    if (strcmp(buffer, "SOUND_DETECTED") == 0) {
        printf("Sound detected!\n");
        if (gpiod_line_set_value(*sensor_line, 1) < 0) {
            perror("gpiod_line_set_value (high)");
            return -1;
        }
        sleep(ALARM_DURATION_SEC);
        if (gpiod_line_set_value(*sensor_line, 0) < 0) {
            perror("gpiod_line_set_value (low)");
            return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    (void)argc;
    (void)argv;

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;
    struct zmq_ctx *ctx = NULL;
    struct zmq_poll *poll = NULL;
    int ret = EXIT_FAILURE;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio(&chip, &sensor_line, &led_line) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (init_zmq(&ctx, &poll) < 0) {
        fprintf(stderr, "ZMQ initialization failed. Exiting.\n");
        goto cleanup_gpio;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        printf("Sound sensor mode. Polling GPIO%d every %d ms.\n", SOUND_SENSOR_GPIO, SOUND_POLL_INTERVAL_MS);
        while (program_running) {
            int val = gpiod_line_get_value(sensor_line);
            if (val < 0) {
                perror("gpiod_line_get_value (sensor)");
                break;
            }
            if (val == 0) {
                if (publish_sound_alert(poll, sensor_line) < 0) {
                    break;
                }
            }
            usleep(SOUND_POLL_INTERVAL_MS * 1000);
        }
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        printf("Alarm node mode. Subscribing to %s on %s.\n", SOUND_ALERTS_TOPIC, ZMQ_SUBSCRIBE_ENDPOINT);
        int rc = zmq_connect(ctx, ZMQ_SUBSCRIBE_ENDPOINT);
        if (rc < 0) {
            perror("zmq_connect (subscribe)");
            break;
        }

        while (program_running) {
            int rc = zmq_recv(poll, buffer, sizeof(buffer) - 1, 0);
            if (rc < 0) {
                perror("zmq_recv");
                break;
            }
            buffer[rc] = '\0';

            if (strcmp(buffer, "SOUND_DETECTED") == 0) {
                printf("Received alert: %s\n", buffer);
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    perror("gpiod_line_set_value (high)");
                    break;
                }
                sleep(ALARM_DURATION_SEC);
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    perror("gpiod_line_set_value (low)");
                    break;
                }
            }
        }
        zmq_close(poll);
        zmq_destroy(ctx);
    } else {
        fprintf(stderr, "Invalid mode. Use 'sound_sensor' or 'alarm_node'.\n");
    }

cleanup_zmq:
    if (ctx) zmq_ctx_destroy(ctx);
    if (poll) zmq_poll_destroy(poll);
    if (ctx) zmq_ctx_destroy(ctx);
    if (poll) zmq_poll_destroy(poll);
    if (sensor_line) gpiod_line_release(sensor_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

