#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MAX_PULSES 1000
#define NEC_HEADER_MARK_US 9000
#define NEC_HEADER_SPACE_US 4500
#define NEC_BIT_MARK_US 560
#define NEC_SPACE_US_ONE 1690
#define NEC_SPACE_US_ZERO 560
#define NEC_CHECKSUM_MASK 0xFF
#define NEC_CHECKSUM_VALUE 0x33
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PAYLOAD_SIZE 256

static volatile sig_atomic_t running = 1;
static int pigpio_initialized = 0;
static struct mosquitto *mqtt_client = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    static uint32_t last_tick = 0;
    static int last_level = 0;
    static uint32_t pulse_count = 0;
    static uint32_t pulse_times[MAX_PULSES];
    static int pulse_index = 0;
    static uint32_t last_edge_tick = 0;
    static int last_edge_level = 0;

    if (level != 0 && level != 1) {
        return;
    }

    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (last_edge_level != level) {
        if (last_edge_level != 0) {
            pulse_times[pulse_index] = diff;
            pulse_index++;
            if (pulse_index >= MAX_PULSES) {
                pulse_index = 0;
            }
        }
        last_edge_level = level;
        last_edge_tick = tick;
    }

    if (level == 1) {
        if (pulse_index > 0) {
            pulse_times[pulse_index] = tick;
            pulse_index++;
            if (pulse_index >= MAX_PULSES) {
                pulse_index = 0;
            }
        }
    }
}

static int decode_nec(const uint32_t *pulses, int count, uint8_t *address, uint8_t *command) {
    if (count < 33) {
        return -1;
    }

    uint32_t header_mark = 0, header_space = 0, bit_mark = 0, bit_space = 0;
    uint32_t addr = 0, cmd = 0;

    for (int i = 0; i < 33; i++) {
        if (pulses[i] > NEC_HEADER_MARK_US) {
            header_mark = pulses[i];
        } else if (pulses[i] > NEC_HEADER_SPACE_US) {
            header_space = pulses[i];
        } else if (pulses[i] > NEC_BIT_MARK_US) {
            bit_mark = pulses[i];
        } else if (pulses[i] > NEC_SPACE_US_ONE) {
            bit_space = pulses[i];
        } else if (pulses[i] > NEC_SPACE_US_ZERO) {
            bit_space = pulses[i];
        } else {
            return -1;
        }
    }

    if ((header_mark + header_space) != NEC_HEADER_MARK_US + NEC_HEADER_SPACE_US) {
        return -1;
    }

    if (bit_mark > NEC_BIT_MARK_US + NEC_SPACE_US_ONE) {
        return -1;
    }

    uint8_t decoded_addr = 0, decoded_cmd = 0;
    for (int i = 0; i < 8; i++) {
        if (bit_mark > NEC_BIT_MARK_US + NEC_SPACE_US_ONE) {
            return -1;
        }
        uint32_t bit_val = pulses[i + 1] - bit_mark;
        if (bit_val > NEC_SPACE_US_ZERO) {
            decoded_addr |= (1 << i);
        }
        bit_mark = pulses[i + 1] + NEC_SPACE_US_ZERO;
    }

    for (int i = 0; i < 8; i++) {
        if (bit_mark > NEC_BIT_MARK_US + NEC_SPACE_US_ONE) {
            return -1;
        }
        uint32_t bit_val = pulses[i + 10] - bit_mark;
        if (bit_val > NEC_SPACE_US_ZERO) {
            decoded_cmd |= (1 << i);
        }
        bit_mark = pulses[i + 10] + NEC_SPACE_US_ZERO;
    }

    if ((uint8_t)(decoded_addr ^ NEC_CHECKSUM_MASK) != NEC_CHECKSUM_VALUE) {
        return -1;
    }

    *address = decoded_addr;
    *command = decoded_cmd;
    return 0;
}

static int publish_command(const char *command) {
    if (mqtt_client == NULL) {
        mqtt_client = mosquitto_new(NULL, true, NULL);
        if (mqtt_client == NULL) {
            syslog(LOG_ERR, "Failed to create MQTT client");
            return -1;
        }
    }

    if (mosquitto_connect(mqtt_client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mqtt_client);
        mqtt_client = NULL;
        return -1;
    }

