#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR_1  0x23
#define BH1750_ADDR_2  0x24
#define BH1750_ADDR_3  0x25
#define BH1750_ADDR_4  0x26
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS  180
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5005
#define NUM_SENSORS     4
#define READ_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_open(int addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux)
{
    uint8_t cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "BH1750 write: %s\n", w < 0 ? strerror(errno) : "short write");
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 read: %s\n", r < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(const char *data)
{
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) != 1) {
        fprintf(stderr, "inet_pton(%s): invalid address\n", MULTICAST_ADDR);
        close(sock);
        return -1;
    }
    if (sendto(sock, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    close(sock);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++)
        i2c_fds[i] = -1;

    while (g_running) {
        float lux[NUM_SENSORS];
        int ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int fd = i2c_open(i < 3 ? BH1750_ADDR_1 : i < 4 ? BH1750_ADDR_2 : i < 5 ? BH1750_ADDR_3 : BH1750_ADDR_4);
            if (fd < 0) {
                fprintf(stderr, "Sensor %d (addr 0x%02X): read failed\n", i + 1, i < 3 ? BH1750_ADDR_1 : i < 4 ? BH1750_ADDR_2 : i < 5 ? BH1750_ADDR_3 : BH1750_ADDR_4);
                ok = 0;
                continue;
            }
            if (bh1750_read(fd, &lux[i]) < 0) {
                fprintf(stderr, "Sensor %d (addr 0x%02X): read failed\n", i + 1, i < 3 ? BH1750_ADDR_1 : i < 4 ? BH1750_ADDR_2 : i < 5 ? BH1750_ADDR_3 : BH1750_ADDR_4);
                ok = 0;
                close(fd);
            }
            close(fd);
        }

        if (!ok) {
            fprintf(stderr, "All sensors failed this cycle\n");
        } else {
            char buffer[NUM_SENSORS * 64];
            snprintf(buffer, sizeof(buffer), "%d,%.2f;%d,%.2f;%d,%.2f;%d,%.2f",
                     1, lux[0], 2, lux[1], 3, lux[2], 4, lux[3]);
            if (send_multicast(buffer) < 0)
                fprintf(stderr, "Failed to send multicast\n");
        }

        sleep(READ_INTERVAL_S);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0)
            close(i2c_fds[i]);
    }
    return 0;
}

