#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300_ADDR   0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_zero_length(int fd) {
    if (write(fd, NULL, 0) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len) {
            return 0;
        }
        if (n < 0) {
            if (errno == ENXIO) {
                return -1; /* sensor absent */
            }
            if (errno == EIO) {
                return -1; /* bus error */
            }
            return -1;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(RETRY_DELAY_US);
        }
    }
    return -1;
}

static int read_flow_raw(int fd, uint16_t *raw_out) {
    uint8_t buf[2];
