#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define AS7341_I2C_ADDR 0x39
#define AS7341_WHO_AM_I 0x24
#define AS7341_ID       0x19
#define AS7341_ENABLE  0x80
#define AS7341_CFG6    0xAF
#define AS7341_DATA_START 0x60
#define AS7341_EXPECTED_ID 0x19
#define NUM_SPECTRAL_CHANNELS 10
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write reg failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("i2c_read_reg8: read failed");
        return -1;
    }
    return 0;
}

static int as7341_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, AS7341_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != AS7341_EXPECTED_ID) {
        fprintf(stderr, "AS7341 WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, AS7341_EXPECTED_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_ENABLE, 0x01) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_CFG6, 0x00) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_ENABLE, 0x01) < 0) return -1;
    usleep(10000);

    return 0;
}

static int read_spectral_data(int fd, uint16_t *data) {
    for (int i = 0; i < NUM_SPECTRAL_CHANNELS; i++) {
        uint8_t reg = AS7341_DATA_START + (uint8_t)(i * 2);
        uint8_t val;
        if (i2c_read_reg8(fd, reg, &val) < 0) {
            return -1;
        }
        data[i] = (uint16_t)val;
    }
    return 0;
}

static float calculate_lux(const uint16_t *data) {
    float sum = 0.0f;
    for (int i = 0; i < NUM_SPECTRAL_CHANNELS; i++) {
        sum += (float)data[i];
    }
    return sum * 0.00390625f;
}

static void log_data(FILE *fp, const uint16_t *data, float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            data[0], data[1], data[2], data[3],
            data[4], data[5], data[6], data[7], data[8], data[9]);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (as7341_init(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("spectral_log.csv", "a");
    if (!log_file) {
        perror("fopen spectral_log.csv");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,Clear,NIR,F4,F5,F6,F7,F8\n");
    }

    while (running) {
        uint16_t spectral_data[NUM_SPECTRAL_CHANNELS];
        if (read_spectral_data(i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Error reading spectral data\n");
        } else {
            float lux = calculate_lux(spectral_data);
            log_data(log_file, spectral_data, lux);
            printf("Lux: %.2f\n", lux);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

