#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;
static FILE *error_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!error_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_fp, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
    fflush(error_fp);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        log_error("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, 0x28, buf, 6) != 0) return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * 0.000244f;
    *y = (float)raw_y * 0.000244f;
    *z = (float)raw_z * 0.000244f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (csv_fp) { fclose(csv_fp); csv_fp = NULL; }
    if (error_fp) { fclose(error_fp); error_fp = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int i2c_addr = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char filename[256];

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_addr = (int)strtol(argv[i + 1], NULL, 0);
            if (i2c_addr < 0x03 || i2c_addr > 0x77) {
                fprintf(stderr, "Invalid I2C address 0x%02X\n", i2c_addr);
                return 1;
            }
            i++;
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            interval = atoi(argv[i + 1]);
            if (interval <= 0) {
                fprintf(stderr, "Interval must be positive\n");
                return 1;
            }
            i++;
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            strncpy(filename, argv[i + 1], sizeof(filename) - 1);
            filename[sizeof(filename) - 1] = '\0';
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n", argv[0]);
            return 1;
        }
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    if (i2c_write_reg8(i2c_fd, 0x00, 0x00) != 0) {
        log_error("Failed to reset sensor");
        cleanup();
        return 1;
    }

    csv_fp = fopen(filename, "a");
    if (!csv_fp) {
        log_error("Failed to open CSV file");
        cleanup();
        return 1;
    }

    error_fp = fopen(filename, "a");
    if (!error_fp) {
        log_error("Failed to open error log file");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting seismic data logging to %s every %d seconds...\n", filename, interval);

    while (running) {
        float x, y, z;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                success = 1;
                break;
            }
            log_error("Sensor read failed, retrying...");
            usleep(RETRY_DELAY_MS * 1000);
        }

        if (success) {
            log_data(csv_fp, x, y, z);
            printf("X: %.6f g, Y: %.6f g, Z: %.6f g\n", x, y, z);
        } else {
            log_error("Sensor read failed after retries");
        }

        sleep(interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

