#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_cmd(fd, 0x01) < 0) return -1;
    if (i2c_write_cmd(fd, 0x10) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_data(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char message[64];
    int len = snprintf(message, sizeof(message), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(message)) {
        fprintf(stderr, "Message formatting failed\n");
        return -1;
    }

    if (sendto(sock_fd, message, (size_t)len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "UDP sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor may be absent)\n");
        close(i2c_fd);
        return 1;
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int ttl = TTL;
    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Failed to set TTL: %s\n", strerror(errno));
        close(sock_fd);
        close(i2c_fd);
        return 1;
    }

    printf("BH1750 light sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            if (send_multicast(lux) < 0) {
                fprintf(stderr, "Failed to send multicast data\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (sock_fd >= 0) close(sock_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

