#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 8192
#define MAGIC_WORD_SIZE 8
#define TLV_HEADER_SIZE 8
#define MAX_OBJECTS 100

#define TLV_TYPE_DETECTED_POINTS 1
#define TLV_TYPE_RANGE_PROFILE 2
#define TLV_TYPE_VELOCITY_PROFILE 3

#define RANGE_PROFILE_SIZE 12
#define VELOCITY_PROFILE_SIZE 12

typedef struct {
    float range;
    float velocity;
} RadarData;

static int uart_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file %s\n", CSV_FILE);
        return -1;
    }
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    fflush(csv_file);
    return 0;
}

static int read_exact(int handle, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = serRead(handle, (char *)(buf + total), len - total);
        if (n < 0) {
            fprintf(stderr, "UART read error\n");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int sync_magic_word(int handle, uint8_t *buf, int len) {
    uint8_t mw[MAGIC_WORD_SIZE];
    for (int i = 0; i < len; i++) {
        if (buf[i] != mw[i]) {
            return -1;
        }
    }
    return 0;
}

static int parse_tlv_payload(int handle, uint8_t *buf, int len, RadarData *data, int *num_objects) {
    int offset = 0;
    *num_objects = 0;
    while (offset + TLV_HEADER_SIZE <= len) {
        uint32_t tlv_type = (uint32_t)buf[offset] | ((uint32_t)buf[offset + 1] << 8) |
                           ((uint32_t)buf[offset + 2] << 16) | ((uint32_t)buf[offset + 3] << 24);
        uint32_t tlv_length = (uint32_t)buf[offset + 4] | ((uint32_t)buf[offset + 5] << 8) |
                             ((uint32_t)buf[offset + 6] << 16) | ((uint32_t)buf[offset + 7] << 24);
        offset += TLV_HEADER_SIZE;
        if (offset + tlv_length > len) {
            fprintf(stderr, "TLV length exceeds frame bounds\n");
            return -1;
        }
        if (tlv_type == TLV_TYPE_DETECTED_POINTS) {
            if (tlv_length < 4) {
                fprintf(stderr, "Detected points TLV too short\n");
                return -1;
            }
            int num_points = tlv_length / 4;
            for (int i = 0; i < num_points; i++) {
                int p_offset = offset + i * 4;
                int p_range = (int16_t)buf[p_offset] | ((int16_t)buf[p_offset + 1] << 8);
                int p_velocity = (int16_t)buf[p_offset + 2] | ((int16_t)buf[p_offset + 3] << 8);
                data[*num_objects].range = p_range / 100.0f;
                data[*num_objects].velocity = p_velocity / 100.0f;
                (*num_objects)++;
            }
        } else if (tlv_type == TLV_TYPE_RANGE_PROFILE) {
            if (tlv_length < 12) {
                fprintf(stderr, "Range profile TLV too short\n");
                return -1;
            }
            int profile_len = tlv_length;
            if (profile_len < 12) {
                fprintf(stderr, "Range profile incomplete\n");
                return -1;
            }
            uint16_t range_idx = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
            uint16_t vel_idx = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
            uint16_t num_bins = (uint16_t)buf[8] | ((uint16_t)buf[9] << 8);
            uint16_t bin_size = (uint16_t)buf[10] | ((uint16_t)buf[11] << 8);
            if (num_bins == 0) {
                fprintf(stderr, "Range profile has zero bins\n");
                return -1;
            }
            float min_range = (float)range_idx * bin_size;
            float max_range = min_range + (float)num_bins * bin_size;
            float min_vel = (float)vel_idx * bin_size;
            float max_vel = min_vel + (float)num_bins * bin_size;
            for (int i = 0; i < num_bins; i++) {
                int p_offset = offset + i * 12;
                int p_range = (int16_t)buf[p_offset] | ((int16_t)buf[p_offset + 1] << 8);
