#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define READ_BUF_SIZE 512
#define LINE_BUF_SIZE 256
#define TIMEOUT_SEC 2

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart(int fd, char *buf, size_t buf_size) {
    fd_set rfds;
    struct timeval tv;

    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    int ret = select(fd + 1, &rfds, NULL, NULL, &tv);
    if (ret < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "select() error: %s\n", strerror(errno));
        return -1;
    }
    if (ret == 0) return 0; /* timeout */

    ssize_t n = read(fd, buf, buf_size - 1);
    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) return 0;
        fprintf(stderr, "read() error: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) return 0; /* no data available */

    buf[n] = '\0';
    return n;
}

static int parse_line(const char *line, float *range) {
    char *endptr = NULL;
    errno = 0;
    long val = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line) return -1;
    *range = (float)val;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_fd < 0) return 1;

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;

    printf("Radar data acquisition started on %s. Press Ctrl+C to exit.\n", UART_DEVICE);

    while (g_running) {
        char read_buf[READ_BUF_SIZE];
        int n = read_uart(g_fd, read_buf, sizeof(read_buf));
        if (n < 0) {
            fprintf(stderr, "UART read error, continuing...\n");
            sleep(1);
            continue;
        }
        if (n == 0) {
            /* Timeout, no data */
            continue;
        }

        for (int i = 0; i < n && g_running; i++) {
            char c = read_buf[i];
            if (c == '\n') {
                line_buf[line_len] = '\0';
                if (line_len > 0) {
                    float range;
                    if (parse_line(line_buf, &range) == 0) {
                        printf("Timestamp: %ld, Range: %.2f meters\n", (long)time(NULL), range);
                    } else {
                        fprintf(stderr, "Invalid data: '%s'\n", line_buf);
                    }
                    line_len = 0;
                }
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line too long, discarding.\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_fd >= 0) {
        tcflush(g_fd, TCIOFLUSH);
        close(g_fd);
        g_fd = -1;
    }
    printf("\nRadar data acquisition stopped.\n");
    return 0;
}

