#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <string.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define LOOP_DELAY_US 100000  /* 100 ms = 10 Hz */

static volatile sig_atomic_t running = 1;
static int serial_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_sensor(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d.\n", pin);
        return -1;
    }
    return val;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n",
           timestamp, left, middle, right);
}

static int send_emergency_stop(void) {
    if (serial_fd < 0) {
        fprintf(stderr, "Error: serial port not initialized.\n");
        return -1;
    }

    ssize_t bytes_written = write(serial_fd, "EMERGENCY STOP!\n", 20);
    if (bytes_written < 0) {
        perror("Error writing to serial port");
        return -1;
    }
    if ((size_t)bytes_written != 20) {
        fprintf(stderr, "Warning: partial write to serial port.\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd < 0) {
        perror("Error opening serial port");
        gpioTerminate();
        return 1;
    }

    if (fcntl(serial_fd, F_SETFL, 0) < 0) {
        perror("Error clearing O_NDELAY flags");
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    struct termios options;
    memset(&options, 0, sizeof(options));
    if (tcgetattr(serial_fd, &options) != 0) {
        perror("Error from tcgetattr");
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag = (options.c_cflag & ~CSIZE) | CS8;
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~(PARENB | PARODD);
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CRTSCTS;

    options.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    options.c_oflag &= ~OPOST;
    options.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 1;  /* 100 ms timeout */

    if (tcsetattr(serial_fd, TCSANOW, &options) != 0) {
        perror("Error from tcsetattr");
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    printf("KY-033 3-Way Tracking Sensor Monitor\n");
    printf("Left: GPIO%d, Middle: GPIO%d, Right: GPIO%d\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Serial port: %s @ %d baud\n", SERIAL_PORT, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Warning: sensor read error, continuing.\n");
        } else {
            log_sensor_data(left, middle, right);
            if (left == 0 && middle == 0 && right == 0) {
                if (send_emergency_stop() != 0) {
                    fprintf(stderr, "Warning: failed to send emergency stop.\n");
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (serial_fd >= 0) {
        close(serial_fd);
    }
    gpioTerminate();
    return 0;
}

